/* Planning Timeline (tasks) */
function buildTasksPrintSheets(){
  const rows0 = safeArray(data && data.tasks);
  const done = rows0.filter(t => _cvpStatusClass(t.status) === 'done').length;
  const prog = rows0.filter(t => _cvpStatusClass(t.status) === 'praying').length;
  const todayISO = new Date().toISOString().slice(0, 10);
  const nextDue = rows0.filter(t => _cvpStatusClass(t.status) !== 'done' && _cvpStr(t.date || t.suggestedDue) >= todayISO).length;
  const today = new Date().toLocaleDateString('en-US', { year:'numeric', month:'long', day:'numeric' });

  /* group tasks by phase, preserving first-seen order */
  const phases = [];
  rows0.forEach(t => { const p = _cvpStr(t.phase) || _cvpStr(t.cat) || 'General'; if (phases.indexOf(p) < 0) phases.push(p); });
  const cur = rows0.find(t => _cvpStatusClass(t.status) !== 'done') || rows0[0] || {};
  const curPhaseName = _cvpStr(cur.phase) || _cvpStr(cur.cat) || '—';

  const phaseBlocks = phases.map(p => {
    const items = rows0.filter(t => (_cvpStr(t.phase) || _cvpStr(t.cat) || 'General') === p);
    const rowsHtml = items.map(t =>
      '<tr><td class="date">' + _cvpShortDate(t.date || t.suggestedDue) + '</td>'
      + '<td class="strong">' + escapeHtml(_cvpStr(t.task)) + '</td>'
      + '<td>' + escapeHtml(_cvpStr(t.assigned)) + '</td>'
      + '<td>' + (_cvpStr(t.status) ? _cvpPill(t.status) : '') + '</td>'
      + '<td>' + escapeHtml(_cvpStr(t.notes)) + '</td></tr>'
    ).join('');
    return '<div class="cvp-phasehead"><span class="pn">' + escapeHtml(p) + '</span><span class="pc">' + items.length + (items.length === 1 ? ' task' : ' tasks') + '</span></div>'
      + '<div class="cvp-phaserule"></div>'
      + '<table class="cvp-table"><thead><tr><th>Due</th><th>Task</th><th>Owner</th><th>Status</th><th>Notes / details</th></tr></thead><tbody>' + rowsHtml + '</tbody></table>';
  }).join('') || '<div class="cvp-empty">No tasks yet.</div>';

  const info = _cvpInfoCell('Couple', _cvpCouple()) + _cvpInfoCell('Wedding date', _cvpWedDate())
    + _cvpInfoCell('Current phase', curPhaseName) + _cvpInfoCell('Last updated', today);
  const stats = _cvpSec('Where planning stands') + '<div class="cvp-stats">'
    + _cvpStat('Total tasks', rows0.length) + _cvpStat('Completed', done, 'mauve')
    + _cvpStat('In progress', prog, 'gold') + _cvpStat('Next due', nextDue, 'burg') + '</div>';
  const register = _cvpSec('Task register by phase') + phaseBlocks;
  const cards = _cvpSec('How to use this timeline')
    + '<div class="cvp-cards">'
    + '<div class="cvp-card"><h3 class="cvp-card-title">This season</h3><p>Choose the few decisions that unlock the next group of tasks. Keep the conversation calm, clear, and shared.</p><div class="cvp-writeline"></div><div class="cvp-writeline"></div></div>'
    + '<div class="cvp-card mauve"><h3 class="cvp-card-title">Partner handoff</h3><p>Bring this page into your weekly planning conversation and assign one clear owner to each next step.</p><div class="cvp-writeline"></div><div class="cvp-writeline"></div></div>'
    + '</div>';
  const notes = _cvpSec('Notes &amp; reminders') + '<div class="cvp-note"><div class="cvp-writeline"></div><div class="cvp-writeline"></div><div class="cvp-writeline"></div></div>';

  return _cvpPage(_CVP_BRAND + ' &middot; Planning', 'Planning Timeline', 'Every planning task by phase — from proposal to honeymoon', info, stats + register + cards + notes, 'She looketh well to the ways of her household.', 'Planning Timeline');
}

/* Smart Calendar (aggregated dates) */
function buildCalendarPrintSheets(){
  const items = [];
  safeArray(data && data.calendarEvents).forEach(e => { if (_cvpStr(e.date)) items.push({ date:_cvpStr(e.date), time:_cvpStr(e.time), label:_cvpStr(e.title), type:_cvpStr(e.category) || 'Event' }); });
  safeArray(data && data.appointments).forEach(a => { if (_cvpStr(a.date)) items.push({ date:_cvpStr(a.date), time:_cvpStr(a.time), label:_cvpStr(a.title), type:'Appointment' }); });
  safeArray(data && data.payments).forEach(p => { if (_cvpStr(p.date) && _cNum(p.due) > _cNum(p.paid)) items.push({ date:_cvpStr(p.date), time:'', label:(_cvpStr(p.vendor) || 'Payment') + (_cvpStr(p.desc) ? ' — ' + _cvpStr(p.desc) : ''), type:'Payment due' }); });
  safeArray(data && data.tasks).forEach(t => { const d = _cvpStr(t.date); if (d) items.push({ date:d, time:'', label:_cvpStr(t.task), type:'Task' }); });
  items.sort((a, b) => (a.date + a.time).localeCompare(b.date + b.time));
  const body = items.map(i => '<tr><td class="date">' + _cvpShortDate(i.date) + '</td><td>' + escapeHtml(i.time) + '</td><td class="strong">' + escapeHtml(i.label) + '</td><td>' + escapeHtml(i.type) + '</td></tr>').join('');
  const info = _cvpInfoCell('Couple', _cvpCouple()) + _cvpInfoCell('Wedding date', _cvpWedDate()) + _cvpInfoCell('Dates tracked', items.length);
  const table = _cvpSec('Everything with a date') + _cvpTable([{label:'Date'},{label:'Time'},{label:'What'},{label:'Type'}], body, 'No dated items yet.');
  return _cvpPage(_CVP_BRAND + ' &middot; Planning', 'Smart Calendar', 'Every dated item across the planner, in order', info, table, 'To every thing there is a season.', 'Smart Calendar');
}

