  if (dISO) { const d = new Date(dISO.length <= 10 ? dISO + 'T00:00:00' : dISO); if (!isNaN(d.getTime())) daysLeft = Math.max(0, Math.ceil((d - new Date()) / 86400000)); }
  const overall = _cNum(s.budget);
  let spent = 0; try { if (typeof computeBudgetVariance === 'function') spent = _cNum(computeBudgetVariance().totalActual); } catch (e) {}
  const budgetPct = overall ? Math.round(spent / overall * 100) + '%' : '—';
  const yes = g.filter(x => /^(yes|accept)/i.test(_cvpStr(x.rsvp))).length;
  const tasksDone = t.filter(x => _cvpStatusClass(x.status) === 'done').length;
  const paid = pays.reduce((a, p) => a + _cNum(p.paid), 0), dueTot = pays.reduce((a, p) => a + _cNum(p.due), 0);
  const booked = vends.filter(v => (typeof vendorBookedStatus === 'function' ? vendorBookedStatus(v.status) : /book|confirm/i.test(_cvpStr(v.status))) || v.contract).length;
  const verse = _cvpStr(s.bannerVerse), verseRef = _cvpStr(s.bannerRef);
