function buildPacketsPrintSheets(){
  const sec = (typeof _pktSection !== 'undefined') ? _pktSection : 'vendor';
  if (sec === 'party') return _cvpPartyPacket(typeof _pktActiveKey !== 'undefined' ? _pktActiveKey : 'bridesmaids');
  if (sec === 'coordinator') return _cvpCoordinatorPacket();
  if (sec === 'weekend') return _cvpWeekendPacket(typeof _pktWeekendKey !== 'undefined' ? _pktWeekendKey : 'itinerary');
  return _cvpVendorPacket(typeof _pktActiveKey !== 'undefined' ? _pktActiveKey : 'florist');
}

/* Every packet variant (all vendor + party keys, coordinator, all weekend tabs). */
function _cvpAllPacketsSheets(){
  const out = [];
  const add = h => { if (h) out.push(h); };
  try { if (typeof VENDOR_PACKET_FIELDS !== 'undefined') Object.keys(VENDOR_PACKET_FIELDS).forEach(k => add(_cvpVendorPacket(k))); } catch (e) {}
  try { if (typeof PARTY_PACKET_FIELDS !== 'undefined') Object.keys(PARTY_PACKET_FIELDS).forEach(k => add(_cvpPartyPacket(k))); } catch (e) {}
  try { add(_cvpCoordinatorPacket()); } catch (e) {}
  try { if (typeof WEEKEND_PACKET_TABS !== 'undefined') WEEKEND_PACKET_TABS.forEach(t => add(_cvpWeekendPacket(t[0]))); } catch (e) {}
  return out.join('');
}
/* The whole planner as one printout — every page, sub-tab, and packet. */
function buildAllCovenantPrintSheets(){
  const parts = [];
  const add = fn => { try { const h = fn(); if (h) parts.push(h); } catch (e) { if (typeof console !== 'undefined') console.error('Print-all builder failed:', e); } };
  const builders = [
    buildDashboardPrintSheets,
    buildVisionFoundationPrintSheets, buildCounselingPrintSheets, buildPrayerPrintSheets,
    buildInstructionsPrintSheets, buildGuidePrintSheets, buildFaqPrintSheets, buildDataHubPrintSheets, buildSetupPrintSheets,
    buildTasksPrintSheets, buildCalendarPrintSheets, buildAppointmentsPrintSheets, buildNotesPrintSheets, buildLogisticsPrintSheets,
    buildBudgetPrintSheets, buildPaymentsPrintSheets, buildContractsPrintSheets,
    buildVenuePrintSheets, buildVendorsPrintSheets, buildCateringPrintSheets,
    buildGuestListPrintSheets, buildPartyPrintSheets, buildTablesPrintSheets,
    buildCeremonyPrintSheets, buildTimelinePrintSheets, buildEntertainmentPrintSheets, buildShotlistPrintSheets,
    buildMoodPrintSheets, buildEssentialsPrintSheets, buildGiftsPrintSheets,
    buildHoneymoonPrintSheets, buildRhythmsPrintSheets, buildHomecomingPrintSheets
  ];
  builders.forEach(add);
  add(_cvpAllPacketsSheets);   // all share packets
  return parts.join('');
}
/* Trigger: open the full-planner preview (paginated, style toggle, print-first). */
function printAllCovenantSheets(){
  try {
    if (typeof showToast === 'function') showToast('Building the full planner printout…');
  } catch (e) {}
  setTimeout(() => openCovenantPrintTemplate(buildAllCovenantPrintSheets()), 30);
}

/* Registry + dispatch: which pages have a dedicated Covenant print template. */
function tryCovenantPrintTemplate(target){
  const reg = {
    vendors: buildVendorsPrintSheets, guests: buildGuestListPrintSheets, budget: buildBudgetPrintSheets,
    counseling: buildCounselingPrintSheets, prayer: buildPrayerPrintSheets, payments: buildPaymentsPrintSheets,
    contracts: buildContractsPrintSheets, party: buildPartyPrintSheets, catering: buildCateringPrintSheets,
    timeline: buildTimelinePrintSheets, appointments: buildAppointmentsPrintSheets, tasks: buildTasksPrintSheets,
    calendar: buildCalendarPrintSheets, notes: buildNotesPrintSheets, logistics: buildLogisticsPrintSheets,
    venue: buildVenuePrintSheets, tables: buildTablesPrintSheets, ceremony: buildCeremonyPrintSheets,
    entertainment: buildEntertainmentPrintSheets, shotlist: buildShotlistPrintSheets, mood: buildMoodPrintSheets,
    essentials: buildEssentialsPrintSheets, gifts: buildGiftsPrintSheets, honeymoon: buildHoneymoonPrintSheets,
    dashboard: buildDashboardPrintSheets, setup: buildSetupPrintSheets, 'data-hub': buildDataHubPrintSheets,
    faq: buildFaqPrintSheets, guide: buildGuidePrintSheets, instructions: buildInstructionsPrintSheets
  };
  try {
    if (target === 'reflect' && typeof _rflTab !== 'undefined') {
      if (_rflTab === 'vision') { openCovenantPrintTemplate(buildVisionFoundationPrintSheets()); return true; }
      if (_rflTab === 'rhythms') { openCovenantPrintTemplate(buildRhythmsPrintSheets()); return true; }
      if (_rflTab === 'homecoming') { openCovenantPrintTemplate(buildHomecomingPrintSheets()); return true; }
    }
    if (target === 'vision') { openCovenantPrintTemplate(buildVisionFoundationPrintSheets()); return true; }
    if (target === 'firstmonth' || target === 'rhythms') { openCovenantPrintTemplate(buildRhythmsPrintSheets()); return true; }
    if (target === 'homecoming') { openCovenantPrintTemplate(buildHomecomingPrintSheets()); return true; }
    if (target === 'packets') {
      openCovenantPrintTemplate(buildPacketsPrintSheets());
      return true;
    }
    if (typeof reg[target] === 'function') {
      openCovenantPrintTemplate(reg[target]());
      return true;
    }
  } catch (err) {
    if (typeof console !== 'undefined') console.error('Covenant print template failed:', err);
  }
  return false;
}

// Small helpers shared by print templates.
function pvMoney(v){ const n = _cNum(v); return '$' + n.toLocaleString('en-US', { maximumFractionDigits: 0 }); }
function pvDate(str){
  const d = _cDate(str);
  return d ? d.toLocaleDateString('en-US', { weekday:'long', year:'numeric', month:'long', day:'numeric' }) : '';
}

/* ── Track 3 — print/PDF templates (place cards, menu, program, labels) ── */
function _pvCoupleSub(){ const s = data.setup || {}; return [s.bride, s.groom].filter(Boolean).join(' & '); }
function _pvAttendingGuests(){
  return safeArray(data.guests).filter(g => !/^(no|declined|regret)/i.test(String(g.rsvp || '')) && (g.name || '').trim());
}
function openPlaceCards(guestList){
  const esc = escapeHtml;
  const guests = Array.isArray(guestList) ? guestList.filter(g => g && String(g.name || '').trim()) : _pvAttendingGuests();
  if (!guests.length){ covAlert(Array.isArray(guestList) ? 'Select attending guests to print place cards.' : 'Add guests to your list first — place cards use attending guests.'); return; }
  const cards = guests.map(g => {
    const table = g.table ? (typeof tableLabel === 'function' ? tableLabel(g.table) : ('Table ' + g.table)) : '';
    return `<div class="pv-card"><div style="font-size:20px;color:var(--pv-accent);font-family:Georgia,serif">${esc(g.name)}</div>${table ? `<div class="pv-note" style="margin-top:6px">${esc(table)}</div>` : ''}</div>`;
  }).join('');
  openPrintView('Place Cards', `<div class="pv-cards">${cards}</div>`, { subtitle: _pvCoupleSub(), accent: '#2D4A3E' });
}
function openMenuCard(){
  const esc = escapeHtml;
  const menu = safeArray(data.menu).map(r => (typeof normalizeMenuRow === 'function' ? normalizeMenuRow(r) : r)).filter(r => (r.dish || r.item));
  if (!menu.length){ covAlert('Add menu items on the Catering page first.'); return; }
  const order = ['appetizer','starter','hors','salad','soup','main','entrée','entree','side','dessert','late'];
  const byCourse = {};
  menu.forEach(r => { const c = r.course || 'Other'; (byCourse[c] = byCourse[c] || []).push(r); });
  const rank = name => { const l = String(name).toLowerCase(); const i = order.findIndex(o => l.startsWith(o)); return i < 0 ? 90 : i; };
  const courses = Object.keys(byCourse).sort((a,b) => rank(a) - rank(b));
  let html = '<div style="text-align:center">';
  courses.forEach(c => {
    html += `<h2 class="pv-section" style="border:0;text-align:center;letter-spacing:2px;text-transform:uppercase;font-size:12px;color:var(--pv-accent)">${esc(c)}</h2>`;
    byCourse[c].forEach(r => { html += `<div style="margin:2px 0 14px"><div style="font-size:16px;font-family:Georgia,serif">${esc(r.dish || r.item || '')}</div>${r.dietary ? `<div class="pv-note">${esc(r.dietary)}</div>` : ''}</div>`; });
  });
  html += '</div>';
  openPrintView('Wedding Menu', html, { subtitle: _pvCoupleSub(), accent: '#5A6F55' });
}
function openCeremonyProgram(){
  const esc = escapeHtml;
  const s = data.setup || {};
  const section = (title, rows) => rows.length ? `<h2 class="pv-section" style="text-align:center;border:0;letter-spacing:1px">${esc(title)}</h2>` + rows.join('') : '';
  const proc = safeArray(data.ceremonyProcessional).filter(r => r.name).map(r => `<div style="text-align:center;margin:3px 0">${esc(r.name)}${r.role ? ` — <em>${esc(r.role)}</em>` : ''}</div>`);
  const ordr = safeArray(data.ceremonyOrder).filter(r => r.moment || r.step).map(r => `<div style="text-align:center;margin:3px 0">${esc(r.moment || r.step)}${r.person ? ` — <em>${esc(r.person)}</em>` : ''}</div>`);
  const reads = safeArray(data.scriptures).filter(r => r.passage).map(r => `<div style="text-align:center;margin:3px 0">${esc(r.passage)}${r.reader ? ` — <em>${esc(r.reader)}</em>` : ''}${r.translation ? ` <small>(${esc(r.translation)})</small>` : ''}</div>`);
  const rec = safeArray(data.ceremonyRecessional).filter(r => r.name).map(r => `<div style="text-align:center;margin:3px 0">${esc(r.name)}${r.role ? ` — <em>${esc(r.role)}</em>` : ''}</div>`);
  if (!proc.length && !ordr.length && !reads.length && !rec.length){ covAlert('Add ceremony details (order of service, processional, or scriptures) first.'); return; }
  let html = '';
  if (s.date || s['venue-ceremony']) html += `<p style="text-align:center" class="pv-note">${esc(pvDate(s.date))}${s['venue-ceremony'] ? ' · ' + esc(s['venue-ceremony']) : ''}</p>`;
  html += section('Processional', proc) + section('Order of Service', ordr) + section('Scripture Readings', reads) + section('Recessional', rec);
  openPrintView('Ceremony Program', html, { subtitle: _pvCoupleSub(), accent: '#2D4A3E' });
}
function guestAddressLines(g){
  if (!g) return [];
  const lines = [];
  const a1 = String(g.address1 || g.address || '').trim();
  const a2 = String(g.address2 || '').trim();
  if (a1) lines.push(a1);
  if (a2) lines.push(a2);
  const cityLine = [g.city, g.state, g.zip].map(v => String(v || '').trim()).filter(Boolean).join(', ');
  if (cityLine) lines.push(cityLine);
  const country = String(g.country || '').trim();
  if (country) lines.push(country);
  return lines;
}
function openAddressLabels(householdMode){
  const esc = escapeHtml;
  const withAddr = safeArray(data.guests).filter(g =>
    (typeof guestHasAddress === 'function' ? guestHasAddress(g) : !!(g.address || g.address1 || g.city || g.zip)));
  if (!withAddr.length){ covAlert('No guest addresses on file yet. Add addresses on the Guest List first.'); return; }
  let rows = withAddr;
  if (householdMode) {
    const seen = new Set();
    rows = [];
    withAddr.forEach(g => {
      const key = String(g.household || g.name || g._id || '').trim().toLowerCase();
      if (seen.has(key)) return;
      seen.add(key);
      rows.push(g);
    });
  }
  const labels = rows.map(g => {
    const title = householdMode
      ? (String(g.household || '').trim() || g.name || 'Household')
      : (g.name || '');
    const body = guestAddressLines(g).map(l => esc(l)).join('<br>');
    return `<div class="pv-label"><strong>${esc(title)}</strong>${body ? '<br>' + body : ''}</div>`;
  }).join('');
  openPrintView(householdMode ? 'Household Address List' : 'Address Labels', `<div class="pv-labels">${labels}</div>`, { subtitle: _pvCoupleSub(), accent: '#3E5870' });
}
function exportAddressCSV(){
  const rows = safeArray(data.guests).filter(g => (g.name || '').trim());
  if (!rows.length){ if (typeof showToast === 'function') showToast('No guests to export yet.', 'warn'); return; }
  const cell = v => { const str = String(v == null ? '' : v).replace(/"/g, '""'); return /[",\n]/.test(str) ? `"${str}"` : str; };
  const header = ['Name','Household','Address 1','Address 2','City','State','Zip','Country','Email','Phone','Has address'];
  const lines = [header.join(',')].concat(rows.map(g => {
    const has = typeof guestHasAddress === 'function' ? guestHasAddress(g) : !!(g.address || g.address1);
    return [g.name, g.household, g.address1 || g.address || '', g.address2 || '', g.city || '', g.state || '', g.zip || '', g.country || '', g.email, g.phone, has ? 'Yes' : 'No'].map(cell).join(',');
  }));
  const csv = '\ufeff' + lines.join('\n');
  const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'guest-addresses-' + new Date().toISOString().split('T')[0] + '.csv';
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
  if (typeof showToast === 'function') showToast('Guest addresses exported as CSV.');
}


function isTypingInputEvent() {
  const evt = window.event;
  if (!evt || evt.type !== 'input') return false;
  const el = evt.target || document.activeElement;
  if (!el || !el.matches) return false;
  return el.matches('textarea, input:not([type="checkbox"]):not([type="radio"]):not([type="file"]):not([type="color"]):not([type="range"])');
}
function renderWhenInputComplete(renderFn) {
  const evt = window.event;
  if (isTypingInputEvent()) {
    const el = evt.target || document.activeElement;
    if (el && !el.dataset.renderWhenTypingDone) {
      el.dataset.renderWhenTypingDone = '1';
      el.addEventListener('blur', () => {
        delete el.dataset.renderWhenTypingDone;
        if (typeof renderFn === 'function') renderFn();
      }, { once:true });
    }
    return;
  }
  if (typeof renderFn === 'function') renderFn();
}

/* ════════════════════════════════════════════════
   PLANNER HISTORY, UNDO, AND REDO
════════════════════════════════════════════════ */
const HISTORY_SNAPSHOT_LIMIT = 15;
/* Readable change log capacity (All.dc 18b). Undo snapshots stay at 15. */
const HISTORY_LOG_LIMIT = 200;
const HISTORY_GROUP_MS = 3000;
/* _recordHistory belongs here for the same reason the others do: it is a
   record OF changes, not a change. Left out, every per-record history write
   would itself register as a data change — creating an undo step and a
   "_recordHistory: updated" log line, which then writes more history. */
const HISTORY_META_KEYS = new Set(['_historyLog','_undoSnapshots','_redoSnapshots','_historyPrefs','_recordHistory']);
let HISTORY_BASE_SNAPSHOT = '';
let HISTORY_SUSPENDED = false;
let HISTORY_TRACKING_READY = false;

function normalizeHistoryState() {
  if (!Array.isArray(data._historyLog)) data._historyLog = [];
  if (!Array.isArray(data._undoSnapshots)) data._undoSnapshots = [];
  if (!Array.isArray(data._redoSnapshots)) data._redoSnapshots = [];
  if (!data._historyPrefs || typeof data._historyPrefs !== 'object') data._historyPrefs = {};
  if (!data._recordHistory || typeof data._recordHistory !== 'object' || Array.isArray(data._recordHistory)) data._recordHistory = {};
}
function historyCloneWithoutMeta(value) {
  if (Array.isArray(value)) return value.map(historyCloneWithoutMeta);
  if (value && typeof value === 'object') {
    const out = {};
    Object.keys(value).forEach(key => {
      if (!HISTORY_META_KEYS.has(key)) out[key] = historyCloneWithoutMeta(value[key]);
    });
    return out;
  }
  return value;
}
function historySnapshotString(source = data) {
  return JSON.stringify(historyCloneWithoutMeta(source));
}
function initializeHistoryTracking() {
  normalizeHistoryState();
  HISTORY_BASE_SNAPSHOT = historySnapshotString();
  HISTORY_TRACKING_READY = true;
  updateHistoryControls();
}
function historyTodayISO() {
  const d = new Date();
  const offset = d.getTimezoneOffset();
  return new Date(d.getTime() - offset * 60000).toISOString().slice(0,10);
}
function historyPanelId() {
  return document.body?.getAttribute('data-active-panel') || document.querySelector('.panel.active')?.id?.replace('panel-', '') || 'planner';
}
function historyPanelLabel(id = historyPanelId()) {
  const labels = {
    instructions:'Get Started', faq:'FAQ', history:'Planner History', dashboard:'Dashboard', setup:'Wedding Setup', 'data-hub':'Database Hub',
    budget:'Budget', payments:'Payments', vendors:'Venue & Vendors', guests:'Guest List', tasks:'Planning Timeline',
    calendar:'Smart Calendar', appointments:'Appointments', notes:'Notes', contracts:'Contracts, Invoices & Rentals',
    venue:'Venue & Vendors', catering:'Catering & Menu', party:'Wedding Party', tables:'Table Layout',
    ceremony:'Ceremony & Reception', timeline:'Wedding Day Timeline', entertainment:'Music & Speeches', shotlist:'Photo & Video Shot Lists',
    mood:'Vision Board', essentials:'Essentials Checklist', gifts:'Gift Log', honeymoon:'Honeymoon',
    prayer:'Prayer Journal', counseling:'Premarital Counseling'
  };
  return labels[id] || id.replace(/[-_]/g, ' ').replace(/\b\w/g, ch => ch.toUpperCase());
}
function historySectionLabel(section) {
  const labels = {
    setup:'Wedding Setup', budget:'Budget', payments:'Payments', vendors:'Vendors', guests:'Guest List',
    tasks:'Tasks', appointments:'Appointments', calendarEvents:'Smart Calendar', timeline:'Wedding Day Timeline',
    ceremony:'Ceremony & Reception', ceremonyOrder:'Ceremony Order', ceremonyProcessional:'Processional Order',
    ceremonyRecessional:'Recessional Order', ceremonyChecklist:'Ceremony Notes', scriptures:'Scripture & Prayer',
    prayer:'Prayer Journal', counseling:'Premarital Counseling', notes:'Notes', party:'Wedding Party',
    tables:'Table Layout', gifts:'Gift Log', shotlist:'Photo & Video Shot Lists', recSongs:'Reception Music Cues',
    recMoments:'Special Dances', speeches:'Speeches & Toasts', menu:'Menu', beverages:'Beverages',
    kidsMenu:'Kids Menu', placeSettings:'Place Settings', cateringRentals:'Catering Rentals',
    cateringMeta:'Catering Settings', venue:'Wedding Venue', vtimeline:'Vendor Arrival Timeline',
    essentials:'Essentials Checklist', plan:'Planning Timeline', entertainment:'Entertainment Details',
    mustPlay:'Must-Play Songs', doNotPlay:'Do-Not-Play Songs', receptionPlaylist:'Reception Playlist',
    palettes:'Color Palettes', moodPhotos:'Vision Photos', moodFavorites:'Vision Favorites', moodItems:'Vision Board Details',
    honeymoon:'Honeymoon Details', honeyItinerary:'Honeymoon Itinerary', packing:'Honeymoon Packing',
    nameChange:'Name Change Checklist', honeyDetails:'Honeymoon Details', honeyTransport:'Honeymoon Transportation',
    contracts:'Contracts, Invoices & Rentals', rentals:'Rentals', weekendTimeline:'Wedding Weekend Timeline',
    travelAccommodations:'Travel & Accommodations', hotelBlocks:'Hotel Room Blocks',
    transportation:'Transportation', vipCare:'Family & VIP Care'
  };
  return labels[section] || historyPanelLabel(section);
}
function historySummarizeChange(beforeText, afterText) {
  let before = {};
  let after = {};
  try { before = beforeText ? JSON.parse(beforeText) : {}; } catch(e) { before = {}; }
  try { after = afterText ? JSON.parse(afterText) : {}; } catch(e) { after = {}; }
  const keys = Array.from(new Set([...Object.keys(before), ...Object.keys(after)])).filter(k => !HISTORY_META_KEYS.has(k));
  const changed = [];
  keys.forEach(key => {
    const oldVal = before[key];
    const newVal = after[key];
    const oldText = JSON.stringify(oldVal ?? null);
    const newText = JSON.stringify(newVal ?? null);
    if (oldText === newText) return;
    let detail = historySectionLabel(key);
    if (Array.isArray(oldVal) || Array.isArray(newVal)) {
      const oldLen = Array.isArray(oldVal) ? oldVal.length : 0;
      const newLen = Array.isArray(newVal) ? newVal.length : 0;
      const diff = newLen - oldLen;
      if (diff > 0) detail += `: ${diff} item${diff === 1 ? '' : 's'} added`;
      else if (diff < 0) detail += `: ${Math.abs(diff)} item${Math.abs(diff) === 1 ? '' : 's'} removed`;
      else detail += ': updated';
    } else {
      detail += ': updated';
    }
    changed.push({ key, detail });
  });
  if (!changed.length) return null;
  const page = historyPanelLabel();
  const visible = changed.slice(0,4).map(item => item.detail).join('; ');
  const extra = changed.length > 4 ? `; plus ${changed.length - 4} more section${changed.length - 4 === 1 ? '' : 's'}` : '';
  const primary = changed[0] ? historySectionLabel(changed[0].key) : page;
  const fieldCount = changed.length;
  const changeTitle = fieldCount === 1
    ? `Changed 1 field on ${primary}`
    : `Changed ${fieldCount} fields on ${primary}`;
  const fields = changed.slice(0, 6).map(item => {
    const m = String(item.detail || '').match(/^([^:]+):\s*(.*)$/);
    return { label: m ? m[1].trim() : historySectionLabel(item.key), from: '', to: m ? m[2].trim() : (item.detail || 'updated') };
  });
  const who = (() => {
    const bride = String((data.setup && data.setup.bride) || '').trim();
    return bride ? bride.split(/\s+/)[0] : 'You';
  })();
  return {
    source: page,
    action: changeTitle,
    change: changeTitle,
    record: page + (primary && primary !== page ? ' · ' + primary : ''),
    who,
    fields,
    details: visible + extra,
    groupKey: page + '|' + changed.map(item => item.key).join(',')
  };
}
function recordPlannerHistory() {
  normalizeHistoryState();
  if (HISTORY_SUSPENDED || !HISTORY_TRACKING_READY) return;
  const nextSnapshot = historySnapshotString();
  if (!HISTORY_BASE_SNAPSHOT) {
    HISTORY_BASE_SNAPSHOT = nextSnapshot;
    return;
  }
  if (nextSnapshot === HISTORY_BASE_SNAPSHOT) return;
  const summary = historySummarizeChange(HISTORY_BASE_SNAPSHOT, nextSnapshot);
  if (!summary) {
    HISTORY_BASE_SNAPSHOT = nextSnapshot;
    return;
  }
  const now = new Date();
  const stamp = now.toISOString();
  const last = data._historyLog[0];
  const isGrouped = last && last.groupKey === summary.groupKey && (now - new Date(last.iso)) < HISTORY_GROUP_MS && isTypingInputEvent();
  if (isGrouped) {
    last.iso = stamp;
    last.date = historyTodayISO();
    last.time = now.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'});
    last.details = summary.details;
    last.action = summary.action;
    last.change = summary.change || summary.action;
    last.record = summary.record || summary.source;
    last.fields = summary.fields || last.fields;
  } else {
    data._undoSnapshots.unshift(HISTORY_BASE_SNAPSHOT);
    data._undoSnapshots = data._undoSnapshots.slice(0, HISTORY_SNAPSHOT_LIMIT);
    data._redoSnapshots = [];
    data._historyLog.unshift({
      id: 'h' + Date.now() + Math.random().toString(16).slice(2),
      iso: stamp,
      date: historyTodayISO(),
      time: now.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}),
      source: summary.source,
      action: summary.action,
      change: summary.change || summary.action,
      record: summary.record || summary.source,
      who: summary.who || 'You',
      fields: summary.fields || [],
      details: summary.details,
      groupKey: summary.groupKey,
      hasSnapshot: true
    });
    data._historyLog = data._historyLog.slice(0, HISTORY_LOG_LIMIT);
  }
  HISTORY_BASE_SNAPSHOT = nextSnapshot;
  updateHistoryControls();
  if (document.body?.getAttribute('data-active-panel') === 'history' && typeof renderHistoryRd === 'function') {
    renderWhenInputComplete(renderHistoryRd);
  }
}
function saveHistorySilent() {
  normalizeHistoryState();
  localStorage.setItem(profileDataKey(activeProfile), JSON.stringify(data));
  if (typeof syncCurrentDataToSqlite === 'function') syncCurrentDataToSqlite();
  const now = new Date();
  const el = document.getElementById('last-saved');
  if (el) el.textContent = 'Saved on this device ' + now.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});
  const warn = document.getElementById('storage-warning');
  if (warn) warn.classList.remove('visible');
  if (typeof placeNavigationBelowTopbar === 'function') placeNavigationBelowTopbar();
}
function applyHistorySnapshot(snapshot, direction) {
  normalizeHistoryState();
  let restored;
  try { restored = JSON.parse(snapshot); } catch(e) { covAlert('That history snapshot could not be restored.'); return; }
  const log = data._historyLog || [];
  const undo = data._undoSnapshots || [];
  const redo = data._redoSnapshots || [];
  /* Snapshots are stripped of meta keys, so the restored object carries no
     _recordHistory. Carry it across or undo would erase the record trail. */
  const recHist = data._recordHistory || {};
  data = { ...blankData(), ...restored };
  data._historyLog = log;
  data._undoSnapshots = undo;
  data._redoSnapshots = redo;
  data._recordHistory = recHist;
  addHistorySystemEntry(direction, direction === 'Undo' ? 'Restored the previous planner snapshot.' : 'Re-applied the next planner snapshot.');
  HISTORY_SUSPENDED = true;
  try { saveHistorySilent(); } finally { HISTORY_SUSPENDED = false; }
  initializeHistoryTracking();
  initAll();
  const activePanel = document.body.getAttribute('data-active-panel') || 'dashboard';
  showPanel(activePanel);
}
function addHistorySystemEntry(action, details) {
  normalizeHistoryState();
  const now = new Date();
  data._historyLog.unshift({
    id: 'h' + Date.now() + Math.random().toString(16).slice(2),
    iso: now.toISOString(),
    date: historyTodayISO(),
    time: now.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit'}),
    source: 'Planner History',
    action,
    change: action,
    record: 'Planner History',
    who: 'You',
    fields: [],
    details,
    groupKey: 'system|' + action,
    hasSnapshot: false
  });
  data._historyLog = data._historyLog.slice(0, HISTORY_LOG_LIMIT);
}
function undoPlannerChange() {
  normalizeHistoryState();
  if (!data._undoSnapshots.length) return;
  const currentSnapshot = historySnapshotString();
  const previousSnapshot = data._undoSnapshots.shift();
  data._redoSnapshots.unshift(currentSnapshot);
  data._redoSnapshots = data._redoSnapshots.slice(0, HISTORY_SNAPSHOT_LIMIT);
  applyHistorySnapshot(previousSnapshot, 'Undo');
}
function redoPlannerChange() {
  normalizeHistoryState();
  if (!data._redoSnapshots.length) return;
  const currentSnapshot = historySnapshotString();
  const nextSnapshot = data._redoSnapshots.shift();
  data._undoSnapshots.unshift(currentSnapshot);
  data._undoSnapshots = data._undoSnapshots.slice(0, HISTORY_SNAPSHOT_LIMIT);
  applyHistorySnapshot(nextSnapshot, 'Redo');
}
function updateHistoryControls() {
  if (!data) return;
  normalizeHistoryState();
  const undoDisabled = data._undoSnapshots.length === 0;
  const redoDisabled = data._redoSnapshots.length === 0;
  ['undo-btn','history-undo-btn','drawer-undo-btn'].forEach(id => { const el = document.getElementById(id); if (el) el.disabled = undoDisabled; });
  ['redo-btn','history-redo-btn','drawer-redo-btn'].forEach(id => { const el = document.getElementById(id); if (el) el.disabled = redoDisabled; });
  const ids = {
    'history-stat-total': data._historyLog.length,
    'history-stat-undo': data._undoSnapshots.length,
    'history-stat-redo': data._redoSnapshots.length
  };
  Object.entries(ids).forEach(([id, value]) => { const el = document.getElementById(id); if (el) el.textContent = value; });
}
function renderHistoryPage() {
  normalizeHistoryState();
  const dateInput = document.getElementById('history-date-filter');
  if (dateInput && !dateInput.value) dateInput.value = data._historyPrefs.selectedDate || data._historyLog[0]?.date || historyTodayISO();
  const selectedDate = dateInput?.value || historyTodayISO();
  data._historyPrefs.selectedDate = selectedDate;
  const rows = data._historyLog.filter(item => item.date === selectedDate);
  const body = document.getElementById('history-log-body');
  if (body) {
    body.innerHTML = rows.length ? rows.map(item => `<tr>
      <td>${escapeHtml(item.time || '')}</td>
      <td>${escapeHtml(item.source || 'Planner')}</td>
      <td><span class="history-badge">${escapeHtml(item.action || 'Updated Planner')}</span></td>
      <td>${escapeHtml(item.details || '')}</td>
    </tr>`).join('') : `<tr><td colspan="4"><div class="history-empty">No changes were recorded for this date.</div></td></tr>`;
  }
  const title = document.getElementById('history-table-title');
  if (title) title.textContent = `Changes for ${selectedDate}`;
  const dayStat = document.getElementById('history-stat-day');
  if (dayStat) dayStat.textContent = rows.length;
  updateHistoryControls();
  renderHistoryDrawer();
}
function renderHistoryDrawer() {
  normalizeHistoryState();
  const body = document.getElementById('history-drawer-body');
  if (!body) return;
  const recent = data._historyLog.slice(0,20);
  body.innerHTML = recent.length ? recent.map(item => `<div class="history-drawer-item">
    <div class="history-drawer-time">${escapeHtml(item.date || '')} • ${escapeHtml(item.time || '')}</div>
    <div class="history-drawer-action">${escapeHtml(item.action || 'Updated Planner')}</div>
    <div class="history-drawer-detail">${escapeHtml(item.details || '')}</div>
  </div>`).join('') : '<div class="history-empty">No history has been recorded yet.</div>';
}
function openHistoryDrawer() {
  renderHistoryDrawer();
  updateHistoryControls();
  document.getElementById('history-drawer')?.classList.add('open');
}
function closeHistoryDrawer() {
  document.getElementById('history-drawer')?.classList.remove('open');
}
function openProfileDrawer() {
  const drawer = document.getElementById('profile-drawer');
  const scrim = document.getElementById('profile-drawer-scrim');
  const btn = document.getElementById('profile-drawer-btn');
  drawer?.classList.add('open');
  drawer?.setAttribute('aria-hidden', 'false');
  scrim?.classList.add('visible');
  scrim?.setAttribute('aria-hidden', 'false');
  btn?.setAttribute('aria-expanded', 'true');
  document.body.classList.add('profile-drawer-open');
  if (typeof renderProfileDrawerPhoto === 'function') renderProfileDrawerPhoto();
  if (typeof renderTemplatesGalleryHosts === 'function') renderTemplatesGalleryHosts();
  if (typeof loadAppearance === 'function') loadAppearance();
}
function closeProfileDrawer() {
  const drawer = document.getElementById('profile-drawer');
  const scrim = document.getElementById('profile-drawer-scrim');
  const btn = document.getElementById('profile-drawer-btn');
  drawer?.classList.remove('open');
  drawer?.setAttribute('aria-hidden', 'true');
  scrim?.classList.remove('visible');
  scrim?.setAttribute('aria-hidden', 'true');
  btn?.setAttribute('aria-expanded', 'false');
  document.body.classList.remove('profile-drawer-open');
  closeThemePicker();
  if (typeof closeFontPicker === 'function') closeFontPicker();
}
function toggleProfileDrawer() {
  const drawer = document.getElementById('profile-drawer');
  if (drawer?.classList.contains('open')) closeProfileDrawer();
  else openProfileDrawer();
}
document.addEventListener('keydown', function(e){
  if (e.key !== 'Escape') return;
  if (document.getElementById('nav-menu-drawer')?.classList.contains('open')) { closeNavMenuDrawer(); return; }
  if (document.getElementById('profile-drawer')?.classList.contains('open')) closeProfileDrawer();
});
async function clearPlannerHistory() {
  if (!(await covConfirm('Clear the visible History log and Undo/Redo snapshots? This cannot be undone.', {title:'Clear history?', danger:true, okText:'Clear'}))) return;
  if (!(await covConfirm('This removes the saved history record for privacy and file-size control, but it will not delete your planner content. Clear it now?', {title:'Clear history?', danger:true, okText:'Clear'}))) return;
  normalizeHistoryState();
  data._historyLog = [];
  data._undoSnapshots = [];
  data._redoSnapshots = [];
  data._historyPrefs = {};
  HISTORY_BASE_SNAPSHOT = historySnapshotString();
  HISTORY_SUSPENDED = true;
  try { saveHistorySilent(); } finally { HISTORY_SUSPENDED = false; }
  if (typeof renderHistoryRd === 'function') renderHistoryRd();
  else renderHistoryPage();
  renderHistoryDrawer();
  updateHistoryControls();
}
window.undoLastChange = undoPlannerChange;
window.redoLastChange = redoPlannerChange;

/* ── Track 4 / Phase B — SQLite write-through ──
   After every JSON/localStorage save, mirror the current `data` into the live
   SQLite database so the .sqlite export always reflects current data (no more
   write-once drift). The in-memory rebuild is synchronous and fast; the heavier
   IndexedDB write is debounced. Fully guarded: any SQLite failure is logged and
   NEVER interferes with the localStorage/JSON save (which stays the source of
   truth this phase). `_sqliteBootProfile` tracks which profile has been
   opened/hydrated so boot-time hydration runs once per profile. */
let _sqliteBootProfile = null;
let _sqliteSyncTimer = null;
// Captured at the START of load() (before seedDefaults()/save() can recreate the
// localStorage key) so the SQLite boot block can reliably tell whether the
// profile's JSON was actually missing at page load — the trigger for recovery
// hydration from a populated SQLite DB. null = not yet captured.
let _jsonExistedAtStartup = null;
// Write-through is OFF until the SQLite boot/hydration decision completes. This
// prevents boot-time saves (e.g. seedDefaults() on a JSON-less reload) from
// clobbering a populated recovery DB before hydration has had a chance to run.
let _sqliteSyncSuppressed = true;
// Immediate in-memory rebuild + debounced IndexedDB persist. Returns true if it
// actually synced. `flushSqliteSync()` (below) forces a pending sync before an
// export so a downloaded .sqlite always reflects the very latest edit.
function _doSqliteSync() {
  try {
    if (_sqliteSyncSuppressed) return false; // suppressed during SQLite boot/hydration window
    if (typeof COVENANT_SQLITE === 'undefined' || !COVENANT_SQLITE.enabled) return false;
    if (!COVENANT_SQLITE.db || COVENANT_SQLITE.profileId !== activeProfile) return false; // db not ready / mid profile-switch
    if (typeof syncDataToSqlite !== 'function') return false;
    syncDataToSqlite(data, COVENANT_SQLITE.db);   // rebuild managed tables from `data` (delete-then-insert)
    if (typeof window !== 'undefined' && window.DBRepo && typeof DBRepo.schedulePersist === 'function') {
      DBRepo.schedulePersist();                    // debounced IndexedDB persist
    } else if (typeof persistDbToIndexedDB === 'function') {
      persistDbToIndexedDB(COVENANT_SQLITE.profileId, COVENANT_SQLITE.db).catch(e => console.warn('[SQLite] persist failed', e));
    }
    return true;
  } catch (e) {
    console.warn('[SQLite] write-through sync failed; localStorage/JSON is unaffected.', e);
    return false;
  }
}
// Called from save()/saveHistorySilent(): coalesce a burst of saves (e.g. typing)
// into a single SQLite rebuild. Guarded so it can never break the JSON save.
function syncCurrentDataToSqlite() {
  if (typeof COVENANT_SQLITE === 'undefined' || !COVENANT_SQLITE.enabled) return;
  if (_sqliteSyncTimer) clearTimeout(_sqliteSyncTimer);
  _sqliteSyncTimer = setTimeout(() => { _sqliteSyncTimer = null; _doSqliteSync(); }, 250);
}
// Force any pending write-through immediately (used before a .sqlite export).
function flushSqliteSync() {
  if (_sqliteSyncTimer) { clearTimeout(_sqliteSyncTimer); _sqliteSyncTimer = null; }
  return _doSqliteSync();
}
// Gate user-facing .sqlite backup until boot completes for the active profile.
function sqliteBackupReady() {
  if (typeof COVENANT_SQLITE === 'undefined' || !COVENANT_SQLITE.enabled) return false;
  if (!COVENANT_SQLITE.db || COVENANT_SQLITE.profileId !== activeProfile) return false;
  if (_sqliteSyncSuppressed) return false;
  return true;
}

function save() {
  const warn = document.getElementById('storage-warning');
  try {
    ensurePlannerRecordModel();
    recordPlannerHistory();
    data.schemaVersion = CURRENT_SCHEMA_VERSION;
    data.updatedAt = new Date().toISOString();
    if (!_suppressEditCount) {
      if (!data.onboard || typeof data.onboard !== 'object') data.onboard = {};
      data.onboard.editsSinceBackup = (data.onboard.editsSinceBackup || 0) + 1;
    }
    localStorage.setItem(profileDataKey(activeProfile), JSON.stringify(data));
    syncCurrentDataToSqlite();
    const now = new Date();
    const el = document.getElementById('last-saved');
    const savedText = 'Saved on this device ' + now.toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});
    if (el) el.textContent = savedText;
    const footerSave = document.getElementById('footer-save-status');
    if (footerSave) footerSave.textContent = savedText;
    if (warn) warn.classList.remove('visible');
    if (typeof placeNavigationBelowTopbar === 'function') placeNavigationBelowTopbar();
    if (document.body?.getAttribute('data-active-panel') === 'calendar' && typeof renderSmartCalendar === 'function') renderWhenInputComplete(renderSmartCalendar);
    if (document.body?.getAttribute('data-active-panel') === 'catering' && typeof renderCateringStats === 'function') renderWhenInputComplete(renderCateringStats);
    if (document.body?.getAttribute('data-active-panel') === 'history') renderWhenInputComplete(renderHistoryPage);
    renderHistoryDrawer();
    updateHistoryControls();
    updateSectionProgress();
    if (typeof updateTopbarNotificationsBell === 'function') updateTopbarNotificationsBell();
    plannerDirty = false;
    if (typeof uxSavedFlashOnSave === 'function') uxSavedFlashOnSave();
  } catch(e) {
    console.warn('Save error', e);
    if (e.name === 'QuotaExceededError' || (e.code && e.code === 22)) {
      if (warn) warn.classList.add('visible');
      if (typeof placeNavigationBelowTopbar === 'function') placeNavigationBelowTopbar();
    }
  }
}

