const DATABASE_HUB_LABEL = 'Database Hub';
function databaseHubCategoryTitle(catLabel, tableLabel){
  if (tableLabel) return `${catLabel} ${DATABASE_HUB_LABEL} — ${tableLabel}`;
  return catLabel ? `${catLabel} ${DATABASE_HUB_LABEL}` : DATABASE_HUB_LABEL;
}
function dataHubCategoryForTableKey(tableKey){
  for (const [catId, cat] of Object.entries(DATA_HUB_REGISTRY)) {
    if (cat.tables.some(t => (t.key || (t.custom === 'budget' ? 'budgetHub' : '')) === tableKey)) return catId;
  }
  return null;
}
function systemAllNavPageIds(){
  const ids = new Set();
  NAV_CATEGORIES.forEach(cat => safeArray(cat.pages).forEach(page => {
    if (page && page.id) ids.add(page.id === 'plan' ? 'tasks' : page.id);
  }));
  ids.add('data-hub');
  return [...ids].filter(id => id !== 'ui-system');
}
function systemHubForTableKey(tableKey){
  return dataHubCategoryForTableKey(tableKey) || 'none';
}
function getSystemBulkActionRegistry(){
  const tables = (window.CWP && window.CWP.TABLES) || {};
  const out = {};
  Object.keys(tables).forEach(key => {
    const table = tables[key] || {};
    const bulk = table.bulk || {};
    const enabled = bulk.enabled !== false;
    const page = Object.values(SYSTEM_PAGE_REGISTRY).find(p => safeArray(p.tableKeys).includes(key));
    out[key] = {
      key,
      entity: table.entity || '',
      pageId: page ? page.id : '',
      hub: systemHubForTableKey(key),
      mode: enabled ? ((page && page.bulkMode) || 'shared') : 'disabled',
      actions: enabled ? safeArray(bulk.actions && bulk.actions.length ? bulk.actions : ['edit','delete']) : [],
      reason: enabled ? '' : (SYSTEM_BULK_EXCEPTIONS[key] || 'Bulk disabled by CWP descriptor; document the product reason before standardizing.')
    };
  });
  return out;
}
function verifySystemConsistency(showDialog){
  const navIds = systemAllNavPageIds();
  const missingPages = navIds.filter(id => !SYSTEM_PAGE_REGISTRY[id]);
  const registryPagesWithoutPanel = Object.keys(SYSTEM_PAGE_REGISTRY).filter(id => id !== 'data-hub' && !document.getElementById('panel-' + id));
  const bulkRegistry = getSystemBulkActionRegistry();
  const tableKeys = window.CWP && window.CWP.TABLES ? Object.keys(window.CWP.TABLES) : [];
  const missingBulk = tableKeys.filter(key => !bulkRegistry[key] || !bulkRegistry[key].mode);
  const tableWithoutPage = tableKeys.filter(key => {
    if (key === 'budgetItems') return false;
    return !Object.values(SYSTEM_PAGE_REGISTRY).some(page => {
      const keys = safeArray(page.tableKeys);
      return keys.includes(key) || keys.includes('*');
    });
  });
  const result = {
    ok: !missingPages.length && !registryPagesWithoutPanel.length && !missingBulk.length,
    missingPages,
    registryPagesWithoutPanel,
    missingBulk,
    tableWithoutPage,
    pageCount: Object.keys(SYSTEM_PAGE_REGISTRY).length,
    tableCount: tableKeys.length
  };
  if (!result.ok || tableWithoutPage.length) console.warn('[System consistency]', result);
  if (showDialog) {
    const lines = [
      result.ok ? 'System registry check passed.' : 'System registry check needs attention.',
      'Registered pages: ' + result.pageCount,
      'CWP tables: ' + result.tableCount,
      'Missing page registry entries: ' + (missingPages.join(', ') || 'none'),
      'Registry entries without panels: ' + (registryPagesWithoutPanel.join(', ') || 'none'),
      'Missing bulk registry rows: ' + (missingBulk.join(', ') || 'none'),
      'Tables not assigned to a page: ' + (tableWithoutPage.join(', ') || 'none')
    ];
    if (typeof covAlert === 'function') covAlert(lines.join('\n'));
    else alert(lines.join('\n'));
  }
  return result;
}
window.SYSTEM_PAGE_REGISTRY = SYSTEM_PAGE_REGISTRY;
window.SYSTEM_STATUS_SEMANTICS = SYSTEM_STATUS_SEMANTICS;
window.getSystemBulkActionRegistry = getSystemBulkActionRegistry;
window.verifySystemConsistency = verifySystemConsistency;
function isCwpHubMount(mountId){
  return mountId === 'cwp-data-hub-active' || !!document.getElementById(mountId || '')?.closest('#panel-data-hub');
}
function guestCompanionsSummary(g){
  const comps = safeArray(g?.companions).filter(c => String(c?.name || c?.meal || '').trim());
  if (comps.length) return comps.map(c => c.name || 'Companion').join(', ');
  const parts = [];
  if (g?.plusone) parts.push('+1');
  const kids = parseInt(g?.children, 10);
  if (kids > 0) parts.push(kids + ' kid' + (kids === 1 ? '' : 's'));
  if (g?.family) parts.push('Family');
  return parts.length ? parts.join(' · ') : '—';
}
