/* Read-only preview cards: fold the header's "Read only" badge + Export/Edit
   actions into the table's own toolbar row (next to Search / Clear / Auto-fit),
   and hide the duplicate title (the table already renders its own header label). */
function cwpMergeReadOnlyHeaders(){
  var cards = document.querySelectorAll('.ued-table-card');
  for (var i = 0; i < cards.length; i++){
    var card = cards[i];
    var head = card.querySelector(':scope > .ued-table-head');
    var toolbar = card.querySelector('.cwp-toolbar');
    if (!head || !toolbar) continue;
    if (head.getAttribute('data-ro-merged') === '1' && toolbar.querySelector('[data-ro-merged]')) continue;
    var old = toolbar.querySelectorAll('[data-ro-merged]');
    for (var j = 0; j < old.length; j++) old[j].remove();
    head.style.removeProperty('display');
    head.removeAttribute('data-ro-hidden');
    var badge = head.querySelector('.ro-badge-inline');
    if (badge){ var bc = badge.cloneNode(true); bc.setAttribute('data-ro-merged','1'); toolbar.appendChild(bc); badge.remove(); }
    var actions = head.querySelector('.ued-actions');
    if (actions){
      var kids = actions.children;
      for (var k = 0; k < kids.length; k++){
        var c = kids[k].cloneNode(true);
        c.setAttribute('data-ro-merged','1');
        c.classList.add('cwp-btn');
        c.classList.remove('primary','ued-btn','ued-link','db-edit-btn');
        toolbar.appendChild(c);
      }
      actions.remove();
    }
    head.setAttribute('data-ro-merged','1');
  }
  if (typeof syncPlannerTableWidths === 'function') requestAnimationFrame(function(){ syncPlannerTableWidths(document); });
}
(function(){
  var pending = false;
  function schedule(){ if (pending) return; pending = true; setTimeout(function(){ pending = false; try { cwpMergeReadOnlyHeaders(); } catch(e){} }, 80); }
  if (window.MutationObserver){ try { new MutationObserver(schedule).observe(document.documentElement, { childList:true, subtree:true }); } catch(e){} }
  if (document.readyState !== 'loading') schedule(); else document.addEventListener('DOMContentLoaded', schedule);
})();
