const SIMPLE_MODE_HIDDEN_PAGES = ['logistics','contracts','venue','party','tables','shotlist','mood','honeymoon','packets','emails'];
const MENU_ALWAYS_VISIBLE_PAGES = ['prayer','instructions','dashboard','setup','data-hub'];
const MENU_EXCLUDED_PAGES = [];
const FOCUS_PRESETS = {
  full:     { label:'Full planner',       pages:null },
  planning: { label:'Planning core',      pages:['dashboard','tasks','plan','calendar','appointments','notes'] },
  guests:   { label:'Guests & seating',   pages:['dashboard','guests','party','tables','catering','emails'] },
  money:    { label:'Money',              pages:['dashboard','budget','payments','contracts'] },
  weekend:  { label:'Wedding weekend',    pages:['dashboard','timeline','ceremony','entertainment','logistics','catering','tables'] }
};
const ESSENTIALS_HUB_LINKS = [
  { id:'setup', label:'Wedding Setup', note:'Names, date & budget' },
  { id:'guests', label:'Guest List', note:'RSVPs & headcount' },
  { id:'budget', label:'Budget', note:'Spending & categories' },
  { id:'plan', label:'Planning Timeline', note:'Month-by-month steps' },
  { id:'calendar', label:'Smart Calendar', note:'Dates in one place' },
  { id:'tasks', label:'Tasks', note:'To-dos & deadlines' },
  { action:'startHereBackup()', label:'Download Backup', note:'Protect your work' }
];
const BLENDED_FAMILY_PROMPTS = {
  setup: {
    key:'setup',
    title:'Blessed are the peacemakers',
    body:'If you are blending two families, you are not alone. Wedding Setup is a gentle place to note family traditions, ceremony wishes, and anything your pastor should know.',
    optInLabel:'Yes, this applies to us'
  },
  guests: {
    key:'guests',
    title:'Planning with children from previous relationships?',
    body:'Consider separate guest groups, plus-one rules, or seating notes that honor every family with grace. The Side and Group fields on each guest can help you organize thoughtfully.',
    optInLabel:'Yes, this applies to us'
  },
  party: {
    key:'party',
    title:'Honoring everyone in your wedding party',
    body:'Blended families sometimes include step-parents, older children, or family friends in special roles. There is no one right answer — choose what feels loving and fair for your covenant day.',
    optInLabel:'Yes, this applies to us'
  },
  tables: {
    key:'tables',
    title:'Seating with blended families',
    body:'Mixed-family tables deserve extra care. Use table notes and VIP flags to seat parents, step-parents, and children thoughtfully. The Guest List table number field feeds this layout.',
    optInLabel:'Yes, this applies to us'
  }
};
function isSimpleModePageHidden(id){ return !!(data && data.setup && data.setup.simpleMode && SIMPLE_MODE_HIDDEN_PAGES.includes(id)); }
function isPlannerPageVisibleInMenu(id){
  if (!id) return false;
  if (MENU_EXCLUDED_PAGES.includes(id)) return false;
  if (MENU_ALWAYS_VISIBLE_PAGES.includes(id)) return true;
  return !(isSimpleModePageHidden(id) || getHiddenMenuPages().includes(id));
}
function navPanelIdFromButton(btn){
  const call = btn ? (btn.getAttribute('onclick') || '') : '';
  const match = call.match(/showPanel\((['"])([^'"]+)\1\)/);
  if (match) return match[2];
  if (/showReflectTabPage\(/.test(call) || /showNameChangePage\(/.test(call)) return 'reflect';
  if (/showWeddingSetup\(/.test(call)) return 'setup';
  return '';
}
function navLabelFromButton(btn){
  if (!btn) return '';
  const clone = btn.cloneNode(true);
  clone.querySelectorAll('svg,.nav-icon,.nav-prog').forEach(el => el.remove());
  return clone.textContent.replace(/\s+/g,' ').trim();
}
function getMenuVisibilityPages(){
  const seen = new Set();
  return Array.from(document.querySelectorAll('#sidebar .nav-item')).map(btn => {
    const id = navPanelIdFromButton(btn);
    const label = navLabelFromButton(btn);
    if (!id || seen.has(id) || MENU_EXCLUDED_PAGES.includes(id)) return null;
    seen.add(id);
    return { id, label };
  }).filter(Boolean);
}
function getHiddenMenuPages(){
  if (!data.setup) data.setup = {};
  if (!Array.isArray(data.setup.hiddenMenuPages)) data.setup.hiddenMenuPages = [];
  return data.setup.hiddenMenuPages;
}
function isMenuPageHidden(id){
  return !!(id && !isPlannerPageVisibleInMenu(id));
}
function applyMenuVisibility(){
  if (typeof applyProgressiveUnlock === 'function') applyProgressiveUnlock();
  document.querySelectorAll('#sidebar .nav-item').forEach(btn => {
    const id = navPanelIdFromButton(btn);
    if (!id) return;
    const customHidden = MENU_EXCLUDED_PAGES.includes(id) || (!MENU_ALWAYS_VISIBLE_PAGES.includes(id) && getHiddenMenuPages().includes(id));
    const simpleHidden = isSimpleModePageHidden(id);
    const hidden = !isPlannerPageVisibleInMenu(id);
    btn.classList.toggle('menu-hidden', customHidden);
    btn.classList.toggle('simple-hidden', simpleHidden);
    btn.classList.toggle('is-menu-hidden', hidden);
    if (hidden) btn.style.setProperty('display', 'none', 'important');
    else btn.style.removeProperty('display');
    btn.hidden = hidden;
    btn.setAttribute('aria-hidden', hidden ? 'true' : 'false');
    btn.tabIndex = hidden ? -1 : 0;
  });
  document.querySelectorAll('#sidebar .nav-section').forEach(section => {
    const hasVisibleItem = Array.from(section.querySelectorAll('.nav-item')).some(btn => !btn.classList.contains('is-menu-hidden'));
    section.classList.toggle('is-menu-hidden', !hasVisibleItem);
    if (!hasVisibleItem) section.style.setProperty('display', 'none', 'important');
    else section.style.removeProperty('display');
    section.hidden = !hasVisibleItem;
    section.setAttribute('aria-hidden', hasVisibleItem ? 'false' : 'true');
  });
  if (document.getElementById('nav-menu-drawer')?.classList.contains('open')) syncNavMenuDrawerContent();
  if (document.body.classList.contains('context-sidebar-mode') && typeof renderContextSidebarNav === 'function') renderContextSidebarNav();
  if (typeof renderCategoryMenubar === 'function') renderCategoryMenubar();
  if (typeof syncPlannerChromeAfterNavChange === 'function') syncPlannerChromeAfterNavChange();
  renderMenuVisibilitySettings();
}
function renderMenuVisibilitySettings(){
  const list = document.getElementById('menu-visibility-list');
  if (!list) return;
  const hiddenPages = new Set(getHiddenMenuPages());
  list.innerHTML = getMenuVisibilityPages().map(page => {
    const locked = MENU_ALWAYS_VISIBLE_PAGES.includes(page.id);
    const simpleHidden = isSimpleModePageHidden(page.id);
    const visible = isPlannerPageVisibleInMenu(page.id);
    const checked = locked || !hiddenPages.has(page.id);
    const status = locked ? 'Always visible' : (simpleHidden ? 'Hidden in Essentials View' : (visible ? 'Shown' : 'Hidden'));
    return `<label class="menu-toggle-row ${locked ? 'locked' : ''}">
      <input type="checkbox" ${checked ? 'checked' : ''} ${locked ? 'disabled' : ''} onchange="updateMenuPageVisibility('${page.id}', this.checked)">
      <span>${escapeHtml(page.label)}</span>
      <em>${status}</em>
    </label>`;
  }).join('');
}
function updateMenuPageVisibility(id, visible){
  if (MENU_ALWAYS_VISIBLE_PAGES.includes(id)) return;
  const hiddenPages = new Set(getHiddenMenuPages());
  if (visible) hiddenPages.delete(id);
  else hiddenPages.add(id);
  data.setup.hiddenMenuPages = Array.from(hiddenPages);
  save();
  applyMenuVisibility();
  const active = document.body.getAttribute('data-active-panel');
  if (isMenuPageHidden(active) || isSimpleModePageHidden(active)) showPanel('dashboard');
}
function setAllMenuPagesVisible(){
  data.setup.hiddenMenuPages = [];
  save();
  applyMenuVisibility();
  showToast('All menu pages are visible.');
}
function applySimpleMenuPreset(){
  data.setup.hiddenMenuPages = SIMPLE_MODE_HIDDEN_PAGES.filter(id => !MENU_ALWAYS_VISIBLE_PAGES.includes(id));
  save();
  applyMenuVisibility();
  showToast('Advanced pages are hidden from the top menu.');
}
function applySimpleMode(){
  const on = !!(data.setup && data.setup.simpleMode);
  document.body.classList.toggle('simple-mode', on);
  const btn = document.getElementById('simple-mode-btn');
  if (btn) {
    btn.classList.toggle('is-active-essentials', on);
    if (btn.classList.contains('pd-switch')) {
      btn.classList.toggle('on', on);
      btn.setAttribute('aria-checked', on ? 'true' : 'false');
    } else {
      btn.textContent = on ? 'Full Planner' : 'Focus on Essentials';
    }
  }
  applyMenuVisibility();
  if (typeof placeNavigationBelowTopbar === 'function') placeNavigationBelowTopbar();
  if (typeof renderEssentialsHubHosts === 'function') renderEssentialsHubHosts();
}
function syncFocusPresetSelect(){
  const sel = document.getElementById('focus-preset-select');
  if (!sel) return;
  const key = (data.setup && data.setup.focusPreset) || 'full';
  sel.value = FOCUS_PRESETS[key] ? key : 'full';
}
function getAllMenuPageIds(){
  const seen = new Set();
  return Array.from(document.querySelectorAll('#sidebar .nav-item')).map(btn => navPanelIdFromButton(btn)).filter(id => {
    if (!id || seen.has(id) || MENU_EXCLUDED_PAGES.includes(id)) return false;
    seen.add(id);
    return true;
  });
}
function applyFocusPreset(key){
  if (PLANNING_VIEWS[key]) {
    applyPlanningView(key);
    return;
  }
  if (!data.setup) data.setup = {};
  if (!FOCUS_PRESETS[key]) key = 'full';
  data.setup.focusPreset = key;
  if (key === 'full') {
    data.setup.hiddenMenuPages = [];
    data.setup.simpleMode = false;
    data.setup.planningView = 'full';
  } else {
    const visible = new Set([...MENU_ALWAYS_VISIBLE_PAGES, ...FOCUS_PRESETS[key].pages]);
    const allPages = getAllMenuPageIds();
    data.setup.hiddenMenuPages = allPages.filter(id => !visible.has(id));
    data.setup.simpleMode = false;
    data.setup.planningView = 'standard';
  }
  save();
  applySimpleMode();
  syncFocusPresetSelect();
  syncPlanningViewSelect();
  applyMenuVisibility();
  const active = document.body.getAttribute('data-active-panel');
  if (!isPlannerPageVisibleInMenu(active)) showPanel('dashboard');
  showToast(key === 'full' ? 'Full planner restored — all pages visible.' : FOCUS_PRESETS[key].label + ' focus applied.');
}
function toggleSimpleMode(){
  applyPlanningView(data.setup?.simpleMode ? 'full' : 'essentials');
}
function applyReadOnlyMode(){
  const on = !!(data && data.setup && data.setup.readOnlyPreview);
  document.body.classList.toggle('locked-planner', on);
  const btn = document.getElementById('read-only-btn');
  if (btn){
    btn.setAttribute('aria-pressed', on ? 'true' : 'false');
    if (btn.classList.contains('pd-switch')) {
      btn.classList.toggle('on', on);
      btn.setAttribute('aria-checked', on ? 'true' : 'false');
    } else {
      btn.textContent = on ? 'Unlock Editing' : 'Preview Mode';
    }
  }
  document.querySelectorAll('#main input,#main select,#main textarea,#main button').forEach(el => {
    if (el.closest('.record-editor-inline-shell,.record-editor-overlay')) {
      if (el.dataset.lockPrevDisabled) {
        el.disabled = el.dataset.lockPrevDisabled === '1';
        delete el.dataset.lockPrevDisabled;
      }
      return;
    }
    if (on) {
      if (!el.dataset.lockPrevDisabled) el.dataset.lockPrevDisabled = el.disabled ? '1' : '0';
      el.disabled = true;
    } else if (el.dataset.lockPrevDisabled) {
      el.disabled = el.dataset.lockPrevDisabled === '1';
      delete el.dataset.lockPrevDisabled;
    }
  });
}
function toggleReadOnlyMode(){
  data.setup.readOnlyPreview = !data.setup.readOnlyPreview;
  save();
  applyReadOnlyMode();
  showToast(data.setup.readOnlyPreview ? 'Read-only preview is on. Editing is locked.' : 'Editing unlocked.');
}
function sharedPagePrintHtml(panelId){
  const panel = document.getElementById('panel-' + panelId);
  if (!panel) return '';
  const copy = panel.cloneNode(true);
  const sourceFields = panel.querySelectorAll('input,select,textarea');
  const copiedFields = copy.querySelectorAll('input,select,textarea');
  copiedFields.forEach((field, i) => {
    const source = sourceFields[i];
    if (!source) return;
    let value = '';
    if (source.type === 'checkbox' || source.type === 'radio') value = source.checked ? 'Yes' : '';
    else if (source.tagName === 'SELECT') value = source.options[source.selectedIndex]?.textContent?.trim() || '';
    else value = source.value || source.getAttribute('placeholder') || '';
    const span = document.createElement('span');
    span.className = 'pv-field-value';
    span.textContent = value;
    field.replaceWith(span);
  });
  copy.querySelectorAll('button,input,select,textarea,.no-print,.ued-actions,.cwp-table-actions,.table-toolbar').forEach(el => el.remove());
  copy.querySelectorAll('[contenteditable]').forEach(el => el.removeAttribute('contenteditable'));
  copy.querySelectorAll('table').forEach(table => {
    table.classList.remove('cwp-table','ued-table','planner-resizable-table','record-editor-small-table');
    table.classList.add('pv-table');
    table.removeAttribute('style');
    table.querySelectorAll('[style]').forEach(el => el.removeAttribute('style'));
  });
  copy.querySelectorAll('.panel-head,.section-head,.page-actions,.cwp-table-wrap').forEach(el => el.classList.add('pv-section-wrap'));
  copy.querySelectorAll('.card,.kpi,.tile,.info-card,.vendor-card,.contact-card,.writing-box,.notes-block,.mauve-card,.scripture-card').forEach(el => el.classList.add('pv-card-block'));
  copy.querySelectorAll('h1,h2,h3').forEach(el => el.classList.add('pv-section-heading'));
  return copy.innerHTML;
}
function printSharedPage(target){
  const panel = document.getElementById('panel-' + target);
  if (!panel) { window.print(); return; }
  // Dedicated Covenant print templates take precedence over the generic clone.
  if (tryCovenantPrintTemplate(target)) return;
  const label = document.querySelector('#print-target-select option[value="' + target + '"]')?.textContent?.trim() || target;
  openSharedPrintCanvas(label, sharedPagePrintHtml(target), {
    subtitle: _pvCoupleSub(),
    accent: '#2D4A3E',
    extraCss: '.pv-doc{font-family:Arial,sans-serif}.pv-section-wrap{margin:0 0 18px}.pv-section-wrap h1,.pv-section-wrap h2,.pv-section-wrap h3{color:#2D4A3E;break-after:avoid}.pv-table{width:100%;border-collapse:collapse;font-size:10px;margin:8px 0 18px}.pv-table th{background:#2D4A3E;color:#fff;padding:6px;text-align:left}.pv-table td{padding:5px 6px;border-bottom:1px solid #ddd;vertical-align:top}.pv-table tr:nth-child(even) td{background:#faf8f4}.pv-empty-cta,.cwp-ghost-row{color:#6a655d}'
  });
}
function printSelectedSection(){
  const sel = document.getElementById('print-target-select');
  const target = sel ? sel.value : 'current';
  const active = document.body?.getAttribute('data-active-panel') || '';
  const printTarget = target && target !== 'current' ? target : active;
  if (target && target !== 'current') showPanel(target);
  if (printTarget === 'timeline' && typeof openWdayTimelinePrint === 'function') {
    setTimeout(() => openWdayTimelinePrint(), 120);
    return;
  }
  if (printTarget === 'appointments') {
    setTimeout(() => openAppointmentsAgendaPrint(), 120);
    return;
  }
  setTimeout(() => printSharedPage(printTarget), 160);
}
function printCurrentPage(){
  const active = document.body?.getAttribute('data-active-panel') || '';
  if (active === 'timeline' && typeof openWdayTimelinePrint === 'function') {
    setTimeout(() => openWdayTimelinePrint(), 120);
    return;
  }
  if (active === 'appointments') {
    setTimeout(() => openAppointmentsAgendaPrint(), 120);
    return;
  }
  setTimeout(() => printSharedPage(active), 160);
}
