function scrollToPlannerKeyboardShortcuts(openSidebar) {
  if (openSidebar !== false && document.body.classList.contains('context-sidebar-collapsed')) {
    if (typeof toggleContextSidebarCollapse === 'function') toggleContextSidebarCollapse();
  }
  requestAnimationFrame(function () {
    var host = document.getElementById('planner-sidebar-shortcuts');
    if (host) {
      host.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      host.classList.add('is-highlight');
      setTimeout(function () { host.classList.remove('is-highlight'); }, 1600);
    }
  });
}
function plannerShortcutTypingContext() {
  var el = document.activeElement;
  if (!el || !el.tagName) return false;
  var tag = el.tagName;
  if (tag === 'TEXTAREA' || tag === 'SELECT') return true;
  if (tag === 'INPUT') {
    var type = (el.type || 'text').toLowerCase();
    return type !== 'button' && type !== 'checkbox' && type !== 'radio' && type !== 'range' && type !== 'color';
  }
  return !!el.isContentEditable;
}
window.getPlannerKeyboardShortcuts = getPlannerKeyboardShortcuts;
window.getPlannerKeyboardShortcutsText = getPlannerKeyboardShortcutsText;
window.scrollToPlannerKeyboardShortcuts = scrollToPlannerKeyboardShortcuts;
window.showShortcutHelp = showShortcutHelp;
document.addEventListener('keydown', function(e){
  if (e.key === 'Escape') {
    if (document.body.classList.contains('context-sidebar-mobile-open')) {
      if (typeof toggleContextSidebarMobile === 'function') toggleContextSidebarMobile(false);
      return;
    }
    if (document.getElementById('nav-menu-drawer')?.classList.contains('open') || document.getElementById('profile-drawer')?.classList.contains('open')) return;
    closeNav();
  }
  const meta = e.ctrlKey || e.metaKey;
  if (meta && e.key.toLowerCase() === 's' && !plannerShortcutTypingContext()) {
    e.preventDefault();
    saveNow();
    return;
  }
  if (meta && !e.shiftKey && e.key.toLowerCase() === 'z' && !plannerShortcutTypingContext()) {
    e.preventDefault();
    undoPlannerChange();
    return;
  }
  if (meta && ((e.key.toLowerCase() === 'y') || (e.shiftKey && e.key.toLowerCase() === 'z')) && !plannerShortcutTypingContext()) {
    e.preventDefault();
    redoPlannerChange();
    return;
  }
  if(meta && e.key.toLowerCase()==='k'){ e.preventDefault(); if(typeof openCommandPalette==='function') openCommandPalette(); else document.getElementById('gs-input')?.focus(); }
  if (e.altKey && e.key.toLowerCase()==='m'){
    e.preventDefault();
    if (document.body.classList.contains('context-sidebar-mode')) {
      if (window.matchMedia('(max-width: 900px)').matches) {
        if (typeof toggleContextSidebarMobile === 'function') toggleContextSidebarMobile();
      } else if (typeof toggleContextSidebarCollapse === 'function') {
        toggleContextSidebarCollapse();
      }
      return;
    }
    if (document.body.classList.contains('nav-category-mode')) toggleNav();
    else document.body.classList.contains('nav-hidden') ? openNav() : closeNav();
  }
  if(e.altKey && e.key==='1'){ e.preventDefault(); showPanel('dashboard'); }
  if(e.altKey && e.key.toLowerCase()==='c'){ e.preventDefault(); showPanel('calendar'); }
  if(e.altKey && e.key.toLowerCase()==='b'){ e.preventDefault(); showPanel('budget'); }
  if (e.key === '?' && !e.ctrlKey && !e.metaKey && !e.altKey && !plannerShortcutTypingContext()) {
    e.preventDefault();
    if (document.body.classList.contains('rd-scope') && typeof openShortcutSheet === 'function') openShortcutSheet();
    else scrollToPlannerKeyboardShortcuts(true);
  }
});

function isCurrencyLikeTableInput(el){
  if (!el || el.tagName !== 'INPUT' || !el.closest('table')) return false;
  /* The CWP unified table engine formats its own money cells (cwpEditMoney) and
     must NOT be touched by this legacy heuristic. */
  if (el.closest('.cwp-table')) return false;
  if (['date','time','datetime-local','checkbox','email','tel','search'].includes(el.type)) return false;
  if (el.classList?.contains('no-currency') || el.dataset?.currency === 'false') return false;
  if (el.classList?.contains('payment-money') || el.dataset?.currency === 'true') return true;
  /* Judge only THIS cell's column header + the input's own attrs.
     Do NOT scan every <th> in the table (a money column elsewhere would
     mark every text cell as currency), and do NOT read oninput — nearly
     every handler contains `this.value`, which falsely matched the
     currency keyword `value` and stripped letters on focus (Newlywed
     Homecoming Item / Name-change Task columns). */
  const cell = el.closest('td, th');
  const row = cell && cell.parentElement;
  const colIndex = (row && cell) ? Array.prototype.indexOf.call(row.children, cell) : -1;
  const headRow = el.closest('table')?.querySelector('thead tr:not(.bulk-table-row)');
  const colTh = (colIndex >= 0 && headRow && headRow.children[colIndex])
    ? String(headRow.children[colIndex].textContent || '')
    : '';
  const ownSig = [el.id, el.name, el.placeholder, el.className, colTh].join(' ').toLowerCase();
  if (/\b(scripture|bible|verse|passage|reference)\b/.test(ownSig)) return false;
  const moneyRe = /\b(cost|price|amount|budget|paid|payment|deposit|balance|quote|rate|actual|value|total|fee)\b/;
  if (/\b(kid|kids|child|children|count|quantity|qty|guest count|headcount|table #|table number)\b/.test(ownSig) && !moneyRe.test(ownSig)) return false;
  return moneyRe.test(ownSig);
}
function stripCurrencyDisplay(value){
  return String(value ?? '').replace(/[^0-9.-]/g,'');
}
function formatCurrencyTableInput(el){
  if (!isCurrencyLikeTableInput(el) || document.activeElement === el) return;
  const raw = stripCurrencyDisplay(el.value);
  if (!raw || Number.isNaN(parseFloat(raw))) return;
  el.type = 'text';
  el.value = fmt(parseFloat(raw));
}
function normalizeCurrencyTableInputs(root=document){
  (root || document).querySelectorAll?.('table input')?.forEach(formatCurrencyTableInput);
}
document.addEventListener('focusin', event => {
  const el = event.target;
  if (isCurrencyLikeTableInput(el)) {
    el.type = 'text';
    el.value = stripCurrencyDisplay(el.value);
  }
}, true);
document.addEventListener('focusout', event => {
  if (isCurrencyLikeTableInput(event.target)) formatCurrencyTableInput(event.target);
}, true);

