function guideBuildAlerts(){
  const alerts = [];
  const push = (priority, title, note, page, action, kind) => alerts.push({priority, title, note, page:page||'dashboard', action:action||'', kind:kind||'general'});
  const totalBudget = parseFloat(data.setup?.budget)||0;
  const spent = (typeof budgetTotalActual === 'function') ? budgetTotalActual() : safeArray(data.budget).reduce((s,r)=>s+(parseFloat(r.actual)||0),0);
  const trueProj = typeof computeTrueTotalProjection === 'function' ? computeTrueTotalProjection() : null;
  const ob = ensureOnboardData();
  const lastBackup = ob.lastBackupTime ? new Date(ob.lastBackupTime).getTime() : 0;

  if (guideHasPlannerContent() && (!ob.backupDone || !lastBackup || Date.now() - lastBackup > 7*86400000)) {
    push(1,'Backup recommended','Protect your offline planner by downloading a fresh backup file.','instructions','startHereBackup()','backup');
  }
  const nonResp = countGuestNonResponders();
  if (nonResp > 0) {
    push(2, `${nonResp} RSVP non-responder${nonResp === 1 ? '' : 's'}`, 'Invited guests still need an RSVP — copy a follow-up or open the guest list.', 'guests', "applyGuestFilterPreset('non-responders')", 'rsvp');
  }
  if (trueProj?.overBudget) {
    push(1, 'True Total over stated budget', `Your real total is likely ${guideMoney(trueProj.trueTotal)} — ${guideMoney(trueProj.overBy)} over your ${guideMoney(trueProj.statedBudget)} target.`, 'budget', '', 'budget');
  } else if (totalBudget > 0 && spent > totalBudget) {
    push(1,'Budget is over target',`${guideMoney(spent-totalBudget)} is currently over your total budget.`, 'budget', '', 'budget');
  }
  const missingMeal = safeArray(data.guests).filter(g => /yes|accepted/i.test(g.rsvp||'') && !String(g.meal||'').trim());
  if (missingMeal.length) push(2,'Meal choices needed',`${missingMeal.length} attending guest${missingMeal.length===1?'':'s'} need meal selections for catering estimates.`, 'guests');
  const missingTable = safeArray(data.guests).filter(g => /yes|accepted/i.test(g.rsvp||'') && !String(g.table||'').trim());
  if (missingTable.length) push(3,'Seating not finished',`${missingTable.length} attending guest${missingTable.length===1?'':'s'} are not assigned to a table yet.`, 'tables');

  safeArray(data.payments).forEach(p => {
    const date = p.date || p.dueDate;
    const diff = guideDateDiff(date);
    if (diff === null || /paid|complete/i.test(p.status||'')) return;
    if (diff < 0) push(1,'Payment overdue',`${p.vendor||p.desc||'A payment'} was due ${guideFmtDate(date)}.`, 'payments');
    else if (diff <= 7) push(2,'Payment due soon',`${p.vendor||p.desc||'A payment'} is due ${guideFmtDate(date)}.`, 'payments');
  });
  safeArray(data.appointments).forEach(a => {
    const diff = guideDateDiff(a.date);
    if (diff === null || diff < 0 || diff > 14) return;
    if (!/confirmed|complete|done/i.test(a.status||'')) push(3,'Appointment needs confirmation',`${a.title||a.vendor||'Appointment'} is coming up ${guideFmtDate(a.date)}.`, 'calendar', '', 'vendor');
  });
  ensureCeremonyArrays();
  const legalOpen = safeArray(data.ceremonyChecklist).filter(r => !r.done && /license|witness|legal|officiant.*confirm/i.test(String(r.item || '')));
  if (legalOpen.length) {
    push(2, 'License / legal checklist open', `${legalOpen.length} ceremony legal item${legalOpen.length === 1 ? '' : 's'} still need attention.`, 'ceremony', '', 'legal');
  }
  const rsvpDeadline = getRsvpDeadlineInfo();
  if (rsvpDeadline && !rsvpDeadline.past && rsvpDeadline.daysLeft !== null && rsvpDeadline.daysLeft <= 14 && nonResp > 0) {
    push(2, 'RSVP deadline approaching', `${nonResp} non-responder${nonResp === 1 ? '' : 's'} — ${rsvpDeadline.label} is ${guideFmtDate(rsvpDeadline.date)}.`, 'guests', "applyGuestFilterPreset('non-responders')", 'rsvp');
  }
  safeArray(data.hotelBlocks).forEach(h => {
    const diff = guideDateDiff(h.cutoff);
    if (diff !== null && diff >= 0 && diff <= 14) push(2,'Hotel block cutoff soon',`${h.hotel||'Hotel block'} cutoff is ${guideFmtDate(h.cutoff)}.`, 'logistics');
  });
  const transportNeeded = safeArray(data.travelAccommodations).filter(r => r.transportNeeded).length;
  if (transportNeeded && !safeArray(data.transportation).length) {
    push(2,'Transportation routes missing',`${transportNeeded} travel row${transportNeeded===1?'':'s'} need transportation, but no routes are planned yet.`, 'logistics');
  }
  const unconfirmedRoutes = safeArray(data.transportation).filter(r => !/confirmed|complete|canceled/i.test(r.status||'') && (r.date || r.pickup || r.dropoff));
  if (unconfirmedRoutes.length) push(3,'Transportation still needs decisions',`${unconfirmedRoutes.length} transportation route${unconfirmedRoutes.length===1?'':'s'} are not confirmed.`, 'logistics');
  const missingWeekendLocation = safeArray(data.weekendTimeline).filter(r => r.event && !String(r.location||'').trim());
  if (missingWeekendLocation.length) push(3,'Weekend locations missing',`${missingWeekendLocation.length} weekend item${missingWeekendLocation.length===1?'':'s'} need a location.`, 'logistics');
  if (typeof plannerRelationshipWarnings === 'function') {
    plannerRelationshipWarnings().slice(0,6).forEach(w => push(w.priority || 3, w.title || 'Linked record needs review', w.note || w.text || '', w.page || 'setup'));
  }

  return alerts.sort((a,b)=>a.priority-b.priority).slice(0,12);
}
function updateAttentionTopbarBadge(){
  if (typeof updateTopbarNotificationsBell === 'function') updateTopbarNotificationsBell();
}
function getBackupReminderState(){
  const ob = ensureOnboardData();
  const last = ob.lastBackupTime;
  const hasData = safeArray(data.guests).length + safeArray(data.tasks).length + safeArray(data.budget).length > 0;
  if (!hasData) return { due: false };
  if (ob._backupSnoozed) {
    const snoozedAt = new Date(ob._backupSnoozed).getTime();
    if (Date.now() - snoozedAt < 86400000) return { due: false, snoozed: true };
  }
  const elapsed = last ? Date.now() - new Date(last).getTime() : Infinity;
  const edits = ob.editsSinceBackup || 0;
  const dueByTime = elapsed >= 7 * 86400000;
  const dueByEdits = edits >= BACKUP_EDIT_THRESHOLD;
  if (!dueByTime && !dueByEdits) return { due: false };
  let message;
  if (!last) message = "You haven't downloaded a backup yet. Download a copy to protect your planner data.";
  else if (dueByEdits && !dueByTime) message = `You've made ${edits} changes since your last backup.`;
  else message = `It's been ${Math.floor(elapsed / 86400000)} days since your last backup.`;
  return {
    due: true,
    title: 'Backup reminder',
    message,
    action: 'backupFromReminder()',
    laterAction: 'snoozeBackupReminderFromNotifications()'
  };
}
function buildSmartCalendarNotificationItems(){
  const events = typeof buildSmartCalendarEvents === 'function' ? buildSmartCalendarEvents() : [];
  const items = [];
  const alerts = events.filter(e => {
    const diff = typeof daysBetween === 'function' ? daysBetween(e.date) : null;
    return diff !== null && diff >= 0 && diff <= 7 && !/complete|paid|confirmed/i.test(e.status || '');
  });
  const nonResp = typeof countGuestNonResponders === 'function' ? countGuestNonResponders() : 0;
  if (nonResp) {
    const rsvpDeadline = typeof getRsvpDeadlineInfo === 'function' ? getRsvpDeadlineInfo() : null;
    items.push({
      id: 'smart-rsvp',
      title: `${nonResp} RSVP non-responder${nonResp === 1 ? '' : 's'}`,
      note: rsvpDeadline && !rsvpDeadline.past && typeof guideFmtDate === 'function' ? guideFmtDate(rsvpDeadline.date) : 'Follow up soon',
      urgent: true,
      action: "showPanel('guests')"
    });
  }
  alerts.slice(0, 8).forEach((e, i) => {
    const diff = typeof daysBetween === 'function' ? daysBetween(e.date) : null;
    const when = diff === 0 ? 'Today' : diff === 1 ? 'Tomorrow' : `${diff} days`;
    items.push({
      id: 'smart-' + i + '-' + String(e.date || ''),
      title: e.title || 'Calendar alert',
      note: when + (e.source ? ' · ' + e.source : ''),
      action: "showPanel('calendar')"
    });
  });
  return items;
}
function buildPlannerNotificationModel(){
  const guidance = typeof plannerGuidanceState === 'function' ? plannerGuidanceState() : { alerts: [], attentionCount: 0 };
  const kindLabel = { rsvp:'RSVP', budget:'Budget', vendor:'Vendors', legal:'Legal', backup:'Backup', general:'General', covenant:'Covenant' };
  const needsYou = safeArray(guidance.alerts).map((a, i) => ({
    id: 'attention-' + i,
    title: (a.kind && kindLabel[a.kind] ? kindLabel[a.kind] + ': ' : '') + (a.title || 'Needs attention'),
    note: a.note || '',
    urgent: a.priority === 1,
    chip: a.chip || (a.priority === 1 ? 'Blocker' : (a.kind === 'covenant' ? 'Covenant' : '')),
    chipTone: a.kind === 'covenant' ? 'gold' : (a.priority === 1 ? 'red' : ''),
    action: a.action || `showPanel('${a.page || 'dashboard'}')`
  }));
  const backup = getBackupReminderState();
  if (backup.due) {
    needsYou.unshift({
      id: 'backup-reminder',
      title: backup.title,
      note: backup.message,
      urgent: true,
      chip: 'Backup',
      chipTone: 'red',
      action: backup.action,
      laterAction: backup.laterAction
    });
  }
  const smart = buildSmartCalendarNotificationItems();
  const activity = smart.map((item, i) => ({
    id: item.id || ('activity-' + i),
    title: item.title,
    note: item.note || '',
    when: item.when || item.chip || 'recently',
    action: item.action || ''
  }));
  return {
    needsYou,
    activity,
    activityMeta: activity.length ? 'recently' : '—',
    quiet: 'No alert is raised for a guest replying, a payment coming due more than 14 days out, or a vendor opening a packet. Those are visible on their own pages and would train you to ignore this panel.',
    needsCount: needsYou.length
  };
}
function buildPlannerNotificationSections(){
  const model = buildPlannerNotificationModel();
  return {
    sections: [
      { id: 'needs', label: 'Needs you', items: model.needsYou },
      { id: 'activity', label: 'Changed since you last looked', items: model.activity }
    ],
    totalCount: model.needsCount,
    model
  };
}
function renderTopbarNotificationsDrop(){
  const drop = document.getElementById('topbar-notifications-drop');
  if (!drop) return;
  const { model } = buildPlannerNotificationSections();
  if (typeof RdFurniture !== 'undefined' && RdFurniture.notificationsHtml) {
    drop.innerHTML = `<div class="topbar-notifications-drop-scroll">${RdFurniture.notificationsHtml(model)}</div>`;
    drop.querySelectorAll('[data-notif-action]').forEach(btn => {
      btn.addEventListener('click', () => {
        const action = btn.getAttribute('data-notif-action') || '';
        closeTopbarNotifications();
        if (!action) return;
        try { Function(action)(); } catch (e) { /* ignore bad action strings */ }
      });
    });
    const mark = drop.querySelector('[data-notif-read]');
    if (mark) mark.onclick = () => { closeTopbarNotifications(); if (typeof showToast === 'function') showToast('Activity marked as read'); };
    const settings = drop.querySelector('[data-notif-settings]');
    if (settings) settings.onclick = () => {
      closeTopbarNotifications();
      const gear = document.getElementById('rd-gear-btn');
      if (gear) gear.click();
    };
    return;
  }
  const html = model.needsYou.length
    ? model.needsYou.map(item => `<button type="button" class="tb-notif-item${item.urgent ? ' urgent' : ''}" role="menuitem" onclick="${item.action};closeTopbarNotifications();"><span class="tb-notif-item-copy"><strong>${escapeHtml(item.title)}</strong><span>${escapeHtml(item.note || '')}</span></span></button>`).join('')
    : '<div class="tb-notif-empty">Nothing needs you right now.</div>';
  drop.innerHTML = `<div class="topbar-notifications-drop-scroll">${html}</div>`;
}
function updateTopbarNotificationsBell(){
  const badge = document.getElementById('topbar-notifications-badge');
  const btn = document.getElementById('topbar-notifications-btn');
  const { totalCount } = buildPlannerNotificationSections();
  if (badge) {
    badge.textContent = String(totalCount);
    badge.hidden = totalCount <= 0;
    badge.classList.toggle('is-empty', totalCount <= 0);
  }
  if (btn) {
    btn.setAttribute('aria-label', totalCount ? `${totalCount} need${totalCount === 1 ? 's' : ''} you` : 'No alerts');
    btn.classList.toggle('has-alerts', totalCount > 0);
  }
  const drop = document.getElementById('topbar-notifications-drop');
  if (drop && drop.classList.contains('open')) renderTopbarNotificationsDrop();
}
function toggleTopbarNotifications(e){
  if (e) e.stopPropagation();
  const drop = document.getElementById('topbar-notifications-drop');
  const btn = document.getElementById('topbar-notifications-btn');
  if (!drop) return;
  const opening = !drop.classList.contains('open');
  if (opening) {
    const qjDrop = document.getElementById('quick-jump-drop');
    if (qjDrop) qjDrop.classList.remove('open');
    const qjBtn = document.getElementById('quick-jump-btn');
    if (qjBtn) qjBtn.setAttribute('aria-expanded', 'false');
    renderTopbarNotificationsDrop();
  }
  drop.classList.toggle('open', opening);
  if (btn) btn.setAttribute('aria-expanded', opening ? 'true' : 'false');
}
function closeTopbarNotifications(){
  const drop = document.getElementById('topbar-notifications-drop');
  const btn = document.getElementById('topbar-notifications-btn');
  if (drop) drop.classList.remove('open');
  if (btn) btn.setAttribute('aria-expanded', 'false');
}
