/* Key Dates summary (Step 1.4) — surfaces upcoming milestones (wedding day,
   payment due dates, appointments/fittings, rehearsal, honeymoon, etc.) by
   reusing the Smart Calendar aggregator so every dated table feeds it. */
function kdDayDiff(iso){
  const d = (typeof dateFromISO === 'function') ? dateFromISO(iso) : new Date(iso);
  const t = new Date(); t.setHours(0,0,0,0);
  return Math.round((d - t) / 86400000);
}
function kdWhen(diff){
  if (diff === 0) return 'Today';
  if (diff === 1) return 'Tomorrow';
  if (diff === -1) return 'Yesterday';
  if (diff < 0) return Math.abs(diff) + ' days ago';
  if (diff < 14) return 'in ' + diff + ' days';
  if (diff < 60) return 'in ' + Math.round(diff/7) + ' wks';
  if (diff < 365) return 'in ' + Math.round(diff/30) + ' mo';
  return 'in ' + (Math.round(diff/30.4/12*10)/10) + ' yr';
}
function renderKeyDatesCard(){
  const host = document.getElementById('key-dates-card');
  if (!host) return;
  const today = (typeof todayISO === 'function') ? todayISO() : new Date().toISOString().slice(0,10);
  const all = (typeof buildSmartCalendarEvents === 'function') ? buildSmartCalendarEvents() : [];
  const doneRe = /paid|complete|celebrat|done|cancel/i;
  const dated = all.filter(e => e.date);
  const past = dated.filter(e => e.date < today && !doneRe.test(e.status || ''));
  const upcoming = dated.filter(e => e.date >= today);
  const overdue = past.slice(-3).reverse();           // closest-to-today overdue first
  const rows = [...overdue, ...upcoming.slice(0, 8)];
  if (!rows.length){
    host.innerHTML = `<div class="kd-head"><h3 class="kd-title">Key Dates</h3></div><div class="kd-empty">Add your wedding date, payments, appointments, or honeymoon travel and your upcoming milestones will gather here automatically.</div>`;
    return;
  }
  const body = rows.map(e => {
    const diff = kdDayDiff(e.date);
    const d = (typeof dateFromISO === 'function') ? dateFromISO(e.date) : new Date(e.date);
    const mon = d.toLocaleDateString('en-US',{month:'short'});
    const day = d.getDate();
    const overdueRow = diff < 0;
    const milestone = e.source === 'Honeymoon' || e.category === 'Wedding Day' || /wedding day/i.test(e.title || '');
    const cls = overdueRow ? 'kd-overdue' : (milestone ? 'kd-milestone' : '');
    const meta = [e.source, e.notes].filter(Boolean).join(' • ');
    const page = e.sourcePage || 'calendar';
    return `<div class="kd-row ${cls}" onclick="showPanel('${page}')" title="Go to ${gsEsc(e.source||'')}">
      <span class="kd-date"><b>${day}</b><span>${gsEsc(mon)}</span></span>
      <span class="kd-body"><span class="kd-name">${gsEsc(e.title || 'Event')}</span><span class="kd-meta">${gsEsc(meta)}</span></span>
      <span class="kd-when">${gsEsc(kdWhen(diff))}</span>
    </div>`;
  }).join('');
  const overdueCount = overdue.length;
  const sub = overdueCount
    ? `<b style="color:var(--red,#b3402f)">${overdueCount} past due</b> &middot; ${upcoming.length} upcoming`
    : `${upcoming.length} upcoming`;
  host.innerHTML = `<div class="kd-head"><h3 class="kd-title">Key Dates</h3><div class="kd-sub">${sub}</div></div><div class="kd-grid">${body}</div>`;
}

