function ensureOnboardData(){
  if (!data.onboard || typeof data.onboard !== 'object') data.onboard = {};
  return data.onboard;
}
/* Track 1.3 — record that a fresh backup was just downloaded: stamp the time
   and clear the "changes since backup" counter without that reset counting as
   a change itself. */
function markBackupTaken(){
  const ob = ensureOnboardData();
  ob.lastBackupTime = new Date().toISOString();
  ob.editsSinceBackup = 0;
  ob.backupDone = true;
  ob.backupEducated = true;
  _suppressEditCount = true;
  try { save(); } finally { _suppressEditCount = false; }
  if (typeof checkMilestoneCelebrations === 'function') checkMilestoneCelebrations();
}
function shouldShowBackupEducation(){
  const ob = ensureOnboardData();
  if (ob.backupEducated || ob.backupDone || ob.lastBackupTime) return false;
  return true;
}
