function applyDashboardCardLayout(page){
  if (!page) return;
  const layout = getDashboardLayout().filter(c => c.visible !== false).sort((a, b) => (a.order ?? 0) - (b.order ?? 0));
  const breakdownIds = new Set(['rsvp-breakdown', 'payments-breakdown', 'vendor-breakdown']);
  const primaryIds = new Set(['planning-progress', 'needs-attention']);
  const secondaryIds = new Set(['next-up', 'payments-due', 'share-readiness']);
  const insightIds = new Set(['guidance-blocks', 'planning-health', 'data-health']);
  let breakdownRow = null;
  let primaryRow = null;
  let secondaryRow = null;
  let insightRow = null;
  layout.forEach(cfg => {
    const el = page.querySelector('[data-dash-card="' + cfg.id + '"]');
    if (el) {
      el.hidden = false;
      if (primaryIds.has(cfg.id)) {
        if (!primaryRow) {
          primaryRow = document.createElement('section');
          primaryRow.className = 'ued-grid dash-primary-row';
          page.appendChild(primaryRow);
        }
        primaryRow.appendChild(el);
      } else if (secondaryIds.has(cfg.id)) {
        if (!secondaryRow) {
          secondaryRow = document.createElement('section');
          secondaryRow.className = 'ued-grid dash-secondary-row';
          page.appendChild(secondaryRow);
        }
        secondaryRow.appendChild(el);
      } else if (insightIds.has(cfg.id)) {
        if (!insightRow) {
          insightRow = document.createElement('section');
          insightRow.className = 'ued-grid dash-insight-row';
          page.appendChild(insightRow);
        }
        insightRow.appendChild(el);
      } else if (breakdownIds.has(cfg.id)) {
        if (!breakdownRow) {
          breakdownRow = document.createElement('section');
          breakdownRow.className = 'ued-grid dash-breakdown-row';
          page.appendChild(breakdownRow);
        }
        breakdownRow.appendChild(el);
      } else {
        page.appendChild(el);
      }
    }
  });
  getDashboardLayout().filter(c => c.visible === false).forEach(cfg => {
    const el = page.querySelector('[data-dash-card="' + cfg.id + '"]');
    if (el) el.hidden = true;
  });
}
