function addCommonBudgetLine(catName, itemName, amount){
  migrateBudget();
  let ci = data.budget.findIndex(c => String(c.cat || '').toLowerCase() === catName.toLowerCase());
  if (ci < 0) { data.budget.push({ cat:catName, target:0, planned:0, tip:'', items:[] }); ci = data.budget.length - 1; }
  const cat = data.budget[ci];
  if (!Array.isArray(cat.items)) cat.items = [];
  if (cat.items.some(it => String(it.name || '').toLowerCase() === itemName.toLowerCase())) {
    if (typeof showToast === 'function') showToast('That line already exists in ' + catName + '.');
    return;
  }
  cat.items.push({ name:itemName, budgeted:amount, actual:0, status:'Pending', notes:'' });
  save();
  activeBudgetCategoryIndex = ci;
  if (typeof renderBudget === 'function') renderBudget();
  if (typeof showToast === 'function') showToast('Added ' + itemName + ' to ' + catName + '.');
}
