  host.innerHTML = `<div class="suggest-chips-row"><span class="suggest-chips-label">Add phase checklist:</span>${phases.map(ph => `<button type="button" class="suggest-chip" onclick="addTaskPhaseChecklist('${ph.replace(/'/g, "\\'")}')">${escapeHtml(ph)}</button>`).join('')}</div>`;
