async function addTaskPhaseChecklist(phase){
  const items = TASK_PHASE_CHECKLISTS[phase];
  if (!items || !items.length) return;
  const existing = data.tasks.filter(t => String(t.phase || '') === phase).length;
  if (existing && !(await starterConfirm('Add ' + items.length + ' standard tasks for "' + phase + '"?'))) return;
  items.forEach(task => {
    if (data.tasks.some(t => String(t.task || '').trim() === task)) return;
    data.tasks.push({ _id:nextRecordId('tasks'), task, cat:'', phase, priority:'Medium', assigned:'Both', date:'', suggestedDue:'', status:'Not Started', done:false, notes:'', subtasks:[] });
  });
  save();
  if (typeof renderTasks === 'function') renderTasks();
  if (typeof showToast === 'function') showToast('Added ' + phase + ' checklist tasks.');
}
