let _etActiveCat = 'All';
let _etActiveView = 'questions';
let _vendorQuestionActiveType = 'Venue';

function etMergeValues(){
  const s = data.setup || {};
  const v = data.venue || {};
  const tl = data.timeline || [];
  const findTL = (kw) => { const e = tl.find(r => (r.event||'').toLowerCase().includes(kw)); return e ? (e.time||'') : ''; };
  return {
    bride: s.bride || '[Bride]',
    groom: s.groom || '[Groom]',
    date: s.date ? fmtDate(s.date, 'long') : '[date]',
    venue: s['venue-ceremony'] || '[venue]',
    ceremonyVenue: s['venue-ceremony'] || '[venue]',
    ceremonyAddress: v['c-address'] || '[address]',
    receptionVenue: s['venue-reception'] || '[reception venue]',
    ceremonyTime: findTL('ceremony') || '[time]',
    receptionTime: findTL('reception') || '[time]',
    guestCount: s.guests || String((data.guests||[]).length) || '[count]',
    colors: s.colors || '[colors]',
    pastor: (s.pastor || '[Pastor]').replace(/^Pastor\s+/i, ''),
    vendor: '[Vendor Name]',
    name: '[Name]',
    service: '[service]',
    dueDate: '[due date]',
    amount: '[amount]',
    rehearsal: findTL('rehearsal') || '[rehearsal time]',
    rehearsalDinner: findTL('dinner') || '[dinner location]',
    partyArrival: findTL('arrival') || findTL('party arrives') || '[arrival time]',
    rsvpDeadline: s.rsvpDeadline || '[RSVP deadline]',
    hotelBlock: '[hotel name]',
    hotelCode: '[booking code]',
    airport: '[airport]',
    driveTime: '[drive time]',
    parking: '[parking info]',
    dressCode: s.style || '[dress code]',
    gift: '[gift description]',
    review: '[review link]',
    city: '[city]'
  };
}

function etFillTemplate(t){
  const v = etMergeValues();
  const fill = s => s.replace(/\{\{(\w+)\}\}/g, (_, k) => v[k] || ('{{' + k + '}}'));
  return { subject: fill(t.subject), body: fill(t.body) };
}

function emailTemplateView(view){
  _etActiveView = view === 'templates' ? 'templates' : 'questions';
  renderEmailTemplates();
}

function normalizeInstructionsFlow(){
  const panel = document.getElementById('panel-instructions');
  if (!panel || panel.dataset.flowNormalized === '1') return;
  const welcome = panel.querySelector('.inst-welcome');
  const guided = document.getElementById('start-here-card');
  const learningGrid = panel.querySelector('.inst-grid-3');
  const wideRow = panel.querySelector('.inst-wide-row');
  const essentialsHub = document.getElementById('start-here-essentials-hub');
  const aloneCard = panel.querySelector('.inst-alone');
  const actions = panel.querySelector('.inst-actions-row');
  if (!welcome || !guided || !learningGrid || !wideRow || !actions) return;
  welcome.insertAdjacentElement('afterend', learningGrid);
  learningGrid.insertAdjacentElement('afterend', wideRow);
  wideRow.insertAdjacentElement('afterend', guided);
  guided.insertAdjacentElement('afterend', actions);
  if (aloneCard) {
    if (essentialsHub) actions.insertAdjacentElement('afterend', essentialsHub);
    actions.insertAdjacentElement('afterend', aloneCard);
  }
  panel.dataset.flowNormalized = '1';
}
function ensureEmailViewTabs(){
  const panel = document.getElementById('panel-emails');
  const header = panel?.querySelector('.et-header');
  if (!panel || !header) return null;
  let tabs = document.getElementById('et-view-tabs');
  if (!tabs) {
    tabs = document.createElement('div');
    tabs.id = 'et-view-tabs';
    tabs.className = 'et-view-tabs';
    header.insertAdjacentElement('afterend', tabs);
  }
  tabs.innerHTML = `<button type="button" class="et-view-tab${_etActiveView==='questions'?' active':''}" onclick="emailTemplateView('questions')">Vendor Questions</button><button type="button" class="et-view-tab${_etActiveView==='templates'?' active':''}" onclick="emailTemplateView('templates')">Email Templates</button>`;
  return tabs;
}
function vendorQuestionStatsHtml(){
  const count = VENDOR_QUESTION_BANK.reduce((s,g)=>s + g.questions.length, 0);
  return `<div class="et-stat"><div class="et-stat-val">${VENDOR_QUESTION_BANK.length}</div><div class="et-stat-label">Vendor Types</div></div>` +
    `<div class="et-stat"><div class="et-stat-val">${count}</div><div class="et-stat-label">Questions</div></div>` +
    `<div class="et-stat"><div class="et-stat-val">Yes</div><div class="et-stat-label">Etsy Friendly</div></div>` +
    `<div class="et-stat"><div class="et-stat-val">Offline</div><div class="et-stat-label">Private Use</div></div>`;
}
function renderVendorQuestionsHTML(){
  const active = VENDOR_QUESTION_BANK.find(g => g.type === _vendorQuestionActiveType) || VENDOR_QUESTION_BANK[0];
  _vendorQuestionActiveType = active?.type || 'Venue';
  return `<div class="vendor-question-intro">
    <h3>Vendor Questions</h3>
    <p>Use these before booking vendors, during consultations, or when preparing emails. The goal is to prevent hidden costs, unclear responsibilities, timeline confusion, and overlooked day-of needs.</p>
    <div class="vendor-question-actions"><button type="button" class="et-copy-btn" onclick="copyVendorQuestions()">Copy All Questions</button></div>
  </div>
  <div class="vendor-question-shell">
    <nav class="vendor-question-rail" aria-label="Vendor question categories">
      ${VENDOR_QUESTION_BANK.map(group => `<button type="button" class="${group.type===_vendorQuestionActiveType?'active':''}" onclick="setVendorQuestionType('${String(group.type).replace(/'/g,"\\'")}')">${escapeHtml(group.type)}</button>`).join('')}
    </nav>
    <section class="vendor-question-card">
      <h3>${escapeHtml(active.type)}</h3>
      <ul>${active.questions.map(q => `<li>${escapeHtml(q)}</li>`).join('')}</ul>
    </section>
  </div>`;
}
function setVendorQuestionType(type){
  _vendorQuestionActiveType = type;
  renderEmailTemplates();
}
function copyVendorQuestions(){
  const text = VENDOR_QUESTION_BANK.map(group => `${group.type}\n${group.questions.map(q => '- ' + q).join('\n')}`).join('\n\n');
  navigator.clipboard.writeText(text).then(() => etShowToast('Vendor questions copied')).catch(() => covPrompt('Copy vendor questions:', {defaultValue: text}));
}
function renderEmailTemplates(){
  ensureEmailViewTabs();
  const cats = [...new Set(EMAIL_TEMPLATES.map(t => t.cat))];
  const catCounts = {};
  cats.forEach(c => { catCounts[c] = EMAIL_TEMPLATES.filter(t => t.cat === c).length; });

  const statsEl = document.getElementById('et-stats');
  const layout = document.querySelector('#panel-emails .et-layout');
  const sidebar = document.querySelector('#panel-emails .et-sidebar');
  const listEl = document.getElementById('et-list');
  if (_etActiveView === 'questions') {
    if (statsEl) statsEl.innerHTML = vendorQuestionStatsHtml();
    if (layout) layout.classList.add('questions-mode');
    if (sidebar) sidebar.style.display = 'none';
    if (listEl) listEl.innerHTML = renderVendorQuestionsHTML();
    return;
  }
  if (layout) layout.classList.remove('questions-mode');
  if (sidebar) sidebar.style.display = '';
  if (statsEl) {
    statsEl.innerHTML = `<div class="et-stat"><div class="et-stat-val">${EMAIL_TEMPLATES.length}</div><div class="et-stat-label">Templates</div></div>` +
      `<div class="et-stat"><div class="et-stat-val">${cats.length}</div><div class="et-stat-label">Categories</div></div>` +
      `<div class="et-stat"><div class="et-stat-val">${data.setup.bride && data.setup.groom ? 'Yes' : 'No'}</div><div class="et-stat-label">Names Filled</div></div>` +
      `<div class="et-stat"><div class="et-stat-val">${data.setup.date ? 'Yes' : 'No'}</div><div class="et-stat-label">Date Filled</div></div>`;
  }

  const tabsEl = document.getElementById('et-cat-tabs');
  if (tabsEl) {
    let tabsHtml = `<button class="et-cat-tab${_etActiveCat==='All'?' active':''}" onclick="etFilterCat('All')">All<span class="et-cat-count">${EMAIL_TEMPLATES.length}</span></button>`;
    cats.forEach(c => {
      tabsHtml += `<button class="et-cat-tab${_etActiveCat===c?' active':''}" onclick="etFilterCat('${escapeHtml(c)}')">${escapeHtml(c)}<span class="et-cat-count">${catCounts[c]}</span></button>`;
    });
    tabsEl.innerHTML = tabsHtml;
  }

  const filtered = _etActiveCat === 'All' ? EMAIL_TEMPLATES : EMAIL_TEMPLATES.filter(t => t.cat === _etActiveCat);
  const grouped = {};
  filtered.forEach(t => {
    if (!grouped[t.cat]) grouped[t.cat] = [];
    grouped[t.cat].push(t);
  });

  let html = '';
  const mergeHint = '<div class="et-merge-hint">Fields like <span class="et-merge-tag">{{name}}</span> are placeholders — edit them before sending, or fill in Wedding Setup for auto-fill.</div>';

  Object.keys(grouped).forEach(cat => {
    html += `<div class="et-section-label">${escapeHtml(cat)}</div>`;
    grouped[cat].forEach((t, i) => {
      const f = etFillTemplate(t);
      const globalIdx = EMAIL_TEMPLATES.indexOf(t);
      const sid = 'et_' + globalIdx + '_s';
      const bid = 'et_' + globalIdx + '_b';
      const mailto = 'mailto:?subject=' + encodeURIComponent(f.subject) + '&body=' + encodeURIComponent(f.body);
      html += `<div class="et-card">
        <h3>${escapeHtml(t.title)}</h3>
        <div class="et-field-label">Subject</div>
        <input type="text" value="${escapeHtml(f.subject)}" id="${sid}">
        <div class="et-field-label" style="margin-top:.5rem">Body</div>
        <textarea id="${bid}">${escapeHtml(f.body)}</textarea>
        <div class="et-actions">
          <button type="button" class="et-copy-btn" onclick="copyEmailTemplate(${globalIdx})"><svg viewBox="0 0 24 24"><rect x="9" y="9" width="13" height="13" rx="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/></svg> Copy</button>
          <a class="et-mail-btn" href="${mailto}"><svg viewBox="0 0 24 24"><rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 7 9 6 9-6"/></svg> Open in Email</a>
        </div>
      </div>`;
    });
  });

  if (filtered.length === 0) {
    html = '<div style="text-align:center;padding:2rem;color:var(--muted);">No templates in this category.</div>';
  }

  html += mergeHint;
  if (listEl) listEl.innerHTML = html;

  renderEmailMergeFields();
}

/* Available Merge Fields card — lists every {{token}} with its live value
   (pulled from etMergeValues, which reads Wedding Setup + planner data). */
function renderEmailMergeFields(){
  const grid = document.getElementById('et-merge-fields');
  if (!grid) return;
  const v = etMergeValues();
  // Friendly labels; any key missing here falls back to the raw token name.
  const LABELS = {
    bride:'Bride', groom:'Groom', date:'Wedding Date', venue:'Ceremony Venue',
    ceremonyVenue:'Ceremony Venue', receptionVenue:'Reception Venue',
    guestCount:'Guest Count', colors:'Colors', pastor:'Pastor', dressCode:'Dress Code',
    city:'City', rsvpDeadline:'RSVP Deadline'
  };
  grid.innerHTML = Object.keys(v).map(k => {
    const val = v[k];
    const filled = val && !/^\[.*\]$/.test(val); // bracketed = placeholder, not yet filled
    return `<div class="et-merge-field${filled?' filled':''}">
      <span class="et-merge-tag">{{${k}}}</span>
      <span class="et-merge-val" title="${escapeHtml(String(val))}">${escapeHtml(String(val))}</span>
    </div>`;
  }).join('');
}

function etFilterCat(cat){
  _etActiveCat = cat;
  renderEmailTemplates();
}

function copyEmailTemplate(idx){
  const sid = 'et_' + idx + '_s';
  const bid = 'et_' + idx + '_b';
  const sEl = document.getElementById(sid);
  const bEl = document.getElementById(bid);
  if (!sEl || !bEl) return;
  const text = 'Subject: ' + sEl.value + '\n\n' + bEl.value;
  navigator.clipboard.writeText(text).then(() => {
    etShowToast('Template copied to clipboard');
  }).catch(() => {
    covPrompt('Copy this template (Ctrl/Cmd+C):', {defaultValue: text});
  });
}

function etShowToast(msg){
  let t = document.querySelector('.et-copied-toast');
  if (t) t.remove();
  t = document.createElement('div');
  t.className = 'et-copied-toast';
  t.textContent = msg;
  document.body.appendChild(t);
  setTimeout(() => { if (t.parentNode) t.remove(); }, 2200);
}

