  caterer:{title:'Caterer Packet',extras:['Final guest count','Meal selections','Dietary restrictions','Vendor meal count','Service timeline','Cocktail hour notes','Reception meal notes','Cake / dessert notes','Kitchen access notes','Final payment notes']},
