    subTabs.innerHTML = `<div class="pkt-weekend-tabs">${WEEKEND_PACKET_TABS.map(([k,l]) => `<button type="button" class="${_pktWeekendKey===k?'active':''}" onclick="pktWeekendSet('${k}')">${escapeHtml(l)}</button>`).join('')}</div>`;
