const LOG_ATTIRE_COLS=[{k:'person',l:'Person'},{k:'item',l:'Item'},{k:'vendor',l:'Vendor'},{k:'size',l:'Size'},{k:'status',l:'Status',opts:['Not Started','Ordered','Fitting','Ready','Picked Up']},{k:'cost',l:'Cost',type:'number'},{k:'notes',l:'Notes'}];
const LOG_DECOR_COLS=[{k:'area',l:'Area',opts:['Ceremony','Cocktail','Reception','Lounge','Bar','Cake','Welcome','Bathroom','Other']},{k:'item',l:'Item'},{k:'qty',l:'Qty',type:'number'},{k:'status',l:'Status',opts:['To Buy','To Make','To Borrow','Ready']},{k:'source',l:'Source'},{k:'cost',l:'Cost',type:'number'},{k:'notes',l:'Notes'}];
const LOG_STATIONERY_COLS=[{k:'item',l:'Item',opts:['Save the Date','Invitation','RSVP Card','Details Card','Program','Menu','Place Card','Escort Card','Thank You','Other']},{k:'qty',l:'Qty',type:'number'},{k:'vendor',l:'Vendor'},{k:'cost',l:'Cost',type:'number'},{k:'status',l:'Status',opts:['Designing','Ordered','Received','Mailed','Complete']},{k:'notes',l:'Notes'}];
const LOG_GENERIC_COLS={attire:LOG_ATTIRE_COLS, decor:LOG_DECOR_COLS, stationery:LOG_STATIONERY_COLS};
function logGenericRowCells(dataKey, cols, r, i){
  let h='';
  cols.forEach(c => {
    if (c.opts) {
      const opts = c.opts.map(o => `<option${o===(r[c.k]||'')?' selected':''}>${escapeHtml(o)}</option>`).join('');
      h += `<td><select onchange="logUpd('${dataKey}',${i},'${c.k}',this.value)">${opts}</select></td>`;
    } else if (c.type === 'number') {
      h += `<td><input type="number" value="${r[c.k]||''}" oninput="logUpd('${dataKey}',${i},'${c.k}',this.value)"></td>`;
    } else {
      h += `<td><input value="${escapeHtml(r[c.k]||'')}" oninput="logUpd('${dataKey}',${i},'${c.k}',this.value)"></td>`;
    }
  });
  h += `<td>${plannerTrashButton("logDel('"+dataKey+"',"+i+")",'Delete')}</td>`;
  return h;
}
function logBuildTable(dataKey, cols, intro, blank){
  if (!Array.isArray(data[dataKey])) data[dataKey] = [];
  const engineKey = {attire:'logAttire', decor:'logDecor', stationery:'logStationery'}[dataKey];
  const label = dataKey.charAt(0).toUpperCase() + dataKey.slice(1);
  return `<div class="log-panel ued-panel"><h2>${label}</h2><div class="log-intro">${intro}</div><hr class="gold">${logHubPreviewBlock(engineKey, label)}</div>`;
}

