/* — Master Contact Directory — */
function contactMergeKey(row){
  const email = String(row.email || '').trim().toLowerCase();
  if (email) return 'email:' + email;
  const phone = String(row.phone || '').replace(/\D+/g,'');
  if (phone) return 'phone:' + phone;
  return 'name:' + [row.name,row.company,row.category].map(v=>String(v||'').trim().toLowerCase()).filter(Boolean).join('|');
}
function pushMergedContact(out, seen, row){
  if (!row || !String(row.name || row.email || row.phone || row.company || '').trim()) return;
  const key = contactMergeKey(row);
  if (!key || seen.has(key)) return;
  seen.add(key);
  out.push(row);
}
function masterContactRows(){
  if (!Array.isArray(data.contacts)) data.contacts = [];
  const rows = [], seen = new Set();
  data.contacts.forEach((r,i)=>pushMergedContact(rows,seen,{...r,_manualIndex:i,_source:'Manual',_sourcePage:'logistics',_sourceKey:'contacts'}));
  safeArray(data.guests).forEach((g,i)=>pushMergedContact(rows,seen,{name:g.name,role:g.role||g.side||'Guest',category:g.group||'Guest',email:g.email,phone:g.phone,company:g.household||'',emergency:false,lastContact:'',notes:[g.notes,g.table?'Table '+g.table:''].filter(Boolean).join(' | '),_source:'Guest List',_sourcePage:'guests',_sourceKey:'guests',_sourceIndex:i}));
  safeArray(data.vendors).forEach((v,i)=>pushMergedContact(rows,seen,{name:v.contact||v.name,role:v.cat||'Vendor',category:'Vendor',email:v.email,phone:v.phone,company:v.name,emergency:false,lastContact:'',notes:v.notes||'',_source:'Vendors',_sourcePage:'vendors',_sourceKey:'vendors',_sourceIndex:i}));
  safeArray(data.party).forEach((p,i)=>pushMergedContact(rows,seen,{name:p.name,role:p.role||'Wedding Party',category:p.side||'Wedding Party',email:p.email,phone:p.phone,company:'',emergency:false,lastContact:'',notes:p.notes||'',_source:'Wedding Party',_sourcePage:'party',_sourceKey:'party',_sourceIndex:i}));
  safeArray(data.appointments).forEach((a,i)=>pushMergedContact(rows,seen,{name:a.contact||a.vendor,role:a.category||'Appointment Contact',category:'Appointment',email:a.email||'',phone:a.phone||'',company:a.vendor||'',emergency:false,lastContact:a.date||'',notes:a.notes||'',_source:'Appointments',_sourcePage:'calendar',_sourceKey:'appointments',_sourceIndex:i}));
  safeArray(data.travelAccommodations).forEach((t,i)=>pushMergedContact(rows,seen,{name:t.guest,role:t.group||'Travel Guest',category:'Travel',email:t.email||'',phone:t.phone||'',company:t.hotel||'',emergency:false,lastContact:t.arrival||'',notes:t.notes||'',_source:'Travel & Accommodations',_sourcePage:'logistics',_sourceKey:'travelAccommodations',_sourceIndex:i}));
  safeArray(data.transportation).forEach((t,i)=>pushMergedContact(rows,seen,{name:t.driver,role:'Transportation',category:'Transportation',email:t.email||'',phone:t.phone||'',company:t.vehicle||'',emergency:false,lastContact:t.date||'',notes:t.notes||'',_source:'Transportation',_sourcePage:'logistics',_sourceKey:'transportation',_sourceIndex:i}));
  safeArray(data.locations).forEach((l,i)=>pushMergedContact(rows,seen,{name:l.contact||l.name,role:l.who||'Location Contact',category:'Location',email:l.email||'',phone:l.phone||'',company:l.name||'',emergency:false,lastContact:'',notes:l.parking||'',_source:'Maps & Directions',_sourcePage:'logistics',_sourceKey:'locations',_sourceIndex:i}));
  return rows;
}
function renderLogDirectory(){
  if (!Array.isArray(data.contacts)) data.contacts = [];
  const rows = masterContactRows();
  const emergencyCount = rows.filter(r => r.emergency).length;
  document.getElementById('log-content').innerHTML = `<div class="log-panel ued-panel">
    <h2>Master Contact Directory</h2>
    <div class="log-intro">${rows.length} contacts · ${emergencyCount} emergency contacts · Manual rows plus synced contacts from guests, vendors, wedding party, appointments, travel, transportation, and locations.</div>
    <hr class="gold">
    ${logHubPreviewBlock('contactsDirectory', 'Contact Directory')}
  </div>`;
  if (typeof cwpRenderTable === 'function' && cwpMountOnPanel('contactsDirectory')) cwpRenderTable('contactsDirectory');
  else paintLogHubPreview('contactsDirectory', { labelField: 'name', secondField: 'category', col1: 'Name', col2: 'Category' });
  standardizeTableTrashButtons(document.getElementById('panel-logistics'));
}

function logExportContacts(){
  const rows = masterContactRows();
  if (!rows.length) return;
  const headers = ['Name','Role','Category','Email','Phone','Company','Emergency','Last Contact','Notes'];
  const csvRows = [headers.join(',')];
  rows.forEach(r => {
    csvRows.push([r.name,r.role,r.category,r.email,r.phone,r.company,r.emergency?'Yes':'No',r.lastContact,r.notes].map(v => '"'+String(v||'').replace(/"/g,'""')+'"').join(','));
  });
  const blob = new Blob([csvRows.join('\n')], {type:'text/csv'});
  const a = document.createElement('a');
  a.href = URL.createObjectURL(blob);
  a.download = 'wedding-contacts.csv';
  a.click();
  URL.revokeObjectURL(a.href);
}

/* — Shared helpers for logistics tables — */
function syncWeddingWeekendToBudget(){
  if (!Array.isArray(data.budget)) return;
  const groups = {
    'Wedding Weekend Activities': safeArray(data.weekendTimeline).map((r,i)=>({
      name: r.event || `Wedding weekend activity ${i+1}`,
      amount: parseFloat(r.cost) || 0,
      due: r.date || '',
      notes: [r.host,r.group,r.location,r.notes].filter(Boolean).join(' | ')
    })).filter(r=>r.amount>0),
    'Travel & Accommodations': safeArray(data.travelAccommodations).map((r,i)=>({
      name: r.guest || r.hotel || `Travel accommodation ${i+1}`,
      amount: parseFloat(r.cost) || 0,
      due: r.arrival || r.departure || '',
      notes: [r.group,r.hotel,r.roomBlock,r.notes].filter(Boolean).join(' | ')
    })).filter(r=>r.amount>0),
    'Transportation': safeArray(data.transportation).map((r,i)=>({
      name: [r.pickup,r.dropoff].filter(Boolean).join(' to ') || r.driver || `Transportation route ${i+1}`,
      amount: parseFloat(r.cost) || 0,
      due: r.date || '',
      notes: [r.driver,r.vehicle,r.group,r.notes].filter(Boolean).join(' | ')
    })).filter(r=>r.amount>0)
  };
  Object.entries(groups).forEach(([catName, lines])=>{
    let cat = data.budget.find(c => String(c.cat || '').trim().toLowerCase() === catName.toLowerCase());
    if (!cat && lines.length) { cat = {cat:catName,target:0,planned:0,tip:'Auto-synced from Wedding Weekend Logistics.',items:[]}; data.budget.push(cat); }
    if (!cat) return;
    cat.items = safeArray(cat.items).filter(it => !it.weekendLine);
    lines.forEach(line => cat.items.push({name:line.name,budgeted:line.amount,cost:0,actual:0,status:'Pending',paid:false,due:line.due,notes:line.notes,weekendLine:true}));
    if (!cat.planned || cat.items.some(it=>it.weekendLine)) cat.planned = safeArray(cat.items).reduce((s,it)=>s+(parseFloat(it.budgeted||it.cost||0)||0),0);
  });
}
function logAfterChange(){
  if (typeof syncWeddingWeekendToBudget === 'function') syncWeddingWeekendToBudget();
  renderSmartCalendarIfActive();
  if (document.body.getAttribute('data-active-panel') === 'budget' && typeof renderBudget === 'function') renderWhenInputComplete(renderBudget);
  if (document.body.getAttribute('data-active-panel') === 'logistics') {
    if (typeof renderLogisticsStats === 'function') renderLogisticsStats();
    if (typeof renderLogisticsBulkBar === 'function') renderLogisticsBulkBar();
    if (typeof renderPageUxChrome === 'function') renderPageUxChrome('logistics');
    if (typeof renderContextSidebar === 'function' && document.body.classList.contains('context-sidebar-mode')) {
      renderContextSidebar('logistics');
    }
  }
}
const LOG_RECORD_EDITOR_KEYS = new Set(['weekendTimeline','travelAccommodations','hotelBlocks','transportation','vipCare','events','locations','contacts','vendorCompare','attire','decor','stationery','guests','vendors','party','appointments']);
function bindLogisticsRecordEditors(){
  const root = document.getElementById('logistics-view-host') || document.getElementById('log-content');
  if (!root || root.dataset.recordEditorBound === 'true') return;
  root.dataset.recordEditorBound = 'true';
  root.addEventListener('click', event => {
    if (event.target.closest('button,a,[data-no-record-editor],input[type="checkbox"],.col-resizer,.payment-plan-popover,.record-editor-overlay')) return;
    /* CWP ro tables open via cwpOpenEditor / bindRoPreviewInline; skip double binding */
    if (event.target.closest('.ro-preview, .cwp-table')) return;
    const row = event.target.closest('tr[data-log-key][data-row-index]');
    if (!row || !root.contains(row)) return;
    const key = row.dataset.logKey;
    const idx = Number(row.dataset.rowIndex);
    if (!LOG_RECORD_EDITOR_KEYS.has(key) || !Array.isArray(data[key]) || Number.isNaN(idx) || !data[key][idx]) return;
    event.preventDefault();
    event.stopPropagation();
    if (document.activeElement && typeof document.activeElement.blur === 'function') document.activeElement.blur();
    if (LOGISTICS_DRAWER_KEYS.has(key) && typeof rdOpenDrawer === 'function' && document.getElementById('record-drawer-body')) {
      rdOpenDrawer(key, idx);
    } else {
      openRecordEditor(key, idx);
    }
  }, true);
}
function logUpd(key, i, field, val){
  if (data[key] && data[key][i]) { data[key][i][field] = val; save(); logAfterChange(); }
}
/* Quiet updater for inputs that are typed into continuously (e.g. Vendor Comparison
   option boxes). Persists the value but does NOT re-render — a full re-render on every
   keystroke was destroying the focused <input>, which made the boxes feel untypeable.
   Save is debounced; derived UI (rankings, best-value/top-rated) refreshes on blur/
   change via vcmpQuoteBlur / vcmpNameChange, which already call renderVendorCompare(). */
let _quietSaveTimer = null;
function scheduleQuietSave(){
  clearTimeout(_quietSaveTimer);
  _quietSaveTimer = setTimeout(() => { try { save(); } catch (e) { console.warn('quiet save', e); } }, 500);
}
function logUpdQuiet(key, i, field, val){
  if (data[key] && data[key][i]) { data[key][i][field] = val; scheduleQuietSave(); }
}
function logDel(key, i){
  if (data[key]) {
    data[key].splice(i, 1);
    save();
    logAfterChange();
    if (key === 'vendorCompare' && document.getElementById('cwp-vendorCompare')) renderVendorCompare();
    else renderLogisticsPage();
  }
}
function logAdd(key, blank){
  if (!Array.isArray(data[key])) data[key] = [];
  if (LOG_RECORD_EDITOR_KEYS.has(key)) {
    if (typeof logisticsInlineAdd === 'function' && logisticsInlineAdd(key)) return;
    openRecordEditor(key);
    return;
  }
  if (typeof blank === 'string') blank = JSON.parse(blank.replace(/'/g,'"'));
  data[key].push(Object.assign({}, blank));
  save(); logAfterChange(); renderLogisticsPage();
}
function logSaveObj(key, field, val){
  if (!data[key] || typeof data[key] !== 'object') data[key] = {};
  data[key][field] = val;
  save(); logAfterChange();
}

