function renderHomecomingTab(){
  if (!Array.isArray(data.homecoming)) data.homecoming = [];
  if (!Array.isArray(data.nameChange)) data.nameChange = [];
  const checklistRows = data.homecoming;
  const nameRows = data.nameChange;
  const active = _homecomingSubTab === 'namechange' ? 'namechange' : 'checklist';
  const checklistDone = checklistRows.filter(r => r.status === 'Complete').length;
  const nameDone = nameRows.filter(r => r.done || r.status === 'Complete').length;

  let html = `<div class="rfl-panel ued-panel">
    <h2>Newlywed Homecoming</h2>
    <div class="rfl-intro">The week you return home is its own season. Use the Homecoming Checklist for the first practical rhythms of married life, and use Name Change for legal, financial, and account updates. These lists stay separate so one starter preset never fills the wrong table.</div>
    <hr class="gold">
    <div class="rfl-subtabs">
      <button type="button" class="rfl-subtab ${active==='checklist'?'active':''}" onclick="setHomecomingSubTab('checklist')">Homecoming Checklist</button>
      <button type="button" class="rfl-subtab ${active==='namechange'?'active':''}" onclick="setHomecomingSubTab('namechange')">Name Change</button>
    </div>
    <div class="m-stats rfl-homecoming-stats">
      <div class="m-stat"><div class="m-stat-top"><svg viewBox="0 0 24 24"><path d="M9 4h6l1 2h3v15H5V6h3l1-2Z"/><path d="M9 11h6M9 15h6"/></svg><span class="m-stat-label">Homecoming Items</span></div><div class="m-stat-val">${checklistRows.length}</div><div class="m-stat-sub">Practical after-wedding tasks</div></div>
      <div class="m-stat"><div class="m-stat-top"><svg viewBox="0 0 24 24"><path d="m5 12 4 4L19 6"/></svg><span class="m-stat-label">Homecoming Complete</span></div><div class="m-stat-val">${checklistDone}</div><div class="m-stat-sub">Finished items</div></div>
      <div class="m-stat"><div class="m-stat-top"><svg viewBox="0 0 24 24"><path d="M4 7h16M4 12h16M4 17h10"/></svg><span class="m-stat-label">Name-Change Tasks</span></div><div class="m-stat-val">${nameRows.length}</div><div class="m-stat-sub">Legal and account updates</div></div>
      <div class="m-stat"><div class="m-stat-top"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="9"/><path d="m8 12 2.5 2.5L16 9"/></svg><span class="m-stat-label">Name-Change Complete</span></div><div class="m-stat-val">${nameDone}</div><div class="m-stat-sub">Completed updates</div></div>
    </div>`;

  if (active === 'namechange') {
    html += `
    <div class="log-hub-preview"><div class="ued-table-wrap" id="log-preview-nameChange"></div>${hubPreviewFoot('honeymoon','nameChange','Name Change')}</div></div>`;
    document.getElementById('rfl-content').innerHTML = html;
    if (typeof cwpRenderTable === 'function' && cwpMountOnPanel('nameChange')) cwpRenderTable('nameChange');
    else paintLogHubPreview('nameChange', { labelField: 'task', secondField: 'status', col1: 'Task', col2: 'Status' });
    return;
  }

  html += `
    <div class="log-hub-preview"><div class="ued-table-wrap" id="log-preview-homecoming"></div>${hubPreviewFoot('honeymoon','homecoming','Homecoming Checklist')}</div></div>`;
  document.getElementById('rfl-content').innerHTML = html;
  if (typeof cwpRenderTable === 'function' && cwpMountOnPanel('homecoming')) cwpRenderTable('homecoming');
  else paintLogHubPreview('homecoming', { labelField: 'item', secondField: 'status', col1: 'Item', col2: 'Status' });
}

