/* ── 3-Minute Setup Wizard ── */
function openSetupWizard(){
  const m = document.getElementById('wizard-modal');
  if (!m) return;
  wizardInitThemeGrid();
  wizardWireStepInputs();
  const set = (id, val) => { const el = document.getElementById(id); if (el) el.value = val || ''; };
  set('wz-bride', data.setup.bride);
  set('wz-groom', data.setup.groom);
  set('wz-date', data.setup.date);
  set('wz-venue-ceremony', data.setup['venue-ceremony']);
  set('wz-venue-reception', data.setup['venue-reception']);
  set('wz-style', data.setup.style);
  set('wz-colors', data.setup.colors);
  set('wz-guests', data.setup.guests);
  set('wz-budget', data.setup.budget);
  wizardSyncThemeSelection(data.setup.theme);
  wizardSyncChipStates();
  wizardUpdateBudgetAnchor();
  wizardGoStep(1);
  m.classList.add('open');
}
function closeSetupWizard(markSeen){
  const m = document.getElementById('wizard-modal');
  if (m) m.classList.remove('open');
  if (markSeen){ ensureOnboardData().wizardSeen = true; save(); }
}
const WIZARD_STEPS = 6;
const WIZARD_PROGRESS_PCTS = [12, 28, 45, 62, 78, 100];
function wizardProgressPct(step){
  return WIZARD_PROGRESS_PCTS[Math.max(0, Math.min(step - 1, WIZARD_STEPS - 1))] || 12;
}
function wizardGoStep(n){
  n = Math.max(1, Math.min(WIZARD_STEPS, n));
  document.querySelectorAll('#wizard-modal .wizard-step').forEach(s => s.classList.remove('active'));
  const step = document.getElementById('wizard-step' + n);
  if (step) step.classList.add('active');
  for (let i = 1; i <= WIZARD_STEPS; i++) {
    const dot = document.getElementById('wz-dot' + i);
    if (dot) dot.classList.toggle('active', i <= n);
  }
  const fill = document.getElementById('wizard-progress-fill');
  const pct = wizardProgressPct(n);
  if (fill) fill.style.width = pct + '%';
  const lbl = document.getElementById('wizard-step-label');
  if (lbl) lbl.textContent = n >= WIZARD_STEPS ? 'Done · 100% set up' : ('Step ' + n + ' · ' + pct + '% complete');
  const hdr = document.getElementById('wizard-global-header');
  if (hdr) hdr.style.display = (n === 1 || n === WIZARD_STEPS) ? 'none' : '';
  if (n === 4) wizardSyncThemeSelection();
  if (n === 5) { wizardSyncChipStates(); wizardUpdateBudgetAnchor(); }
  if (n === WIZARD_STEPS) wizardRenderReady();
  const stepEl = document.getElementById('wizard-step' + n);
  const heading = stepEl && stepEl.querySelector('h4');
  if (heading) {
    requestAnimationFrame(function(){
      heading.setAttribute('tabindex', '-1');
      heading.focus({ preventScroll: true });
    });
  }
}
function wizardPreviewSeed(){
  const budgetVal = (document.getElementById('wz-budget') && document.getElementById('wz-budget').value || '').trim();
  const budgetTotal = parseFloat(budgetVal) || parseFloat(data.setup.budget) || 0;
  const willSeedTasks = !data.tasks.length;
  const willSeedTimeline = !data.timeline.length;
  const willSeedEssentials = !data.essentials.length;
  return {
    willSeedTasks,
    willSeedTimeline,
    willSeedEssentials,
    budgetCount: (data.budget && data.budget.length) || DEFAULT_BUDGET_CATS.length,
    taskCount: data.tasks.length + (willSeedTasks ? TASK_TIMELINE_PRESET.length : 0),
    timelineCount: data.timeline.length + (willSeedTimeline ? WDAY_TIMELINE_PRESET.length : 0),
    essentialsCount: data.essentials.length + (willSeedEssentials ? ESSENTIALS_PRESET.length : 0),
    budgetTotal
  };
}
function wizardPlannerHeadStartPct(p){
  let score = 5;
  if (p.taskCount) score += Math.min(6, Math.round(p.taskCount / 8));
  if (p.budgetCount) score += Math.min(4, Math.round(p.budgetCount / 4));
  if (p.timelineCount) score += 3;
  if (p.essentialsCount) score += 2;
  const bride = (document.getElementById('wz-bride') && document.getElementById('wz-bride').value || data.setup.bride || '').trim();
  if (bride) score += 1;
  return Math.max(12, Math.min(25, score));
}
function wizardGiftCheckSvg(){
  return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 6 9 17l-5-5"/></svg>';
}
function wizardRenderReady(){
  const p = wizardPreviewSeed();
  const bride = (document.getElementById('wz-bride') && document.getElementById('wz-bride').value || data.setup.bride || '').trim();
  const titleEl = document.getElementById('wz-ready-title');
  if (titleEl) titleEl.textContent = bride ? ('Your planner is ready, ' + bride) : 'Your planner is ready';
  const gifts = [];
  if (p.taskCount) {
    const taskText = p.willSeedTasks
      ? ('A <strong>12-month task timeline</strong>, pre-populated for your wedding date')
      : ('Your <strong>planning timeline</strong> with ' + p.taskCount + ' tasks');
    gifts.push(taskText);
  }
  if (p.budgetCount) {
    const money = p.budgetTotal ? (typeof fmt === 'function' ? fmt(p.budgetTotal) : ('$' + p.budgetTotal.toLocaleString())) : '';
    gifts.push('<strong>' + p.budgetCount + ' budget categories</strong>' + (money ? (', split from your ' + money) : ' ready to plan against'));
  }
  if (p.timelineCount && p.essentialsCount) gifts.push('A <strong>starter day-of timeline</strong> &amp; packing checklist');
  else if (p.timelineCount) gifts.push('A <strong>starter day-of timeline</strong>');
  else if (p.essentialsCount) gifts.push('A <strong>starter packing checklist</strong>');
  const list = document.getElementById('wz-ready-gifts');
  if (list) {
    list.innerHTML = gifts.length
      ? gifts.map(text => '<li><span class="wz-gift-ck">' + wizardGiftCheckSvg() + '</span><span>' + text + '</span></li>').join('')
      : '<li><span class="wz-gift-ck">' + wizardGiftCheckSvg() + '</span><span>Your planner is connected and ready — start wherever feels right.</span></li>';
  }
  const aheadPct = wizardPlannerHeadStartPct(p);
  const fill = document.getElementById('wz-ready-ahead-fill');
  const cap = document.getElementById('wz-ready-ahead-cap');
  if (fill) fill.style.width = aheadPct + '%';
  if (cap) cap.textContent = 'Setup done — you\'re ' + aheadPct + '% into your whole plan already';
}
function seedTaskTimelineSilent(){
  const phaseCounts = {};
  TASK_TIMELINE_PRESET.forEach(function(row){
    const phase = row[0], task = row[1], priority = row[2], assigned = row[3];
    const clean = normalizePlanPhase(phase);
    const n = phaseCounts[clean] || 0;
    phaseCounts[clean] = n + 1;
    const suggested = planPhaseBaseDate(clean, n);
    data.tasks.push({_id:nextRecordId('tasks'), task:task, cat:'', phase:clean, priority:priority||'Medium', assigned:assigned||'Both', date:'', suggestedDue:suggested, status:'Not Started', done:false, notes:'', subtasks:[]});
  });
}
function seedWdayTimelineSilent(){
  WDAY_TIMELINE_PRESET.forEach(r => data.timeline.push({...r}));
}
function seedEssentialsSilent(){
  ESSENTIALS_PRESET.forEach(([cat, item, assigned, location, notes]) => {
    data.essentials.push({cat, item, packed:false, assigned:assigned||'', location:location||'', notes:notes||''});
  });
}
function wizardApplyBudgetSplit(total){
  const cats = data.budget || [];
  if (!cats.length || !total) return;
  const perCat = Math.round(total / cats.length);
  cats.forEach(c => {
    c.planned = perCat;
    if (!c.target) c.target = Math.round(100 / cats.length);
  });
}
function wizardSeedPlannerData(){
  if (!data.tasks.length) seedTaskTimelineSilent();
  if (!data.timeline.length) seedWdayTimelineSilent();
  if (!data.essentials.length) seedEssentialsSilent();
  const total = parseFloat(data.setup.budget) || 0;
  if (total > 0) wizardApplyBudgetSplit(total);
}
async function wizardSaveFinish(){
  const v = id => { const el = document.getElementById(id); return el ? el.value : ''; };
  const guestVal = (v('wz-guests') || '').trim();
  const budgetVal = (v('wz-budget') || '').trim();
  if (budgetVal && !guestVal) {
    if (!(await covConfirm('You entered a budget but not an estimated guest count. Catering, seating, and per-guest costs work best with a target guest count. Save anyway?', { title: 'Guest count recommended', okText: 'Save anyway' }))) return;
  }
  data.setup.bride = v('wz-bride');
  data.setup.groom = v('wz-groom');
  data.setup.date = v('wz-date');
  data.setup['venue-ceremony'] = v('wz-venue-ceremony');
  data.setup['venue-reception'] = v('wz-venue-reception');
  data.setup.style = v('wz-style');
  data.setup.colors = v('wz-colors');
  const themeVal = (v('wz-theme') || '').trim();
  if (themeVal) {
    data.setup.theme = themeVal;
    if (typeof applyTheme === 'function') applyTheme(themeVal);
  }
  data.setup.guests = guestVal;
  data.setup.budget = budgetVal;
  wizardSeedPlannerData();
  ensureOnboardData().wizardSeen = true;
  save();
  if (typeof loadSetup === 'function') loadSetup();
  if (typeof renderSetupPage === 'function') renderSetupPage();
  closeSetupWizard(false);
  if (typeof applyProgressiveUnlock === 'function') applyProgressiveUnlock();
  save();
  showPanel('instructions');
}
/* Auto-open the wizard once, on a brand-new (empty) planner. */
function maybeAutoOpenWizard(){
  const ob = ensureOnboardData();
  if (ob.wizardSeen) return;
  const blank = !data.setup.bride && !data.setup.groom && !data.setup.date;
  if (blank) setTimeout(openSetupWizard, 400);
  else ob.wizardSeen = true; // existing data — don't nag
}

