function pageScriptureAnchor(panel) {
  if (!panel) return null;
  /* Redesign: verse sits with couple meta under .rd-pagehead (not after whole .rd-page). */
  const rdMeta = panel.querySelector('.rd-page-meta');
  if (rdMeta) return rdMeta;
  const pagehead = panel.querySelector('.rd-pagehead');
  if (pagehead) return pagehead;
  const mast = panel.querySelector(':scope > .m-mast-wrap');
  if (mast) return mast;
  const selectors = [
    '#dash-v4-root header.ued-mast',
    '#dash-v4-root .ued-mast',
    ':scope > header.ued-mast',
    ':scope > .ued-page > header.ued-mast',
    ':scope > .ued-page > .ued-mast',
    ':scope > .inst-title-wrap',
    ':scope > .tasks-title-wrap',
    ':scope > [class*="-title-wrap"]',
    ':scope > [class*="-hero"]',
    ':scope > .smart-page-title-wrap',
    ':scope > .contracts-hero',
    ':scope > .m-stats',
    ':scope > .ued-page'
  ];
  for (let i = 0; i < selectors.length; i++) {
    const el = panel.querySelector(selectors[i]);
    if (el) return el;
  }
  return panel.firstElementChild;
}
function relocateStaticScriptureFooters(panel, anchor) {
  if (!panel || !anchor) return;
  panel.querySelectorAll(':scope [class*="-scripture-footer"]:not(.page-scripture-footer)').forEach(el => {
    if (el !== anchor && !anchor.contains(el)) anchor.insertAdjacentElement('afterend', el);
  });
}
function injectPageScripture(panelId) {
  const panel = document.getElementById('panel-' + panelId);
  if (!panel) return;
  const s = PAGE_SCRIPTURES[panelId];
  if (!s) return;
  const old = panel.querySelector('.page-scripture-footer');
  if (old) old.remove();
  panel.querySelectorAll('.ued-scripture').forEach(el => el.remove());
  const anchor = pageScriptureAnchor(panel);
  relocateStaticScriptureFooters(panel, anchor);
  const footer = document.createElement('div');
  footer.className = 'page-scripture-footer';
  footer.innerHTML = `<span class="psf-text"><em>${escapeHtml(s.verse)}</em><cite>${escapeHtml(s.ref)}</cite></span>`;
  if (anchor) anchor.insertAdjacentElement('afterend', footer);
  else panel.prepend(footer);
}

/** Phase 3 — run the 10-point checklist against a panel (dev audit helper). */
function phase3AuditPage(panelId){
  const panel = document.getElementById('panel-' + panelId);
  if (!panel) return { panelId, error: 'panel not found' };
  const mast = !!panel.querySelector(':scope > .m-mast-wrap');
  const dupSel = ':scope > .ued-mast .ued-title, :scope > .ued-page > .ued-mast .ued-title, :scope > .page-header, :scope > .dash-title';
  const dup = panel.querySelector(dupSel);
  const dupTitle = !!(dup && dup.offsetParent !== null && getComputedStyle(dup).display !== 'none');
  const cards = [...panel.querySelectorAll('.ued-panel, .ued-table-card')].slice(0, 12);
  const cardIssues = cards.filter(c => {
    const cs = getComputedStyle(c);
    return (cs.boxShadow && cs.boxShadow !== 'none') || (parseFloat(cs.borderRadius) || 0) > 12;
  }).length;
  const hubPrimaries = panel.querySelectorAll('.db-edit-btn.primary, .db-edit-btn.ued-btn.primary, button.ued-btn.primary[onclick*="openDataHub"]').length;
  const inlineScripture = panel.querySelectorAll('.tasks-scripture-card, [class*="scripture-card"]:not(.page-scripture-footer), :scope > .m-soft .m-verse, :scope > .m-block .m-verse').length;
  const staticScriptureFooters = panel.querySelectorAll('[class*="-scripture-footer"]:not(.page-scripture-footer)').length;
  const legacyButtons = panel.querySelectorAll('.smart-search-actions .btn-forest, .smart-search-actions .btn-outline, .app-search-actions .btn-forest').length;
  const pageScripture = !!panel.querySelector('.page-scripture-footer');
  const legacyProgress = panel.querySelectorAll('.ux-goal-bar, .progress-track:not(.ued-track)').length;
  return {
    panelId,
    masthead: mast,
    dupTitleVisible: dupTitle,
    cardSamples: cards.length,
    cardStyleIssues: cardIssues,
    hubPrimaryConflicts: hubPrimaries,
    inlineScripturePanels: inlineScripture,
    staticScriptureFooters: staticScriptureFooters,
    legacyToolbarButtons: legacyButtons,
    injectPageScripture: pageScripture,
    legacyProgressBars: legacyProgress,
    pass: mast && !dupTitle && !cardIssues && !hubPrimaries && !inlineScripture && !legacyProgress && !staticScriptureFooters && !legacyButtons
  };
}
function phase3AuditBatch(ids){
  const list = ids || ['dashboard','budget','guests','vendors','payments','tasks','calendar','appointments','prayer','counseling','ceremony','catering','entertainment','shotlist','mood','honeymoon','logistics','data-hub'];
  return list.map(id => { showPanel(id, true); return phase3AuditPage(id); });
}
function phase3AuditDataHub(categories){
  if (typeof DATA_HUB_REGISTRY === 'undefined') return [];
  const list = categories || Object.keys(DATA_HUB_REGISTRY);
  return list.map(catId => {
    setDataHubContext(catId);
    renderDataHub();
    if (typeof injectMasthead === 'function') injectMasthead('data-hub');
    if (typeof injectPageScripture === 'function') injectPageScripture('data-hub');
    const base = phase3AuditPage('data-hub');
    return Object.assign({ category: catId, table: _dataHub.table }, base);
  });
}
function spacingAuditPage(panelId){
  const panel = document.getElementById('panel-' + panelId);
  if (!panel) return { panelId, error: 'panel not found' };
  const padNorm = (v) => parseFloat(v) || 0;
  const root = getComputedStyle(document.documentElement);
  const expectPanel = padNorm(root.getPropertyValue('--planner-panel-padding')) || 24;
  const expectHeadX = padNorm(root.getPropertyValue('--planner-table-head-x')) || expectPanel;
  const shells = [...panel.querySelectorAll(':scope .ued-panel, :scope .ued-table-card, :scope [class*="-card"]:not([class*="-card-head"]):not([class*="-card-icon"]):not([class*="-card-title"]):not([class*="-card-grid"]):not([class*="-card-foot"]):not([class*="-card-pager"]):not(.hub-record-card):not(.hub-record-card-badge)')].filter(el => {
    if (el.closest('.hub-record-card-grid')) return false;
    if (el.closest('.record-editor-shell')) return false;
    return el.offsetParent !== null || panel.contains(el);
  }).slice(0, 10);
  const samples = shells.map(el => {
    const cs = getComputedStyle(el);
    const isTable = el.classList.contains('ued-table-card');
    const head = el.querySelector(':scope > .ued-table-head, :scope > [class*="-card-head"], :scope > .m-head');
    const hcs = head ? getComputedStyle(head) : null;
    return {
      tag: el.tagName.toLowerCase(),
      cls: (el.className || '').split(/\s+/).slice(0, 3).join(' '),
      isTable,
      padTop: cs.paddingTop,
      padLeft: cs.paddingLeft,
      marginBottom: cs.marginBottom,
      headMarginBottom: hcs ? hcs.marginBottom : null
    };
  });
  const contentPads = samples.filter(s => !s.isTable).map(s => padNorm(s.padTop));
  const tableShells = samples.filter(s => s.isTable);
  const padSpread = contentPads.length ? Math.max(...contentPads) - Math.min(...contentPads) : 0;
  const tablePadOk = tableShells.every(s => padNorm(s.padTop) === 0 && padNorm(s.padLeft) === 0);
  const contentPadOk = !contentPads.length || padSpread <= 2;
  return {
    panelId,
    expectPanelPx: expectPanel,
    expectHeadXPx: expectHeadX,
    samples,
    tablePadOk,
    contentPadOk,
    pass: tablePadOk && contentPadOk
  };
}
function spacingAuditBatch(ids){
  const list = ids || ['dashboard','budget','guests','vendors','payments','tasks','calendar','appointments','prayer','counseling','ceremony','catering','entertainment','shotlist','mood','honeymoon','logistics','contracts','gifts','notes','venue','tables','packets','emails'];
  return list.map(id => { showPanel(id, true); return spacingAuditPage(id); });
}
window.phase3AuditPage = phase3AuditPage;
window.phase3AuditBatch = phase3AuditBatch;
window.phase3AuditDataHub = phase3AuditDataHub;
window.spacingAuditPage = spacingAuditPage;
window.spacingAuditBatch = spacingAuditBatch;

