function renderSetupPage() {
  const panel = document.getElementById('panel-setup');
  if (!panel) return;
  placePlannerPreferences();
  loadSetup();
  loadLocaleSettings();
  const s = data.setup || {};
  const dateObj = setupDateParts(s.date);
  const today = new Date();
  today.setHours(0,0,0,0);
  const diff = dateObj ? Math.ceil((dateObj - today) / 86400000) : null;
  const daysEl = document.getElementById('setup-stat-days');
  const dateEl = document.getElementById('setup-stat-date');
  if (daysEl) daysEl.textContent = dateObj ? Math.max(diff, 0) : '—';
  if (dateEl) dateEl.textContent = dateObj ? fmtDate(s.date, 'long') : 'Set your wedding date';
  const dateNote = document.getElementById('setup-date-note');
  if (dateNote) dateNote.textContent = dateObj ? (diff >= 0 ? Math.max(diff,0) + ' day' + (Math.max(diff,0)===1?'':'s') + ' from today' : 'Your covenant celebration date has passed.') : 'This powers your countdown and timeline pacing.';

  const engagedNote = document.getElementById('setup-engaged-note');
  const engagedObj = setupDateParts(s.engaged);
  if (engagedNote) engagedNote.textContent = engagedObj ? fmtDate(s.engaged, 'long') : 'Capture the beginning of your covenant journey.';

  const taskDone = data.tasks.filter(t => t.status === 'Complete').length;
  const taskTotal = data.tasks.length;
  const taskPct = taskTotal ? Math.round(taskDone / taskTotal * 100) : 0;
  const taskEl = document.getElementById('setup-stat-tasks');
  const taskSubEl = document.getElementById('setup-stat-task-sub');
  if (taskEl) taskEl.textContent = taskDone;
  if (taskSubEl) taskSubEl.textContent = taskTotal ? taskPct + '% of total' : 'Add tasks to track progress';

  const vendorsBooked = data.vendors.filter(v => ['Booked','Paid','Complete'].includes(v.status)).length;
  const vendorTotal = data.vendors.length;
  const vendorPct = vendorTotal ? Math.round(vendorsBooked / vendorTotal * 100) : 0;
  const vendorEl = document.getElementById('setup-stat-vendors');
  const vendorSubEl = document.getElementById('setup-stat-vendor-sub');
  if (vendorEl) vendorEl.textContent = vendorsBooked;
  if (vendorSubEl) vendorSubEl.textContent = vendorTotal ? vendorPct + '% of tracked vendors' : 'Start your vendor list';

  const guestCount = data.guests.length;
  const guestEl = document.getElementById('setup-stat-guests');
  const guestSubEl = document.getElementById('setup-stat-guest-sub');
  if (guestEl) guestEl.textContent = guestCount;
  if (guestSubEl) guestSubEl.textContent = guestCount ? 'Guests currently in your list' : 'Let’s build your list!';

  const checklist = [
    { label: 'Add couple names', done: !!((s.bride||'').trim() && (s.groom||'').trim()) },
    { label: 'Set wedding date', done: !!s.date },
    { label: 'Choose ceremony venue', done: !!(s['venue-ceremony']||'').trim() },
    { label: 'Choose reception venue', done: !!(s['venue-reception']||'').trim() },
    { label: 'Add total budget', done: parseFloat(s.budget) > 0 },
    { label: 'Set target guest count', done: parseInt(s.guests || '0', 10) > 0 },
    { label: 'Choose wedding style', done: !!(s.style||'').trim() },
    { label: 'Set time zone', done: !!(s.timezone||'').trim() },
    { label: 'Add marriage verse', done: !!(s.verse||'').trim() },
    { label: 'Write mission statement', done: !!(s.mission||'').trim() },
    { label: 'Upload wedding photo', done: !!s.photo }
  ];
  const listEl = document.getElementById('setup-checklist');
  if (listEl) {
    listEl.innerHTML = checklist.map(item => `
      <div class="setup-check-item ${item.done ? 'done' : ''}">
        <span class="setup-check-mark"><svg viewBox="0 0 24 24"><path d="M5 12.5 9.2 17 19 7.5"/></svg></span>
        <span class="setup-check-label">${escapeHtml(item.label)}</span>
        <span class="setup-check-state">${item.done ? 'Complete' : 'Pending'}</span>
      </div>`).join('');
  }
  const completed = checklist.filter(i => i.done).length;
  const note = document.getElementById('setup-side-note');
  if (note) {
    note.innerHTML = `<strong>${completed >= checklist.length ? 'Your setup foundation is beautifully in place.' : 'You’re on your way to an unforgettable celebration!'}</strong><p>${completed} of ${checklist.length} setup steps are complete. Finish the remaining details above to build a beautiful plan together.</p>`;
  }
  renderSetupPhotoBox();
  renderProfileDrawerPhoto();
  if (typeof renderMarriageLicense === 'function') renderMarriageLicense();
  renderTopbarPhoto();
  renderMenuVisibilitySettings();
  renderEssentialsHubHosts();
  /* All.dc 18b — Clear History lives in Wedding Setup danger zone, not on the log. */
  let danger = document.getElementById('setup-history-danger');
  if (!danger && panel) {
    danger = document.createElement('section');
    danger.id = 'setup-history-danger';
    danger.className = 'm-block rd-setup-danger';
    danger.innerHTML = `
      <div class="m-head">Danger zone</div>
      <p class="v4-help-note">Irreversible actions. Clearing history removes the readable log and undo/redo snapshots — it does not delete guests, budget lines, or any other planner content.</p>
      <div class="rd-setup-danger__grid">
        <div class="rd-setup-danger__cell">
          <div class="rd-setup-danger__title">Clear Planner History</div>
          <p>Drops up to ${HISTORY_LOG_LIMIT} log entries and ${HISTORY_SNAPSHOT_LIMIT} undo snapshots. Download a backup first if you may need the record later.</p>
          <div class="rd-setup-danger__row">
            <button type="button" class="btn btn-danger" onclick="clearPlannerHistory()">Clear History</button>
            <button type="button" class="m-btn" onclick="showPanel('history', true)">Open Planner History</button>
          </div>
        </div>
      </div>`;
    panel.appendChild(danger);
  }
}

/* ════════════════════════════════════════════════
   HELPERS — TABLE CELLS
════════════════════════════════════════════════ */
function inp(val, type='text', placeholder='') {
  val = escapeHtml(val);
  return `<input type="${type}" value="${val}" placeholder="${placeholder}">`;
}

function sel(val, options) {
  let s = '<select>';
  options.forEach(o => {
    const sel = o === val ? ' selected' : '';
    s += `<option${sel}>${o}</option>`;
  });
  return s + '</select>';
}

function chk(val) {
  return `<input type="checkbox" ${val ? 'checked' : ''} style="width:auto">`;
}

function statusBadge(v) {
  if (typeof statusPill === 'function') return statusPill(v || '—', 'status');
  if (typeof pill === 'function') {
    const scheme = typeof pillSchemeFor === 'function' ? pillSchemeFor(v, 'status') : 'neutral';
    return pill(v || '—', scheme);
  }
  if (!v) return '<span class="badge badge-grey">—</span>';
  const map = {
    'Booked':'forest','Paid':'green','Complete':'green',
    'Not Paid':'red','Contacted':'amber','Quote Received':'amber',
    'Yes':'green','No':'red','Pending':'grey','Maybe':'amber',
    'Not Started':'grey','In Progress':'amber','Completed':'green','Scheduled':'forest',
    'Deposit Paid':'amber','Partially Paid':'amber','Researching':'grey'
  };
  const cls = map[v] || 'grey';
  return `<span class="badge badge-${cls}">${v}</span>`;
}

const VENDOR_STATUS = ['Researching','Contacted','Quote Received','Considering','Meeting Scheduled','Tasting Scheduled','Booked','Paid','Complete','Not Booked'];
const PAYMENT_STATUS = ['Not Paid','Paid','Partially Paid','Payment Due'];
const RSVP_STATUS = ['Pending','Accepted','Declined','Maybe'];
