    appointments: () => pick(row.title, row.vendor, 'Appointment'),
    plan: () => pick(row.task, row.phase, 'Planning item'),
    gifts: () => pick(row.from, row.name, row.desc, 'Gift'),
    contracts: () => pick(row.name, row.vendor, 'Contract'),
    rentals: () => pick(row.item, row.name, 'Rental'),
    menu: () => pick(row.name, row.item, row.dish, 'Menu item'),
    beverages: () => pick(row.name, row.item, 'Beverage'),
