/* Primary tracker tabs (always visible). Remaining schemas appear under "More categories". */
const VENDOR_PRIMARY_TAB_KEYS = ['venue','catering','photo','video','florals','music','hair','makeup','attire','cake','coord','foodTruck'];

function vendorCategorySchemaList(){ return VENDOR_CATEGORY_SCHEMAS; }
function vendorCategoryLabels(){ return VENDOR_CATEGORY_SCHEMAS.map(s => s.label); }
function vendorCategoryByKey(key){ return VENDOR_CATEGORY_SCHEMAS.find(s => s.key === key) || null; }
function _vendorCatNorm(s){ return String(s || '').trim().toLowerCase().replace(/&/g,'and').replace(/[^a-z0-9]+/g,' ').replace(/\s+/g,' ').trim(); }
function vendorCategorySchemaFromLabel(label){
  const raw = String(label || '').trim();
  if (!raw) return null;
  const exact = VENDOR_CATEGORY_SCHEMAS.find(s => s.label === raw);
  if (exact) return exact;
  const n = _vendorCatNorm(raw);
  return VENDOR_CATEGORY_SCHEMAS.find(s => {
    if (_vendorCatNorm(s.label) === n || s.key === n) return true;
    return (s.aliases || []).some(a => _vendorCatNorm(a) === n || n.includes(_vendorCatNorm(a)) || _vendorCatNorm(a).includes(n));
  }) || null;
}
function normalizeVendorCategoryLabel(cat){
  const schema = vendorCategorySchemaFromLabel(cat);
  return schema ? schema.label : (String(cat || '').trim() || '');
}
function isLegacyBeautyCategory(cat){
  const n = _vendorCatNorm(cat);
  if (!n) return false;
  if (n === 'beauty' || n === 'attire') return true;
  if (n.includes('beauty') && n.includes('attire')) return true;
  return false;
}
function inferSplitBeautyCategory(vendor){
  const v = vendor && typeof vendor === 'object' ? vendor : { cat: vendor || '' };
  const hay = [v.cat, v.name, v.contact, v.notes, v.pros, v.cons].filter(Boolean).join(' ').toLowerCase();
  const oldNorm = _vendorCatNorm(v.cat);
  if (oldNorm && !isLegacyBeautyCategory(v.cat)) {
    const schema = vendorCategorySchemaFromLabel(v.cat);
    if (schema) return schema.label;
  }
  if (/\b(dress|gown|tux|tuxedo|suit|bridal|boutique|formalwear|alteration|fitting|veil)\b/.test(hay)) return 'Attire & Formalwear';
  if (/\b(makeup|mua|cosmetic|airbrush|lashes|lash)\b/.test(hay)) return 'Makeup';
  if (/\b(hair|stylist|salon|updo|extensions|barber|braid)\b/.test(hay)) return 'Hair & Styling';
  if (oldNorm === 'attire' || (oldNorm.includes('attire') && !oldNorm.includes('beauty'))) return 'Attire & Formalwear';
  if (oldNorm.includes('makeup')) return 'Makeup';
  if (oldNorm.includes('hair')) return 'Hair & Styling';
  return 'Hair & Styling';
}
function migrateBeautyVendorAttrs(vendor, newLabel){
  const attrs = ensureVendorAttrs(vendor);
  const legacy = { ...attrs };
  const schema = vendorCategorySchemaFromLabel(newLabel);
  const schemaKey = schema ? schema.key : '';
  if (schemaKey === 'hair' || schemaKey === 'makeup') {
    ['trial', 'partyCount', 'onLocation'].forEach(k => {
      if (legacy[k] != null && attrs[k] == null) attrs[k] = legacy[k];
    });
  }
  if (schemaKey === 'makeup' && legacy.touchups != null && attrs.touchups == null) attrs.touchups = legacy.touchups;
  if (schemaKey === 'attire' && legacy.partyCount != null && attrs.partyOutfits == null) attrs.partyOutfits = legacy.partyCount;
}
function migrateLegacyBeautyVendor(vendor){
  if (!vendor || typeof vendor !== 'object') return;
  if (!isLegacyBeautyCategory(vendor.cat)) {
    const normalized = normalizeVendorCategoryLabel(vendor.cat);
    if (normalized && normalized !== vendor.cat) vendor.cat = normalized;
    return;
  }
  const next = inferSplitBeautyCategory(vendor);
  migrateBeautyVendorAttrs(vendor, next);
  vendor.cat = next;
}
function migrateLegacyBeautyCompareCategory(row){
  if (!row || !row.category || !isLegacyBeautyCategory(row.category)) return;
  row.category = inferSplitBeautyCategory({ cat: row.category, name: row.decision || '', notes: '' });
}
function vendorCategoryMatches(cat, labelOrKey){
  const a = vendorCategorySchemaFromLabel(cat);
  const b = vendorCategorySchemaFromLabel(labelOrKey) || vendorCategoryByKey(labelOrKey);
  if (a && b) return a.key === b.key;
  return _vendorCatNorm(cat) === _vendorCatNorm(labelOrKey);
}
function vendorTrackerCatKey(){
  if (!data.setup || typeof data.setup !== 'object') data.setup = {};
  const k = data.setup.vendorTrackerCat || 'all';
  if (k === 'all') return 'all';
  return vendorCategoryByKey(k) ? k : 'all';
}
function vendorTrackerSchema(){
  const k = vendorTrackerCatKey();
  return k === 'all' ? null : vendorCategoryByKey(k);
}
function ensureVendorAttrs(v){
  if (!v || typeof v !== 'object') return {};
  if (!v.attrs || typeof v.attrs !== 'object' || Array.isArray(v.attrs)) v.attrs = {};
  return v.attrs;
}
function vendorAttrGet(v, fieldId){
  if (!v || !fieldId) return '';
  const attrs = ensureVendorAttrs(v);
  return attrs[fieldId] == null ? '' : attrs[fieldId];
}
function vendorAttrSet(v, fieldId, value){
  if (!v || !fieldId) return;
  const attrs = ensureVendorAttrs(v);
  attrs[fieldId] = value;
}
function vendorAttrDisplay(field, value){
  if (!field) return value == null || value === '' ? '—' : String(value);
  if (field.type === 'bool') {
    if (value === true || value === 'true' || value === 1 || value === '1' || value === 'yes') return '✓';
    if (value === false || value === 'false' || value === 0 || value === '0' || value === 'no') return '—';
    return value == null || value === '' ? '—' : String(value);
  }
  if (field.type === 'money') {
    const n = parseFloat(value);
    return isNaN(n) || value === '' || value == null ? '—' : '$' + n.toLocaleString();
  }
  if (value == null || value === '') return '—';
  return String(value);
}
function vendorAttrIsTruthy(value){
  return value === true || value === 'true' || value === 1 || value === '1' || value === 'yes' || value === 'Yes';
}
function vendorAttrNum(value){
  const n = parseFloat(value);
  return isNaN(n) ? null : n;
}
function setVendorTrackerCat(key){
  if (!data.setup || typeof data.setup !== 'object') data.setup = {};
  data.setup.vendorTrackerCat = (key === 'all' || vendorCategoryByKey(key)) ? key : 'all';
  if (key !== 'all' && !VENDOR_PRIMARY_TAB_KEYS.includes(key)) {
    data.setup.vendorCatTabsMoreOpen = true;
  }
  save();
  renderVendorCategoryTabs();
  if (typeof cwpRenderTable === 'function' && cwpMountOnPanel('vendors')) cwpRenderTable('vendors');
  else if (typeof renderVendors === 'function') renderVendors();
  requestAnimationFrame(() => {
    const panel = document.getElementById('panel-vendors');
    if (typeof makeColumnsResizable === 'function') makeColumnsResizable(panel || document);
  });
}
function vendorCatTabsMoreOpen(){
  return !!(data.setup && data.setup.vendorCatTabsMoreOpen);
}
function toggleVendorCatTabsMore(){
  if (!data.setup || typeof data.setup !== 'object') data.setup = {};
  data.setup.vendorCatTabsMoreOpen = !vendorCatTabsMoreOpen();
  save();
  renderVendorCategoryTabs();
}
function _vendorCatTabBtn(t, active){
  return `<button type="button" class="vnd-cat-tab${t.key === active ? ' on' : ''}" data-cat="${escapeHtml(t.key)}" onclick="setVendorTrackerCat('${escapeHtml(t.key)}')">${escapeHtml(t.label)}</button>`;
}
function renderVendorCategoryTabs(){
  const host = document.getElementById('vendor-cat-tabs');
  if (!host) return;
  const active = vendorTrackerCatKey();
  const primary = [{ key:'all', label:'All' }].concat(
    VENDOR_CATEGORY_SCHEMAS.filter(s => VENDOR_PRIMARY_TAB_KEYS.includes(s.key)).map(s => ({ key:s.key, label:s.label }))
  );
  const more = VENDOR_CATEGORY_SCHEMAS.filter(s => !VENDOR_PRIMARY_TAB_KEYS.includes(s.key)).map(s => ({ key:s.key, label:s.label }));
  if (active !== 'all' && more.some(t => t.key === active) && !vendorCatTabsMoreOpen()) {
    if (!data.setup || typeof data.setup !== 'object') data.setup = {};
    data.setup.vendorCatTabsMoreOpen = true;
  }
  host.innerHTML = primary.map(t => _vendorCatTabBtn(t, active)).join('');
  const moreHost = document.getElementById('vendor-cat-tabs-more');
  if (moreHost) {
    const open = vendorCatTabsMoreOpen();
    moreHost.classList.toggle('open', open);
    moreHost.innerHTML = more.map(t => _vendorCatTabBtn(t, active)).join('');
  }
  const toggleBtn = document.getElementById('vendor-cat-tabs-toggle');
  if (toggleBtn) {
    const open = vendorCatTabsMoreOpen();
    toggleBtn.classList.toggle('open', open);
    toggleBtn.setAttribute('aria-expanded', open ? 'true' : 'false');
    toggleBtn.innerHTML = `More categories <span class="vnd-cat-chevron" aria-hidden="true">${open ? '▴' : '▾'}</span>`;
  }
}
function vendorAttrColumnDefs(schema){
  if (!schema || !schema.fields) return [];
  return schema.fields.map(f => {
    const base = {
      key: 'attrs.' + f.id,
      label: f.label,
      min: f.type === 'bool' ? 90 : 120,
      filter: false,
      render: (r, n, e) => {
        const val = vendorAttrGet(r, f.id);
        const id = r._id;
        if (f.type === 'bool') {
          return `<input type="checkbox" ${vendorAttrIsTruthy(val) ? 'checked' : ''} onchange="cwpEditAttr('${e}','${id}','${f.id}',this.checked)">`;
        }
        if (f.type === 'number' || f.type === 'money') {
          return `<input type="number" value="${escapeHtml(val === 0 || val ? String(val) : '')}" placeholder="${f.type === 'money' ? '$' : ''}" oninput="cwpEditAttr('${e}','${id}','${f.id}',this.value)">`;
        }
        if (f.type === 'select') {
          const opts = ['<option value="">—</option>'].concat((f.options || []).map(o => `<option value="${escapeHtml(o)}"${String(val) === o ? ' selected' : ''}>${escapeHtml(o)}</option>`));
          return `<select onchange="cwpEditAttr('${e}','${id}','${f.id}',this.value)">${opts.join('')}</select>`;
        }
        return `<textarea rows="1" oninput="cwpEditAttr('${e}','${id}','${f.id}',this.value);cwpGrow(this)">${escapeHtml(val == null ? '' : String(val))}</textarea>`;
      }
    };
    if (f.type === 'bool') base.type = 'checkbox';
    else if (f.type === 'number' || f.type === 'money') base.type = 'number';
    else base.type = 'text';
    return base;
  });
}
function vendorSharedColumns(){
  return [
    {key:'name',    label:'Vendor',   type:'text', min:170,
      render:(r,n,e)=>'<div class="cwp-vname">'+(typeof pinButtonHtml==='function'?pinButtonHtml('vendors', r._id, r.name||'Vendor', 'vendors'):'')+(typeof vendorCategoryIcon==='function'?vendorCategoryIcon(r.cat,r.status):'')+'<textarea rows="1" oninput="cwpEdit(\''+e+'\',\''+r._id+'\',\'name\',this.value);cwpGrow(this)">'+escapeHtml(r.name||'')+'</textarea></div>'},
    {key:'cat',     label:'Category', type:'select', filter:true, min:150, options:vendorCategoryLabels(), blank:true,
      render:(r,n,e)=>{
        const cur = r.cat || '';
        const labels = vendorCategoryLabels();
        const opts = ['<option value="">—</option>'].concat(labels.map(l => `<option value="${escapeHtml(l)}"${l===cur?' selected':''}>${escapeHtml(l)}</option>`));
        if (cur && !labels.includes(cur)) opts.push(`<option value="${escapeHtml(cur)}" selected>${escapeHtml(cur)}</option>`);
        return `<select onchange="cwpEdit('${e}','${r._id}','cat',this.value)">${opts.join('')}</select>`;
      }},
    {key:'phone',   label:'Phone',    type:'text',   min:130},
    {key:'email',   label:'Email',    type:'text',   min:170},
    {key:'contact', label:'Contact',  type:'text',   min:120},
    {key:'quote',   label:'Quote',    type:'money'},
    {key:'deposit', label:'Deposit',  type:'money'},
    {key:'balance', label:'Balance',  type:'computed', compute:(r)=>'$'+Math.max(0,(+r.quote||0)-(+r.deposit||0)).toLocaleString(undefined,{maximumFractionDigits:0})},
    {key:'status',  label:'Status',   type:'status', enum:'vendorStatus', filter:true, min:150},
    {key:'rating',  label:'Rating',   type:'stars',  min:120},
    {key:'contract',label:'Contract', type:'checkbox'},
    {key:'pros',    label:'Pros',     type:'text',   min:150},
    {key:'cons',    label:'Cons',     type:'text',   min:150},
    {key:'review',  label:'Review',   type:'review', min:170},
    {key:'notes',   label:'Notes',    type:'longtext'}
  ];
}
function buildVendorTableColumns(){
  const schema = vendorTrackerSchema();
  const cols = vendorSharedColumns();
  if (schema) return cols.concat(vendorAttrColumnDefs(schema));
  return cols;
}

/* ════════════════════════════════════════════════
   VENDORS
════════════════════════════════════════════════ */
function addVendorRow() {
  const schema = vendorTrackerSchema();
  const seed = { attrs:{} };
  if (schema) seed.cat = schema.label;
  else {
    const catKey = typeof vendorTrackerCatKey === 'function' ? vendorTrackerCatKey() : 'all';
    const catDef = typeof vendorCategoryByKey === 'function' ? vendorCategoryByKey(catKey) : null;
    if (catDef && catDef.label) seed.cat = catDef.label;
  }
  if (typeof rdOpenNewInDrawer === 'function' && rdOpenNewInDrawer('vendors', seed)) return;
  if (document.body.getAttribute('data-active-panel') === 'vendors' && document.getElementById('vendor-inline-editor-body')) {
    covInlineLoad('vendors', null, 'vendor-inline-editor-body', seed);
    return;
  }
  openRecordEditor('vendors', null, seed);
}

function vendorBookedStatus(status) { return ['Booked','Paid','Complete'].includes(status); }
function vendorConsideringStatus(status) {
  const s = status || 'Researching';
  return ['Researching','Contacted','Quote Received','Considering','Meeting Scheduled','Tasting Scheduled'].includes(s);
}
function vendorStatusSlug(status) { return String(status || 'Researching').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,''); }
function vendorDisplayStatus(status) {
  const s = status || 'Researching';
  if (vendorBookedStatus(s)) return 'Booked';
  if (s === 'Not Booked') return 'Not Booked';
  return 'Considering';
}
function vendorCategoryIcon(cat, status) {
  const c = String(cat || '').toLowerCase();
  const cls = vendorBookedStatus(status) ? ' booked' : '';
  let svg = '<svg viewBox="0 0 24 24"><path d="M4 20h16"/><path d="M6 20V8l6-4 6 4v12"/><path d="M9 20v-6h6v6"/></svg>';
  if (/video|film/.test(c) && !/photo/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M4 7h11v10H4z"/><path d="M15 10l5-3v10l-5-3z"/></svg>';
  else if (/photo/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M4 8h4l2-3h4l2 3h4v11H4z"/><circle cx="12" cy="13" r="3.5"/></svg>';
  else if (/flor|flower|bloom|decor/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M12 20c4-3 6-6 6-10a6 6 0 0 0-12 0c0 4 2 7 6 10Z"/><path d="M12 20V9"/><path d="M8 13c-2 0-3.5-1.3-4-3.5C6.5 9 8.5 9.6 10 11"/><path d="M16 13c2 0 3.5-1.3 4-3.5-2.5-.5-4.5.1-6 1.5"/></svg>';
  else if (/music|dj|band|entertain/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M9 18V5l10-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="16" cy="16" r="3"/></svg>';
  else if (/cake|bakery|dessert/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M4 20h16"/><path d="M6 20v-5h12v5"/><path d="M8 15v-4h8v4"/><path d="M12 11V7"/><path d="M10 7c0-1 .8-2 2-3 1.2 1 2 2 2 3"/></svg>';
  else if (/rental|table|linen/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M5 9h14"/><path d="M7 9v11M17 9v11"/><path d="M8 5h8l3 4H5z"/></svg>';
  else if (/formalwear|bridal|tux|dress|attire/.test(c) && !/hair|makeup|stylist|salon/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M12 3c2 2 3 5 3 9l3 9H6l3-9c0-4 1-7 3-9Z"/><path d="M9 7h6"/></svg>';
  else if (/makeup|mua|cosmetic/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M8 21h8"/><path d="M12 17v4"/><path d="M8 8a4 4 0 0 1 8 0c0 5-4 9-4 9s-4-4-4-9Z"/><path d="M10 8h4"/></svg>';
  else if (/hair|stylist|salon|barber/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M6 4h12v2l-2 14H8L6 6V4Z"/><path d="M9 8h6M10 12h4"/></svg>';
  else if (/beauty/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M12 21s-7-4.4-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 11c0 5.6-7 10-7 10Z"/></svg>';
  else if (/transport|limo|shuttle|car service/.test(c) && !/honeymoon|travel agent/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M5 16h14l-1.5-5h-11z"/><path d="M7 16v2M17 16v2"/><circle cx="8" cy="18" r="1.5"/><circle cx="16" cy="18" r="1.5"/></svg>';
  else if (/honeymoon|travel agent|vacation|resort/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M3 18h18"/><path d="M7 18V9l5-4 5 4v9"/><path d="M9 13h6"/><path d="M12 9v4"/></svg>';
  else if (/food truck|mobile catering|taco truck/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M3 13h15l2 4H3z"/><path d="M5 13V8h10v5"/><circle cx="7" cy="17" r="1.5"/><circle cx="14" cy="17" r="1.5"/><path d="M18 13V9h3l1 4"/></svg>';
  else if (/stationery|invitation|invites|paper goods/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M6 4h12v16H6z"/><path d="M9 8h6M9 12h6M9 16h4"/></svg>';
  else if (/photo booth|photobooth|selfie booth|360 booth/.test(c)) svg = '<svg viewBox="0 0 24 24"><rect x="4" y="6" width="16" height="12" rx="1"/><path d="M8 10h8M8 14h5"/><circle cx="17" cy="9" r="1"/></svg>';
  else if (/favor|guest gift|welcome bag/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M12 8v13"/><path d="M5 8h14v4H5z"/><path d="M12 8c-2-3-5-3-5 0s3 0 5 0 5-3 5 0-3 0-5 0"/></svg>';
  else if (/lighting|uplighting|\bav\b|audio visual/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M12 3v2"/><path d="M8 5l1.5 1.5M16 5l-1.5 1.5"/><path d="M5 12H3M21 12h-2"/><path d="M12 21v-2"/><circle cx="12" cy="12" r="4"/><path d="M12 8v8M8 12h8"/></svg>';
  else if (/jewelry|jeweler|ring/.test(c)) svg = '<svg viewBox="0 0 24 24"><circle cx="12" cy="14" r="5"/><path d="M9 9l3-5 3 5"/></svg>';
  else if (/worship|praise team|worship band/.test(c) && !/officiant|pastor/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M9 18V5l10-2v13"/><circle cx="6" cy="18" r="3"/><circle cx="16" cy="16" r="3"/><path d="M12 3v3"/></svg>';
  else if (/rehearsal dinner|welcome dinner/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M4 11h16v9H4z"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/><path d="M12 4v3"/></svg>';
  else if (/officiant|pastor|ceremony/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M12 3v18"/><path d="M8 7h8"/><path d="M6 21h12"/></svg>';
  else if (/coord|planner/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M8 6h13"/><path d="M8 12h13"/><path d="M8 18h13"/><path d="M3 6h.01"/><path d="M3 12h.01"/><path d="M3 18h.01"/></svg>';
  else if (/cater|food|bar/.test(c)) svg = '<svg viewBox="0 0 24 24"><path d="M4 11h16v9H4z"/><path d="M8 11V7a4 4 0 0 1 8 0v4"/></svg>';
  return `<span class="vendor-row-icon${cls}" aria-hidden="true">${svg}</span>`;
}
function vendorStatusSelect(i, status) {
  const s = status || 'Researching';
  const sel = `<select class="vendor-status-select ${vendorStatusSlug(s)}" onchange="updateVendor(${i},'status',this.value)">${VENDOR_STATUS.map(v=>`<option ${v===s?'selected':''}>${escapeHtml(v)}</option>`).join('')}</select>`;
  if (typeof statusPill === 'function') return statusPill(s, 'status', { selectHtml: sel });
  return sel;
}
function vendorStars(i, val){
  val = Math.max(0, Math.min(5, parseInt(val)||0));
  let s = '<div class="record-stars" aria-label="'+val+' of 5 vendor stars">';
  for(let n=1;n<=5;n++) s += `<button type="button" class="record-star${n<=val?' on':''}" onclick="setVendorRating(${i},${n})" title="${n} star${n>1?'s':''}" aria-label="${n} star">★</button>`;
  return s + '</div>';
}
function setVendorRating(i,n){
  if(!data.vendors[i]) return;
  const cur = parseInt(data.vendors[i].rating)||0;
  data.vendors[i].rating = (cur === n) ? n-1 : n;
  save();
  renderVendors();
}
function vendorCurrency(v) { const n = Number(v)||0; return '$' + n.toLocaleString(undefined,{maximumFractionDigits:0}); }

function renderVendors() {
  uedVendorShell();
  if (typeof renderPageUxChrome === 'function') renderPageUxChrome('vendors');
  syncVendorTabChrome();
  if (_vndTab === 'shortlist') {
    renderVendorCompare();
    if (typeof renderVendorStats === 'function') renderVendorStats();
    // The shortlist branch returns early and would otherwise leave the panel in the
    // ux-panel-loading skeleton state, which sets pointer-events:none on all content
    // (making the Option A/B/C compare inputs untypeable). Clear it explicitly.
    if (typeof uxRevealPanel === 'function') uxRevealPanel('vendors');
    return;
  }
  if (typeof renderVendorStats === 'function') renderVendorStats();
  if (typeof renderVendorCategoryTabs === 'function') renderVendorCategoryTabs();
  if (typeof cwpRenderTable === 'function') {
    cwpRenderTable('vendors');
    bindRoPreviewInline('vendors', 'cwp-vendors', 'vendor-inline-editor-body');
  }
  renderHubRecordCards('vendors', { wrapId: 'vendor-card-grid', footId: 'vendor-card-foot', pagerId: 'vendor-card-pager', page: _vendorCardPage, pageSize: 8, pageFn: 'setVendorCardPage', filter: (row) => vendorCardMatchesFilter(row) });
  bindVendorCardsInline();
  if (document.getElementById('vendor-inline-editor-body')
      && document.body.getAttribute('data-active-panel') === 'vendors'
      && !(recordEditorState?.inlineMount === 'vendor-inline-editor-body' && recordEditorState.key === 'vendors')) {
    covInlineLoad('vendors', null, 'vendor-inline-editor-body', null, { scroll: false });
  }
  if (isDataHubPanelActive() && _dataHub.category === 'vendors' && _dataHub.table === 'vendors' && typeof cwpRenderTable === 'function') {
    cwpRenderTable('vendors', 'cwp-data-hub-active');
  }
}

let _vendorCardPage = 0;
function setVendorCardPage(p){ _vendorCardPage = Math.max(0, parseInt(p, 10) || 0); renderVendors(); }
function vendorCardMatchesFilter(row){
  const key = typeof vendorTrackerCatKey === 'function' ? vendorTrackerCatKey() : 'all';
  if (key === 'all') return true;
  const schema = typeof vendorCategoryByKey === 'function' ? vendorCategoryByKey(key) : null;
  if (!schema) return true;
  return typeof vendorCategoryMatches === 'function' ? vendorCategoryMatches(row.cat, schema.label) : String(row.cat || '') === schema.label;
}
function bindVendorCardsInline(){
  const grid = document.getElementById('vendor-card-grid');
  if (!grid || !document.getElementById('vendor-inline-editor-body')) return;
  grid.querySelectorAll('.hub-record-card[data-record-index]').forEach(card => {
    if (card.dataset.inlineVendorBound === '1') return;
    card.dataset.inlineVendorBound = '1';
    const select = (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      if (ev.stopImmediatePropagation) ev.stopImmediatePropagation();
      const index = parseInt(card.dataset.recordIndex, 10);
      if (Number.isFinite(index)) covInlineLoad('vendors', index, 'vendor-inline-editor-body');
    };
    card.addEventListener('click', select, true);
    card.addEventListener('keydown', (ev) => {
      if (ev.key === 'Enter' || ev.key === ' ') select(ev);
    }, true);
  });
}
