function vendorReviewButton(i, value) {
  const clean = String(value || '').trim();
  const preview = clean ? clean : 'Add review feedback…';
  return `<button type="button" class="review-pop-btn ${clean ? 'has-review' : ''}" onclick="openVendorReviewPopover(${i}, this)"><span class="review-pop-preview">${escapeHtml(preview)}</span></button>`;
}
function closeVendorReviewPopover() {
  const old = document.querySelector('.review-popover');
  if (old) old.remove();
}
function openVendorReviewPopover(i, anchor) {
  closeVendorReviewPopover();
  const row = data.vendors[i] || {};
  const pop = document.createElement('div');
  pop.className = 'review-popover';
  pop.dataset.vendorIndex = String(i);
  pop.innerHTML = `
    <h4>Review Feedback</h4>
    <textarea id="vendor-review-pop-text" placeholder="Write the review feedback or testimonial notes here…">${escapeHtml(row.review || '')}</textarea>
    <div class="review-popover-actions">
      <button type="button" class="btn btn-outline btn-sm" onclick="closeVendorReviewPopover()">Cancel</button>
      <button type="button" class="btn btn-forest btn-sm" onclick="saveVendorReviewPopover()">Save</button>
    </div>`;
  document.body.appendChild(pop);
  const rect = anchor && anchor.getBoundingClientRect ? anchor.getBoundingClientRect() : {left:20,bottom:120,right:420};
  const margin = 14;
  const width = Math.min(420, window.innerWidth - margin*2);
  let left = Math.min(Math.max(rect.left, margin), window.innerWidth - width - margin);
  let top = rect.bottom + 8;
  pop.style.width = width + 'px';
  pop.style.left = left + 'px';
  pop.style.top = top + 'px';
  requestAnimationFrame(() => {
    const pr = pop.getBoundingClientRect();
    if (pr.bottom > window.innerHeight - margin) {
      const above = rect.top - pr.height - 8;
      pop.style.top = Math.max(margin, above) + 'px';
    }
    const ta = pop.querySelector('textarea');
    if (ta) { ta.focus(); ta.setSelectionRange(ta.value.length, ta.value.length); }
  });
}
function saveVendorReviewPopover() {
  const pop = document.querySelector('.review-popover');
  if (!pop) return;
  const i = parseInt(pop.dataset.vendorIndex, 10);
  const ta = pop.querySelector('textarea');
  if (!Number.isNaN(i) && data.vendors[i]) {
    data.vendors[i].review = ta ? ta.value : '';
    save();
  }
  closeVendorReviewPopover();
  renderVendors();
}

function updateVendor(i, key, val) {
  if (!data.vendors[i]) return;
  data.vendors[i][key]=val;
  if (key === 'quote' || key === 'deposit') {
    const q = parseFloat(data.vendors[i].quote)||0;
    const d = parseFloat(data.vendors[i].deposit)||0;
    data.vendors[i].balance = Math.max(0, q-d);
  }
  save();
  renderVendorStats();
  renderWhenInputComplete(renderVendors);
}

function vendorStatCard(label, value, sub, icon, cls='') {
  return `<div class="vendor-stat-card"><div class="vendor-stat-icon ${cls}">${icon}</div><div><div class="vendor-stat-kicker">${escapeHtml(label)}</div><div class="vendor-stat-value">${escapeHtml(value)}</div><div class="vendor-stat-sub">${escapeHtml(sub)}</div></div></div>`;
}
function renderVendorStats() {
  const total = data.vendors.length;
  const booked = data.vendors.filter(v=>vendorBookedStatus(v.status) || v.contract).length;
  const notBooked = data.vendors.filter(v=>v.status === 'Not Booked').length;
  const considering = Math.max(0, total - booked - notBooked);
  const el = document.getElementById('vendor-stats');
  if (!el) return;
  const pct = n => total ? Math.round((n/total)*100) : 0;
  const ms=(paths,label,val,sub)=>`<div class="m-stat"><div class="m-stat-top"><svg viewBox="0 0 24 24" aria-hidden="true">${paths}</svg><span class="m-stat-label">${label}</span></div><div class="m-stat-val">${val}</div><div class="m-stat-sub">${sub}</div></div>`;
  el.innerHTML =
    ms('<circle cx="9" cy="8" r="3"/><path d="M3.5 20a5.5 5.5 0 0 1 11 0"/><circle cx="17" cy="9" r="2.4"/><path d="M14.5 15.5A4.6 4.6 0 0 1 20.5 20"/>','Total vendors', total, 'All vendors in your list') +
    ms('<circle cx="12" cy="12" r="8"/><path d="m8.7 12.2 2.2 2.3 4.7-5"/>','Booked', booked, pct(booked)+'% of total') +
    ms('<path d="M7 4h10M7 20h10M8 4c0 4 8 4 8 8s-8 4-8 8M16 4c0 4-8 4-8 8s8 4 8 8"/>','Considering', considering, pct(considering)+'% of total') +
    ms('<circle cx="12" cy="12" r="8" stroke-dasharray="4 4"/>','Not booked', notBooked, pct(notBooked)+'% of total');
}

