  if (!sel) return;
  const current = sel.value || '';
  const values = [...new Set([...(INVITE_DECISIONS||[]), ...(data.guests||[]).map(g=>g.inviteDecision).filter(Boolean)])];
  sel.innerHTML = '<option value="">All Invite Decisions</option>' + values.map(v=>`<option value="${guestAttr(v)}"${v===current?' selected':''}>${guestHtml(v)}</option>`).join('');
  if (current && !values.includes(current)) sel.value = '';
