  ensureGuestEvents();
  const values = data.guestEvents.filter(ev=>ev.active !== false).map(ev=>({id:guestEventId(ev), name:ev.name || guestEventId(ev)}));
  sel.innerHTML = '<option value="">All Events</option>' + values.map(ev=>`<option value="${guestAttr(ev.id)}"${ev.id===current?' selected':''}>${guestHtml(ev.name)}</option>`).join('');
  if (current && !values.some(ev=>ev.id===current)) sel.value = '';
