function toggleGuestCompanions(i){
  i = Number(i);
  const g = data.guests[i]; if(!g) return;
  if(!Array.isArray(g.companions)) g.companions = [];
  if(g.companions.length === 0){
    const need = (g.plusone ? 1 : 0) + (parseInt(g.children)||0);
    for(let n=0;n<Math.max(1,need);n++) g.companions.push({name:'',role:'Adult Guest',meal:'',dietary:'',rsvp:'Pending',table:g.table||'',notes:''});
    save();
  }
  if(expandedGuestCompanions.has(i)) expandedGuestCompanions.delete(i);
  else { expandedGuestCompanions.clear(); expandedGuestCompanions.add(i); }
  renderGuests();
}
