/* ── Tasks: multi-assignee names pulled from the Guest List (+ companions/party); auto-updates ── */
function refreshTaskAssigneeOptions(){
  const dl = document.getElementById('assigned-options');
  if(!dl) return;
  const set = new Set(['Bride','Groom','Both','Wedding Party','Family','Coordinator','Maid of Honor','Best Man','Planner']);
  (data.guests||[]).forEach(g=>{ if(g.name && g.name.trim()) set.add(g.name.trim()); (g.companions||[]).forEach(c=>{ if(c.name && c.name.trim()) set.add(c.name.trim()); }); });
  (data.party||[]).forEach(p=>{ if(p.name && p.name.trim()) set.add(p.name.trim()); });
  dl.innerHTML = [...set].map(n=>`<option value="${escapeHtml(n)}"></option>`).join('');
}
/* ── Tasks: seed the default "Assign 2 witnesses" task once ── */
function ensureWitnessTask(){
  if(!Array.isArray(data.tasks)) data.tasks=[];
  if(!data.onboard || typeof data.onboard!=='object') data.onboard={};
  if(data.onboard.witnessTaskSeeded) return;
  if(!data.tasks.some(t=>/assign 2 witnesses/i.test(t.task||'')))
    data.tasks.push({task:'Assign 2 witnesses', cat:'Ceremony', priority:'High', date:'', status:'Not Started', assigned:'', notes:'Two witnesses are required to sign the marriage license.'});
  data.onboard.witnessTaskSeeded = true;
  save();
}
