function counselingInlineAvailable(){
  return document.body.getAttribute('data-active-panel') === 'counseling' && !!document.getElementById('counseling-inline-editor-body');
}

function addCounselingRow() {
  if (typeof rdOpenNewInDrawer === 'function' && rdOpenNewInDrawer('counseling')) return;
  if (counselingInlineAvailable()) {
    covInlineLoad('counseling', null, 'counseling-inline-editor-body');
    return;
  }
  openRecordEditor('counseling');
}

function renderCounseling() {
  document.getElementById('panel-counseling')?.classList.add('ued-scope');
  /* Converted to the CWP unified system — table renders from the descriptor. */
  if (typeof renderCounselingCurriculum === 'function') renderCounselingCurriculum();
  if (typeof cwpRenderTable === 'function' && cwpMountOnPanel('counseling')) {
    const mount = document.getElementById('cwp-counseling');
    if (mount) mount.classList.add('ro-preview');
    cwpRenderTable('counseling');
    if (typeof bindRoPreviewInline === 'function') bindRoPreviewInline('counseling', 'cwp-counseling', 'counseling-inline-editor-body');
    renderCounselingStats();
    if (counselingInlineAvailable()
      && !(recordEditorState?.inlineMount === 'counseling-inline-editor-body' && recordEditorState.key === 'counseling')) {
      covInlineLoad('counseling', null, 'counseling-inline-editor-body', null, {scroll:false});
    }
    if (isDataHubPanelActive() && _dataHub.category === 'faith' && _dataHub.table === 'counseling' && typeof cwpRenderTable === 'function') {
      cwpRenderTable('counseling', 'cwp-data-hub-active');
    }
    return;
  }
  renderFaithHubPreviews();
  renderCounselingStats();
}

function counselToggleAll(cb){
  document.querySelectorAll('#counseling-body .counsel-rowsel').forEach(x => { x.checked = cb.checked; });
  counselUpdateSelCount();
}
function counselSelectedIndexes(){
  return [...document.querySelectorAll('#counseling-body .counsel-rowsel:checked')].map(cb => parseInt(cb.value)).filter(n => !isNaN(n));
}
function counselUpdateSelCount(){
  const n = counselSelectedIndexes().length;
  const btn = document.getElementById('counsel-delete-selected');
  if (btn){ btn.disabled = n === 0; btn.textContent = n ? `Delete Selected (${n})` : 'Delete Selected'; }
  const sa = document.getElementById('counsel-select-all');
  if (sa){ const total = document.querySelectorAll('#counseling-body .counsel-rowsel').length; sa.checked = total > 0 && n === total; }
}
async function counselDeleteSelected(){
  const idx = counselSelectedIndexes();
  if (!idx.length) return;
  if (!(await covConfirm(`Delete ${idx.length} selected session${idx.length===1?'':'s'}?`, {title:'Delete sessions?', danger:true, okText:'Delete'}))) return;
  const drop = new Set(idx);
  data.counseling = data.counseling.filter((_, i) => !drop.has(i));
  save();
  renderCounseling();
}

function updateCounseling(i, key, val) { data.counseling[i][key]=val; save(); renderCounselingStats(); }

function renderCounselingStats() {
  const done = data.counseling.filter(c=>c.status==='Completed').length;
  const inProg = data.counseling.filter(c=>c.status==='In Progress').length;
  const total = data.counseling.length;
  const pct = total > 0 ? Math.round(done/total*100)+'%' : '—';
  const curHours = typeof counselingCurriculumHours === 'function' ? counselingCurriculumHours() : 0;
  const hourGoal = parseFloat(data.setup?.counselingCurriculum?.hoursGoal) || 8;
  const el = document.getElementById('counseling-stats');
  if (!el) return;
  const ms=(paths,label,val,sub)=>`<div class="m-stat"><div class="m-stat-top"><svg viewBox="0 0 24 24" aria-hidden="true">${paths}</svg><span class="m-stat-label">${label}</span></div><div class="m-stat-val">${val}</div><div class="m-stat-sub">${sub}</div></div>`;
  el.innerHTML =
    ms('<circle cx="9" cy="8" r="3"/><path d="M3.5 20a5.5 5.5 0 0 1 11 0"/><circle cx="17" cy="9" r="2.4"/><path d="M14.5 15.5A4.6 4.6 0 0 1 20.5 20"/>','Sessions planned', total, 'Total meetings') +
    ms('<path d="M5 12l4 4L19 6"/>','Completed', done, 'Finished sessions') +
    ms('<circle cx="12" cy="12" r="8"/><path d="M12 7v5l3 2"/>','In progress', inProg, 'Currently active') +
    ms('<path d="M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18Z"/><path d="M12 7v5"/><circle cx="12" cy="16" r=".8"/>','Progress', pct, 'Session tracker') +
    ms('<path d="M12 3v18M7 8h10"/>','Curriculum hours', `${curHours} / ${hourGoal}`, 'Guided premarital goal') +
    ms('<rect x="4" y="5" width="16" height="15" rx="2"/><path d="M8 3v4M16 3v4M4 10h16"/>','Next session', counselingNextDate(), counselingNextTopic());
  renderCounselTopics();
}

function renderCounselTopics() {
  const topics = [...new Set(data.counseling.map(c=>c.topic).filter(t=>t&&t.trim()))];
  const card = document.getElementById('counsel-topics-card');
  const grid = document.getElementById('counsel-topic-chips');
  if (!card || !grid) return;
  if (topics.length === 0) { card.style.display = 'none'; return; }
  card.style.display = '';
  grid.innerHTML = topics.map(t => `<div class="counsel-topic-chip"><svg viewBox="0 0 24 24"><path d="M5 12l4 4L19 6"/></svg> ${escapeHtml(t)}</div>`).join('');
}
function counselingNextDate(){
  const today = new Date(); today.setHours(0,0,0,0);
  const future = data.counseling.filter(c => c.date && new Date(c.date+'T00:00:00') >= today && c.status !== 'Completed').sort((a,b) => a.date.localeCompare(b.date));
  if (!future.length) return '—';
  const d = new Date(future[0].date+'T00:00:00');
  return d.toLocaleDateString('en-US',{month:'short',day:'numeric'});
}
function counselingNextTopic(){
  const today = new Date(); today.setHours(0,0,0,0);
  const future = data.counseling.filter(c => c.date && new Date(c.date+'T00:00:00') >= today && c.status !== 'Completed').sort((a,b) => a.date.localeCompare(b.date));
  return future.length && future[0].topic ? future[0].topic : 'No upcoming session';
}

