      window.alert = function(){};
      window.open = function(){ return { document:{ open:function(){}, write:function(h){ buf.push(String(h)); }, close:function(){} }, addEventListener:function(){}, focus:function(){}, print:function(){}, close:function(){} }; };
      // Capture the user-data body of print templates WITHOUT the scaffold's own <script>.
      window.openPrintView = function(title, bodyHtml){ buf.push(String(title == null ? '' : title)); buf.push(String(bodyHtml == null ? '' : bodyHtml)); return null; };
      document.getElementById = function(){ return node(); };
