  if (weddingDate) add({id:'wedding-day', title:'WEDDING DAY', source:'Timeline', category:'Wedding Day', date:weddingDate, status:'Celebration', notes:[data.setup?.bride,data.setup?.groom].filter(Boolean).join(' & '), sourcePage:'setup'});
