  if (e.sourcePage === 'payments') return 'payments';
  if (e.sourcePage === 'counseling') return 'counseling';
  if (e.sourcePage === 'vendors') return 'vendors';
  if (e.sourcePage === 'timeline') return 'timeline';
  if (e.sourcePage === 'budget') return 'budget';
