function renderSmartBottomPanels(events){
  const agenda = document.getElementById('smart-week-agenda');
  const breakdown = document.getElementById('smart-source-breakdown');
  const reminders = document.getElementById('smart-reminders');
  const unscheduled = document.getElementById('smart-unscheduled-tasks');
  const start = smartWeekStart(smartSelectedDate || todayISO());
  const end = new Date(start); end.setDate(start.getDate()+6);
  const week = events.filter(e=>{ const d=dateFromISO(e.date); return d && d>=start && d<=end; }).slice(0,6);
  if (agenda) {
    agenda.innerHTML = `<div class="smart-side-title"><span class="smart-side-icon">${appointmentIcon('calendar')}</span><h3>This Week's Agenda</h3></div>
      <div class="smart-agenda-list">${week.length ? week.map(e=>`<div class="smart-agenda-row"><time>${humanDate(e.date,{month:'short',day:'numeric'})}</time><div>${escapeHtml(e.title)}</div><span class="smart-agenda-tag">${escapeHtml(e.source)}</span></div>`).join('') : '<div class="smart-empty-note">No events this week.</div>'}</div>`;
  }
  if (breakdown) {
    const total = Math.max(1, events.length);
    const counts = SMART_SOURCES.map(s=>[s, events.filter(e=>e.source===s).length]);
    let running = 0;
    const pctVals = counts.map(([s,n])=>{ const start=running; running += (n/total)*100; return [s,n,Math.round((n/total)*100),running]; });
    const vars = {
      '--tasks-p': (pctVals.find(x=>x[0]==='Tasks')?.[3] || 0)+'%',
      '--appointments-p': (pctVals.find(x=>x[0]==='Appointments')?.[3] || 0)+'%',
      '--budget-p': (pctVals.find(x=>x[0]==='Budget')?.[3] || 0)+'%',
      '--payments-p': (pctVals.find(x=>x[0]==='Payments')?.[3] || 0)+'%',
      '--vendors-p': (pctVals.find(x=>x[0]==='Vendors')?.[3] || 0)+'%'
    };
    const style = Object.entries(vars).map(([k,v])=>`${k}:${v}`).join(';');
    const sourceColors = ['#c9b275','#9fbf9e','#a9bdd5','#df9a8f','#bba4c3','#b9b9b9','#e0ca74','#8f6d3d','#6f8d7a','#5d7f8f','#b38549','#8f7a66'];
    breakdown.innerHTML = `<div class="smart-side-title"><span class="smart-side-icon">${appointmentIcon('checklist')}</span><h3>Source Breakdown</h3></div>
      <div class="smart-breakdown-grid"><div class="smart-donut" style="${style}"><span>${events.length}<small>Total</small></span></div><div class="smart-breakdown-list">${counts.map(([s,n],idx)=>`<div class="smart-breakdown-row"><i style="background:${sourceColors[idx % sourceColors.length]}"></i><span>${escapeHtml(s)}</span><b>${n}</b><em>${Math.round(n/total*100)}%</em></div>`).join('')}</div></div>`;
  }
  if (reminders) {
    const todo = events.filter(e=>e.date>=todayISO() && !/complete|paid|confirmed/i.test(e.status||'')).slice(0,4);
    reminders.innerHTML = `<div class="smart-side-title"><span class="smart-side-icon">${appointmentIcon('reminder')}</span><h3>Reminder & Follow-Up</h3></div>
      <div class="smart-reminder-list">${todo.length ? todo.map(e=>`<div class="smart-reminder-row"><time>${humanDate(e.date,{month:'short',day:'numeric'})}</time><div><strong>${escapeHtml(e.title)}</strong><br><span>${escapeHtml(e.category||e.source)}</span></div><span class="smart-agenda-tag">${escapeHtml(e.source)}</span></div>`).join('') : '<div class="smart-empty-note">No reminders need attention.</div>'}</div>`;
  }
  if (unscheduled) {
    const tasks = safeArray(data.tasks).map((t,i)=>({t,i})).filter(({t})=>!t.date && (t.task||'').trim() && t.status !== 'Complete').slice(0,5);
    unscheduled.innerHTML = `<div class="smart-side-title"><span class="smart-side-icon">${lineIcon('tasks')}</span><h3>Unscheduled Tasks</h3></div>
      <div class="smart-unscheduled-list">${tasks.length ? tasks.map(({t,i})=>`<div class="smart-unscheduled-row"><div><strong>${escapeHtml(t.task)}</strong><span>${escapeHtml(t.cat||'Planning')} • ${escapeHtml(t.priority||'Medium')} priority</span></div><button class="smart-mini-link" type="button" onclick="openSmartTaskScheduler(${i})">Schedule</button></div>`).join('') : '<div class="smart-empty-note">Every active task has a date.</div>'}</div>`;
  }
}
/* ════════════════════════════════════════════════
   SMART CALENDAR CONFLICT WARNINGS (Step 3.2)
════════════════════════════════════════════════ */
function timeToMinutes(t){
  if (!t) return null;
  const [h,m] = String(t).split(':').map(Number);
  return Number.isNaN(h) ? null : h * 60 + (m || 0);
}
function detectCalendarConflicts(events){
  const byDate = {};
  events.forEach(e => {
    if (!e.date || e.allDay || !e.time) return;
    (byDate[e.date] ||= []).push(e);
  });
  const conflicts = [];
  Object.entries(byDate).forEach(([date, dayEvts]) => {
    if (dayEvts.length < 2) return;
    const timed = dayEvts.map(e => ({
      evt: e,
      start: timeToMinutes(e.time),
      end: timeToMinutes(e.endTime) || (timeToMinutes(e.time) !== null ? timeToMinutes(e.time) + 60 : null)
    })).filter(x => x.start !== null);
    timed.sort((a, b) => a.start - b.start);
    for (let i = 0; i < timed.length; i++) {
      for (let j = i + 1; j < timed.length; j++) {
        if (timed[j].start < timed[i].end) {
          conflicts.push({ date, a: timed[i].evt, b: timed[j].evt });
        }
      }
    }
  });
  return conflicts;
}
function renderSmartConflicts(events){
  const host = document.getElementById('smart-conflicts');
  if (!host) return;
  const conflicts = detectCalendarConflicts(events);
  if (!conflicts.length) { host.style.display = 'none'; host.innerHTML = ''; return; }
  host.style.display = '';
  const warnIcon = '<svg viewBox="0 0 24 24"><path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"/><path d="M12 9v4"/><path d="M12 17h.01"/></svg>';
  const rows = conflicts.slice(0, 6).map(c => {
    const timeA = c.a.time ? humanTime(c.a.time) : '';
    const timeB = c.b.time ? humanTime(c.b.time) : '';
    return `<div class="cf-row">
      <span class="cf-icon">${warnIcon}</span>
      <div class="cf-body">
        <div class="cf-label">${humanDate(c.date, {weekday:'short', month:'short', day:'numeric'})}</div>
        <div class="cf-detail">These events overlap in time:</div>
        <div class="cf-events">
          <span class="cf-chip" onclick="selectSmartDate('${c.date}')" title="${escapeHtml(c.a.title)}">${timeA} ${escapeHtml(c.a.title.length > 22 ? c.a.title.slice(0,20) + '…' : c.a.title)}</span>
          <span class="cf-chip" onclick="selectSmartDate('${c.date}')" title="${escapeHtml(c.b.title)}">${timeB} ${escapeHtml(c.b.title.length > 22 ? c.b.title.slice(0,20) + '…' : c.b.title)}</span>
        </div>
      </div>
    </div>`;
  }).join('');
  const extra = conflicts.length > 6 ? `<div class="cf-detail" style="text-align:center;margin-top:.3rem">+ ${conflicts.length - 6} more conflict${conflicts.length - 6 > 1 ? 's' : ''}</div>` : '';
  host.innerHTML = `<div class="smart-side-title"><span class="smart-side-icon" style="color:var(--red)">${warnIcon}</span><h3>Schedule Conflicts</h3></div>${rows}${extra}`;
}
function getConflictDates(events){
  const conflicts = detectCalendarConflicts(events);
  const dates = new Set();
  conflicts.forEach(c => dates.add(c.date));
  return dates;
}

function openSmartTaskScheduler(i){
  const t = data.tasks?.[i];
  if (!t) return;
  openSmartCalendarCreate('task', smartSelectedDate || todayISO());
  smartSetValue('smart-edit-source','task');
  smartSetValue('smart-edit-index',i);
  smartSetValue('smart-create-source','task');
  smartCalendarEditingEvent = {sourceType:'task',sourceIndex:i,editable:true};
  document.getElementById('smart-create-type').disabled = true;
  document.getElementById('smart-create-source').disabled = true;
  smartSetValue('smart-create-title-input',t.task||'');
  smartSetValue('smart-create-category',t.cat||'Planning');
  smartSetValue('smart-create-status',t.status||'Not Started');
  smartSetValue('smart-create-description',t.description||t.notes||'');
  syncSmartCreateType();
}
function smartGuestNameOptions(){
  const names = new Set();
  safeArray(data.guests).forEach(g=>{
    if (g.name) names.add(g.name);
    if (g.household) names.add(g.household);
    safeArray(g.companions).forEach(c=>{ if (c.name) names.add(c.name); });
  });
  return [...names].sort();
}
function smartCategoryOptions(){
  return [...new Set([
    'Wedding','Ceremony','Reception','Planning','Vendor','Family','Appointment','Deadline','Payment','Travel',
    ...safeArray(data.tasks).map(t=>t.cat).filter(Boolean),
    ...safeArray(data.appointments).map(a=>a.category).filter(Boolean),
    ...safeArray(data.calendarEvents).map(e=>e.category).filter(Boolean)
  ])].sort();
}
function smartSetValue(id,value){ const el=document.getElementById(id); if(el) el.value = value ?? ''; }
function smartGetValue(id){ return document.getElementById(id)?.value || ''; }
function smartDefaultTimezone(){ return data.setup?.timezone || ''; }
function populateSmartCreateOptions(){
  const iconSel = document.getElementById('smart-create-icon');
  if (iconSel) iconSel.innerHTML = SMART_CALENDAR_ICONS.map(([v,l])=>`<option value="${v}">${l}</option>`).join('');
  const guests = document.getElementById('smart-create-guest-options');
  if (guests) guests.innerHTML = smartGuestNameOptions().map(n=>`<option value="${escapeHtml(n)}"></option>`).join('');
  const cats = document.getElementById('smart-create-category-options');
  if (cats) cats.innerHTML = smartCategoryOptions().map(c=>`<option value="${escapeHtml(c)}"></option>`).join('');
}
function syncSmartCreateType(){
  const type = smartGetValue('smart-create-type') || 'event';
  const title = document.getElementById('smart-create-title');
  const subtitle = document.getElementById('smart-create-subtitle');
  if (title) title.textContent = smartCalendarEditingEvent ? `Edit ${typeLabel(type)}` : `Create ${typeLabel(type)}`;
  if (subtitle) subtitle.textContent = type === 'task' ? 'Saves to the Tasks page and appears on every calendar view.' : type === 'appointment' ? 'Saves to the Appointments page and appears on every calendar view.' : 'Saves as a calendar event and appears on every calendar view.';
  const status = document.getElementById('smart-create-status');
  if (status && !smartCalendarEditingEvent) status.value = type === 'task' ? 'Not Started' : type === 'appointment' ? 'Pending' : 'Scheduled';
  const icon = document.getElementById('smart-create-icon');
  if (icon && !smartCalendarEditingEvent) icon.value = type === 'task' ? 'task' : type === 'appointment' ? 'calendar' : 'calendar';
}
function smartSourceToType(source){
  if (source === 'task' || source === 'plan') return 'task';
  if (source === 'appointment') return 'appointment';
  return 'event';
}
function smartSourceLabel(source){
  const labels = {
    event:'Smart Calendar Event',
    task:'Tasks',
    appointment:'Appointments',
    plan:'Planning Timeline',
    timeline:'Wedding Day Timeline',
    vendorArrival:'Vendor Arrival Timeline',
    payment:'Payments',
    paymentInstallment:'Payment Plan',
    budgetItem:'Budget Item',
    contract:'Contracts & Invoices'
  };
  return labels[source] || 'Smart Calendar Event';
}
function smartResolveEditIndex(source,index,sourceId){
  const key = smartSourceDataKey(source);
  const list = Array.isArray(data[key]) ? data[key] : [];
  if (sourceId) {
    const byId = list.findIndex(row => String(recordIdentity(row)) === String(sourceId));
    if (byId >= 0) return byId;
  }
  return Number.isInteger(index) && index >= 0 && list[index] ? index : NaN;
}
function syncSmartCreateSource(){
  const source = smartGetValue('smart-create-source') || 'event';
  const type = smartSourceToType(source);
  smartSetValue('smart-create-type', type);
  if (!smartCalendarEditingEvent) {
    const defaults = {
      event:{cat:'Wedding',status:'Scheduled',icon:'calendar'},
      task:{cat:'Planning',status:'Not Started',icon:'task'},
      appointment:{cat:'Appointment',status:'Pending',icon:'calendar'},
      plan:{cat:'Wedding Month',status:'Upcoming',icon:'task'},
      timeline:{cat:'Wedding Day Timeline',status:'Scheduled',icon:'clock'},
      vendorArrival:{cat:'Wedding Day Vendor',status:'Scheduled',icon:'car'}
    }[source] || {};
    smartSetValue('smart-create-category', defaults.cat || 'Wedding');
    smartSetValue('smart-create-status', defaults.status || 'Scheduled');
    smartSetValue('smart-create-icon', defaults.icon || 'calendar');
  }
  syncSmartCreateType();
  const note = document.getElementById('smart-create-source-note');
  if (note && !smartCalendarEditingEvent) note.textContent = `This will save to ${smartSourceLabel(source)} and appear automatically in Month, Week, and Agenda views. Use local .ics export for outside calendars; external calendar connections are an Enhancement.`;
}
function syncSmartCreateAllDay(){
  const allDay = document.getElementById('smart-create-all-day')?.checked;
  ['smart-create-time','smart-create-end-time'].forEach(id=>{ const el=document.getElementById(id); if(el) el.disabled = !!allDay; });
}
function typeLabel(type){ return type === 'task' ? 'Task' : type === 'appointment' ? 'Appointment' : 'Event'; }
function openSmartCalendarCreate(type='event', dateOverride='', opts){
  /* Prefer 360px drawer create when on Smart Calendar (step8s). Use opts.modal
     or forceModal for multi-source center modal when explicitly requested. */
  const forceModal = !!(opts && (opts.modal || opts.forceModal));
  const onCalendar = document.body?.getAttribute('data-active-panel') === 'calendar'
    || !!document.getElementById('panel-calendar')?.classList.contains('active');
  if (!forceModal && onCalendar && typeof openCalendarDayDrawerCreate === 'function') {
    openCalendarDayDrawerCreate(type || 'appointment', dateOverride);
    return;
  }
  ensureAppointmentData();
  populateSmartCreateOptions();
  smartCalendarEditingEvent = null;
  const modal = document.getElementById('smart-create-modal');
  if (!modal) {
    if (typeof openCalendarDayDrawerCreate === 'function') {
      openCalendarDayDrawerCreate(type || 'appointment', dateOverride);
    }
    return;
  }
  const saveBtn = document.getElementById('smart-save-btn');
  if (saveBtn) { saveBtn.disabled = false; saveBtn.textContent = 'Save'; }
  const deleteBtn = document.getElementById('smart-delete-btn');
  if (deleteBtn) deleteBtn.hidden = true;
  cancelSmartCalendarDelete();
  smartSetValue('smart-edit-source','');
  smartSetValue('smart-edit-index','');
  smartSetValue('smart-create-type',type || 'event');
  smartSetValue('smart-create-source',type || 'event');
  document.getElementById('smart-create-type').disabled = false;
  document.getElementById('smart-create-source').disabled = false;
  smartSetValue('smart-create-title-input','');
  smartSetValue('smart-create-date',dateOverride || smartSelectedDate || todayISO());
  smartSetValue('smart-create-time','10:00');
  smartSetValue('smart-create-end-time','');
  document.getElementById('smart-create-all-day').checked = false;
  smartSetValue('smart-create-category',type === 'task' ? 'Planning' : type === 'appointment' ? 'Appointment' : 'Wedding');
  smartSetValue('smart-create-status',type === 'task' ? 'Not Started' : type === 'appointment' ? 'Pending' : 'Scheduled');
  smartSetValue('smart-create-reminder','');
  smartSetValue('smart-create-timezone',smartDefaultTimezone());
  smartSetValue('smart-create-guests','');
  smartSetValue('smart-create-location','');
  smartSetValue('smart-create-color','#b38549');
  smartSetValue('smart-create-icon',type === 'task' ? 'task' : 'calendar');
  smartSetValue('smart-create-description','');
  const note = document.getElementById('smart-create-source-note');
  if (note) note.textContent = 'This will save to the correct planner source, then appear automatically in Month, Week, and Agenda views. Use local .ics export for outside calendars.';
  syncSmartCreateSource();
  syncSmartCreateAllDay();
  modal.classList.add('open');
}
function closeSmartCalendarCreate(){
  document.getElementById('smart-create-modal')?.classList.remove('open');
  cancelSmartCalendarDelete();
  smartCalendarEditingEvent = null;
}
function openSmartCalendarEditor(id){
  /* §16 redesign path: open the source record in the forest full editor shell
     (same as Timeline & Tasks Full editor / openRecordEditor). Legacy
     #smart-create-modal remains for create-only entry points that still use it. */
  const sid = id == null ? '' : String(id);
  if (!sid) return;
  try { document.getElementById('smart-create-modal')?.classList.remove('open'); } catch (e) {}
  smartCalendarEditingEvent = null;
  if (typeof openSmartCalendarEventFullEditor === 'function') {
    const ok = openSmartCalendarEventFullEditor(sid);
    if (ok) return;
  }
  /* Fallback: if the source cannot resolve, keep the day drawer Entry tab focused. */
  const event = (typeof buildSmartCalendarEvents === 'function' ? buildSmartCalendarEvents() : [])
    .find(e => String(e.id) === sid);
  if (event) {
    smartSelectedDate = event.date || smartSelectedDate;
    smartCalDrawerOpen = true;
    smartCalDrawerEntryId = event.id;
    smartCalDrawerTab = 0;
    if (typeof renderSmartCalendar === 'function') renderSmartCalendar();
  }
}
function smartCurrentDeleteTarget(){
  if (!smartCalendarEditingEvent || !smartCalendarEditingEvent.editable) return null;
  const source = smartGetValue('smart-edit-source') || smartCalendarEditingEvent.sourceType || '';
  const rawIndex = parseInt(smartGetValue('smart-edit-index'),10);
  const index = smartResolveEditIndex(source,rawIndex,smartCalendarEditingEvent.sourceId || '');
  if (!source || !Number.isInteger(index) || index < 0) return null;
  const lists = {
    event:data.calendarEvents,
    task:data.tasks,
    appointment:data.appointments,
    plan:data.plan,
    timeline:data.timeline,
    vendorArrival:data.vtimeline
  };
  const list = lists[source];
  if (!Array.isArray(list) || !list[index]) return null;
  return {source,index,list,label:smartSourceLabel(source),title:smartCalendarEditingEvent.title || smartGetValue('smart-create-title-input') || 'this entry'};
}
function beginSmartCalendarDelete(){
  const target = smartCurrentDeleteTarget();
  if (!target) return;
  const panel = document.getElementById('smart-delete-confirm');
  const text = document.getElementById('smart-delete-confirm-text');
  if (text) text.textContent = `This will delete "${target.title}" from Month View, Week View, Agenda View, and from its original source: ${target.label}.`;
  if (panel) panel.hidden = false;
}
function cancelSmartCalendarDelete(){
  const panel = document.getElementById('smart-delete-confirm');
  if (panel) panel.hidden = true;
}
function confirmSmartCalendarDelete(){
  const target = smartCurrentDeleteTarget();
  if (!target) return;
  target.list.splice(target.index,1);
  if (target.source === 'task' && typeof selectedTasks !== 'undefined' && selectedTasks instanceof Set) {
    selectedTasks.delete(target.index);
    selectedTasks = new Set([...selectedTasks].filter(x => x !== target.index).map(x => x > target.index ? x - 1 : x));
  }
  ensureRelationalDataModel();
  save();
  closeSmartCalendarCreate();
  renderSmartCalendar();
  if (typeof renderTasks === 'function') renderWhenInputComplete(renderTasks);
  if (typeof renderAppointments === 'function') renderWhenInputComplete(renderAppointments);
  if (typeof renderPlan === 'function') renderWhenInputComplete(renderPlan);
  if (typeof renderTimeline === 'function') renderWhenInputComplete(renderTimeline);
  if (typeof renderVTimeline === 'function') renderWhenInputComplete(renderVTimeline);
}
function smartFormPayload(){
  const allDay = !!document.getElementById('smart-create-all-day')?.checked;
  return {
    type: smartGetValue('smart-create-type') || 'event',
    source: smartGetValue('smart-create-source') || 'event',
    title: smartGetValue('smart-create-title-input').trim(),
    date: smartGetValue('smart-create-date'),
    time: allDay ? '' : smartGetValue('smart-create-time'),
    endTime: allDay ? '' : smartGetValue('smart-create-end-time'),
    allDay,
    category: smartGetValue('smart-create-category').trim(),
    status: smartGetValue('smart-create-status'),
    reminder: smartGetValue('smart-create-reminder'),
    timezone: smartGetValue('smart-create-timezone') || smartDefaultTimezone(),
    guests: smartGetValue('smart-create-guests').trim(),
    location: smartGetValue('smart-create-location').trim(),
    color: smartGetValue('smart-create-color') || '#b38549',
    icon: smartGetValue('smart-create-icon') || 'calendar',
    description: smartGetValue('smart-create-description').trim()
  };
}
function saveSmartCalendarEntry(){
  ensureAppointmentData();
  if (smartCalendarEditingEvent && !smartCalendarEditingEvent.editable) return;
  const p = smartFormPayload();
  if (!p.title || !p.date || !dateFromISO(p.date)) { covAlert('Please add a title and valid date.'); return; }
  const editSource = smartGetValue('smart-edit-source');
  const editIndex = smartResolveEditIndex(editSource,parseInt(smartGetValue('smart-edit-index'),10),smartCalendarEditingEvent?.sourceId || '');
  const target = editSource || p.source || p.type;
  if (target === 'task') {
    const row = Number.isInteger(editIndex) && data.tasks[editIndex] ? data.tasks[editIndex] : {};
    ensureRowId(row,'tasks');
    Object.assign(row,{task:p.title,cat:p.category||'Planning',date:p.date,time:p.time,endTime:p.endTime,allDay:p.allDay,status:p.status||'Not Started',notes:p.description,description:p.description,guests:p.guests,location:p.location,color:p.color,icon:p.icon,reminder:p.reminder,timezone:p.timezone});
    if (Number.isInteger(editIndex) && data.tasks[editIndex]) data.tasks[editIndex]=row; else data.tasks.push(row);
  } else if (target === 'appointment') {
    const row = Number.isInteger(editIndex) && data.appointments[editIndex] ? data.appointments[editIndex] : {};
    ensureRowId(row,'appointments');
    Object.assign(row,{title:p.title,category:p.category||'Appointment',date:p.date,time:p.time,endTime:p.endTime,allDay:p.allDay,status:p.status||'Pending',notes:p.description,description:p.description,guests:p.guests,location:p.location,color:p.color,icon:p.icon,reminder:p.reminder,timezone:p.timezone});
    if (Number.isInteger(editIndex) && data.appointments[editIndex]) data.appointments[editIndex]=row; else data.appointments.push(row);
  } else if (target === 'plan') {
    const row = Number.isInteger(editIndex) && data.plan[editIndex] ? data.plan[editIndex] : {};
    ensureRowId(row,'plan');
    Object.assign(row,{phase:p.category||'Wedding Month',task:p.title,owner:p.guests,due:p.date,time:p.time,endTime:p.endTime,allDay:p.allDay,priority:row.priority||'Medium',status:p.status||'Upcoming',done:p.status==='Complete',notes:p.description,description:p.description,guests:p.guests,location:p.location,color:p.color,icon:p.icon,reminder:p.reminder,timezone:p.timezone});
    if (Number.isInteger(editIndex) && data.plan[editIndex]) data.plan[editIndex]=row; else data.plan.push(row);
  } else if (target === 'timeline') {
    const row = Number.isInteger(editIndex) && data.timeline[editIndex] ? data.timeline[editIndex] : {};
    ensureRowId(row,'timeline');
    Object.assign(row,{event:p.title,date:p.date,time:p.time,endTime:p.endTime,allDay:p.allDay,location:p.location,responsible:p.guests,duration:row.duration||'',status:p.status||'Scheduled',notes:p.description,description:p.description,guests:p.guests,color:p.color,icon:p.icon,reminder:p.reminder,timezone:p.timezone});
    if (Number.isInteger(editIndex) && data.timeline[editIndex]) data.timeline[editIndex]=row; else data.timeline.push(row);
  } else if (target === 'vendorArrival') {
    const row = Number.isInteger(editIndex) && data.vtimeline[editIndex] ? data.vtimeline[editIndex] : {};
    ensureRowId(row,'vtimeline');
    Object.assign(row,{vendor:p.title,date:p.date,time:p.time,endTime:p.endTime,allDay:p.allDay,location:p.location,contact:p.guests,status:p.status||'Scheduled',notes:p.description,description:p.description,guests:p.guests,color:p.color,icon:p.icon,reminder:p.reminder,timezone:p.timezone});
    if (Number.isInteger(editIndex) && data.vtimeline[editIndex]) data.vtimeline[editIndex]=row; else data.vtimeline.push(row);
  } else {
    const row = Number.isInteger(editIndex) && data.calendarEvents[editIndex] ? data.calendarEvents[editIndex] : {};
    ensureRowId(row,'calendarEvents');
    Object.assign(row,{title:p.title,category:p.category||'Wedding',date:p.date,time:p.time,endTime:p.endTime,allDay:p.allDay,status:p.status||'Scheduled',notes:p.description,description:p.description,guests:p.guests,location:p.location,color:p.color,icon:p.icon,reminder:p.reminder,timezone:p.timezone});
    if (Number.isInteger(editIndex) && data.calendarEvents[editIndex]) data.calendarEvents[editIndex]=row; else data.calendarEvents.push(row);
  }
  ensureRelationalDataModel();
  smartSelectedDate = p.date;
  smartCalendarMonth = new Date(dateFromISO(p.date).getFullYear(), dateFromISO(p.date).getMonth(), 1);
  save();
  closeSmartCalendarCreate();
  renderSmartCalendar();
  if (typeof renderTasks === 'function') renderWhenInputComplete(renderTasks);
  if (typeof renderAppointments === 'function') renderWhenInputComplete(renderAppointments);
  if (typeof renderPlan === 'function') renderWhenInputComplete(renderPlan);
  if (typeof renderTimeline === 'function') renderWhenInputComplete(renderTimeline);
  if (typeof renderVTimeline === 'function') renderWhenInputComplete(renderVTimeline);
}
function smartTimezoneId(label){
  const raw = String(label || '').trim();
  if (/^[A-Za-z]+\/[A-Za-z0-9_+\-]+(?:\/[A-Za-z0-9_+\-]+)?$/.test(raw) || raw === 'Etc/UTC') return raw;
  const s = String(raw || smartDefaultTimezone()).toLowerCase();
  if (s.includes('hawaii')) return 'Pacific/Honolulu';
  if (s.includes('alaska')) return 'America/Anchorage';
  if (s.includes('pacific')) return 'America/Los_Angeles';
  if (s.includes('mountain')) return 'America/Denver';
  if (s.includes('central')) return 'America/Chicago';
  if (s.includes('eastern')) return 'America/New_York';
  if (s.includes('atlantic')) return 'America/Halifax';
  if (s.includes('greenwich') || s.includes('gmt+00')) return 'Etc/UTC';
  return Intl.DateTimeFormat().resolvedOptions().timeZone || 'America/New_York';
}
function smartDateStamp(date,time=''){
  return String(date||'').replaceAll('-','') + (time ? 'T' + String(time).replace(':','') + '00' : '');
}
function smartExportPayload(){
  const p = smartFormPayload();
  if (!p.title || !p.date) return null;
  const end = p.endTime || (p.time ? p.time : '');
  return {...p, tzid:smartTimezoneId(p.timezone), endTime:end};
}
function openSmartGoogleCalendar(){
  const msg = 'External calendar connections are an Enhancement. Use Download .ics or Export All .ics for launch.';
  const note = document.getElementById('smart-create-source-note');
  if (note) note.textContent = msg;
  if (typeof showToast === 'function') showToast(msg);
  else if (typeof covAlert === 'function') covAlert(msg);
}
function smartReminderLabel(v){
  const n = Number(v);
  if (!v && v !== '0') return 'None';
  if (n===0) return 'At event time';
  if (n===15) return '15 minutes before';
  if (n===60) return '1 hour before';
  if (n===1440) return '1 day before';
  if (n===10080) return '1 week before';
  return `${n} minutes before`;
}
function icsEscape(value){ return String(value||'').replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;'); }
function downloadSmartCalendarICS(){
  const p = smartExportPayload();
  if (!p) { covAlert('Add a title and date before exporting.'); return; }
  const uid = `covenant-${Date.now()}@planner`;
  const dtstamp = new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');
  const lines = ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//The Covenant Wedding Planner//Smart Calendar//EN','BEGIN:VEVENT',`UID:${uid}`,`DTSTAMP:${dtstamp}`,`SUMMARY:${icsEscape(p.title)}`];
  if (p.allDay) {
    lines.push(`DTSTART;VALUE=DATE:${smartDateStamp(p.date)}`,`DTEND;VALUE=DATE:${smartDateStamp(dateAddISO(p.date,1))}`);
  } else {
    lines.push(`DTSTART;TZID=${p.tzid}:${smartDateStamp(p.date,p.time||'09:00')}`,`DTEND;TZID=${p.tzid}:${smartDateStamp(p.date,p.endTime||p.time||'10:00')}`);
  }
  if (p.location) lines.push(`LOCATION:${icsEscape(p.location)}`);
  const desc = [p.description, p.guests ? `Guests: ${p.guests}` : ''].filter(Boolean).join('\n');
  if (desc) lines.push(`DESCRIPTION:${icsEscape(desc)}`);
  if (p.reminder !== '') {
    const mins = Number(p.reminder||0);
    const trigger = mins === 0 ? 'PT0M' : mins >= 1440 ? `-P${Math.round(mins/1440)}D` : `-PT${mins}M`;
    lines.push('BEGIN:VALARM',`TRIGGER:${trigger}`,'ACTION:DISPLAY',`DESCRIPTION:${icsEscape(p.title)}`,'END:VALARM');
  }
  lines.push('END:VEVENT','END:VCALENDAR');
  const blob = new Blob([lines.join('\r\n')], {type:'text/calendar'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = `${p.title.replace(/[^a-z0-9]+/gi,'-').replace(/^-|-$/g,'') || 'calendar-event'}.ics`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
function downloadBulkICS(){
  const events = buildSmartCalendarEvents();
  if (!events.length) { covAlert('No events to export.'); return; }
  const tz = data.setup.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone || 'America/New_York';
  const dtstamp = new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');
  const lines = ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//The Covenant Wedding Planner//Bulk Export//EN'];
  events.forEach((ev, idx) => {
    if (!ev.date) return;
    const uid = `covenant-bulk-${idx}-${Date.now()}@planner`;
    lines.push('BEGIN:VEVENT',`UID:${uid}`,`DTSTAMP:${dtstamp}`,`SUMMARY:${icsEscape(ev.title||'Event')}`);
    const ds = ev.date.replace(/-/g,'');
    if (ev.allDay || !ev.time) {
      lines.push(`DTSTART;VALUE=DATE:${ds}`);
    } else {
      const ts = (ev.time||'09:00').replace(':','') + '00';
      lines.push(`DTSTART;TZID=${tz}:${ds}T${ts}`);
      if (ev.endTime) { const es = ev.endTime.replace(':','') + '00'; lines.push(`DTEND;TZID=${tz}:${ds}T${es}`); }
    }
    if (ev.source) lines.push(`DESCRIPTION:${icsEscape('Source: '+ev.source)}`);
    lines.push('END:VEVENT');
  });
  lines.push('END:VCALENDAR');
  const blob = new Blob([lines.join('\r\n')], {type:'text/calendar'});
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
  a.download = 'covenant-wedding-all-events.ics'; a.click(); URL.revokeObjectURL(a.href);
}
function addManualCalendarEvent(dateOverride){
  openSmartCalendarCreate('event', dateOverride || smartSelectedDate || todayISO());
}
function deleteManualCalendarEvent(i){
  if (!Array.isArray(data.calendarEvents) || !data.calendarEvents[i]) return;
  data.calendarEvents.splice(i,1);
  save();
  renderSmartCalendar();
}

/* ════════════════════════════════════════════════
   EXPORT / IMPORT
════════════════════════════════════════════════ */
function exportJSON() {
  markBackupTaken();
  const blob = new Blob([JSON.stringify(data, null, 2)], {type:'application/json'});
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = 'covenant-wedding-planner-backup-' + new Date().toISOString().split('T')[0] + '.json';
  a.click();
  URL.revokeObjectURL(url);
  if (typeof renderBackupReminder === 'function') renderBackupReminder();
}

function deepMergePlannerData(base, incoming) {
  if (!incoming || typeof incoming !== 'object') return base;
  const out = Array.isArray(base) ? base.slice() : { ...base };
  Object.keys(incoming).forEach(key => {
    const val = incoming[key];
    if (Array.isArray(val)) { out[key] = val; return; }
    if (val && typeof val === 'object' && base && typeof base[key] === 'object' && !Array.isArray(base[key])) {
      out[key] = deepMergePlannerData({ ...base[key] }, val);
      return;
    }
    out[key] = val;
  });
  return out;
}

function importJSON(event) {
  const file = event.target.files[0];
  if (!file) return;
  const reader = new FileReader();
  reader.onload = async e => {
    try {
      const imported = JSON.parse(e.target.result);
      const ig = (imported.guests||[]).length, ip = (imported.payments||[]).length, it = (imported.tasks||[]).length;
      const cg = (data.guests||[]).length, cp = (data.payments||[]).length, ct = (data.tasks||[]).length;
      const preview = 'This backup contains: ' + ig + ' guests, ' + ip + ' payments, ' + it + ' tasks.\n'
        + 'Your current profile has: ' + cg + ' guests, ' + cp + ' payments, ' + ct + ' tasks.\n\n'
        + 'Import will replace all current data. Continue?';
      if (!(await covConfirm(preview, {title:'Restore backup?', danger:true, okText:'Import & replace'}))) return;
      data = deepMergePlannerData(blankData(), imported);
      save();
      initAll();
      showToast('Planner restored successfully!');
    } catch(err) {
      covAlert('Error reading backup file. Make sure it is a valid Covenant Planner backup (.json).');
    }
  };
  reader.readAsText(file);
  event.target.value = '';
}

/* ════════════════════════════════════════════════
   DUAL-FORMAT RESTORE (Track 4.4 / Phase B)
   One "Restore" control now accepts BOTH a .json backup and a portable
   .sqlite database. CovenantBackup.restoreFromFile() (sqlite-backup.js)
   auto-detects the format and calls back into applyRestoredPlannerData()
   to repopulate + re-render the visible app. JSON stays the default/legacy
   path; SQLite restore hydrates via hydrateDataFromSqlite() then re-renders.
════════════════════════════════════════════════ */

// Apply a restored planner object (from either a JSON backup or a SQLite
// hydration) into the live app: confirm, replace `data`, persist, re-render.
// Returns true if applied, false if the user cancelled. Shared by both formats.
function applyRestoredPlannerData(obj, opts) {
  opts = opts || {};
  if (!obj || typeof obj !== 'object') { covAlert('That backup did not contain any readable planner data.'); return false; }
  const ig = (obj.guests || []).length, ip = (obj.payments || []).length, it = (obj.tasks || []).length;
  const cg = (data.guests || []).length, cp = (data.payments || []).length, ct = (data.tasks || []).length;
  const fmtLabel = opts.format === 'sqlite' ? 'SQLite database backup' : 'JSON backup';
  const preview = 'This ' + fmtLabel + ' contains: ' + ig + ' guests, ' + ip + ' payments, ' + it + ' tasks.\n'
    + 'Your current profile has: ' + cg + ' guests, ' + cp + ' payments, ' + ct + ' tasks.\n\n'
    + 'Restore will replace all current data in this profile. Continue?';
  if (!opts.skipConfirm && !confirm(preview)) return false;
  data = deepMergePlannerData(blankData(), obj);
  if (typeof migrateData === 'function') migrateData(data);
  save();
  initAll();
  if (typeof showToast === 'function') showToast('Planner restored successfully!');
  return true;
}

// Text entry point kept for CovenantBackup / programmatic JSON restore.
function importJSONText(text) {
  let parsed;
  try { parsed = JSON.parse(text); }
  catch (e) { covAlert('Error reading backup file. Make sure it is a valid Covenant Planner backup (.json).'); return false; }
  return applyRestoredPlannerData(parsed, { format: 'json' });
}

// File-input handler for the unified Restore button (accepts .json and .sqlite).
function restorePlannerBackup(event) {
  const file = event.target && event.target.files && event.target.files[0];
  if (event.target) event.target.value = '';
  if (!file) return;
  if (typeof CovenantBackup === 'undefined' || !CovenantBackup || typeof CovenantBackup.restoreFromFile !== 'function') {
    // Fallback: no backup bridge loaded — treat as JSON via the legacy reader.
    const reader = new FileReader();
    reader.onload = e => importJSONText(e.target.result);
    reader.readAsText(file);
    return;
  }
  Promise.resolve(CovenantBackup.restoreFromFile(file, activeProfile)).catch(err => {
    console.warn('Restore failed', err);
    covAlert('Could not restore that file: ' + ((err && err.message) || err) + '\n\nMake sure it is a Covenant Planner .json or .sqlite backup.');
  });
}

// Trigger a portable .sqlite database download (dual-format backup).
function downloadSqliteBackup() {
  try {
    const backupReady = (typeof sqliteBackupReady === 'function' && sqliteBackupReady()) ||
      (typeof CovenantBackup !== 'undefined' && CovenantBackup && typeof CovenantBackup.sqliteBackupReady === 'function' && CovenantBackup.sqliteBackupReady(activeProfile));
    if (!backupReady) {
      if (typeof showToast === 'function') showToast('Backup is still loading — try again in a moment.', 'warn');
      return;
    }
    if (typeof CovenantBackup !== 'undefined' && CovenantBackup && typeof CovenantBackup.downloadSqliteBackup === 'function') {
      if (typeof flushSqliteSync === 'function') flushSqliteSync();   // ensure the .sqlite reflects the latest edit
      if (typeof markBackupTaken === 'function') markBackupTaken();
      CovenantBackup.downloadSqliteBackup(undefined, activeProfile);
      if (typeof showToast === 'function') showToast('Backup downloaded.');
      if (typeof renderBackupReminder === 'function') renderBackupReminder();
      return;
    }
    // SQLite engine unavailable — fall back to JSON with an explicit notice (never silent).
    if (typeof exportJSON === 'function') {
      exportJSON();
      if (typeof showToast === 'function') showToast('SQLite unavailable — downloaded JSON backup instead.', 'warn');
      return;
    }
    covAlert('Backup is unavailable in this build.');
  } catch (e) {
    console.warn('SQLite backup failed; falling back to JSON backup.', e);
    if (typeof exportJSON === 'function') {
      try {
        exportJSON();
        if (typeof showToast === 'function') showToast('SQLite backup failed — downloaded JSON backup instead.', 'warn');
        return;
      } catch (e2) {}
    }
    covAlert('Could not create a backup: ' + ((e && e.message) || e));
  }
}

