function addTable() {
  const nameEl = document.getElementById('new-table-name');
  const capEl = document.getElementById('new-table-cap');
  const name = (nameEl.value || '').trim();
  const cap = parseInt(capEl.value) || 8;
  if (!name) { covAlert('Please enter a table name or number.'); return; }
  if (data.tables.some(t => String(t.name).toLowerCase() === name.toLowerCase())) { covAlert('That table already exists.'); return; }
  data.tables.push({ name, capacity: cap, placement: '', type: inferTableType(name), shape: inferTableType(name)==='guest' ? 'circle' : 'rect', vip: isVipName(name), facing: 'down' });
  nameEl.value = ''; capEl.value = '';
  document.getElementById('table-add-inline')?.classList.remove('open');
  save();
  renderTables();
}
async function addSpecialTable(kind) {
  const cfgs = {
    head: { name:'Head Table', type:'head', shape:'rect', capacity:10, placement:'Front of reception, facing the dance floor', vip:true, facing:'down' },
    'sweetheart-rect': { name:'Sweetheart Rectangle Table', type:'sweetheart', shape:'rect', capacity:2, placement:'Couple table, centered near the dance floor', vip:true, facing:'down' },
    'sweetheart-circle': { name:'Sweetheart Circle Table', type:'sweetheart', shape:'circle', capacity:2, placement:'Couple table, centered near the dance floor', vip:true, facing:'down' },
    parents: { name:'Parents Table', type:'parents', shape:'circle', capacity:8, placement:'VIP family table close to the head table', vip:true, facing:'down' }
  };
  const cfg = Object.assign({}, cfgs[kind] || cfgs.head);
  let name = cfg.name;
  if (data.tables.some(t => String(t.name).toLowerCase() === name.toLowerCase())) {
    let n = 2;
    while (data.tables.some(t => String(t.name).toLowerCase() === `${name} ${n}`.toLowerCase())) n++;
    name = `${name} ${n}`;
  }
  let capacity = cfg.capacity;
  if (cfg.type === 'head') {
    const answer = await covPrompt('How many people should sit at the head table?', {defaultValue: String(cfg.capacity)});
    if (answer === null) return;
    capacity = Math.max(1, parseInt(answer) || cfg.capacity);
  }
  data.tables.push({ name, capacity, placement: cfg.placement, type: cfg.type, shape: cfg.shape, vip: cfg.vip, facing: cfg.facing });
  save();
  renderTables();
}
function updateTable(i, key, val) {
  if (!data.tables[i]) return;
  const oldName = data.tables[i].name;
  if (key === 'capacity') val = Math.max(1, parseInt(val) || 1);
  if (key === 'vip') val = !!val;
  if (key === 'preset') {
    const preset = tablePreset(val);
    if (preset) {
      data.tables[i].shape = preset.shape;
      data.tables[i].capacity = preset.capacity;
      /* Preset owns footprint orientation for banquet rectangles. */
      if (preset.shape === 'circle') data.tables[i].vert = false;
    }
  }
  /* Shape is owned by Size & Shape (preset). A direct shape change means
     custom geometry — clear preset so normalizeTableRecord cannot fight back. */
  if (key === 'shape') data.tables[i].preset = '';
  if (key === 'type') {
    if (!data.tables[i].preset) {
      if (val === 'head') data.tables[i].shape = 'rect';
      else if (val === 'sweetheart') {
        if (data.tables[i].shape !== 'rect' && data.tables[i].shape !== 'circle') {
          data.tables[i].shape = 'circle';
        }
      } else if (val === 'parents' || val === 'guest') {
        if (!data.tables[i].shape) data.tables[i].shape = 'circle';
      }
    }
  }
  data.tables[i][key] = val;
  if (key === 'name') {
    if (!data.tables[i].type) data.tables[i].type = inferTableType(val);
    (data.guests || []).forEach(g => { if (tableNamesMatch(g.table, oldName)) g.table = tableLabel(val); });
  }
  save();
  if (['name','capacity','type','shape','preset','vip','facing'].includes(key)) {
    const shell = document.getElementById('panel-tables')?.dataset?.uedShell || '';
    if (typeof window.__tablesRenderRd === 'function' && String(shell).indexOf('tables-rd8a') === 0) {
      /* Redesign page owns the full refresh via tablesUpdateField; still
         redraw the floor plan so Size & Shape changes are visible immediately
         even when called from older card markup. */
      renderGuestTableOptions();
      if (typeof renderTableMap === 'function') renderTableMap();
      return;
    }
    renderTableLayoutStats(); renderTableAssignments(); renderTableMap(); renderGuestTableOptions(); if (typeof renderPageUxChrome === 'function') renderPageUxChrome('tables');
  }
}
async function removeTable(i) {
  if (!(await covConfirm('Remove this table? Guests keep their table number on the Guest List.', {title:'Remove table?', danger:true, okText:'Remove'}))) return;
  data.tables.splice(i, 1); save(); renderTables();
}
// Show "Table 3" for plain numbers, or the custom name as-is.
function tableLabel(name) { return /^\d+$/.test(String(name).trim()) ? 'Table ' + String(name).trim() : (name || '(unnamed)'); }


