function mergePeopleNames(existing, toAdd){
  const list = parsePeopleNames(existing);
  toAdd.forEach(name => {
    const n = String(name || '').trim();
    if (!n) return;
    if (!list.some(x => x.toLowerCase() === n.toLowerCase())) list.push(n);
  });
  return list.join(', ');
}
function syncShotPeopleInput(entity, id, val){
  const mount = document.getElementById(entity === 'videoShots' ? 'cwp-videoShots' : 'cwp-shotlist');
  if (!mount) return;
  const tr = [...mount.querySelectorAll('tr[data-id]')].find(row => String(row.getAttribute('data-id')) === String(id));
  const input = tr ? tr.querySelector('.shot-people-input') : null;
  if (input) {
    input.value = val;
    if (typeof cwpGrow === 'function') cwpGrow(input);
  }
}
function setShotPeopleValue(entity, id, val){
  const row = shotPeopleRow(entity, id);
  if (!row) return false;
  row.people = val;
  save();
  syncShotPeopleInput(entity, id, val);
  if (entity === 'videoShots') {
    if (typeof renderVideoShotlistStats === 'function') renderVideoShotlistStats();
  } else if (typeof renderShotlistStats === 'function') renderShotlistStats();
  return true;
}
function syncShotPeoplePickerChecks(entity, id){
  const pop = document.getElementById('shot-people-picker-pop');
  const row = shotPeopleRow(entity, id);
  if (!pop || !row) return;
  const current = parsePeopleNames(row.people);
  pop.querySelectorAll('.spp-list input[type="checkbox"]').forEach(cb => {
    const name = cb.getAttribute('data-name') || '';
    cb.checked = current.some(c => c.toLowerCase() === name.toLowerCase());
  });
}
function closeShotPeoplePicker(){
  const pop = document.getElementById('shot-people-picker-pop');
  if (pop) pop.remove();
  _shotPeoplePickerTarget = null;
  document.removeEventListener('mousedown', shotPeoplePickerOutside, true);
}
function shotPeoplePickerOutside(ev){
  const pop = document.getElementById('shot-people-picker-pop');
  if (pop && !pop.contains(ev.target) && !ev.target.closest('.shot-people-pick')) closeShotPeoplePicker();
}
function openShotPeoplePicker(entity, id, btn){
  closeShotPeoplePicker();
  const row = shotPeopleRow(entity, id);
  if (!row) return;
  _shotPeoplePickerTarget = { entity, id };
  const current = parsePeopleNames(row.people);
  const pop = document.createElement('div');
  pop.id = 'shot-people-picker-pop';
  pop.className = 'shot-people-picker-pop';
  const opts = shotGuestChecklistOptions();
  pop.innerHTML = '<div class="spp-head"><strong>Who\'s in this shot</strong><button type="button" class="cwp-modal-close" onclick="closeShotPeoplePicker()">×</button></div>'
    + '<p class="spp-hint">Check names from your guest list and wedding party, then click <strong>Add</strong> to append them to the Who\'s In It field.</p>'
    + '<div class="spp-list">' + (opts.length ? opts.map(o => {
      const checked = current.some(c => c.toLowerCase() === o.label.toLowerCase());
      return '<label class="spp-item"><input type="checkbox" data-name="'+escapeAttr(o.label)+'" '+(checked?'checked':'')+'><span>'+escapeHtml(o.label)+'</span><small>'+escapeHtml(o.group)+'</small></label>';
    }).join('') : '<p class="spp-empty">Add guests on the Guest List first, then pick names here.</p>')
    + '</div><div class="spp-actions"><button type="button" class="cwp-btn cwp-btn-ghost cwp-btn-sm" onclick="closeShotPeoplePicker()">Cancel</button><button type="button" class="cwp-btn cwp-btn-primary cwp-btn-sm" onclick="addShotPeoplePicker()">Add</button></div>';
  document.body.appendChild(pop);
  if (typeof window.rdAnchorToButton === 'function') {
    window.rdAnchorToButton(pop, btn, { keepWidth: true, minWidth: 280, gap: 6, zIndex: 12000 });
  } else {
    const rect = btn.getBoundingClientRect();
    pop.style.position = 'fixed';
    pop.style.display = 'inline-block';
    const w = Math.max(pop.offsetWidth || 0, 280);
    pop.style.top = (rect.bottom + 6) + 'px';
    pop.style.left = Math.max(8, Math.min(rect.left, window.innerWidth - w - 12)) + 'px';
  }
  setTimeout(() => document.addEventListener('mousedown', shotPeoplePickerOutside, true), 0);
}
function addShotPeoplePicker(){
  const target = _shotPeoplePickerTarget;
  const pop = document.getElementById('shot-people-picker-pop');
  if (!target || !pop) return;
  const checked = [...pop.querySelectorAll('.spp-list input[type="checkbox"]:checked')].map(cb => cb.getAttribute('data-name')).filter(Boolean);
  if (!checked.length) { covAlert('Check at least one name, then click Add.'); return; }
  const row = shotPeopleRow(target.entity, target.id);
  if (!row) return;
  const val = mergePeopleNames(row.people, checked);
  if (!setShotPeopleValue(target.entity, target.id, val)) return;
  syncShotPeoplePickerChecks(target.entity, target.id);
}
function shotlistTab(tab){
  syncShotlistPageTab(tab);
  if (_shotlistTab === 'video') renderVideoShotlist();
  else renderShotlist();
  const key = _shotlistTab === 'video' ? 'videoShots' : 'shotlist';
  if (shotInlineAvailable() && !(recordEditorState?.inlineMount === 'shotlist-inline-editor-body' && recordEditorState.key === key)) {
    setShotInlineTable(key, null, {scroll:false});
  }
}
async function loadVideoShotPreset(){
  if (!Array.isArray(data.videoShotlist)) data.videoShotlist = [];
  if (data.videoShotlist.length && !await starterConfirm('Add the starter wedding video shot list to your current video shots?')) return;
  VIDEO_SHOT_PRESET.forEach(([section, shot, must, people, notes]) => data.videoShotlist.push({
    section, shot, must, priority: must === 'Yes' ? 'Must-Have' : 'Important', people,
    timing: shotDefaultTiming(section), notes, completed: false
  }));
  save();
  renderVideoShotlist();
}
function renderVideoShotlistStats(){
  const host = document.getElementById('video-shotlist-stat-grid');
  if (!host) return;
  const rows = safeArray(data.videoShotlist).map(normalizeShotRow);
  const total = rows.length;
  const must = rows.filter(r => shotDefaultPriority(r) === 'Must-Have' || r.must === 'Yes').length;
  const ceremony = rows.filter(r => /ceremony/i.test(r.section || '')).length;
  const completed = rows.filter(shotIsCompleted).length;
  const ms = (icon, label, value, sub) => `<div class="m-stat"><div class="m-stat-top">${shotLineIcon(icon)}<span class="m-stat-label">${escapeHtml(label)}</span></div><div class="m-stat-val">${escapeHtml(String(value))}</div><div class="m-stat-sub">${escapeHtml(sub)}</div></div>`;
  host.innerHTML = [
    ms('camera','Video shots', total, total ? 'Planned film moments' : 'Load the starter list'),
    ms('star','Must-capture', must, total ? Math.round((must / Math.max(total, 1)) * 100) + '% of list' : 'Prioritize key clips'),
    ms('chapel','Ceremony clips', ceremony, 'Liturgical & vow coverage'),
    ms('check','Completed', completed, total ? Math.round((completed / Math.max(total, 1)) * 100) + '% done' : '0% done')
  ].join('');
}
function renderVideoShotlist(){
  if (!Array.isArray(data.videoShotlist)) data.videoShotlist = [];
  data.videoShotlist.forEach(normalizeShotRow);
  if (typeof cwpRenderTable === 'function' && cwpMountOnPanel('videoShots')) {
    renderShotPeopleDatalist();
    cwpRenderTable('videoShots');
    afterShotPreviewRendered('videoShots');
    renderVideoShotlistStats();
    renderVideoShotOverviewCards();
    if (typeof renderPageUxChrome === 'function') renderPageUxChrome('shotlist');
    return;
  }
}
function renderShotlist() {
  document.getElementById('panel-shotlist')?.classList.add('ued-scope');
  if (!Array.isArray(data.shotlist)) data.shotlist = [];
  data.shotlist.forEach(normalizeShotRow);
  /* Converted to the CWP unified table engine. */
  if (typeof cwpRenderTable === 'function' && cwpMountOnPanel('shotlist')) {
    renderShotPeopleDatalist();
    cwpRenderTable('shotlist');
    afterShotPreviewRendered('shotlist');
    renderShotlistStats();
    renderShotOverviewCards();
    if (typeof renderPageUxChrome === 'function') renderPageUxChrome('shotlist');
    return;
  }
  renderDesignHubPreviews();
  updateShotFilterOptions();
  renderShotPeopleDatalist();
  renderShotlistStats();
  renderShotOverviewCards();
  const tbody = document.getElementById('shotlist-body');
  if (!tbody) return;
  tbody.innerHTML = '';
  const filters = currentShotFilters();
  const visible = data.shotlist.map((row, i) => ({row: normalizeShotRow(row), i})).filter(({row}) => shotMatchesFilters(row, filters));
  renderShotlistSummary(data.shotlist.length, visible.length);
  if (!visible.length) {
    tbody.innerHTML = `<tr class="shotlist-empty-row" data-no-bulk="true"><td colspan="10">No photo shots match these filters. Clear filters or add a new shot.</td></tr>`;
    return;
  }
  visible.forEach(({row, i}) => {
    const priority = shotDefaultPriority(row);
    const tr = document.createElement('tr');
    tr.dataset.rowIndex = i;
    tr.innerHTML = `
      <td><label class="shotlist-complete-check"><input type="checkbox" ${shotIsCompleted(row) ? 'checked' : ''} onchange="updateShot(${i},'completed',this.checked)" aria-label="Mark shot completed"></label></td>
      <td><input type="text" list="shot-section-options" value="${escapeHtml(row.section)}" placeholder="Pick or type" oninput="updateShot(${i},'section',this.value)"></td>
      <td><input type="text" value="${escapeHtml(row.shot)}" style="min-width:220px" oninput="updateShot(${i},'shot',this.value)"></td>
      <td><select class="shot-priority-pill ${shotPriorityClass(priority)}" onchange="updateShot(${i},'priority',this.value)">${SHOT_PRIORITY_OPTIONS.map(opt=>`<option value="${opt}" ${priority===opt?'selected':''}>${opt}</option>`).join('')}</select></td>
      <td>${selInline(row.must||'No', ['No','Yes'], i, 'must', 'updateShot')}</td>
      <td><input type="text" list="shot-people-options" value="${escapeHtml(row.people)}" placeholder="Who's in it" oninput="updateShot(${i},'people',this.value)"></td>
      <td><input type="text" list="shot-timing-options" value="${escapeHtml(row.timing || '')}" placeholder="e.g. Ceremony" oninput="updateShot(${i},'timing',this.value)"></td>
      <td><input type="text" value="${escapeHtml(row.notes)}" placeholder="Notes" oninput="updateShot(${i},'notes',this.value)"></td>
      <td>${plannerTrashButton(`deleteRow('shotlist',${i})`,'Delete shot')}</td>`;
    tbody.appendChild(tr);
  });
  standardizeTableTrashButtons(document.getElementById('panel-shotlist'));
}
function updateShot(i, key, val) {
  if (!data.shotlist[i]) return;
  if (key === 'completed') val = !!val;
  data.shotlist[i][key] = val;
  if (key === 'section' && !data.shotlist[i].timing) data.shotlist[i].timing = shotDefaultTiming(val);
  save();
  renderWhenInputComplete(() => {
    renderShotlistStats();
    renderShotOverviewCards();
    updateShotFilterOptions();
  });
}

/* ════════════════════════════════════════════════
   FAQ
════════════════════════════════════════════════ */
const FAQ_ITEMS = [
  ['What is the Database Hub vs the regular pages?',
   'The <strong>Database Hub</strong> (Start Planning menu or top bar) is one workspace for full tables — guest tracker, payments, catering menus, budget line items, and more — with bulk edit and filters. <strong>Minimal pages</strong> like Guest List, Budget, and Catering &amp; Menu stay read-first: stats, alerts, and record cards. Use the hub link at the bottom of those pages when you need every row or bulk actions.'],
  ['Will edits stay if I close the browser tab?',
   'Yes. Everything you type saves automatically to a private SQLite database in this browser, with a localStorage mirror for crash safety. Your work will still be here when you reopen the file in the same browser. Clearing browser history or site data erases it — use <strong>Download Backup</strong> regularly to save a portable <code>.sqlite</code> file. If backup says it is still loading, wait a few seconds after opening the planner so SQLite finishes booting for your active profile, then try again.'],
  ['Can this planner send invitations, RSVP reminders, or vendor emails for me?',
   'No — and that is intentional. This is an offline, privacy-first planner with no cloud account and no email server. It cannot send invites, RSVP reminders, or vendor messages on your behalf. Use <strong>Email Templates</strong> to draft copy-ready messages, then paste them into your own email or text app. For guest RSVPs, many couples use Google Forms and import responses with <strong>Import RSVP CSV</strong> on the Guest List page. Share Packets and Print Section are the best way to hand off read-only details to vendors, family, or your coordinator.'],
  ['What is the easiest way to use this planner on another laptop?',
   'On your current device click <strong>Download Backup</strong> to download the <code>.sqlite</code> file. Copy that file to the other laptop (USB, email, or cloud storage), open the planner there, click <strong>Restore</strong>, and select the file. Your whole planner comes with it.'],
  ['Can I rename categories, columns, and vendor types?',
   'You can freely rename anything you type in — budget categories, vendor categories, table names, task categories, and so on. The fixed column headers and dropdown choices (like RSVP or payment status) stay the same so the totals keep working.'],
  ['How do budget totals update in this dashboard?',
   'The dashboard reads straight from your Budget and Payments pages. As you edit "Actual" spending and payment statuses, the Budget Used %, Remaining, and the charts recalculate instantly — there’s nothing to refresh.'],
  ['What is the fastest method for seating assignments?',
   'On the <strong>Guest List</strong>, fill in the <strong>Table #</strong> column for each guest. Then open <strong>Table Layout</strong> — a card is created automatically for every table number, showing who’s seated there and a "5 of 8 seated" counter. Set each table’s seat count and add a placement note.'],
  ['Does this planner upload my information anywhere?',
   'No. It runs entirely on your device with no account, no cloud, and no internet required. Your information — including any photo you add — never leaves your computer unless you choose to export a backup or CSV.'],
  ['How can I turn off backup prompts?',
   'On first open, a one-time <strong>Protect your planning</strong> welcome invites you to download a backup or choose <strong>Remind me later</strong>. After that, a gentle banner under the top bar may appear when you have not backed up recently or after about 25 edits. You cannot fully disable these nudges — because your data lives only in this browser, downloading a <code>.sqlite</code> backup now and then is the only way to protect your work.'],
  ['Why did backup say it is still loading, or download JSON instead of .sqlite?',
   'Backup is gated until SQLite finishes booting and <code>COVENANT_SQLITE.profileId</code> matches your active wedding profile. If you click <strong>Download Backup</strong> in the first few seconds after opening the file, you may see “Backup is still loading — try again in a moment.” Wait until the planner finishes opening, then retry. If SQLite is unavailable in your browser session, the planner falls back to a legacy <code>.json</code> export and shows an explicit toast — it never silently substitutes JSON for <code>.sqlite</code>. Prefer <code>.sqlite</code> for full restore on another device.'],
  ['Is there a shorter onboarding PDF?',
   'You can make one in seconds: open the <strong>Instructions</strong> page and click <strong>Print</strong> in the top bar, then choose "Save as PDF." That gives you a concise, printable quick-start to keep or share.'],
  ['How do I see what a finished planner looks like?',
   'On the <strong>Instructions</strong> page click <strong>Load Sample Data</strong> to fill every section with an example wedding. When you’re ready for your own plan, use <strong>Reset All Data</strong> on the Instructions page to clear it.'],
  ['What device or browser works best?',
   'For setup and heavy editing, use a desktop or laptop in <strong>Chrome</strong> or <strong>Edge</strong>. The planner is viewable on tablets and phones, but large tables, CSV imports, backups, and detailed budget/guest work are much easier on a larger screen. Always reopen the planner in the same browser unless you restore from a backup.'],
  ['Can I track gifts from people who weren’t invited?',
   'Yes. On the <strong>Gift Log</strong>, the "From" box suggests names and households from your Guest List (and auto-fills their phone, email, and address when it matches) — but you can also type anyone who isn’t on it.'],
  ['Can I edit many rows at once?',
   'Yes. Every table has a checkbox on each row and a "select all" box in the header. Tick the rows you want, then use the <strong>Bulk edit</strong> menu above the table to pick a field (e.g. RSVP) and a value (e.g. Yes), or to delete the selected rows in one step.'],
  ['What does the Save button do if everything auto-saves?',
   'Your work already saves automatically as you type. The <strong>Save</strong> button is just a reassurance — click it to write immediately and refresh the "Saved …" time. It does the same thing as the automatic save.'],
  ['Can I show a scripture at the top of every page?',
   'Yes. On the <strong>Dashboard</strong>, fill in the <strong>Banner Scripture</strong> field (and an optional reference). It appears as a banner across the top of every page, and it saves with your data. Clear the field to hide it.'],
  ['How do the “Load …” preset buttons work?',
   'Several pages have a button that fills in a ready-made starter list — the 12-month <strong>Planning Timeline</strong>, the <strong>Essentials Checklist</strong>, the full <strong>Photo Shot List</strong>, standard <strong>Reception</strong> song moments, the honeymoon <strong>Packing</strong> list, and <strong>Newlywed Homecoming</strong> tasks, including its Name Change tab. They add to whatever is already there, and every row stays fully editable.'],
  ['Where do I keep my signed contracts and big PDFs?',
   'Keep the actual PDF files in a folder on your computer or cloud storage. On the <strong>Contracts, Invoices &amp; Rentals</strong> page, log each one (name, vendor, date, amount, status) and note where it is saved. You can attach a small photo/scan of a page for quick reference — large files are not embedded so your planner keeps saving reliably.'],
  ['Can I build my own color palette on the Vision Board?',
   'Yes. On the <strong>Vision Board</strong>, pick a ready-made palette or use the color pickers to build your own, then “Save Palette.” Each palette card shows the swatch, name, and hex on its face, with a <strong>Specs</strong> dropdown for HEX/RGB/CMYK/Pantone/fabric/paint. You can also upload inspiration photos into the gallery, organized into <strong>category tabs</strong> (Floral, Bridal, Decor, Stationery, Favorite Details), shrunk to fit and saved with your planner.'],
  ['How does the itemized Budget work?',
   'Each category has its own line items — type a cost for any item and it instantly rolls up into the category total, the top budget boxes, and the donut + bar at the top showing that category’s share of your budget. Click <strong>Load Full Budget Categories</strong> for a complete itemized starter (with tips and target %s), including Bride, Groom, Bridal Party, and Groom Party. Category names are a dropdown you can also type into.'],
  ['Can I widen the columns or rearrange tables?',
   'Yes. Drag the right edge of any column header to make a column wider (handy for long text). On the <strong>Table Layout</strong> page, use the <strong>Floor Plan</strong> to drag each table around the room and switch it between a circle and a rectangle with the ↺ button.'],
  ['Can I plan more than one wedding in the same file?',
   'Yes. Use the <strong>Wedding profile</strong> menu in the green bar at the top to create separate, independent planners — handy for a vow renewal, a second event, or a planner managing more than one couple. Each profile saves on its own and has its own backup. Switch any time; “Reset All Data” only clears the profile you’re currently in.'],
  ['Can I change the colors and fonts?',
   'Yes. In <strong>Wedding Setup</strong>, use the <strong>Theme</strong> and <strong>Font</strong> controls to restyle the whole planner. Try Forest & Gold, Burgundy & Cream, Dusty Blue, Blush & Rose Gold, Sage & Sand, or Classic Charcoal, and pick a font pairing you love. You can also click <strong>+ Custom Colors</strong> next to the Theme menu to build and save your own color theme. Your choice saves with each wedding profile.'],
  ['How does the Catering &amp; Menu page connect to Budget?',
   'The <strong>Catering &amp; Menu</strong> page owns four budget categories — Food, Cake &amp; Desserts, Drinks, and Rentals. As you build your menu and add costs, those items automatically appear in your <strong>Budget</strong> page as read-only lines with a "Managed in Catering &amp; Menu" badge. This prevents double-counting while keeping your budget totals accurate.'],
  ['How do Payments link to Budget and Contracts?',
   'Each payment row has a <strong>Budget Category</strong> dropdown — assign a category and the payment automatically appears in that budget section as a read-only "from Payments" line. You can also link each payment to a <strong>Contract</strong>. The planner keeps stable internal links behind the scenes and shows Data Health alerts if a linked vendor, category, contract, or source row needs review.'],
  ['What is the Smart Calendar?',
   'The <strong>Smart Calendar</strong> automatically pulls dates from 12 sources across your planner: Tasks, Appointments, Budget due dates, Payments, Vendors, Wedding Day Timeline, Planning Timeline, Wedding Weekend Logistics, Honeymoon dates, Rental pickup/return, Gift thank-you reminders, and manual calendar events. Toggle sources on or off to focus on what matters.'],
  ['What happens if my storage runs out?',
   'Browsers typically allow limited local storage. If you upload many large images (especially on the Vision Board), you may hit this limit. A red warning banner appears at the top if a save fails, prompting you to download a <code>.sqlite</code> backup immediately. To free space, remove some Vision Board images or inspiration photos.'],
  ['Where is my data stored?',
   'Your planner data is saved automatically in this browser using a private SQLite database on your device, with a localStorage mirror for extra crash safety. Nothing is uploaded to a cloud. Use <strong>Download Backup</strong> to save a portable <code>.sqlite</code> file, and <strong>Restore</strong> to bring it back on this or another device (also accepts <code>.db</code> and legacy <code>.json</code>).'],
  ['How do plus-ones and children count toward my totals?',
   'On the <strong>Guest List</strong>, tick <strong>+1</strong>, enter children, tick <strong>Family</strong>, or click <strong>Add Companions</strong> under a guest to enter each plus-one or child (name, meal, RSVP, table, etc.). Companions automatically roll into your guest count, kids count, seating, meal counts, and the Catering &amp; Budget estimates — and every page that reads your guest list sees them too.'],
  ['Can I create my own theme color?',
   'Yes. In <strong>Wedding Setup</strong> next to the Theme menu, click <strong>+ Custom Colors</strong> to open the Theme Builder. Name your theme and choose five colors (primary, primary-deep, accent, accent-light, soft) with a live preview. Saving adds it to the Theme menu, applies it across every page, and stores it with your wedding profile. You can re-apply or delete your custom themes from the same window.'],
  ['Do the Share Packets fill in automatically?',
   'Yes. On the <strong>Share Packets</strong> page, the vendor and wedding-party fields <strong>auto-fill from your planner</strong> — guest counts, meals, timeline, contacts, and more — and stay fully editable. Anything you type is saved and always wins. To pull a live value back into one box, click <strong>↺ Use planner value</strong>; to revert a whole packet, use <strong>Reset to planner data</strong>. The new <strong>Wedding Weekend Packets</strong> tab pulls live itinerary, travel, hotel, transportation, and VIP-care details from Wedding Weekend Logistics.'],
  ['How do the Email Templates personalize each message?',
   'On the <strong>Email Templates</strong> page, pick a category from the left rail and the editable cards appear on the right. Merge fields like <strong>{{bride}}</strong> and <strong>{{date}}</strong> fill in automatically from your Wedding Setup — the <strong>Available Merge Fields</strong> card lists every field and its current value. Edit the subject and body, then <strong>Copy</strong> or <strong>Open in Email</strong> in your own mail app. The planner does not send mail — it prepares copy you paste or open locally.'],
  ['Is my honeymoon budget part of my wedding budget?',
   'No — your honeymoon spending on the <strong>Honeymoon</strong> page is tracked <strong>separately</strong> so it never inflates your wedding budget totals. That page also has a built-in <strong>Currency Converter</strong> for planning costs in another currency.'],
  ['Can I rate tasks or assign them to specific people?',
   'Yes. On the <strong>Tasks</strong> page each task has priority, status, due date, notes, and an <strong>Assigned to</strong> field that lets you pick anyone from your Guest List or Wedding Party — the list grows automatically as you add people. Vendor star ratings live on the <strong>Vendors</strong> page where comparison and shortlisting happen. A starter <strong>"Assign 2 witnesses"</strong> task is included for you.'],
  ['Where is the Wedding Day Timeline?',
   'It has its own page under <strong>Ceremony &amp; Reception</strong> in the menu, with two tabs: <strong>Vertical Timeline</strong> (an elegant top-to-bottom view) and <strong>Day-Of Details</strong> (the Key Moments, Coordinator Notes, and Contact Reminders cards above the editable Day-Of table). The same vertical timeline also appears on your <strong>Dashboard</strong>, and any edits you make sync to both instantly.'],
  ['Are there keyboard shortcuts?',
   'Yes — the full list lives in the <strong>page sidebar</strong> under <strong>Keyboard shortcuts</strong>. Press <strong>[</strong> to show or hide that sidebar, <strong>?</strong> to jump to the shortcut list, <strong>Ctrl/Cmd+K</strong> for search, and <strong>Alt+1</strong>, <strong>Alt+C</strong>, or <strong>Alt+B</strong> to jump to Dashboard, Calendar, or Budget. <strong>Ctrl/Cmd+Z</strong> undoes, <strong>Ctrl/Cmd+Y</strong> (or <strong>Cmd+Shift+Z</strong> on Mac) redoes, and <strong>Ctrl/Cmd+S</strong> saves now. Auto-save also runs as you edit.'],
  ['Can I use a simpler version of the planner?',
   'Yes — and <strong>new users start in Essentials View by default</strong> so the menu stays calmer until you choose otherwise. Open <strong>Profile &amp; Display</strong> in the top bar and click <strong>Focus on Essentials</strong> to hide advanced pages like packets, Vision Board, contracts, and honeymoon planning — nothing is deleted. Use the <strong>Focus</strong> dropdown for presets like Planning core, Guests &amp; seating, Money, or Wedding weekend. Choose <strong>Full planner</strong> anytime to restore every page. The Essentials hub on Get Started, Dashboard, and Wedding Setup offers quick links to core pages.'],
  ['What are Data Health and Linked Records?',
   'Data Health appears on the Dashboard and points out relationship issues in plain language, such as a payment linked to a missing vendor or a guest assigned to a table that no longer exists. Linked Records appear inside key pop-out editors so you can see related payments, contracts, appointments, guests, tables, gifts, tasks, budget lines, or logistics without re-entering the same data.'],
  ['Can I share a read-only copy without live hosting?',
   'Because this is a local downloadable planner, it cannot do true Google-Docs-style live collaboration. The best share-safe workflow is to export a backup for yourself, print or save PDF packets for vendors/family/wedding party, or turn on <strong>Preview Mode</strong> in Wedding Setup before sharing or presenting a copy. This is a local preview lock, not bank-level security.'],
  ['Can I import a large guest list from Excel or Google Sheets?',
   'Yes. Open the <strong>Guest List</strong> page and click <strong>Import Guests CSV</strong>. Choose a CSV exported from Excel or Google Sheets, map each spreadsheet column to a planner field, preview the rows, then import. The import is additive: existing guests are matched by email or name, updated with non-empty values, and new guests are added. Use <strong>Download Template</strong> in the import window if you want a clean starting spreadsheet.'],
  ['Can guests RSVP online even though this planner is offline?',
   'Yes, the recommended bridge is <strong>Google Forms</strong>. Create a Google Form with guest name, email, RSVP, meal, dietary notes, plus-one, children, and comments. When responses come in, export the response sheet as CSV, then use <strong>Import RSVP CSV</strong> on the Guest List page. The planner updates matching guests by email or name and adds unmatched RSVP rows so no response is lost.'],
  ['How can my fiance, mom, or coordinator help if there is no live collaboration?',
   'This planner is offline-first, so helpers work through <strong>handoff files</strong> instead of live sync. Three practical options:<br><br><strong>1. Full backup (.sqlite)</strong> — The main editor clicks <strong>Download Backup</strong>, sends the file (USB, email attachment, or cloud folder), the helper clicks <strong>Restore</strong> on their device, edits, then sends a fresh <code>.sqlite</code> backup back for you to restore. Always download your own backup before restoring someone else\'s file.<br><strong>2. Partner sync packet (.json)</strong> — On Get Started, use <strong>Export Partner Packet</strong> for a lightweight JSON file with names, guests/RSVPs, tasks, and budget summary. Your partner imports it with <strong>Import Partner Packet</strong> to merge updates without replacing your whole planner.<br><strong>3. Share Packets &amp; print</strong> — Use <strong>Share Packets</strong> for vendor, wedding-party, coordinator, and weekend handoffs that auto-fill from your planner but stay editable. Use <strong>Print Section</strong> for PDFs. For comments only, Notes and printed pages work well.<br><br>This is not real-time collaboration, but it keeps your data private and portable.'],
  ['Can I customize this file in Pinegrow?',
   'You can edit colors, spacing, and visible HTML/CSS, but this planner is a full local web app. Some pages are generated by JavaScript, so visual edits to generated areas may be replaced when the page re-renders. Safest edits: theme colors, fonts, headings, helper text, and static page sections.'],
  ['Do you support blended families or second marriages?',
   'Yes. Optional, dismissible prompts on Wedding Setup, Guest List, Wedding Party, and Table Layout offer gentle starter tasks and notes when blending families — choose <strong>Yes, this applies to us</strong> or <strong>Not for us</strong>. The Guest List includes flexible side choices like <strong>Family</strong> and <strong>Our Children</strong>, and the Ceremony page can be adapted for family vows, unity ceremonies, or children\'s blessings. Work with your pastor/officiant to shape wording that fits your family faithfully and respectfully.'],
  ['Someone is paying for part of our wedding as a gift — how do I track that?',
   'On the <strong>Budget</strong> page, open any line item and use the <strong>Gift / contribution</strong> section: enter the gift amount, who it\'s from, and whether it\'s <strong>Pledged</strong> (promised) or <strong>Paid</strong> (settled). The item keeps its full cost, so you still see the real value of your wedding — but the gifted portion is removed from <em>your</em> budget. A fully-gifted item drops your share to $0; a partial gift leaves only your share. The <strong>Budget Reconciliation</strong> panel then shows total wedding value, gifts &amp; contributions, your budget, and a by-contributor list that doubles as a thank-you reference. A <strong>Pledged / Paid</strong> toggle lets you decide whether unpaid promises count yet — Paid (the default) only counts gifts that have actually landed. If a payment is linked to a fully-gifted budget item, it is marked covered and left out of your balance due on the Payments page.']
];
