let guideStep = 0;
let guideSel = 0;

function renderPageGuide(){
  const el = document.getElementById('guide-accordion');
  if (!el || typeof PAGE_GUIDE === 'undefined') return;
  /* Carousel/stepper card (pgJourney) removed — keep the list + detail below. */
  el.innerHTML = pgMaster();
}

function renderPageGuideJourney(){
  const host = document.getElementById('guide-accordion');
  const journey = host && host.querySelector('.pg-journey');
  if (journey) journey.outerHTML = pgJourney();
  else renderPageGuide();
}

function pgJourney(){
  const n = PAGE_GUIDE.length;
  guideStep = Math.max(0, Math.min(n - 1, guideStep));
  const i = guideStep, [title, cat, body] = PAGE_GUIDE[i];
  const dots = PAGE_GUIDE.map((_, k) =>
    `<span class="pg-dot${k === i ? ' on' : ''}"></span>`).join('');
  return `<section class="pg-journey">
    <div class="pg-j-eyebrow">Guided walkthrough</div>
    <div class="pg-track"><div class="pg-fill" style="width:${Math.round((i+1)/n*100)}%"></div></div>
    <div class="pg-step">Step ${i+1} of ${n} · ${escapeHtml(cat)}</div>
    <h3 class="pg-j-title">${escapeHtml(title)}</h3>
    <div class="pg-j-body">${body}</div>
    <div class="pg-j-nav">
      <button class="pg-btn" type="button" onclick="guideNav(-1)" ${i===0?'disabled':''}>← Back</button>
      <div class="pg-dots">${dots}</div>
      <button class="pg-btn primary" type="button" onclick="guideNav(1)" ${i===n-1?'disabled':''}>${i===n-1?'Done':'Next →'}</button>
    </div>
  </section>`;
}
function guideNav(d){ guideStep += d; renderPageGuideJourney(); }

function pgMasterDetail(){
  const n = PAGE_GUIDE.length;
  guideSel = Math.max(0, Math.min(n - 1, guideSel));
  const [t, c, b] = PAGE_GUIDE[guideSel];
  return `<div class="pg-md-detail">
    <div class="pg-md-tag">${escapeHtml(c)}</div>
    <h3 class="pg-md-title">${escapeHtml(t)}</h3>
    <div class="pg-md-body">${b}</div>
  </div>`;
}

function pgMaster(){
  const n = PAGE_GUIDE.length;
  guideSel = Math.max(0, Math.min(n - 1, guideSel));
  let lastCat = '';
  const list = PAGE_GUIDE.map(([title, cat], i) => {
    let head = '';
    if (cat !== lastCat){ lastCat = cat; head = `<div class="pg-md-cat">${escapeHtml(cat)}</div>`; }
    return head + `<button class="pg-md-item${i===guideSel?' sel':''}" type="button" data-guide-idx="${i}" onclick="guideSelect(${i})">${escapeHtml(title)}</button>`;
  }).join('');
  return `<section class="pg-md">
    <div class="pg-md-list">${list}</div>
    ${pgMasterDetail()}
  </section>`;
}
function guideSelect(i){
  guideSel = i;
  const section = document.querySelector('#guide-accordion .pg-md');
  if (!section) { renderPageGuide(); return; }
  section.querySelectorAll('.pg-md-item').forEach(function(btn){
    btn.classList.toggle('sel', Number(btn.getAttribute('data-guide-idx')) === guideSel);
  });
  const detail = section.querySelector('.pg-md-detail');
  if (detail) detail.outerHTML = pgMasterDetail();
  else renderPageGuide();
}

function setFaqCat(cat){ activeFaqCat=cat; renderFAQ(); }
function renderFAQ() {
  const el = document.getElementById('faq-list');
  if (!el) return;
  const input = document.getElementById('faq-search');
  const term = (input ? input.value : '').trim().toLowerCase();
  const cats = ['All',...[...new Set(FAQ_CATS)]];
  const filterBar = document.getElementById('faq-cat-bar');
  if(filterBar) filterBar.innerHTML = cats.map(c=>`<button type="button" class="faq-cat-btn${c===activeFaqCat?' active':''}" onclick="setFaqCat('${c}')">${c}</button>`).join('');
  const items = FAQ_ITEMS.map(([q,a], index) => ({ q, a, index, cat: FAQ_CATS[index]||'Features' })).filter(item => {
    if (activeFaqCat !== 'All' && item.cat !== activeFaqCat) return false;
    if (!term) return true;
    return (item.q + ' ' + stripFaqHtml(item.a)).toLowerCase().includes(term);
  });
  if (!items.length) {
    el.innerHTML = `<div class="faq-empty">No FAQ answers match "${escapeHtml(term)}"${activeFaqCat!=='All'?' in '+activeFaqCat:''}. Try a different category or search term.</div>`;
    return;
  }
  el.innerHTML = items.map(({q,a,index}) => {
    const iconName = FAQ_ICON_NAMES[index % FAQ_ICON_NAMES.length];
    return `<article class="faq-card open" data-faq-index="${index}" tabindex="0" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();toggleFAQCard(this.querySelector('.faq-toggle'));}">
      <span class="faq-icon">${faqLineIcon(iconName)}</span>
      <div class="faq-copy"><h3 class="faq-q">${q}</h3><div class="faq-a">${a}</div></div>
      <button class="faq-toggle" type="button" onclick="toggleFAQCard(this)" aria-label="Toggle answer" aria-expanded="true"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m6 9 6 6 6-6"/></svg></button>
    </article>`;
  }).join('');
}

/* ════════════════════════════════════════════════
   GLOBAL SCRIPTURE BANNER
════════════════════════════════════════════════ */
function loadBannerInputs() {
  const v = document.getElementById('banner-verse');
  const r = document.getElementById('banner-ref');
  if (v) v.value = data.setup.bannerVerse || '';
  if (r) r.value = data.setup.bannerRef || '';
}
function saveBannerVerse() {
  data.setup.bannerVerse = (document.getElementById('banner-verse') || {}).value || '';
  data.setup.bannerRef = (document.getElementById('banner-ref') || {}).value || '';
  save();
  renderScriptureBanner();
}
function renderScriptureBanner() {
  const el = document.getElementById('scripture-banner');
  if (!el) return;
  const v = (data.setup.bannerVerse || '').trim();
  const r = (data.setup.bannerRef || '').trim();
  if (!v && !r) {
    el.style.display = 'none';
    el.innerHTML = '';
    return;
  }
  el.style.display = 'block';
  el.innerHTML = `${escapeHtml(v)}${r ? `<span class="ref">${escapeHtml(r)}</span>` : ''}`;
}

/* ════════════════════════════════════════════════
   MANUAL SAVE BUTTON
════════════════════════════════════════════════ */
function saveNow() {
  save();
  if (typeof savedFlash === 'function') savedFlash('Saved');
  const el = document.getElementById('last-saved');
  if (el) { el.classList.add('saved-flash'); setTimeout(() => el.classList.remove('saved-flash'), 900); }
  const btn = document.getElementById('save-btn');
  const t = btn && btn.querySelector('.btn-text');
  if (t) {
    const original = t.dataset.defaultText || 'Save';
    t.dataset.defaultText = original;
    t.textContent = 'Saved';
    clearTimeout(saveNow._labelTimer);
    saveNow._labelTimer = setTimeout(() => { t.textContent = original; }, 1400);
  }
}

/* ════════════════════════════════════════════════
   BULK ROW SELECTION (two-step: field + value)
════════════════════════════════════════════════ */
const ASSIGNED_OPTIONS = ['Bride','Groom','Both','Wedding Party','Family','Planner'];
const BOOL_VALS = [{label:'Yes', val:true}, {label:'No', val:false}];
const BULK_TABLES = {
  tasks:'task-body', timeline:'timeline-body', scriptures:'scripture-body', prayer:'prayer-body',
  counseling:'counseling-body', party:'party-body', gifts:'gift-body', shotlist:'shotlist-body',
  recSongs:'ent-recsongs-body', speeches:'speeches-body', menu:'menu-body', beverages:'beverages-body', kidsMenu:'kidsmenu-body', placeSettings:'placesettings-body', cateringRentals:'cateringrentals-body',
  vtimeline:'vtimeline-body', essentials:'essentials-body', plan:'plan-body',
  entertainment:'entertainment-body', mustPlay:'mustplay-body', doNotPlay:'donotplay-body', receptionPlaylist:'reception-playlist-body',
  contracts:'contracts-body', rentals:'rentals-body',
  honeyItinerary:'honeyiti-body', packing:'packing-body', nameChange:'homecoming-namechange-body', honeyDetails:'honeydetails-body', honeyTransport:'honeytransport-body', notesDetails:'notes-details-body',
  ceremonyOrder:'ceremony-order-body', ceremonyProcessional:'processional-body', ceremonyRecessional:'recessional-body',
  ceremonyChecklist:'ceremony-checklist-body', ceremonyReceptionDetails:'ceremony-reception-body', ceremonyTraditions:'ceremony-traditions-body',
  moodItems:'mooditems-body', homecoming:'homecoming-body', snacks:'snacks-body', vendorMeals:'vendor-meals-body'
};
