function bulkHeaderRowOf(table) {
  return table ? table.querySelector('thead tr:not(.bulk-table-row)') : null;
}
function bulkBarOf(key) {
  const tbody = document.getElementById(BULK_TABLES[key]);
  if (!tbody) return null;
  const table = tbody.closest('table'); if (!table) return null;
  if (key === 'payments') {
    const card = document.querySelector('#panel-payments .payments-bulk-card[data-bulk-key="payments"]');
    if (card) return card;
  }
  if (key === 'plan') {
    const card = document.querySelector('#panel-plan .timeline-bulk-card[data-bulk-key="plan"]');
    if (card) return card;
  }
  if (key === 'contracts') {
    const card = document.querySelector('#panel-contracts .contracts-bulk-card[data-bulk-key="contracts"]');
    if (card) return card;
  }
  if (key === 'vendors') {
    let card = document.querySelector('#panel-vendors .vendors-bulk-card[data-bulk-key="vendors"]');
    if (!card && isDataHubCategoryActive('vendors')) card = document.querySelector('#panel-data-hub .vendors-bulk-card[data-bulk-key="vendors"]');
    if (card) return card;
  }
  if (key === 'vtimeline') {
    let card = document.querySelector('#panel-vendors .vendors-day-bulk-card[data-bulk-key="vtimeline"]');
    if (!card && isDataHubCategoryActive('vendors')) card = document.querySelector('#panel-data-hub .vendors-day-bulk-card[data-bulk-key="vtimeline"]');
    if (card) return card;
  }
  if (key === 'guests') {
    const card = document.querySelector('#panel-guests .guests-bulk-card[data-bulk-key="guests"]');
    if (card) return card;
  }
  if (key === 'tasks') {
    const card = document.querySelector('#panel-tasks .tasks-bulk-card[data-bulk-key="tasks"]');
    if (card) return card;
  }
  if (key === 'party') {
    const card = document.querySelector('#panel-party .party-bulk-card[data-bulk-key="party"]');
    if (card) return card;
  }
  if (key === 'gifts') {
    const card = document.querySelector('#panel-gifts .gift-bulk-card[data-bulk-key="gifts"]');
    if (card) return card;
  }
  if (key === 'shotlist') {
    const card = document.querySelector('#panel-shotlist .shotlist-bulk-card[data-bulk-key="shotlist"]');
    if (card) return card;
  }
  if (key === 'timeline') {
    const card = document.querySelector('#panel-timeline .wday-bulk-card[data-bulk-key="timeline"]');
    if (card) return card;
  }
  if (['menu','beverages','kidsMenu','placeSettings','cateringRentals'].includes(key)) {
    const card = document.querySelector(`#panel-catering .catering-bulk-card[data-bulk-key="${key}"]`);
    if (card) return card;
  }
  if (['honeyItinerary','packing','nameChange','honeyDetails','honeyTransport'].includes(key)) {
    const card = document.querySelector(`#panel-honeymoon .hm-bulk-card[data-bulk-key="${key}"]`);
    if (card) return card;
  }
  if (key === 'notesDetails') {
    const card = document.querySelector('#panel-notes .notes-bulk-card[data-bulk-key="notesDetails"]');
    if (card) return card;
  }
  if (key === 'essentials') {
    const card = document.querySelector('#panel-essentials .essentials-bulk-card[data-bulk-key="essentials"]');
    if (card) return card;
  }
  const hubCard = dataHubBulkCardFor(key);
  if (hubCard) return hubCard;
  const row = table.querySelector(`thead tr.bulk-table-row[data-bulk-key="${key}"]`);
  return row ? row.querySelector('.bulk-bar') : null;
}
function bulkOptionValue(raw) {
  return raw === '' ? '__blank__' : String(raw);
}
function bulkOptionLabel(raw, label) {
  if (label != null) return label;
  return raw === '' ? 'Blank' : String(raw);
}
function essentialsBulkValues(key, fallback){
  const live = (typeof uniqueEssentialsValues === 'function') ? uniqueEssentialsValues(key) : [];
  return [...new Set([...(fallback || []), ...live].filter(v => v !== '' && v != null))];
}
function bulkFieldsFor(key) {
  if (key === 'vtimeline') {
    const vendors = [...new Set([...(data.vendors || []).map(v => v.name), ...(data.vtimeline || []).map(r => r.vendor)].map(v => String(v || '').trim()).filter(Boolean))].sort();
    const locations = [...new Set(['Ceremony Site','Reception Venue','Bridal Suite','Groom Suite','Loading Dock','Vendor Entrance','Parking Lot', ...(data.vtimeline || []).map(r => r.location)].map(v => String(v || '').trim()).filter(Boolean))].sort();
    return [
      {k:'vendor', label:'Vendor', vals:vendors},
      {k:'location', label:'Arrival Location', vals:locations}
    ];
  }
  if (key === 'rentals') {
    const vendors = [...new Set([...(data.vendors || []).map(v => v.name), ...(data.rentals || []).map(r => r.vendor)].map(v => String(v || '').trim()).filter(Boolean))].sort();
    const pickupDates = [...new Set((data.rentals || []).map(r => r.pickup).filter(Boolean))].sort();
    const returnDates = [...new Set((data.rentals || []).map(r => r.ret).filter(Boolean))].sort();
    return [
      {k:'vendor', label:'Vendor', vals:vendors},
      {k:'pickup', label:'Pick-Up Date', vals:pickupDates},
      {k:'ret', label:'Return Date', vals:returnDates}
    ];
  }
  if (key === 'appointments') {
    const vendors = [...new Set([...(data.vendors || []).map(v => v.name), ...(data.appointments || []).map(r => r.vendor)].map(v => String(v || '').trim()).filter(Boolean))].sort();
    const categories = [...new Set((data.appointments || []).map(r => r.category).filter(Boolean))].sort();
    return [
      {k:'status', label:'Status', vals:(typeof APPOINTMENT_STATUS !== 'undefined' ? APPOINTMENT_STATUS : ['Unconfirmed','Pending','Confirmed','Completed','Cancelled'])},
      {k:'category', label:'Category', vals:categories},
      {k:'vendor', label:'Vendor', vals:vendors}
    ];
  }
  if (key === 'ceremonyOrder') {
    return [
      {k:'person', label:'Person Responsible', vals:[...new Set((data.ceremonyOrder || []).map(r => r.person).filter(Boolean))].sort()},
      {k:'length', label:'Suggested Length', vals:['1 min','2 min','3 min','5 min','8 min','10 min']}
    ];
  }
  if (key === 'ceremonyProcessional' || key === 'ceremonyRecessional') {
    return [{k:'role', label:'Role', vals:['Officiant','Parents','Grandparent','Wedding Party','Best Man','Maid of Honor','Flower Girl','Ring Bearer','Bride','Groom','Newlyweds','Guests','Other']}];
  }
  if (key === 'ceremonyChecklist') {
    return [{k:'done', label:'Done', vals:BOOL_VALS}];
  }
  if (key === 'ceremonyReceptionDetails') {
    return [
      {k:'category', label:'Category', vals:['Christian Tradition','Cultural Tradition','Family Honor','Meal Prayer','Reception Flow','Hospitality','Other']},
      {k:'timing', label:'Timing', vals:['Before dinner','During dinner','After dinner','During reception','Before send-off','Other']}
    ];
  }
  if (key === 'ceremonyTraditions') {
    return [
      {k:'part', label:'Part of Wedding', vals:['Ceremony','Reception','Rehearsal','Wedding Weekend','Private Family Moment','Other']},
      {k:'context', label:'Context', vals:['Christian','Cultural','Family','Blended Family','Memorial','Hospitality','Other']}
    ];
  }
  if (key === 'moodItems') {
    return [
      {k:'section', label:'Vision Category', vals:(typeof MOOD_ITEM_SECTIONS !== 'undefined' ? MOOD_ITEM_SECTIONS : ['Overall Vibe & Theme','Color Palette','Other'])},
      {k:'vendorMatch', label:'Vendor Match', vals:(typeof MOOD_VENDOR_MATCH_OPTIONS !== 'undefined' ? MOOD_VENDOR_MATCH_OPTIONS : ['Needed','Matched','Not Needed'])},
      {k:'finalized', label:'Finalized', vals:(typeof MOOD_FINALIZED_OPTIONS !== 'undefined' ? MOOD_FINALIZED_OPTIONS : ['Gathering Ideas','Shortlisted','Finalized'])}
    ];
  }
  if (key === 'homecoming') {
    return [
      {k:'cat', label:'Category', vals:(typeof HC_CATEGORIES !== 'undefined' ? HC_CATEGORIES : ['Home','Legal','Financial','Marriage Rhythms','Other'])},
      {k:'status', label:'Status', vals:(typeof HC_STATUSES !== 'undefined' ? HC_STATUSES : ['Not Started','In Progress','Complete'])},
      {k:'owner', label:'Owner', vals:(typeof HC_OWNERS !== 'undefined' ? HC_OWNERS : ['Bride','Groom','Both'])}
    ];
  }
  if (key === 'snacks') {
    return [{k:'when', label:'When', vals:[...new Set((data.snacks || []).map(r => r.when).filter(Boolean))].sort()}];
  }
  if (key === 'vendorMeals') {
    const vendors = [...new Set([...(data.vendors || []).map(v => v.name), ...(data.vendorMeals || []).map(r => r.vendor)].map(v => String(v || '').trim()).filter(Boolean))].sort();
    return [{k:'vendor', label:'Vendor', vals:vendors}];
  }
  if (key !== 'essentials') return BULK_FIELDS[key] || [];
  return [
    {k:'packed',label:'Packed',vals:BOOL_VALS},
    {k:'cat',label:'Category',vals:essentialsBulkValues('cat', ['Tech','Tech Kit','Quick Fixes','Emergency Kit','Personal & Health','Medicine Kit','Snack Kit','Beauty Kit','Marriage Essentials','Ceremony Documents','Bride Essentials','Groom Essentials','Reception Bag','Decor & Signage','Exit / Send-Off','Misc'])},
    {k:'item',label:'Item',vals:essentialsBulkValues('item', [])},
    {k:'assigned',label:'Assigned To',vals:essentialsBulkValues('assigned', ['Bride','Groom','Bride & Groom','Best Man','Coordinator','Photographer','Officiant','Family','Wedding Party'])},
    {k:'location',label:'Location',vals:essentialsBulkValues('location', ['Getting-ready suite','Emergency kit','Tech kit','Ceremony folder','Coordinator binder','Venue entrance','Reception tables','Reception bag','Beauty bag','Groom bag','Gift table','Exit supplies','Personal bag'])}
  ];
}
function bulkControlMarkup(key) {
  const fields = bulkFieldsFor(key);
  if (!fields.length) return '<span class="page-subtitle" style="margin:0;">Select rows to edit them together.</span>';
  return fields.map(f => {
    const options = (f.vals || []).map(v => {
      const isObj = (typeof v === 'object');
      const raw = isObj ? v.val : v;
      const label = bulkOptionLabel(raw, isObj ? v.label : null);
      return `<option value="${escapeHtml(bulkOptionValue(raw))}" data-bool="${isObj}">${escapeHtml(label)}</option>`;
    }).join('');
    return `<label class="bulk-field"><span>Set ${escapeHtml(f.label)}</span><select class="bulk-select" data-field="${escapeHtml(f.k)}"><option value="">No change</option>${options}</select></label>`;
  }).join('');
}
function ensurePaymentBulkCard(key, table, headerRow) {
  // Payments needs a web-app style Bulk Edit card, not a row inside the table.
  // Remove any old integrated bulk row first so the spreadsheet header stays clean.
  table.querySelectorAll('thead tr.bulk-table-row').forEach(row => row.remove());
  const card = table.closest('.payments-table-card');
  const head = document.querySelector('#panel-payments .payments-table-head');
  if (!card || !head) return null;
  let bar = document.querySelector('#panel-payments .payments-bulk-card[data-bulk-key="payments"]');
  if (!bar) {
    bar = document.createElement('div');
    bar.className = 'bulk-bar payments-bulk-card';
    bar.dataset.bulkKey = 'payments';
    head.insertAdjacentElement('afterend', bar);
  }
  if (!bar.dataset.ready) {
    bar.dataset.ready = '1';
    const bulkInner = `
      <div class="bulk-head"><strong>Bulk Edit</strong><span class="bulk-count">0 selected</span></div>
      <div class="bulk-controls">${bulkControlMarkup(key)}</div>
      <div class="bulk-actions"><button class="btn btn-forest btn-sm" onclick="applyBulk('${key}')">Apply Changes</button><button class="btn btn-sm bulk-delete-btn" onclick="deleteBulkRows('${key}')">Delete Selected</button></div>`;
    bar.innerHTML = `<div class="bulk-left-cluster">${bulkInner}</div>`;
  }
  return bar;
}

