  if (!row) row = {};
  if (!row.option) row.option = row.item || "Kids' meal";
  if (row.count == null || row.count === '') row.count = cateringGuests().kids;
  if (row.costChild == null || row.costChild === '') row.costChild = '8';
  if (!row.dietary) row.dietary = 'Kids';
