function cateringLineCost(row){
  const basis = String(row.costBasis || row.cost || '').toLowerCase();
  const parsedBasis = cateringNumber(row.costBasis || row.cost || '');
  const unit = cateringNumber(row.unitCost) || parsedBasis;
  if (basis.includes('included')) return 0;
  if (basis.includes('guest') || basis.includes('/')) return unit * (cateringNumber(row.servings || row.qty || cateringGuests().total) || cateringGuests().total);
  if (basis.includes('flat')) return unit;
  if (unit && cateringNumber(row.servings)) return unit * cateringNumber(row.servings);
  return unit;
}
function menuSubtotal(){ return (data.menu || []).map(normalizeMenuRow).reduce((sum,r)=>sum + cateringLineCost(r), 0); }
function beverageSubtotal(){ return (data.beverages || []).map(normalizeBeverageRow).reduce((sum,r)=>sum + (r.included ? 0 : cateringLineCost(r)), 0); }
function kidsSubtotal(){ return (data.kidsMenu || []).map(normalizeKidsRow).reduce((sum,r)=>sum + cateringNumber(r.count) * cateringNumber(r.costChild), 0); }
function placeSettingPerGuest(){ return (data.placeSettings || []).map(normalizePlaceSettingRow).reduce((sum,r)=>sum + cateringNumber(r.qtySetting) * cateringNumber(r.costSetting), 0); }
function placeSettingSubtotal(){ return placeSettingPerGuest() * cateringGuests().total; }
function rentalSubtotal(){ return (data.cateringRentals || []).map(normalizeRentalRow).reduce((sum,r)=>sum + cateringNumber(r.cost), 0); }

/* ── Pre-Wedding Snacks + Vendor Meals (Batch 4) — both feed the Budget (Food bucket) ── */
function snacksSubtotal(){ return (data.snacks || []).reduce((s,r)=>s + cateringNumber(r.qty||1) * cateringNumber(r.cost), 0); }
function vendorMealsSubtotal(){ return (data.vendorMeals || []).reduce((s,r)=>s + cateringNumber(r.count||1) * cateringNumber(r.cost), 0); }
function addSnackRow(){ if(!Array.isArray(data.snacks)) data.snacks=[]; if (cateringInlineAdd('snacks')) return; openRecordEditor('snacks'); }
function addVendorMealRow(){ if(!Array.isArray(data.vendorMeals)) data.vendorMeals=[]; if (cateringInlineAdd('vendorMeals')) return; openRecordEditor('vendorMeals'); }
function updateSnack(i,k,v){ if(!data.snacks||!data.snacks[i]) return; data.snacks[i][k]=v; save(); renderSnacks(); renderCateringOverview(); }
function updateVendorMeal(i,k,v){ if(!data.vendorMeals||!data.vendorMeals[i]) return; data.vendorMeals[i][k]=v; save(); renderVendorMeals(); renderCateringOverview(); }
function removeSnack(i){ if(!data.snacks) return; data.snacks.splice(i,1); save(); renderSnacks(); renderCateringOverview(); }
function removeVendorMeal(i){ if(!data.vendorMeals) return; data.vendorMeals.splice(i,1); save(); renderVendorMeals(); renderCateringOverview(); }
async function loadSnackPreset(){ if(!Array.isArray(data.snacks)) data.snacks=[]; if(data.snacks.length && !await starterConfirm('Add starter pre-wedding snacks?')) return;
  [['Charcuterie board','Bridal suite',1,60],['Fruit & pastries','Groom getting-ready',1,40],['Water & sports drinks','Wedding party',2,15],['Coffee & tea station','Pre-ceremony',1,35]].forEach(([item,when,qty,cost])=>data.snacks.push({item,when,qty,cost,notes:''}));
  save(); renderSnacks(); renderCateringOverview(); }
async function loadVendorMealPreset(){ if(!Array.isArray(data.vendorMeals)) data.vendorMeals=[]; if(data.vendorMeals.length && !await starterConfirm('Add starter vendor meals?')) return;
  ['Photographer','Videographer','DJ','Musicians','Singers','Other Special Vendor'].forEach(v=>data.vendorMeals.push({vendor:v,count:1,cost:25,notes:''}));
  save(); renderVendorMeals(); renderCateringOverview(); }
function renderSnacks(){
  if(!Array.isArray(data.snacks)) data.snacks=[];
  if (typeof cwpRenderTable === 'function' && cwpMountOnPanel('snacks')) { cwpRenderTable('snacks'); afterCateringTableRendered('snacks'); renderCateringOverview(); return; }
  const tb=document.getElementById('snacks-body'); if(!tb) return;
  tb.innerHTML = data.snacks.length ? data.snacks.map((r,i)=>{
    const tot=cateringNumber(r.qty||1)*cateringNumber(r.cost);
    return `<tr>
      <td><input type="text" value="${escapeHtml(r.item||'')}" placeholder="Snack item" oninput="updateSnack(${i},'item',this.value)"></td>
      <td><input type="text" value="${escapeHtml(r.when||'')}" placeholder="Getting ready…" oninput="updateSnack(${i},'when',this.value)"></td>
      <td><input type="number" min="0" value="${cateringNumber(r.qty||1)}" oninput="updateSnack(${i},'qty',this.value)" style="width:64px"></td>
      <td><input type="number" min="0" value="${cateringNumber(r.cost)}" oninput="updateSnack(${i},'cost',this.value)" style="width:90px"></td>
      <td class="cat-line-total">${cateringMoney(tot)}</td>
      <td><input type="text" value="${escapeHtml(r.notes||'')}" placeholder="Notes" oninput="updateSnack(${i},'notes',this.value)"></td>
      <td>${plannerTrashButton(`removeSnack(${i})`,'Remove snack')}</td></tr>`;
  }).join('') : tableEmptyState(7,'No pre-wedding snacks yet','Add getting-ready and pre-ceremony bites — they roll into your Budget under Food.','+ Add Snack','addSnackRow()','Load Starter','loadSnackPreset()');
  requestAnimationFrame(()=>makeColumnsResizable(document.getElementById('panel-catering')));
}
function renderVendorMeals(){
  if(!Array.isArray(data.vendorMeals)) data.vendorMeals=[];
  if (typeof cwpRenderTable === 'function' && cwpMountOnPanel('vendorMeals')) { cwpRenderTable('vendorMeals'); afterCateringTableRendered('vendorMeals'); renderCateringOverview(); return; }
  const tb=document.getElementById('vendor-meals-body'); if(!tb) return;
  tb.innerHTML = data.vendorMeals.length ? data.vendorMeals.map((r,i)=>{
    const tot=cateringNumber(r.count||1)*cateringNumber(r.cost);
    return `<tr>
      <td><input type="text" value="${escapeHtml(r.vendor||'')}" placeholder="Photographer, DJ…" oninput="updateVendorMeal(${i},'vendor',this.value)"></td>
      <td><input type="number" min="0" value="${cateringNumber(r.count||1)}" oninput="updateVendorMeal(${i},'count',this.value)" style="width:64px"></td>
      <td><input type="number" min="0" value="${cateringNumber(r.cost)}" oninput="updateVendorMeal(${i},'cost',this.value)" style="width:90px"></td>
      <td class="cat-line-total">${cateringMoney(tot)}</td>
      <td><input type="text" value="${escapeHtml(r.notes||'')}" placeholder="Dietary, timing…" oninput="updateVendorMeal(${i},'notes',this.value)"></td>
      <td>${plannerTrashButton(`removeVendorMeal(${i})`,'Remove vendor meal')}</td></tr>`;
  }).join('') : tableEmptyState(6,'No vendor meals yet','Add meals for your working vendors (photographer, DJ, etc.) — they roll into your Budget.','+ Add Vendor','addVendorMealRow()','Load Starter','loadVendorMealPreset()');
  requestAnimationFrame(()=>makeColumnsResizable(document.getElementById('panel-catering')));
}

/* ── C1: Catering owns the Food / Cake & Desserts / Drinks / Rentals budget categories ──
   The catering itemization is the single source of truth; these four budget categories are
   projected from it and rendered read-only on the Budget page (no double-entry, no double-count). */
const CATERING_OWNED_CATS = ['Food','Cake & Desserts','Drinks','Rentals'];
function cateringBudgetBreakdown(){
  const out = {'Food':[], 'Cake & Desserts':[], 'Drinks':[], 'Rentals':[]};
  (data.menu || []).map(normalizeMenuRow).forEach(r=>{
    const bucket = /dessert/i.test(r.course || '') ? 'Cake & Desserts' : 'Food';
    out[bucket].push({ name: r.dish || r.course || 'Menu item', amount: Math.round(cateringLineCost(r)) });
  });
  (data.kidsMenu || []).map(normalizeKidsRow).forEach(r=>{
    out['Food'].push({ name: (r.option || 'Kids meal') + ' (kids)', amount: Math.round(cateringNumber(r.count) * cateringNumber(r.costChild)) });
  });
  (data.beverages || []).map(normalizeBeverageRow).forEach(r=>{
    out['Drinks'].push({ name: r.name || r.barType || 'Beverage', amount: r.included ? 0 : Math.round(cateringLineCost(r)) });
  });
  (data.cateringRentals || []).map(normalizeRentalRow).forEach(r=>{
    out['Rentals'].push({ name: r.item || 'Rental', amount: Math.round(cateringNumber(r.cost)) });
  });
  const ps = Math.round(placeSettingSubtotal());
  if (ps > 0 || (data.placeSettings || []).length) out['Rentals'].push({ name: `Place settings (× ${cateringGuests().total} guests)`, amount: ps });
  // Pre-Wedding Snacks + Vendor Meals → Food bucket
  (data.snacks || []).forEach(r => { const amt = Math.round(cateringNumber(r.qty||1) * cateringNumber(r.cost)); if (r.item || amt) out['Food'].push({ name: 'Snack — ' + (r.item || 'Pre-wedding snack'), amount: amt }); });
  (data.vendorMeals || []).forEach(r => { const amt = Math.round(cateringNumber(r.count||1) * cateringNumber(r.cost)); if (r.vendor || amt) out['Food'].push({ name: 'Vendor meal — ' + (r.vendor || 'Vendor'), amount: amt }); });
  return out;
}
function syncCateringToBudget(){
  if (!Array.isArray(data.budget)) return;
  const breakdown = cateringBudgetBreakdown();
  Object.entries(breakdown).forEach(([catName, lines])=>{
    let cat = data.budget.find(c => String(c.cat || '').trim().toLowerCase() === catName.toLowerCase());
    if (!cat) { cat = { cat: catName, target: 0, planned: 0, tip: '', items: [] }; data.budget.push(cat); }
    cat.cateringOwned = true;
    cat.items = lines.map(l => ({ name: l.name, budgeted: l.amount, cost: 0, actual: 0, status: 'Pending', paid: false, due: '', notes: '', cateringLine: true }));
    cat.planned = lines.reduce((s,l)=>s + (l.amount || 0), 0);
  });
}
function cateringTotal(){ return menuSubtotal() + beverageSubtotal() + kidsSubtotal() + placeSettingSubtotal() + rentalSubtotal() + snacksSubtotal() + vendorMealsSubtotal(); }
function cateringDietaryCounts(){
  const counts = {};
  (data.guests || []).forEach(g => {
    const dietary = String(g.dietary || g.meal || '').trim();
    if (!dietary) return;
    dietary.split(/[;,/]/).map(x=>x.trim()).filter(Boolean).forEach(tag => counts[tag] = (counts[tag] || 0) + 1);
  });
  (data.menu || []).map(normalizeMenuRow).forEach(r => {
    String(r.dietary || '').split(/[;,/]/).map(x=>x.trim()).filter(Boolean).forEach(tag => counts[tag] = counts[tag] || 0);
  });
  if (!Object.keys(counts).length) return {};
  return counts;
}

/* Track 1.2 — printable caterer meal count sheet.
   Reads computeMealCounts() + menu/kids/vendor-meal data; opens a clean
   print/PDF window via openPrintView(). */
function openMealCountSheet(){
  const esc = (typeof escapeHtml === 'function') ? escapeHtml : (s => String(s == null ? '' : s));
  const counts = computeMealCounts();
  const g = (typeof cateringGuests === 'function') ? cateringGuests() : { total: counts.total, adults: counts.adults, kids: counts.kids, basis: 'target' };
  const planned = (typeof cateringGuests === 'function') ? cateringGuests('target').total : counts.total;
  const confirmed = (typeof cateringGuests === 'function') ? cateringGuests('rsvp').total : counts.total;
  const setup = data.setup || {};

  const stat = (label, val, sub) =>
    `<div class="pv-card" style="text-align:left;padding:12px 14px"><div style="font-size:11px;text-transform:uppercase;letter-spacing:.4px;color:#6a655d">${esc(label)}</div>`
    + `<div style="font-size:24px;color:var(--pv-accent);font-weight:bold">${esc(String(val))}</div>`
    + (sub ? `<div class="pv-note">${esc(sub)}</div>` : '') + `</div>`;

  let html = '';
  html += `<div class="pv-cards" style="grid-template-columns:repeat(4,1fr);gap:0.2in">`
    + stat('Guests Served', g.total, `${g.adults} adults · ${g.kids} children`)
    + stat('Planned', planned, 'Setup target')
    + stat('Confirmed RSVPs', confirmed, 'RSVP “Yes”')
    + stat('Dietary Flags', Object.values(counts.dietary || {}).reduce((a,b)=>a + (Number(b)||0), 0), 'from guest list')
    + `</div>`;
  html += `<p class="pv-note">Headcount basis: <strong>${g.basis === 'rsvp' ? 'Confirmed RSVPs' : 'Planned guest count'}</strong>. Declined RSVPs are excluded from meal selections.</p>`;

  // Meal selections
  html += `<h2 class="pv-section">Meal Selections</h2>`;
  if (counts.meals.length){
    html += `<table class="pv-table"><thead><tr><th>Meal / Entrée choice</th><th class="num">Count</th></tr></thead><tbody>`;
    counts.meals.forEach(m => { html += `<tr><td>${esc(m.meal)}</td><td class="num">${m.count}</td></tr>`; });
    html += `<tr class="pv-total-row"><td>Total meals counted</td><td class="num">${counts.totalCounted}</td></tr>`;
    html += `</tbody></table>`;
    if (counts.unspecified) html += `<p class="pv-note">${counts.unspecified} guest(s) have no meal selection yet.</p>`;
  } else {
    html += `<p class="pv-note">No guests recorded yet. Meal selections appear here once guests choose an entrée on the Guest List.</p>`;
  }

  // Dietary restrictions
  const dietary = counts.dietary || {};
  const dietKeys = Object.keys(dietary).filter(k => (Number(dietary[k]) || 0) > 0);
  if (dietKeys.length){
    html += `<h2 class="pv-section">Dietary Restrictions &amp; Allergies</h2>`;
    html += `<table class="pv-table"><thead><tr><th>Restriction / Allergy</th><th class="num">Guests</th></tr></thead><tbody>`;
    dietKeys.sort((a,b)=>dietary[b]-dietary[a]).forEach(k => { html += `<tr><td>${esc(k)}</td><td class="num">${dietary[k]}</td></tr>`; });
    html += `</tbody></table>`;
  }

  // Menu by course
  const menu = safeArray(data.menu).map(r => (typeof normalizeMenuRow === 'function' ? normalizeMenuRow(r) : r));
  if (menu.length){
    html += `<h2 class="pv-section">Menu &amp; Service</h2>`;
    html += `<table class="pv-table"><thead><tr><th>Course</th><th>Dish</th><th>Service</th><th class="num">Servings</th><th>Dietary</th></tr></thead><tbody>`;
    menu.forEach(r => {
      html += `<tr><td>${esc(r.course || '')}</td><td>${esc(r.dish || r.item || '')}</td><td>${esc(r.service || '')}</td><td class="num">${esc(String(r.servings ?? ''))}</td><td>${esc(r.dietary || '')}</td></tr>`;
    });
    html += `</tbody></table>`;
  }

  // Kids menu
  const kids = safeArray(data.kidsMenu).map(r => (typeof normalizeKidsRow === 'function' ? normalizeKidsRow(r) : r));
  if (kids.length){
    html += `<h2 class="pv-section">Children's Menu</h2>`;
    html += `<table class="pv-table"><thead><tr><th>Option</th><th class="num">Count</th></tr></thead><tbody>`;
    kids.forEach(r => { html += `<tr><td>${esc(r.option || 'Kids meal')}</td><td class="num">${esc(String(r.count ?? ''))}</td></tr>`; });
    html += `</tbody></table>`;
  }

  // Vendor meals
  const vendorMeals = safeArray(data.vendorMeals);
  if (vendorMeals.length){
    const totalVendorMeals = vendorMeals.reduce((s,r)=>s + (parseInt(r.count) || 0), 0);
    html += `<h2 class="pv-section">Vendor Meals</h2>`;
    html += `<table class="pv-table"><thead><tr><th>Vendor</th><th class="num">Meals</th></tr></thead><tbody>`;
    vendorMeals.forEach(r => { html += `<tr><td>${esc(r.vendor || 'Vendor')}</td><td class="num">${esc(String(r.count ?? ''))}</td></tr>`; });
    html += `<tr class="pv-total-row"><td>Total vendor meals</td><td class="num">${totalVendorMeals}</td></tr>`;
    html += `</tbody></table>`;
  }

  html += `<p class="pv-note" style="margin-top:24px">Prepared ${esc(new Date().toLocaleDateString('en-US', { year:'numeric', month:'long', day:'numeric' }))}${setup.date ? ' · Wedding ' + esc(pvDate(setup.date)) : ''}${setup['venue-reception'] ? ' · ' + esc(setup['venue-reception']) : ''}.</p>`;

  openPrintView('Caterer Meal Count Sheet', html, { subtitle: [setup.bride, setup.groom].filter(Boolean).join(' & ') || 'Wedding Catering', accent: '#5A6F55' });
}

function renderCateringStats(){
  const wrap = document.getElementById('catering-stats'); if (!wrap) return;
  const g = cateringGuests();
  const planned = cateringGuests('target');
  const confirmed = cateringGuests('rsvp');
  const total = cateringTotal();
  const budget = cateringNumber(data.setup?.budget) || 10000;
  const dietaryCount = Object.values(cateringDietaryCounts()).reduce((a,b)=>a + (Number(b)||0), 0);
  const menuItems = (typeof uxCateringRowCount === 'function') ? uxCateringRowCount(data) : 0;
  const menuConfirmed = (typeof uxCateringConfirmedCount === 'function') ? uxCateringConfirmedCount(data) : 0;
  const guestVal = formatGuestTargetLabel(g.total);
  const plannedLabel = formatGuestTargetLabel(planned.total);
  const confirmedLabel = formatGuestTargetLabel(confirmed.total);
  wrap.innerHTML = `
    <div class="m-stat"><div class="m-stat-top">${catIcon('guests')}<span class="m-stat-label">Guests served</span></div><div class="m-stat-val">${guestVal}</div><div class="m-stat-sub">${g.targetSet ? `${g.adults} adults · ${g.kids} children` : 'Set target guest count in Wedding Setup'}</div>${cateringBasisToggle(g.basis)}</div>
    <div class="m-stat"><div class="m-stat-top">${catIcon('dollar')}<span class="m-stat-label">Cost / Planned Guest</span></div><div class="m-stat-val">${planned.total ? cateringMoney2(total / planned.total) : '—'}</div><div class="m-stat-sub">Planned: ${plannedLabel}${planned.total ? ' guests' : ''}</div></div>
    <div class="m-stat"><div class="m-stat-top">${catIcon('dollar')}<span class="m-stat-label">Cost / Confirmed RSVP Guest</span></div><div class="m-stat-val">${confirmed.total ? cateringMoney2(total / confirmed.total) : '—'}</div><div class="m-stat-sub">Confirmed headcount: ${confirmedLabel}${confirmed.total ? '' : ' — add guests or RSVPs'}</div></div>
    <div class="m-stat"><div class="m-stat-top">${catIcon('utensils')}<span class="m-stat-label">Menu & bar items</span></div><div class="m-stat-val">${menuItems}</div><div class="m-stat-sub">${menuConfirmed} confirmed</div></div>
    <div class="m-stat"><div class="m-stat-top">${catIcon('utensils')}<span class="m-stat-label">Total catering</span></div><div class="m-stat-val">${cateringMoney(total)}</div><div class="m-stat-sub">${budget ? Math.round(total / budget * 100) : 0}% of ${cateringMoney(budget)}</div></div>
    <div class="m-stat"><div class="m-stat-top">${catIcon('alert')}<span class="m-stat-label">Dietary flags</span></div><div class="m-stat-val">${dietaryCount}</div><div class="m-stat-sub">guest list + menu tags</div></div>`;
}
function renderCateringMenuSummary(){
  const wrap = document.getElementById('catering-menu-summary'); if (!wrap) return;
  const rows = (data.menu || []).map(normalizeMenuRow);
  const labels = ['Appetizer','Salad','Main','Side','Dessert','Late-Night'];
  const lines = labels.map(label => {
    const matches = rows.filter(r => String(r.course || '').toLowerCase().replace(/\s+/g,'-').includes(label.toLowerCase().replace(/\s+/g,'-')) || (label === 'Late-Night' && String(r.course||'').toLowerCase().includes('late')));
    const service = matches[0]?.service || '—';
    const count = matches.length;
    const word = label === 'Main' ? 'entrees' : label === 'Dessert' || label === 'Late-Night' ? 'selected' : 'selected';
    return `<div class="cat-summary-row"><strong>${escapeHtml(label)}</strong><span>${escapeHtml(service)} · ${count} ${word}</span></div>`;
  }).join('');
  wrap.innerHTML = `<div class="cat-summary-list">${lines}</div><div class="cat-divider"></div><div class="cat-note">Buffet @ ${cateringMoney2((menuSubtotal() || 0) / Math.max(1,cateringGuests().adults || cateringGuests().total))}/adult · full table below</div>`;
}
function renderCateringBarSummary(){
  const wrap = document.getElementById('catering-bar-summary'); if (!wrap) return;
  const m = data.cateringMeta || {};
  const fields = [
    ['Bar type','barType','Beer & Wine'],
    ['Signature mocktail','signature','Covenant Cooler'],
    ['Toast pour','toast','Sparkling cider'],
    ['Est. wine bottles','wineBottles', setupTargetGuestCount() ? String(Math.ceil(setupTargetGuestCount() / 2.5)) : ''],
    ['Coffee & tea station','coffeeStation','Included']
  ];
  wrap.innerHTML = fields.map(([label,key,fallback]) => `<div class="cat-meta-row"><label>${escapeHtml(label)}</label><input value="${escapeHtml(m[key] || fallback)}" oninput="updateCateringMeta('${key}',this.value)"></div>`).join('');
}
function renderKidsSummary(){
  const wrap = document.getElementById('catering-kids-summary'); if (!wrap) return;
  const badge = document.getElementById('catering-kids-badge');
  const kids = cateringGuests().kids;
  if (badge) badge.textContent = `${kids} from Guest List`;
  const rows = (data.kidsMenu || []).map(normalizeKidsRow);
  const list = rows.map(r=>`<div class="cat-kids-mini-row"><span>${escapeHtml(r.option)}</span><span>${escapeHtml(String(r.count))} kids</span></div>`).join('');
  const subtotal = kidsSubtotal();
  const avg = kids ? subtotal / kids : 0;
  wrap.innerHTML = `<div class="cat-kids-list"><div class="cat-stat-kicker">Kids' Meal Options</div>${list || '<p class="cat-note">Add kids meal options below.</p>'}<div class="cat-note" style="text-align:left;margin-top:.55rem;">Counts update automatically when Guest List children change</div></div><div class="cat-kids-cost"><div class="cat-stat-kicker">Cost</div><div class="cat-cost-row"><span>Children (from guests)</span><strong>${kids}</strong></div><div class="cat-cost-row"><span>Avg. price / child</span><strong>${cateringMoney2(avg)}</strong></div><div class="cat-cost-row total"><span>Kids subtotal</span><strong>${cateringMoney(subtotal)}</strong></div><div class="cat-note" style="text-align:left;margin-top:.55rem;">Added to catering costs</div></div>`;
}
function colorForName(name){
  const n = String(name || '').toLowerCase();
  if (n.includes('gold')) return '#c59b55';
  if (n.includes('sage')) return '#91a083';
  if (n.includes('ivory')) return '#f1eadc';
  if (n.includes('clear')) return '#e6edf0';
  if (n.includes('blush')) return '#e8b9a8';
  if (n.includes('black')) return '#222';
  return '#d4b896';
}
function renderPlaceSummary(){
  const wrap = document.getElementById('catering-place-summary'); if (!wrap) return;
  const rows = (data.placeSettings || []).map(normalizePlaceSettingRow);
  const total = cateringGuests().total;
  const totalLabel = formatGuestTargetLabel(total);
  const totalLine = total
    ? `Per setting <strong>${cateringMoney2(placeSettingPerGuest())}</strong> × ${total} = <strong>${cateringMoney(placeSettingSubtotal())}</strong>`
    : `Per setting <strong>${cateringMoney2(placeSettingPerGuest())}</strong> — set target guest count in Wedding Setup for a total estimate`;
  wrap.innerHTML = `<div class="cat-setting-grid">${rows.slice(0,4).map(r=>`<div class="cat-setting-card"><div class="cat-setting-title">${escapeHtml(r.item)}</div><div class="cat-color-chip"><i style="--chip:${colorForName(r.color)}"></i>${escapeHtml(r.color)}</div><div class="cat-setting-sub">${escapeHtml(r.material)}</div></div>`).join('')}</div><div class="cat-setting-total">${totalLine}</div>`;
}
function renderDietarySummary(){
  const wrap = document.getElementById('catering-dietary-summary'); if (!wrap) return;
  const counts = cateringDietaryCounts();
  if (!Object.keys(counts).length) { wrap.innerHTML = '<span class="cat-pill blue" style="opacity:.7">No dietary info yet &mdash; add meal choices on the Guest List page.</span>'; return; }
  wrap.innerHTML = Object.entries(counts).slice(0,8).map(([label,count]) => `<span class="cat-pill ${/v|veg/i.test(label)?'green':/gluten|gf/i.test(label)?'gold':/nut|allergy/i.test(label)?'red':'blue'}">${escapeHtml(label)} · ${count}</span>`).join('');
}
function renderCateringCosts(){
  const wrap = document.getElementById('catering-costs'); if (!wrap) return;
  const lines = [
    ['Adult food & service', menuSubtotal()],
    ["Children's meals", kidsSubtotal()],
    ['Drinks & bar', beverageSubtotal()],
    ['Place settings', placeSettingSubtotal()],
    ['Tableware & rentals', rentalSubtotal()]
  ];
  wrap.innerHTML = lines.map(([label,value])=>`<div class="cat-cost-row"><span>${escapeHtml(label)}</span><strong>${cateringMoney(value)}</strong></div>`).join('') + `<div class="cat-cost-row total"><span>Total → Budget</span><strong>${cateringMoney(cateringTotal())}</strong></div>`;
}
function renderCateringOverview(){
  if(typeof syncCateringToBudget==='function') syncCateringToBudget();
  if (typeof renderPageUxChrome === 'function') renderPageUxChrome('catering');
  renderCateringStats();
  renderCateringMenuSummary();
  renderCateringBarSummary();
  renderKidsSummary();
  renderPlaceSummary();
  renderDietarySummary();
  renderCateringCosts();
  const targetNote = document.getElementById('catering-guest-target-note');
  if (targetNote) {
    const n = setupTargetGuestCount();
    targetNote.innerHTML = n
      ? `Planning for <strong>${n}</strong> guests (from Wedding Setup). Change it anytime under <button type="button" class="footer-link" onclick="showPanel('setup')">Wedding Setup</button>.`
      : `No target guest count yet — set it in <button type="button" class="footer-link" onclick="showPanel('setup')">Wedding Setup</button> or run the setup wizard so catering and seating estimates stay accurate.`;
  }
  const foot = document.getElementById('catering-menu-foot');
  if (foot) foot.innerHTML = `Adult food subtotal&nbsp;&nbsp;<strong style="color:var(--forest);">${cateringMoney(menuSubtotal())}</strong>`;
}

const CATERING_INLINE_TABLES = [
  { key:'menu', mount:'cwp-menu', label:'Menu Builder', short:'Menu', icon:'menu', addLabel:'+ Add dish', help:'Courses, dishes, servings, cost basis, status, and notes.' },
  { key:'beverages', mount:'cwp-beverages', label:'Beverage & Bar Detail', short:'Beverages', icon:'glass', addLabel:'+ Add beverage', help:'Bar type, packages, quantities, included items, specialty drinks, and notes.' },
  { key:'kidsMenu', mount:'cwp-kidsMenu', label:"Children's Menu", short:'Kids Menu', icon:'child', addLabel:'+ Add kids item', help:'Kids meal options, counts, per-child cost, dietary notes, and status.' },
  { key:'placeSettings', mount:'cwp-placeSettings', label:'Place Setting Designer', short:'Place Settings', icon:'plate', addLabel:'+ Add place setting', help:'Place setting items, color, material, quantity, vendor, and per-setting cost.' },
  { key:'cateringRentals', mount:'cwp-cateringRentals', label:'Tableware & Rentals', short:'Rentals', icon:'table', addLabel:'+ Add rental', help:'Rental items, quantities, vendor/source, cost, status, and notes.' },
  { key:'snacks', mount:'cwp-snacks', label:'Pre-Wedding Snacks', short:'Snacks', icon:'leaf', addLabel:'+ Add snack', help:'Getting-ready snacks, timing, quantities, costs, and notes.' },
  { key:'vendorMeals', mount:'cwp-vendorMeals', label:'Vendor Meals', short:'Vendor Meals', icon:'utensils', addLabel:'+ Add vendor meal', help:'Working vendor meals, counts, cost per meal, and dietary/timing notes.' }
];
let _cateringInlineKey = 'menu';
function cateringInlineDef(key){
  return CATERING_INLINE_TABLES.find(t => t.key === key) || CATERING_INLINE_TABLES[0];
}
function cateringInlineActive(){
  return document.body.getAttribute('data-active-panel') === 'catering' && !!document.getElementById('catering-inline-editor-body');
}
function cateringInlineAdd(key){
  if (!cateringInlineActive()) return false;
  setCateringInlineTable(key || _cateringInlineKey, null);
  return true;
}
function cateringIcon(id){
  return `<span class="cat-section-icon"><svg><use href="#cat-i-${id}"></use></svg></span>`;
}
function cateringInlineTabsHtml(){
  return CATERING_INLINE_TABLES.map(t => `<button type="button" class="m-tab${t.key === _cateringInlineKey ? ' on' : ''}" data-catering-inline-tab="${t.key}" onclick="setCateringInlineTable('${t.key}',null)" role="tab" aria-selected="${t.key === _cateringInlineKey ? 'true' : 'false'}">${escapeHtml(t.short)}</button>`).join('');
}
function syncCateringInlineTabs(){
  document.querySelectorAll('[data-catering-inline-tab]').forEach(btn => {
    const on = btn.getAttribute('data-catering-inline-tab') === _cateringInlineKey;
    btn.classList.toggle('on', on);
    btn.setAttribute('aria-selected', on ? 'true' : 'false');
  });
  const shell = document.getElementById('catering-inline-editor-wrap');
  if (shell) shell.dataset.inlineKey = _cateringInlineKey;
  const title = document.getElementById('catering-inline-table-label');
  if (title) title.textContent = cateringInlineDef(_cateringInlineKey).label;
}
function cateringInlineShellHtml(){
  return `<section class="ued-panel span12 record-editor-inline-shell catering-inline-editor" id="catering-inline-editor-wrap">
    <div class="inline-editor-head">
      <div><div class="ued-table-title">${uedIcon('table')} Catering inline editor <span id="catering-inline-table-label">${escapeHtml(cateringInlineDef(_cateringInlineKey).label)}</span> <span class="gie-mode" data-inline-editor-mode>Adding a new menu item</span></div><p class="gie-note">Choose a Catering table, edit one row here, then use the read-only previews below to scan, filter, Auto-fit, View all, and select another row.</p></div>
      <span class="inline-editor-position" data-inline-editor-position>New record</span>
    </div>
    <div class="m-tabbar catering-inline-tabs" id="catering-inline-table-tabs" role="tablist">${cateringInlineTabsHtml()}</div>
    <div id="catering-inline-editor-body" class="gie-body record-editor-inline"></div>
    <div class="inline-editor-actions">
      <button type="button" class="ued-link danger" data-inline-editor-delete onclick="recordEditorDelete()" style="display:none">Delete</button>
      <span class="inline-editor-spacer"></span>
      <button type="button" class="ued-btn" data-inline-editor-cancel onclick="setCateringInlineTable(_cateringInlineKey,null)" style="display:none">Start new row</button>
      <button type="button" class="ued-btn" onclick="saveInlineRecordEditor(true)">Save &amp; add another</button>
      <button type="button" class="ued-btn primary" data-inline-editor-save onclick="saveInlineRecordEditor(false)">+ Add menu item</button>
    </div>
  </section>`;
}
function cateringTableCardHtml(t){
  return `<section class="cat-table-card cat-table-section catering-preview-card" data-catering-table="${escapeHtml(t.key)}">
    <div class="cat-table-head">
      <div class="cat-card-title">${cateringIcon(t.icon)}<div><h3>${escapeHtml(t.label)} <span class="ro-badge-inline">Read only</span></h3><p>${escapeHtml(t.help)}</p></div></div>
      <div class="cat-table-actions no-print">
        <button type="button" class="ued-link" onclick="setCateringInlineTable('${t.key}',null)">${escapeHtml(t.addLabel)}</button>
        <button type="button" class="ued-btn db-edit-btn" onclick="openDataHub('catering','${t.key}')">Edit in Catering Hub</button>
      </div>
    </div>
    <div id="${escapeHtml(t.mount)}" class="ro-preview"></div>
    <div class="preview-foot"><span class="ued-soft">Select a row to edit it above. Spreadsheet edits and bulk actions live in Catering Hub.</span></div>
  </section>`;
}
function cateringTablesShellHtml(){
  return `<section class="catering-preview-grid" id="catering-preview-grid" aria-label="Catering tracker previews">${CATERING_INLINE_TABLES.map(cateringTableCardHtml).join('')}</section>`;
}
function uedCateringShell(){
  const panel = document.getElementById('panel-catering');
  if (!panel) return;
  panel.classList.add('ued-scope', 'catering-b2-standard');
  if (!document.getElementById('catering-inline-editor-wrap')) {
    const anchor = panel.querySelector('.preview-foot.data-hub-foot') || panel.querySelector('.cat-top-grid') || panel.querySelector('.cat-title-wrap');
    if (anchor) anchor.insertAdjacentHTML('afterend', cateringInlineShellHtml());
  }
  if (!document.getElementById('catering-preview-grid')) {
    const inlineShell = document.getElementById('catering-inline-editor-wrap');
    const anchor = inlineShell || panel.querySelector('.preview-foot.data-hub-foot') || panel.querySelector('.cat-bottom-grid');
    if (anchor) anchor.insertAdjacentHTML(inlineShell ? 'afterend' : 'beforebegin', cateringTablesShellHtml());
  }
  CATERING_INLINE_TABLES.forEach(t => {
    const mount = document.getElementById(t.mount);
    if (mount) mount.classList.add('ro-preview');
  });
  syncCateringInlineTabs();
}
async function setCateringInlineTable(key, index=null, options={}){
  const prev = _cateringInlineKey;
  const def = cateringInlineDef(key);
  _cateringInlineKey = def.key;
  syncCateringInlineTabs();
  if (!document.getElementById('catering-inline-editor-body')) return;
  await covInlineLoad(def.key, index, 'catering-inline-editor-body', null, { scroll: options.scroll !== false });
  if (recordEditorState?.inlineMount === 'catering-inline-editor-body') _cateringInlineKey = recordEditorState.key;
  else _cateringInlineKey = prev;
  syncCateringInlineTabs();
}
function bindCateringPreviewInline(key){
  const def = cateringInlineDef(key);
  const preview = document.getElementById(def.mount);
  if (!preview) return;
  preview.querySelectorAll('tr[data-id]').forEach(tr => {
    if (tr.dataset.cateringInlineBound === '1') return;
    tr.dataset.cateringInlineBound = '1';
    tr.setAttribute('tabindex', '0');
    tr.setAttribute('role', 'button');
    const select = event => {
      if (event.target.closest('.cwp-empty,.cwp-pager,.cwp-toolbar')) return;
      event.preventDefault();
      event.stopImmediatePropagation();
      const id = tr.getAttribute('data-id');
      const rows = Array.isArray(data[def.key]) ? data[def.key] : [];
      const idx = rows.findIndex(row => String(row?._id) === String(id));
      if (idx > -1) setCateringInlineTable(def.key, idx);
    };
    tr.addEventListener('click', select, true);
    tr.addEventListener('keydown', event => {
      if (event.key !== 'Enter' && event.key !== ' ') return;
      select(event);
    });
  });
}
function afterCateringTableRendered(key){
  const def = cateringInlineDef(key);
  const mount = document.getElementById(def.mount);
  if (mount) mount.classList.add('ro-preview');
  bindCateringPreviewInline(def.key);
  syncCateringInlineTabs();
}
