function ensureVenueComparePreview(){ return null; }
function renderVenueComparePreview(){}
function renderVenuePage() {
  loadVenue();
  standardizeVenuePageShell();
  const v = data.venue || {};
  const ceremonyName = venueText(v['c-name'], data.setup['venue-ceremony'] || '—');
  const receptionName = venueText(v['r-name'], data.setup['venue-reception'] || '—');
  const cSub = venueText(v['c-address'], 'Add ceremony venue details');
  const rSub = venueText(v['r-address'], 'Add reception venue details');
  const cCap = venueNumber(v['c-capacity']);
  const rCap = venueNumber(v['r-capacity']);
  const maxCap = cCap || rCap ? Math.max(cCap || 0, rCap || 0) : venueNumber(data.setup.guests);
  const costText = [venueCurrency(v['c-cost']), venueCurrency(v['r-cost'])].filter(x => x && x !== '—');
  const costSummary = costText.length ? costText.join(' • ') : '—';
  const depositText = [venueCurrency(v['c-deposit']), venueCurrency(v['r-deposit'])].filter(x => x && x !== '—');
  const statCer = document.getElementById('venue-stat-ceremony');
  const statCerSub = document.getElementById('venue-stat-ceremony-sub');
  const statRec = document.getElementById('venue-stat-reception');
  const statRecSub = document.getElementById('venue-stat-reception-sub');
  const statCap = document.getElementById('venue-stat-capacity');
  const statCapSub = document.getElementById('venue-stat-capacity-sub');
  const statCost = document.getElementById('venue-stat-cost');
  const statCostSub = document.getElementById('venue-stat-cost-sub');
  if (statCer) statCer.textContent = ceremonyName;
  if (statCerSub) statCerSub.textContent = cSub;
  if (statRec) statRec.textContent = receptionName;
  if (statRecSub) statRecSub.textContent = rSub;
  if (statCap) statCap.textContent = maxCap ? String(maxCap) : '—';
  if (statCapSub) statCapSub.textContent = maxCap ? 'Largest listed capacity' : 'Comfortable seating overview';
  if (statCost) statCost.textContent = costSummary;
  if (statCostSub) statCostSub.textContent = depositText.length ? 'Deposit paid: ' + depositText.join(' • ') : (costText.length ? 'Ceremony and reception costs' : 'Track your venue investment');
  const cTitle = document.getElementById('venue-detail-c-name');
  const rTitle = document.getElementById('venue-detail-r-name');
  if (cTitle) cTitle.textContent = ceremonyName === '—' ? 'Ceremony Venue' : ceremonyName;
  if (rTitle) rTitle.textContent = receptionName === '—' ? 'Reception Venue' : receptionName;
  renderVenueShortlist();
  setVenueView(currentVenueView);
  const compareToggle = document.getElementById('venue-compare-toggle');
  if (compareToggle) toggleVenueCompare(compareToggle.checked);
  renderVenueFullDetails();
  if (typeof renderPageUxChrome === 'function') renderPageUxChrome('venue');
  if (isDataHubPanelActive() && _dataHub.category === 'vendors' && _dataHub.table === 'vendorCompare' && typeof cwpRenderTable === 'function') cwpRenderTable('vendorCompare', 'cwp-data-hub-active');
}


const VENUE_WIDGETS = ['details','shortlist','notes','reminders'];
function defaultVenueLayout() {
  return {
    details: { order: 0, size: 'half' },
    shortlist: { order: 1, size: 'half' },
    notes: { order: 2, size: 'half' },
    reminders: { order: 3, size: 'half' }
  };
}
function ensureVenueCardLayout() {
  if (!data.venueLayout || typeof data.venueLayout !== 'object') data.venueLayout = defaultVenueLayout();
  const d = defaultVenueLayout();
  VENUE_WIDGETS.forEach(key => {
    if (!data.venueLayout[key]) data.venueLayout[key] = d[key];
    if (data.venueLayout[key].order == null) data.venueLayout[key].order = d[key].order;
    if (!data.venueLayout[key].size) data.venueLayout[key].size = d[key].size;
  });
  return data.venueLayout;
}
function applyVenueWidgetLayout() {
  const grid = document.getElementById('venue-arrange-grid');
  if (!grid) return;
  const layout = ensureVenueCardLayout();
  const widgets = Array.from(grid.querySelectorAll('.venue-widget'));
  widgets.sort((a,b) => (layout[a.dataset.card]?.order ?? 0) - (layout[b.dataset.card]?.order ?? 0));
  widgets.forEach(widget => {
    const key = widget.dataset.card;
    const item = layout[key] || {};
    widget.dataset.size = item.size || 'half';
    if (item.height) widget.style.height = item.height;
    grid.appendChild(widget);
    const label = widget.querySelector('.venue-size-toggle span');
    if (label) label.textContent = widget.dataset.size === 'wide' ? 'Half Width' : 'Make Wide';
  });
}
function initVenueCardLayout() {
  const grid = document.getElementById('venue-arrange-grid');
  if (!grid) return;
  applyVenueWidgetLayout();
  if (grid.dataset.layoutReady === 'true') return;
  grid.dataset.layoutReady = 'true';
  grid.addEventListener('dragstart', e => {
    const handle = e.target.closest('.venue-drag-handle');
    if (!handle) { e.preventDefault(); return; }
    const widget = handle.closest('.venue-widget');
    if (!widget) return;
    widget.classList.add('dragging');
    e.dataTransfer.effectAllowed = 'move';
    e.dataTransfer.setData('text/plain', widget.dataset.card || '');
  });
  grid.addEventListener('dragend', e => {
    const widget = e.target.closest('.venue-widget');
    if (widget) widget.classList.remove('dragging');
    grid.querySelectorAll('.drag-over').forEach(el => el.classList.remove('drag-over'));
    saveVenueWidgetOrder();
  });
  grid.addEventListener('dragover', e => {
    const dragging = grid.querySelector('.venue-widget.dragging');
    if (!dragging) return;
    e.preventDefault();
    const after = venueDragAfterElement(grid, e.clientY);
    grid.querySelectorAll('.drag-over').forEach(el => el.classList.remove('drag-over'));
    if (after == null) {
      grid.appendChild(dragging);
    } else {
      after.classList.add('drag-over');
      grid.insertBefore(dragging, after);
    }
  });
  grid.addEventListener('drop', e => {
    e.preventDefault();
    grid.querySelectorAll('.drag-over').forEach(el => el.classList.remove('drag-over'));
    saveVenueWidgetOrder();
  });
  let saveTimer = null;
  const scheduleSizeSave = () => {
    clearTimeout(saveTimer);
    saveTimer = setTimeout(saveVenueWidgetHeights, 250);
  };
  grid.addEventListener('mouseup', scheduleSizeSave);
  grid.addEventListener('touchend', scheduleSizeSave, { passive:true });
}
function venueDragAfterElement(container, y) {
  const els = [...container.querySelectorAll('.venue-widget:not(.dragging)')];
  return els.reduce((closest, child) => {
    const box = child.getBoundingClientRect();
    const offset = y - box.top - box.height / 2;
    if (offset < 0 && offset > closest.offset) return { offset, element: child };
    return closest;
  }, { offset: Number.NEGATIVE_INFINITY, element: null }).element;
}
function saveVenueWidgetOrder() {
  const grid = document.getElementById('venue-arrange-grid');
  if (!grid) return;
  const layout = ensureVenueCardLayout();
  Array.from(grid.querySelectorAll('.venue-widget')).forEach((widget, index) => {
    const key = widget.dataset.card;
    if (!layout[key]) layout[key] = {};
    layout[key].order = index;
  });
  save();
}
function saveVenueWidgetHeights() {
  const grid = document.getElementById('venue-arrange-grid');
  if (!grid) return;
  const layout = ensureVenueCardLayout();
  Array.from(grid.querySelectorAll('.venue-widget')).forEach(widget => {
    const key = widget.dataset.card;
    if (!layout[key]) layout[key] = {};
    if (widget.style.height) layout[key].height = widget.style.height;
  });
  save();
}
function toggleVenueWidgetSize(key) {
  const layout = ensureVenueCardLayout();
  if (!layout[key]) layout[key] = { order: VENUE_WIDGETS.indexOf(key), size: 'half' };
  layout[key].size = layout[key].size === 'wide' ? 'half' : 'wide';
  save();
  applyVenueWidgetLayout();
}
function resetVenueCardLayout() {
  data.venueLayout = defaultVenueLayout();
  const grid = document.getElementById('venue-arrange-grid');
  if (grid) grid.querySelectorAll('.venue-widget').forEach(widget => { widget.style.height = ''; widget.style.width = ''; });
  save();
  applyVenueWidgetLayout();
}

