function addVTimelineRow(){ openRecordEditor('vtimeline'); }
function pullBookedVendors(){
  const booked = data.vendors.filter(v=>['Booked','Paid','Complete'].includes(v.status));
  let added=0;
  booked.forEach(v=>{ if(!data.vtimeline.some(t=>(t.vendor||'').toLowerCase()===(v.name||'').toLowerCase() && v.name)){ data.vtimeline.push({vendor:v.name||'',time:'',location:'',contact:v.phone||v.email||'',notes:v.cat||''}); added++; } });
  save(); renderVTimeline();
  covAlert(added? added+' booked vendor(s) added to the timeline.' : 'No new booked vendors to add.');
}
function syncFilterSelect(id, values, allLabel){
  const sel = document.getElementById(id);
  if (!sel) return;
  const old = sel.value || '';
  const clean = [...new Set(values.map(v => String(v || '').trim()).filter(Boolean))].sort();
  sel.innerHTML = `<option value="">${escapeHtml(allLabel)}</option>` + clean.map(v => `<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('');
  sel.value = clean.includes(old) ? old : '';
}
function syncVTimelineFilters(){
  syncFilterSelect('vtimeline-vendor-filter', (data.vtimeline || []).map(r => r.vendor).concat((data.vendors || []).map(v => v.name)), 'All Vendors');
  syncFilterSelect('vtimeline-location-filter', (data.vtimeline || []).map(r => r.location), 'All Locations');
}
function filteredVTimelineRows(){
  const q = (document.getElementById('vtimeline-search')?.value || '').trim().toLowerCase();
  const vendor = document.getElementById('vtimeline-vendor-filter')?.value || '';
  const location = document.getElementById('vtimeline-location-filter')?.value || '';
  return (data.vtimeline || []).map((r,i)=>({r,i})).filter(({r}) => {
    const hay = [r.vendor,r.time,r.location,r.contact,r.notes].join(' ').toLowerCase();
    return (!q || hay.includes(q)) && (!vendor || r.vendor === vendor) && (!location || r.location === location);
  });
}
function clearVTimelineFilters(){
  ['vtimeline-search','vtimeline-vendor-filter','vtimeline-location-filter'].forEach(id => { const el = document.getElementById(id); if (el) el.value = ''; });
  renderVTimeline();
}
function renderVTimeline(){
  if (typeof cwpRenderTable === 'function' && cwpMountOnPanel('vtimeline')) {
    if (typeof syncVTimelineFilters === 'function') syncVTimelineFilters();
    cwpRenderTable('vtimeline');
    return;
  }
  const tb=document.getElementById('vtimeline-body'); if(!tb) return;
  syncVTimelineFilters();
  tb.innerHTML='';
  const rows = filteredVTimelineRows();
  rows.forEach(({r,i})=>{
    const tr=document.createElement('tr');
    tr.dataset.rowIndex = i;
    tr.className = 'tracker-row-clickable';
    tr.onclick = event => { if (!event.target.closest('input,select,textarea,button,a')) openRecordEditor('vtimeline', i); };
    tr.innerHTML=`<td><input type="text" value="${escapeHtml(r.vendor)}" oninput="updateVTimeline(${i},'vendor',this.value)"></td><td><input type="time" value="${escapeHtml(r.time)}" oninput="updateVTimeline(${i},'time',this.value)"></td><td><input type="text" value="${escapeHtml(r.location)}" placeholder="Venue, bride's house…" oninput="updateVTimeline(${i},'location',this.value)"></td><td><input type="text" value="${escapeHtml(r.contact)}" oninput="updateVTimeline(${i},'contact',this.value)"></td><td><input type="text" value="${escapeHtml(r.notes)}" oninput="updateVTimeline(${i},'notes',this.value)"></td><td><button type="button" class="tracker-open-btn" onclick="openRecordEditor('vtimeline',${i})">Edit</button> ${plannerTrashButton(`deleteRow('vtimeline',${i})`,'Delete vendor arrival')}</td>`;
    tb.appendChild(tr);
  });
  if(!rows.length) tb.innerHTML = (data.vtimeline || []).length
    ? `<tr data-no-bulk="true"><td colspan="6" style="padding:1.1rem;text-align:center;color:#7a7268;">No vendor arrivals match the current filters.</td></tr>`
    : tableEmptyState(6, 'No vendor arrivals yet', 'Pull booked vendors or add arrivals manually for the wedding day.', '+ Add Arrival', 'addVTimelineRow()');
  if(!rows.length) tb.querySelectorAll('tr').forEach(tr => { tr.dataset.noBulk = 'true'; });
  decorateBulk('vtimeline');
  standardizeTableTrashButtons(document.getElementById('panel-vendors'));
  requestAnimationFrame(()=>makeColumnsResizable(document.getElementById('panel-vendors')));
}
function updateVTimeline(i,k,v){ data.vtimeline[i][k]=v; save(); if(document.body.getAttribute('data-active-panel')==='timeline') renderTimeline(); }

