function essentialMatchesFilters(r){
  const cat=essentialsFilterValue('ess-filter-cat');
  const packed=essentialsFilterValue('ess-filter-packed');
  const assigned=essentialsFilterValue('ess-filter-assigned');
  const location=essentialsFilterValue('ess-filter-location');
  const item=essentialsFilterValue('ess-filter-item');
  const notes=essentialsFilterValue('ess-filter-notes');
  if(cat && String(r.cat||'').toLowerCase()!==cat) return false;
  if(packed==='yes' && !r.packed) return false;
  if(packed==='no' && r.packed) return false;
  if(assigned && String(r.assigned||'').toLowerCase()!==assigned) return false;
  if(location && String(r.location||'').toLowerCase()!==location) return false;
  if(item && !String(r.item||'').toLowerCase().includes(item)) return false;
  if(notes && !String(r.notes||'').toLowerCase().includes(notes)) return false;
  return true;
}
function renderEssentials(){
  const panel = document.getElementById('panel-essentials');
  if (panel) panel.setAttribute('data-essentials-v2', 'true');
  /* Converted to the CWP unified table engine (theme-fill header, row hairlines,
     selection + bulk, per-column Excel filters, search, shared modal editor). */
  if (typeof renderPageUxChrome === 'function') renderPageUxChrome('essentials');
  if (typeof cwpRenderTable === 'function' && cwpMountOnPanel('essentials')) {
    cwpRenderTable('essentials');
    if (typeof bindRoPreviewInline === 'function') bindRoPreviewInline('essentials', 'cwp-essentials', 'essentials-inline-editor-body');
    renderEssentialsStats();
    renderEssentialsCategoryProgress();
    if (typeof renderEssentialsKitChips === 'function') renderEssentialsKitChips();
    if (document.getElementById('essentials-inline-editor-body') && document.body.getAttribute('data-active-panel') === 'essentials' && !(recordEditorState?.inlineMount === 'essentials-inline-editor-body' && recordEditorState.key === 'essentials')) {
      covInlineLoad('essentials', null, 'essentials-inline-editor-body', null, {scroll:false});
    }
    return;
  }
  renderEssentialsStats();
  renderEssentialsCategoryProgress();
  if (typeof renderEssentialsKitChips === 'function') renderEssentialsKitChips();
  renderDesignHubPreviews();
  const tb=document.getElementById('essentials-body'); if(!tb) return; syncEssentialsFilters(); tb.innerHTML=''; data.essentials.forEach((r,i)=>{ if(!essentialMatchesFilters(r)) return; ensureRowId(r,'essentials'); const tr=document.createElement('tr'); tr.dataset.rowIndex=i; tr.className='tracker-row-clickable'; tr.onclick=event=>{ if(!event.target.closest('input,select,textarea,button,a')) openRecordEditor('essentials',i); }; tr.innerHTML=`<td><input type="text" list="essentials-cat-options" placeholder="Pick or type" value="${escapeHtml(r.cat||'')}" oninput="updateEssential(${i},'cat',this.value)"></td><td><input type="text" value="${escapeHtml(r.item||'')}" oninput="updateEssential(${i},'item',this.value)"></td><td><input type="checkbox" ${r.packed?'checked':''} style="width:auto" onchange="updateEssential(${i},'packed',this.checked)"></td><td><input type="text" value="${escapeHtml(r.assigned||'')}" oninput="updateEssential(${i},'assigned',this.value)"></td><td><input type="text" value="${escapeHtml(r.location||'')}" oninput="updateEssential(${i},'location',this.value)"></td><td><input type="text" value="${escapeHtml(r.notes||'')}" oninput="updateEssential(${i},'notes',this.value)"></td><td><button type="button" class="tracker-open-btn" onclick="openRecordEditor('essentials',${i})">Edit</button> ${plannerTrashButton(`deleteRow('essentials',${i})`,'Delete item')}</td>`; tb.appendChild(tr); }); if(!tb.children.length){ tb.innerHTML = data.essentials.length ? `<tr><td colspan="7" style="text-align:center;padding:1.25rem;color:#7a7268;">No items match the current filters.</td></tr>` : tableEmptyState(7, 'No essentials yet', 'Build your wedding-day essentials and emergency kit. Load our starter checklist or add items yourself.', 'Load Starter Checklist', 'loadEssentialsPreset()', '+ Add Item', 'addEssentialRow()'); } renderEssentialsStats(); renderEssentialsCategoryProgress(); requestAnimationFrame(()=>bindRecordEditorTable('essentials-body','essentials')); }
function renderEssentialsCategoryProgress(){
  const host = document.getElementById('essentials-category-progress');
  if (!host) return;
  const items = safeArray(data.essentials);
  if (!items.length) { host.innerHTML = ''; host.hidden = true; return; }
  const groups = {};
  items.forEach(r => {
    const cat = String(r.cat || '').trim() || 'Uncategorized';
    if (!groups[cat]) groups[cat] = { total: 0, packed: 0 };
    groups[cat].total++;
    if (r.packed) groups[cat].packed++;
  });
  const sorted = Object.keys(groups).sort((a, b) => a.localeCompare(b));
  host.hidden = false;
  host.innerHTML = '<div class="ess-cat-progress-head"><span class="ess-hub-kicker">By category</span><h4 class="ess-cat-progress-title">Packing progress by group</h4></div><div class="ess-cat-progress-grid">' +
    sorted.map(cat => {
      const g = groups[cat];
      const pct = g.total ? Math.round(g.packed / g.total * 100) : 0;
      return `<div class="ess-cat-chip"><div class="ess-cat-chip-top"><span class="ess-cat-name">${escapeHtml(cat)}</span><span class="ess-cat-count">${g.packed}/${g.total}</span></div><div class="ess-cat-bar" role="progressbar" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100" aria-label="${escapeHtml(cat)}: ${pct}% packed"><span style="width:${pct}%"></span></div></div>`;
    }).join('') + '</div>';
}

function renderEssentialsStats() {
  const el = document.getElementById('essentials-stats');
  const overview = document.getElementById('essentials-progress-overview');
  if (!el) return;
  const total = data.essentials.length;
  const packed = data.essentials.filter(r => r.packed).length;
  const remaining = total - packed;
  const cats = [...new Set(data.essentials.map(r => r.cat).filter(Boolean))].length;
  const pct = total > 0 ? Math.round(packed / total * 100) : 0;
  if (overview) {
    if (total > 0) {
      overview.hidden = false;
      overview.innerHTML = `<div class="ess-overall-progress"><div class="ess-overall-head"><span class="ess-overall-label">Overall packing progress</span><strong class="ess-overall-val">${packed} of ${total} packed</strong></div><div class="ess-overall-bar" role="progressbar" aria-valuenow="${pct}" aria-valuemin="0" aria-valuemax="100"><span style="width:${pct}%"></span></div><p class="ess-overall-sub">${remaining ? remaining + ' item' + (remaining === 1 ? '' : 's') + ' still to pack' : 'Everything is checked off — well done!'}</p></div>`;
    } else {
      overview.innerHTML = '';
      overview.hidden = true;
    }
  }
  const ms=(paths,label,val,sub)=>`<div class="m-stat"><div class="m-stat-top"><svg viewBox="0 0 24 24" aria-hidden="true">${paths}</svg><span class="m-stat-label">${label}</span></div><div class="m-stat-val">${val}</div><div class="m-stat-sub">${sub}</div></div>`;
  el.innerHTML =
    ms('<path d="M9 5H7a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-2"/><path d="M9 5a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v0a2 2 0 0 1-2 2h-2a2 2 0 0 1-2-2Z"/>','Total items', total, 'On your checklist') +
    ms('<path d="M5 12l4 4L19 6"/>','Packed', packed, total>0?pct+'% done':'Ready to start') +
    ms('<circle cx="12" cy="12" r="8"/><path d="M12 8v4"/><circle cx="12" cy="16" r=".5" fill="currentColor"/>','Remaining', remaining, 'Still to pack') +
    ms('<path d="M3 7v10a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V9a2 2 0 0 0-2-2h-6l-2-2H5a2 2 0 0 0-2 2Z"/>','Categories', cats, 'Organized groups');
}
function updateEssential(i,k,v){
  data.essentials[i][k]=v;
  save();
  if(['cat','item','assigned','location'].includes(k)){
    syncEssentialsFilters();
    const table=document.getElementById('essentials-body')?.closest('table');
    if(table) ensureEssentialsBulkCard('essentials', table, bulkHeaderRowOf(table));
  }
}

/* ════════════════════════════════════════════════
   PLANNING TIMELINE
════════════════════════════════════════════════ */
const PLAN_PHASES = ['12+ Months Before','9-12 Months Before','6-9 Months Before','3 Months Before','1 Month Before','1 Week Before','Wedding Day','After the Wedding'];
const PLAN_STATUS = ['','Not Started','In-Progress','Complete'];
function normalizePlanPhase(phase){
  const p = String(phase || '').trim().toLowerCase();
  if (/get started|12\+|12 months/.test(p)) return '12+ Months Before';
  if (/9-12|9 to 12|jun 2026/.test(p)) return '9-12 Months Before';
  if (/6-9|6 to 9|jul 2026|3-6/.test(p)) return '6-9 Months Before';
  if (/3 months|3 month/.test(p)) return '3 Months Before';
  if (/1 month|wedding month/.test(p)) return '1 Month Before';
  if (/1 week|wedding week/.test(p)) return '1 Week Before';
  if (/wedding day/.test(p)) return 'Wedding Day';
  if (/after/.test(p)) return 'After the Wedding';
  return PLAN_PHASES.includes(phase) ? phase : '12+ Months Before';
}
function planPhaseBaseDate(phase, offset=0){
  const wedding = data.setup?.date || '';
  if (!wedding) return '';
  const d = new Date(wedding + 'T00:00:00');
  const p = normalizePlanPhase(phase);
  if (p === '12+ Months Before') d.setMonth(d.getMonth() - 12);
  else if (p === '9-12 Months Before') d.setMonth(d.getMonth() - 10);
  else if (p === '6-9 Months Before') d.setMonth(d.getMonth() - 7);
  else if (p === '3 Months Before') d.setMonth(d.getMonth() - 3);
  else if (p === '1 Month Before') d.setMonth(d.getMonth() - 1);
  else if (p === '1 Week Before') d.setDate(d.getDate() - 7);
  else if (p === 'After the Wedding') d.setDate(d.getDate() + 14);
  if (!['Wedding Day','1 Week Before'].includes(p)) d.setDate(d.getDate() + Math.min(28, Math.max(0, offset) * 4));
  return d.toISOString().slice(0,10);
}
