async function loadFullWeddingChecklist(){
  if(data.plan.length && !await starterConfirm('Add the Full Wedding Checklist (59 tasks across 8 phases) to your Planning Timeline?')) return;
  const phaseCounts = {};
  FULL_CHECKLIST.forEach(([phase,task,subCount,doneCount])=>{
    const cleanPhase = normalizePlanPhase(phase);
    const phaseOffset = phaseCounts[cleanPhase] || 0;
    phaseCounts[cleanPhase] = phaseOffset + 1;
    const suggested = planPhaseBaseDate(cleanPhase, phaseOffset);
    const subtasks=[];
    for(let n=0;n<subCount;n++) subtasks.push({text:'', done:n<doneCount});
    data.plan.push({phase:cleanPhase,task,owner:'',suggestedDue:suggested,due:suggested,priority:'Medium',status:(doneCount>0&&doneCount<subCount)?'In Progress':'Not Started',done:false,notes:'',subtasks});
  });
  save(); renderPlan();
}

/* ── Plan task subtasks (expandable checklist with an X/Y badge) ── */
const expandedPlanSubs = new Set();
function planSubArr(i){ if(!Array.isArray(data.plan[i].subtasks)) data.plan[i].subtasks=[]; return data.plan[i].subtasks; }
function togglePlanSub(i){ if(expandedPlanSubs.has(i)) expandedPlanSubs.delete(i); else expandedPlanSubs.add(i); renderPlan(); }
function addPlanSubtask(i){ planSubArr(i).push({text:'',done:false}); expandedPlanSubs.add(i); save(); renderPlan(); }
function updatePlanSubtaskText(i,si,val){ const s=planSubArr(i); if(s[si]){ s[si].text=val; save(); } }
function togglePlanSubtaskDone(i,si,checked){ const s=planSubArr(i); if(s[si]){ s[si].done=checked; save(); renderPlan(); } }
function removePlanSubtask(i,si){ const s=planSubArr(i); s.splice(si,1); save(); renderPlan(); }
function planSubtaskRow(i){
  const subs=planSubArr(i);
  const items=subs.map((s,si)=>`<div class="plan-sub-item"><label class="plan-sub-check"><input type="checkbox" ${s.done?'checked':''} onchange="togglePlanSubtaskDone(${i},${si},this.checked)"></label><input type="text" class="plan-sub-text" value="${escapeHtml(s.text||'')}" placeholder="Describe this step…" oninput="updatePlanSubtaskText(${i},${si},this.value)">${plannerTrashButton(`removePlanSubtask(${i},${si})`,'Remove subtask')}</div>`).join('') || '<div class="plan-sub-empty">No subtasks yet — add the steps for this task.</div>';
  return `<tr class="plan-sub-row"><td colspan="10"><div class="plan-sub-wrap"><div class="plan-sub-head">${escapeHtml(data.plan[i].task||'Task')} — subtasks</div>${items}<button type="button" class="btn btn-outline btn-sm plan-sub-add" onclick="addPlanSubtask(${i})">+ Add subtask</button></div></td></tr>`;
}

function planPhaseClass(phase) {
  const p = (phase || '').toLowerCase();
  if (p.includes('12')) return 'phase-12';
  if (p.includes('9-12')) return 'phase-9';
  if (p.includes('6-9')) return 'phase-6';
  if (p.includes('3-6')) return 'phase-3';
  if (p.includes('month')) return 'phase-month';
  if (p.includes('week')) return 'phase-week';
  if (p.includes('after')) return 'phase-after';
  return 'phase-12';
}
function planPriorityClass(priority) {
  const p = (priority || '').toLowerCase();
  if (p.includes('high')) return 'priority-high';
  if (p.includes('low')) return 'priority-low';
  return 'priority-medium';
}
function planDisplayStatus(row) {
  const status = (row.status || '').trim().toLowerCase();
  if (row.done || status === 'complete') return 'Complete';
  if (status === 'in-progress' || status === 'in progress') return 'In Progress';
  return 'Upcoming';
}
function planStatusClass(displayStatus) {
  const s = (displayStatus || '').toLowerCase();
  if (s.includes('complete')) return 'status-complete';
  if (s.includes('progress')) return 'status-progress';
  return 'status-upcoming';
}
function planOptions(selected, options) {
  return options.map(opt => `<option value="${escapeHtml(opt)}" ${String(selected||'')===String(opt)?'selected':''}>${escapeHtml(opt)}</option>`).join('');
}
function planFilterOptions() {
  const phaseSel = document.getElementById('timeline-phase-filter');
  const statusSel = document.getElementById('timeline-status-filter');
  const currentPhase = phaseSel?.dataset.current || phaseSel?.value || 'All Phases';
  const currentStatus = statusSel?.dataset.current || statusSel?.value || 'All Statuses';
  if (phaseSel) {
    phaseSel.innerHTML = ['All Phases', ...PLAN_PHASES].map(v => `<option ${v===currentPhase?'selected':''}>${escapeHtml(v)}</option>`).join('');
    phaseSel.dataset.current = phaseSel.value;
  }
  if (statusSel) {
    const statuses = ['All Statuses','Complete','In Progress','Upcoming'];
    statusSel.innerHTML = statuses.map(v => `<option ${v===currentStatus?'selected':''}>${escapeHtml(v)}</option>`).join('');
    statusSel.dataset.current = statusSel.value;
  }
}
function renderPlanStats() {
  const total = data.plan.length;
  const complete = data.plan.filter(r => planDisplayStatus(r) === 'Complete').length;
  const progress = data.plan.filter(r => planDisplayStatus(r) === 'In Progress').length;
  const upcoming = data.plan.filter(r => planDisplayStatus(r) === 'Upcoming').length;
  const totalEl = document.getElementById('plan-stat-total');
  const totalSub = document.getElementById('plan-stat-total-sub');
  const completeEl = document.getElementById('plan-stat-complete');
  const completeSub = document.getElementById('plan-stat-complete-sub');
  const progressEl = document.getElementById('plan-stat-progress');
  const progressSub = document.getElementById('plan-stat-progress-sub');
  const upcomingEl = document.getElementById('plan-stat-upcoming');
  const upcomingSub = document.getElementById('plan-stat-upcoming-sub');
  const dateEl = document.getElementById('plan-stat-date');
  const dateSub = document.getElementById('plan-stat-date-sub');
  if (totalEl) totalEl.textContent = total;
  if (totalSub) totalSub.textContent = total ? 'All timeline tasks' : 'Add timeline tasks to begin';
  if (completeEl) completeEl.textContent = complete;
  if (completeSub) completeSub.textContent = total ? `${Math.round((complete/total)*100)}% complete` : '0% complete';
  if (progressEl) progressEl.textContent = progress;
  if (progressSub) progressSub.textContent = total ? `${Math.round((progress/Math.max(total,1))*100)}% in progress` : 'Tasks in motion';
  if (upcomingEl) upcomingEl.textContent = upcoming;
  if (upcomingSub) upcomingSub.textContent = total ? `${Math.round((upcoming/Math.max(total,1))*100)}% upcoming` : 'Next tasks ahead';
  const dateStr = data.setup?.date || '';
  if (dateEl && dateSub) {
    if (dateStr) {
      const d = new Date(dateStr + 'T00:00:00');
      const today = new Date(); today.setHours(0,0,0,0);
      const diff = Math.ceil((d - today) / 86400000);
      dateEl.textContent = d.toLocaleDateString('en-US', { month:'short', day:'numeric', year:'numeric' });
      dateSub.textContent = diff >= 0 ? `${diff} day${diff===1?'':'s'} to go` : 'Wedding date has passed';
    } else {
      dateEl.textContent = '—';
      dateSub.textContent = 'Set your wedding date';
    }
  }
}
function renderPlan() {
  const tb = document.getElementById('plan-body');
  if (!tb) return;
  planFilterOptions();
  renderPlanStats();
  const phaseFilter = document.getElementById('timeline-phase-filter')?.value || 'All Phases';
  const statusFilter = document.getElementById('timeline-status-filter')?.value || 'All Statuses';
  let rows = data.plan.map((row, index) => ({ row, index, displayStatus: planDisplayStatus(row) }));
  rows.forEach(item => { item.row.phase = normalizePlanPhase(item.row.phase); });
  if (phaseFilter !== 'All Phases') rows = rows.filter(item => normalizePlanPhase(item.row.phase) === phaseFilter);
  if (statusFilter !== 'All Statuses') rows = rows.filter(item => item.displayStatus === statusFilter);
  tb.innerHTML = rows.map(({ row:r, index:i, displayStatus }) => {
    const phase = normalizePlanPhase(r.phase);
    r.phase = phase;
    const priority = r.priority || 'Medium';
    const owner = r.owner || '';
    const notes = r.notes || '';
    const suggested = r.suggestedDue || '';
    const subs = Array.isArray(r.subtasks) ? r.subtasks : [];
    const subDone = subs.filter(s=>s.done).length;
    const expanded = expandedPlanSubs.has(i);
    const subToggle = `<button type="button" class="plan-sub-toggle${expanded?' open':''}" onclick="togglePlanSub(${i})">${expanded?'▾':'▸'} ${subs.length?(subDone+'/'+subs.length+' subtasks'):'add subtasks'}</button>`;
    return `<tr>
      <td class="timeline-cell-compact"><span class="timeline-pill ${planPhaseClass(phase)}"><select class="timeline-select" onchange="updatePlan(${i},'phase',this.value)">${planOptions(phase, PLAN_PHASES)}</select></span></td>
      <td><input class="timeline-input" type="text" value="${escapeHtml(r.task || r.focus || '')}" oninput="updatePlan(${i},'task',this.value)">${/bachelor|bachelorette|bridal shower|engagement party|hen party/i.test(r.task||'')?'<span style="font-size:.65rem;color:var(--v4-gold,#B89968);margin-left:.35rem;opacity:.8">(Optional)</span>':''}${subToggle}</td>
      <td><div class="timeline-owner-meta"><svg viewBox="0 0 24 24"><circle cx="12" cy="8" r="3.5"/><path d="M5 21a7 7 0 0 1 14 0"/></svg><input class="timeline-input" type="text" list="assigned-options" value="${escapeHtml(owner)}" placeholder="Pick or type" oninput="updatePlan(${i},'owner',this.value)"></div></td>
      <td><div class="timeline-date-meta"><svg viewBox="0 0 24 24"><path d="M16 3v4M8 3v4M4 9h16"/><rect x="4" y="5" width="16" height="15" rx="2"/></svg><input class="timeline-input" type="date" value="${escapeHtml(suggested)}" readonly title="Suggested date based on your wedding date"></div></td>
      <td><div class="timeline-date-meta"><svg viewBox="0 0 24 24"><path d="M16 3v4M8 3v4M4 9h16"/><rect x="4" y="5" width="16" height="15" rx="2"/></svg><input class="timeline-input" type="date" value="${escapeHtml(r.due || '')}" oninput="updatePlan(${i},'due',this.value)"></div></td>
      <td class="timeline-cell-compact"><span class="timeline-pill ${planPriorityClass(priority)}"><select class="timeline-select" onchange="updatePlan(${i},'priority',this.value)">${planOptions(priority, PRIORITY)}</select></span></td>
      <td class="timeline-cell-compact"><span class="timeline-pill ${planStatusClass(displayStatus)}"><select class="timeline-select" onchange="updatePlan(${i},'status',this.value)">${planOptions(r.status || (displayStatus === 'Upcoming' ? 'Not Started' : displayStatus), ['', 'Not Started','Upcoming','In Progress','Complete'])}</select></span></td>
      <td class="timeline-cell-compact"><div class="timeline-done-wrap"><label class="timeline-done-check"><input type="checkbox" ${r.done?'checked':''} onchange="updatePlan(${i},'done',this.checked)"></label></div></td>
      <td><input class="timeline-note-input" type="text" value="${escapeHtml(notes)}" oninput="updatePlan(${i},'notes',this.value)"></td>
      <td class="timeline-actions payment-row-actions"><button class="payment-icon-btn" title="Delete task" onclick="deleteRow('plan',${i})"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 6h18"/><path d="M8 6V4h8v2"/><path d="M19 6l-1 14H6L5 6"/><path d="M10 11v6M14 11v6"/></svg></button></td>
    </tr>` + (expanded ? planSubtaskRow(i) : '');
  }).join('');
  if (!rows.length) {
    const ghost = typeof legacyGhostRowsHtml === 'function' ? legacyGhostRowsHtml('plan', 10, { bulk:true, recordLabel:'planning task', addLabel:'+ Add task', addFn:'addPlanRow()' }) : '';
    tb.innerHTML = ghost || `<tr><td colspan="10" style="padding:1.25rem; text-align:center; color:#7a7268;">No tasks match the current filters. Try another phase or status, or add a new task.</td></tr>`;
  }
  const summary = document.getElementById('plan-filter-summary');
  if (summary) {
    const phaseText = phaseFilter === 'All Phases' ? 'all phases' : phaseFilter;
    const statusText = statusFilter === 'All Statuses' ? 'all statuses' : statusFilter.toLowerCase();
    summary.textContent = `Showing ${rows.length} task${rows.length===1?'':'s'} for ${phaseText} and ${statusText}.`;
  }
}
function updatePlan(i,k,v){
  if (!data.plan[i]) return;
  data.plan[i][k]=v;
  if (k === 'phase') {
    data.plan[i].phase = normalizePlanPhase(v);
    data.plan[i].suggestedDue = planPhaseBaseDate(data.plan[i].phase,0);
    if (!data.plan[i].due) data.plan[i].due = data.plan[i].suggestedDue;
  }
  if (k === 'status' && String(v).toLowerCase() === 'complete') data.plan[i].done = true;
  save(); renderWhenInputComplete(renderPlan);
}


/* ════════════════════════════════════════════════
   CONTRACTS & INVOICES + RENTALS
════════════════════════════════════════════════ */
const CONTRACT_STATUS = ['Not Signed','Signed','Invoiced','Paid'];
const CONTRACT_TYPES = ['Contract','Invoice','Receipt','Other'];
function contractCurrency(n){ return fmt(Math.round(Number(n)||0)); }
function contractNumber(r,k){
  if (!r) return 0;
  if (k === 'total') return Number(r.total != null && r.total !== '' ? r.total : (r.amount || 0)) || 0;
  return Number(r[k] || 0) || 0;
}
function contractBalance(r){ return Math.max(0, contractNumber(r,'total') - contractNumber(r,'deposit')); }
function contractStatusSlug(status){ return String(status || 'Not Signed').toLowerCase().replace(/\s+/g,'-'); }
function contractStatusSelect(i,status){
  const s = status || 'Not Signed';
  return `<select class="contract-status-select ${contractStatusSlug(s)}" onchange="updateContract(${i},'status',this.value)">${CONTRACT_STATUS.map(v=>`<option ${v===s?'selected':''}>${escapeHtml(v)}</option>`).join('')}</select>`;
}
function contractStatusPill(status){
  const s = status || 'Not Signed';
  if (typeof pill === 'function') {
    const scheme = typeof pillSchemeFor === 'function' ? pillSchemeFor(s, 'contract') : 'neutral';
    return pill(s, scheme);
  }
  return `<span class="contract-status-pill ${contractStatusSlug(s)}">${escapeHtml(s)}</span>`;
}
function contractRowIcon(type){
  const t = String(type || 'Contract').toLowerCase();
  if (t.includes('invoice')) return '<svg viewBox="0 0 24 24"><path d="M7 4h10v16l-2-1.2-2 1.2-2-1.2-2 1.2-2-1.2z"/><path d="M10 9h4M10 13h4"/></svg>';
  if (t.includes('receipt')) return '<svg viewBox="0 0 24 24"><path d="M7 4h10v16l-2-1.2-2 1.2-2-1.2-2 1.2-2-1.2z"/><path d="M9 8h6M9 12h6M9 16h3"/></svg>';
  return '<svg viewBox="0 0 24 24"><path d="M6 3h9l3 3v15H6z"/><path d="M15 3v4h4"/><path d="M9 12h6M9 16h6M9 8h2"/></svg>';
}
function contractFileIcon(){ return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 3h9l3 3v15H6z"/><path d="M15 3v4h4"/><path d="M9 12h6M9 16h4"/></svg>'; }
function plannerTrashButton(onclick, title='Delete row'){
  return `<button class="payment-icon-btn table-trash-btn" title="${escapeHtml(title)}" aria-label="${escapeHtml(title)}" onclick="${onclick}">${PLANNER_TRASH_ICON}</button>`;
}
function contractFileObject(r,key){
  if (!r) return null;
  const obj = r[key];
  if (obj && typeof obj === 'object') return obj;
  if (typeof obj === 'string' && obj) return {name:obj,type:'file',img:''};
  if (key === 'contractFile' && r.img) return {name:'Contract snapshot',type:'image',img:r.img};
  return null;
}
function contractFileCell(i,r,key,label){
  const obj = contractFileObject(r,key);
  if (obj) {
    const thumb = obj.img ? `<img class="contract-file-thumb" src="${escapeHtml(obj.img)}" alt="">` : contractFileIcon();
    const name = obj.name || label + ' file';
    return `<div class="contract-file-cell"><button type="button" class="contract-file-pill" title="Click to remove ${escapeHtml(name)}" onclick="removeContractFile(${i},'${key}')">${thumb}<span>${escapeHtml(name)}</span></button></div>`;
  }
  return `<div class="contract-file-cell"><label class="contract-file-pill contract-file-upload">${contractFileIcon()}<span>Upload</span><input type="file" accept="image/*,.pdf" style="display:none" onchange="uploadContractFile(${i},'${key}',event)"></label></div>`;
}
/* ── Contracts & rentals filters ──────────────────────────────────────────
   This page still wears the older ued shell, but its filters now use the same
   chip and picker as the redesigned pages. The values used to live on the
   <select> elements themselves; they live here instead so the chips can be
   repainted without losing the selection. */
window._contractFilters = window._contractFilters || { type: 'All Types', status: 'All Status' };
window._rentalFilters = window._rentalFilters || { vendor: '', date: '' };
const RENTAL_DATE_LABELS = { '': 'all', pickup: 'Has pick-up date', ret: 'Has return date', return: 'Has return date', missing: 'Missing a date' };
function rdFilterChipHtml(label, display, active, openCall, clearCall){
  const chev = '<svg viewBox="0 0 24 24" aria-hidden="true" style="width:1em;height:1em;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round"><path d="m6 9 6 6 6-6"/></svg>';
  return `<button type="button" class="rd-chip${active ? ' is-active' : ''}" onclick="${openCall}">${escapeHtml(label + ': ' + display)}`
    + (active ? `<span class="rd-chip__clear" onclick="event.stopPropagation();${clearCall}">&#10005;</span>` : chev)
    + `</button>`;
}
function renderContractFilterChips(){
  const host = document.getElementById('contracts-filter-chips');
  if (!host) return;
  const f = window._contractFilters;
  host.innerHTML =
    rdFilterChipHtml('Type', f.type === 'All Types' ? 'all' : f.type, f.type !== 'All Types',
      "openContractFilter('type',this)", "clearContractFilter('type')")
    + rdFilterChipHtml('Status', f.status === 'All Status' ? 'all' : f.status, f.status !== 'All Status',
      "openContractFilter('status',this)", "clearContractFilter('status')");
}
function openContractFilter(field, btn){
  const all = field === 'type' ? 'All Types' : 'All Status';
  const values = field === 'type' ? (CONTRACT_TYPES || []) : (CONTRACT_STATUS || []);
  const opts = [{ value: all, label: 'All' }].concat(values.map(v => ({ value: v, label: v })));
  window.rdPickOne(btn, opts, window._contractFilters[field] || all, val => {
    window._contractFilters[field] = val;
    renderContracts();
  });
}
function clearContractFilter(field){
  window._contractFilters[field] = field === 'type' ? 'All Types' : 'All Status';
  renderContracts();
}
function renderRentalFilterChips(){
  const host = document.getElementById('rentals-filter-chips');
  if (!host) return;
  const f = window._rentalFilters;
  host.innerHTML =
    rdFilterChipHtml('Vendor', f.vendor || 'all', !!f.vendor,
      "openRentalFilter('vendor',this)", "clearRentalFilter('vendor')")
    + rdFilterChipHtml('Dates', RENTAL_DATE_LABELS[f.date] || 'all', !!f.date,
      "openRentalFilter('date',this)", "clearRentalFilter('date')");
}
function openRentalFilter(field, btn){
  let opts;
  if (field === 'vendor') {
    const names = [...new Set((data.rentals || []).map(r => r.vendor)
      .concat((data.vendors || []).map(v => v.name))
      .map(v => String(v || '').trim()).filter(Boolean))].sort();
    opts = [{ value: '', label: 'All' }].concat(names.map(n => ({ value: n, label: n })));
  } else {
    opts = [
      { value: '', label: 'All' },
      { value: 'pickup', label: 'Has pick-up date' },
      { value: 'return', label: 'Has return date' },
      { value: 'missing', label: 'Missing a date' }
    ];
  }
  window.rdPickOne(btn, opts, window._rentalFilters[field] || '', val => {
    window._rentalFilters[field] = val || '';
    renderRentals();
  });
}
function clearRentalFilter(field){
  window._rentalFilters[field] = '';
  renderRentals();
}
