/* Inspiration Gallery tab window (Batch 7) — one category card per tab. */
let _visionTab='decisions';
let _moodTab='overall-vibe-theme';
function visionTab(name){
  _visionTab=name || 'decisions';
  document.querySelectorAll('#panel-mood [data-vision-tab]').forEach(el => { el.style.display = (el.dataset.visionTab===_visionTab) ? '' : 'none'; });
  document.querySelectorAll('#panel-mood .vision-tabbar .m-tab').forEach(b => b.classList.toggle('on', b.dataset.tab===_visionTab));
  moodTab(_moodTab);
}
function moodTab(name){
  const valid = (MOOD_BOARD_SECTIONS || []).some(sec => sec.id === name);
  _moodTab=valid ? name : ((MOOD_BOARD_SECTIONS || [])[0]?.id || 'overall-vibe-theme');
  document.querySelectorAll('#panel-mood [data-mood-tab]').forEach(el => { el.style.display = (_visionTab === 'inspiration' && el.dataset.moodTab===_moodTab) ? '' : 'none'; });
  document.querySelectorAll('#panel-mood .mood-tabbar .m-tab').forEach(b => b.classList.toggle('on', b.dataset.tab===_moodTab));
}
function renderMoodInspirationCards(){
  const panel = document.getElementById('panel-mood');
  const grid = panel?.querySelector('.mood-board-grid');
  if (!panel || !grid) return;
  const tabbar = panel.querySelector('.mood-tabbar[data-vision-tab="inspiration"]');
  if (tabbar) {
    tabbar.innerHTML = (MOOD_BOARD_SECTIONS || []).map(sec => `<button class="m-tab" data-tab="${escapeHtml(sec.id)}" onclick="moodTab('${String(sec.id).replace(/'/g,"\\'")}')">${escapeHtml(sec.key)}</button>`).join('');
  }
  (MOOD_BOARD_SECTIONS || []).forEach(sec => {
    let article = panel.querySelector(`[data-mood-tab="${sec.id}"]`);
    if (!article) {
      article = document.createElement('article');
      article.className = 'mood-card';
      article.dataset.visionTab = 'inspiration';
      article.dataset.moodTab = sec.id;
      article.style.gridColumn = '1 / -1';
      grid.appendChild(article);
    }
    if (sec.id === 'favorites' && article.querySelector('#mood-favorites-list')) return;
    article.dataset.visionTab = 'inspiration';
    article.dataset.moodTab = sec.id;
    article.style.gridColumn = '1 / -1';
    article.innerHTML = `<div class="mood-card-head"><span class="mood-card-icon" aria-hidden="true">${moodIcon(sec.icon)}</span><div><h3>${escapeHtml(sec.key)}</h3><p>${escapeHtml(sec.note || 'Gather inspiration for this part of your wedding vision.')}</p></div></div><div id="mood-board-${escapeHtml(sec.id)}" class="mood-preview-grid"></div>`;
  });
}
