function hmEnsureData(){
  if(!data.honeymoon || typeof data.honeymoon !== 'object') data.honeymoon = {};
  if(!Array.isArray(data.honeyItinerary)) data.honeyItinerary = [];
  if(!Array.isArray(data.packing)) data.packing = [];
  if(!Array.isArray(data.nameChange)) data.nameChange = [];
  if(!Array.isArray(data.honeyDetails)) data.honeyDetails = [];
  if(!Array.isArray(data.honeyTransport)) data.honeyTransport = [];
}
function loadHoneymoon(){
  document.getElementById('panel-honeymoon')?.classList.add('ued-scope');
  hmEnsureData();
  HM_FIELDS.forEach(k=>{ const el=document.getElementById('hm-'+k); if(el && data.honeymoon[k]!=null) el.value=data.honeymoon[k]; });
  const img=document.getElementById('hm-dest-photo-img');
  const ph=document.getElementById('hm-dest-photo-placeholder');
  const area=document.getElementById('hm-dest-photo-area');
  if(img && data.honeymoon.destPhoto){
    img.src=data.honeymoon.destPhoto;
    img.style.display='block';
    img.style.objectPosition = `${data.honeymoon.destPhotoX || 50}% ${data.honeymoon.destPhotoY || 50}%`;
    if(ph) ph.style.display='none';
    area?.classList.add('has-photo');
  }
  else if(img){ img.style.display='none'; if(ph) ph.style.display=''; area?.classList.remove('has-photo'); }
  setupHoneymoonDestPhotoDrag();
  renderHoneymoonStats(); renderHoneymoonPreviewCards();
  if (typeof renderPageUxChrome === 'function') renderPageUxChrome('honeymoon');
}
function uploadHoneymoonDestPhoto(ev){
  const file=ev.target.files[0]; if(!file) return;
  const url=URL.createObjectURL(file);
  const img=new Image();
  img.onload=()=>{
    URL.revokeObjectURL(url);
    const max=800; let w=img.width,h=img.height;
    if(w>h&&w>max){h=Math.round(h*max/w);w=max;} else if(h>max){w=Math.round(w*max/h);h=max;}
    const c=document.createElement('canvas');c.width=w;c.height=h;c.getContext('2d').drawImage(img,0,0,w,h);
    let q=0.8,result=c.toDataURL('image/jpeg',q);
    while(result.length>200000&&q>0.3){q-=0.1;result=c.toDataURL('image/jpeg',q);}
    hmEnsureData(); data.honeymoon.destPhoto=result; data.honeymoon.destPhotoX=50; data.honeymoon.destPhotoY=50; save(); loadHoneymoon();
  };
  img.onerror=()=>{URL.revokeObjectURL(url);covAlert('Could not read that image.');};
  img.src=url; ev.target.value='';
}
function removeHoneymoonDestPhoto(event){
  if(event){ event.preventDefault(); event.stopPropagation(); }
  hmEnsureData();
  delete data.honeymoon.destPhoto;
  delete data.honeymoon.destPhotoX;
  delete data.honeymoon.destPhotoY;
  save();
  loadHoneymoon();
}
function setupHoneymoonDestPhotoDrag(){
  const area=document.getElementById('hm-dest-photo-area');
  const img=document.getElementById('hm-dest-photo-img');
  if(!area || !img || area.dataset.dragBound === '1') return;
  area.dataset.dragBound = '1';
  area.addEventListener('click', e => {
    if(area.dataset.photoDragging === '1'){
      e.preventDefault();
      e.stopPropagation();
      area.dataset.photoDragging = '0';
    }
  }, true);
  area.addEventListener('pointerdown', e => {
    if(!data.honeymoon?.destPhoto || e.target.closest('button,input')) return;
    e.preventDefault();
    e.stopPropagation();
    const rect = area.getBoundingClientRect();
    const setPos = ev => {
      const x = Math.max(0, Math.min(100, Math.round(((ev.clientX - rect.left) / rect.width) * 100)));
      const y = Math.max(0, Math.min(100, Math.round(((ev.clientY - rect.top) / rect.height) * 100)));
      data.honeymoon.destPhotoX = x;
      data.honeymoon.destPhotoY = y;
      img.style.objectPosition = `${x}% ${y}%`;
    };
    area.dataset.photoDragging = '1';
    setPos(e);
    const move = ev => setPos(ev);
    const up = () => { document.removeEventListener('pointermove', move); document.removeEventListener('pointerup', up); save(); };
    document.addEventListener('pointermove', move);
    document.addEventListener('pointerup', up);
  }, true);
}
function saveHoneymoon(){
  hmEnsureData();
  HM_FIELDS.forEach(k=>{ const el=document.getElementById('hm-'+k); if(el) data.honeymoon[k]=el.value; });
  save(); renderWhenInputComplete(()=>{ renderHoneymoonStats(); renderHoneymoonPreviewCards(); });
}
function hmDate(value){
  if (!value) return null;
  const d = new Date(String(value).split('T')[0] + 'T00:00:00');
  return Number.isNaN(d.getTime()) ? null : d;
}
function hmHumanDate(value){
  const d = hmDate(value);
  return d ? d.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}) : '';
}
function hmDaysUntil(value){
  const d = hmDate(value); if(!d) return null;
  const today = new Date(); today.setHours(0,0,0,0);
  return Math.ceil((d - today) / 86400000);
}
function hmSetText(id,value){ const el=document.getElementById(id); if(el) el.textContent=value; }
function renderHoneymoonStats(){
  hmEnsureData();
  const days = hmDaysUntil(data.honeymoon.depart);
  hmSetText('hm-stat-days', days == null ? '—' : Math.max(days,0));
  hmSetText('hm-stat-days-sub', days == null ? 'Add departure date' : (days > 0 ? 'Exciting days to go!' : (days === 0 ? 'Departure day!' : 'Trip date has passed')));
  const bookingFields = ['flightout','flightback','hotel','transport','insurance','confirm'];
  const completeBookings = bookingFields.filter(k=>String(data.honeymoon[k]||'').trim()).length;
  const transportRows = Array.isArray(data.honeyTransport) ? data.honeyTransport : [];
  const confirmedTransport = transportRows.filter(r=>['booked','confirmed','checked in','picked up','dropped off','complete'].includes(String(r.status||'').toLowerCase())).length;
  const bookingTotal = bookingFields.length + transportRows.length;
  const bookingDone = completeBookings + confirmedTransport;
  hmSetText('hm-stat-bookings', bookingDone);
  hmSetText('hm-stat-bookings-sub', bookingTotal ? Math.round((bookingDone/bookingTotal)*100) + '% of bookings' : 'Add bookings to begin');
  const totalAfter = data.nameChange.length;
  const doneAfter = data.nameChange.filter(r=>r.done || String(r.status||'').toLowerCase()==='complete').length;
  hmSetText('hm-stat-after', totalAfter);
  hmSetText('hm-stat-after-sub', totalAfter ? Math.round(doneAfter/totalAfter*100) + '% of tasks' : 'Load checklist to begin');
  const guests = Array.isArray(data.guests) ? data.guests : [];
  const thankTotal = guests.length;
  const thankDone = guests.filter(g=>g.thankyou).length;
  hmSetText('hm-stat-thanks', Math.max(0, thankTotal - thankDone));
  hmSetText('hm-stat-thanks-sub', thankTotal ? Math.round((thankDone/thankTotal)*100) + '% of total' : 'Based on guest tracker');
}
function hmIconUse(id){ return `<svg><use href="#${id}"></use></svg>`; }
function hmStatusSlug(v){ return String(v||'').toLowerCase().replace(/\s+/g,'-').replace(/[^a-z0-9-]/g,''); }
function hmSelect(options, selected, onchange, cls=''){
  const val = selected || options[0] || '';
  return `<select class="${cls} ${hmStatusSlug(val)}" onchange="${onchange}">${options.map(o=>`<option value="${escapeHtml(o)}" ${String(o)===String(val)?'selected':''}>${escapeHtml(o)}</option>`).join('')}</select>`;
}
function hmInput(value, placeholder, oninput, type='text'){
  return `<input type="${type}" value="${escapeHtml(value||'')}" placeholder="${escapeHtml(placeholder||'')}" oninput="${oninput}">`;
}
function hmTextarea(value, placeholder, oninput){
  return `<textarea class="cell-ta" placeholder="${escapeHtml(placeholder||'')}" oninput="${oninput}">${escapeHtml(value||'')}</textarea>`;
}
function hmNormalizeItinerary(r){
  r.day = r.day || '';
  r.time = r.time || '';
  r.plan = r.plan || '';
  r.location = r.location || '';
  r.status = r.status || 'Planned';
  r.confirmation = r.confirmation || '';
  r.notes = r.notes || '';
  return r;
}
function hmNormalizePacking(r){
  r.item = r.item || '';
  r.category = r.category || 'Travel';
  r.packed = !!r.packed;
  r.priority = r.priority || 'Medium';
  r.status = r.status || (r.packed ? 'Packed' : 'Not Packed');
  r.notes = r.notes || '';
  return r;
}
function hmNormalizeName(r){
  r.task = r.task || '';
  r.category = r.category || 'Legal';
  r.due = r.due || '';
  r.status = r.status || (r.done ? 'Complete' : 'Not Started');
  r.done = !!r.done;
  r.notes = r.notes || '';
  return r;
}
function hmNormalizeDetail(r){
  r.section = r.section || 'Travel Overview';
  r.item = r.item || '';
  r.timeline = r.timeline || '';
  r.vendor = r.vendor || '';
  r.status = r.status || 'Planned';
  r.reference = r.reference || '';
  r.notes = r.notes || '';
  return r;
}
