function packingDefaultCategory(item){ const s=String(item).toLowerCase(); if(s.includes('passport')||s.includes('document')||s.includes('id')) return 'Documents'; if(s.includes('charger')||s.includes('camera')||s.includes('adapter')||s.includes('phone')) return 'Tech'; if(s.includes('sunscreen')||s.includes('medication')||s.includes('toiletries')) return 'Health'; if(s.includes('swim')||s.includes('sunglasses')) return 'Beach / Pool'; if(s.includes('outfit')||s.includes('shoes')) return 'Clothing'; return 'Travel'; }
