function homecomingPresetCategory(task, category){
  const s = String(task || category || '').toLowerCase();
  if (s.includes('bank') || s.includes('joint account')) return 'Banking';
  if (s.includes('insurance')) return 'Insurance';
  if (s.includes('vehicle') || s.includes('registration')) return 'Vehicles';
  if (s.includes('mail') || s.includes('address')) return 'Address';
  if (s.includes('certificate') || s.includes('license') || s.includes('passport') || s.includes('social') || s.includes('driver')) return 'Documents';
  if (s.includes('thank-you')) return 'Thank-You Notes';
  if (s.includes('home')) return 'Home Setup';
  return HC_CATEGORIES.includes(category) ? category : 'Other';
}
