function uedTableFieldText(el){
  if(!el) return '';
  if(el.tagName === 'SELECT') return el.selectedOptions?.[0]?.textContent || el.value || '';
  return el.value || el.placeholder || '';
}
function uedAutosizeOneField(el){
  if(!el || el.type === 'checkbox' || el.type === 'radio') return;
  /* All planner tables use CSS width:100% cell fields; skip inline ch sizing. */
  if(el.closest && (el.closest('.cwp-table') || el.closest('#main table'))) {
    el.style.removeProperty('width');
    el.style.textAlign = 'left';
    return;
  }
  el.style.textAlign = 'left';
  const text = uedTableFieldText(el).replace(/\s+/g,' ');
  let min = el.type === 'date' ? 12 : el.tagName === 'SELECT' ? 10 : 5;
  if(el.classList.contains('payment-money') || /amount|cost|paid|due|balance|budget/i.test(el.getAttribute('aria-label') || el.placeholder || '')) min = Math.max(min,10);
  const ch = Math.max(min, Math.min(90, text.length + (el.tagName === 'SELECT' ? 4 : 2)));
  if(el.tagName === 'TEXTAREA'){
    el.style.width = Math.max(18, Math.min(90, text.length + 2)) + 'ch';
    return;
  }
  el.style.width = ch + 'ch';
}
function uedAutosizeTableFields(scope){
  const root = scope || document;
  uedProtectCountFields(root);
  root.querySelectorAll('table input, table select, table textarea').forEach(el => {
    if (el.closest && el.closest('.record-editor-small-table,.record-editor-inline-shell,.record-editor-overlay')) return;
    uedAutosizeOneField(el);
  });
  uedApplyTableHeaderColor(root);
  if(root.dataset && !root.dataset.uedAutosizeBound){
    root.dataset.uedAutosizeBound = '1';
    root.addEventListener('input', event => {
      if(event.target && event.target.matches('table input, table select, table textarea') && !event.target.closest('.record-editor-small-table,.record-editor-inline-shell,.record-editor-overlay')) uedAutosizeOneField(event.target);
    }, true);
    root.addEventListener('change', event => {
      if(event.target && event.target.matches('table input, table select, table textarea') && !event.target.closest('.record-editor-small-table,.record-editor-inline-shell,.record-editor-overlay')) uedAutosizeOneField(event.target);
    }, true);
  }
}
function uedProtectCountFields(scope){
  const root = scope || document;
  root.querySelectorAll('table input').forEach(el => {
    const sig = [el.id, el.name, el.placeholder, el.className, el.getAttribute('oninput'), el.getAttribute('aria-label')].join(' ').toLowerCase();
    if (!/\b(kid|kids|child|children|count|quantity|qty|headcount|table #|table number)\b/.test(sig)) return;
    if (/\b(cost|price|amount|budget|paid|payment|deposit|balance|quote|rate|actual|value|total|fee)\b/.test(sig)) return;
    el.classList.add('no-currency');
    el.dataset.currency = 'false';
    if (/^\s*[$]/.test(el.value || '')) {
      el.value = stripCurrencyDisplay(el.value);
    }
  });
}
function uedApplyTableHeaderColor(scope){
  const root = scope || document;
  root.querySelectorAll('table thead tr:not(.bulk-table-row)').forEach(row => {
    const table = row.closest('table');
    if (typeof isRecordEditorMiniTable === 'function' && isRecordEditorMiniTable(table)) return;
    /* Sourced from the redesign tokens, not from --forest directly. The table
       header is a SURFACE: it is --forest-deep in light and #1D2F27 in dark,
       with a --gold rule in light and #6B5738 in dark. Hard-coding forest here
       flattened the header in dark mode and put the wrong gold under it.
       These are written inline with !important, so no stylesheet can correct
       them — the values have to be right at the source. */
    row.style.setProperty('background-color', 'var(--table-header-bg)', 'important');
    Array.from(row.children || []).forEach(cell => {
      cell.style.setProperty('background-color', 'var(--table-header-bg)', 'important');
      cell.style.setProperty('background-image', 'none', 'important');
      cell.style.setProperty('color', 'var(--text-on-dark)', 'important');
      cell.style.setProperty('border-left', '0', 'important');
      cell.style.setProperty('border-right', '0', 'important');
      cell.style.setProperty('border-bottom', '1px solid var(--table-header-rule)', 'important');
      cell.querySelectorAll('*').forEach(child => {
        // Keep form controls (e.g. the Option A/B/C vendor dropdowns) readable — they
        // are white boxes with their own dark text; forcing them white here made the
        // native option popup white-on-white (invisible). Labels stay white.
        if (child.closest('select') || child.matches('select, input, textarea, option')) return;
        child.style.setProperty('color', 'var(--text-on-dark)', 'important');
      });
    });
  });
}
