function uedPaymentsDueCard(){
  const overdue = (typeof computeOverduePayments === 'function') ? computeOverduePayments() : [];
  const upcoming = (typeof computeUpcomingPayments === 'function') ? computeUpcomingPayments(30) : [];
  if (!overdue.length && !upcoming.length) return '';
  const fmtDate = d => { const dt = d ? new Date(String(d).length <= 10 ? d + 'T00:00:00' : d) : null; return (dt && !isNaN(dt.getTime())) ? dt.toLocaleDateString('en-US', { month:'short', day:'numeric' }) : ''; };
  const overdueTotal = overdue.reduce((s,p)=>s + p.balance, 0);
  const upcomingTotal = upcoming.reduce((s,p)=>s + p.balance, 0);
  const shownOverdue = overdue.slice(0, 6);
  const shownUpcoming = upcoming.slice(0, Math.max(0, 6 - shownOverdue.length));
  let rows = '';
  shownOverdue.forEach(p => { rows += `<li class="ued-due-row over"><span class="num">!</span><b>${uedEsc(p.vendor)}</b><time>${uedEsc(fmtDate(p.dueDate))} · ${uedMoney(p.balance)}</time></li>`; });
  shownUpcoming.forEach(p => { rows += `<li class="ued-due-row"><span class="num">·</span><b>${uedEsc(p.vendor)}</b><time>${uedEsc(fmtDate(p.dueDate))} · ${uedMoney(p.balance)}</time></li>`; });
  const tag = overdue.length ? `${overdue.length} overdue` : `${upcoming.length} due soon`;
  return `<section class="ued-panel span6 ued-payments-due">${uedCaption('card','Payments Due',tag)}
    <div class="ued-due-summary">
      ${overdue.length ? `<div class="ued-due-stat over"><b>${uedMoney(overdueTotal)}</b><span>Overdue (${overdue.length})</span></div>` : ''}
      <div class="ued-due-stat"><b>${uedMoney(upcomingTotal)}</b><span>Due in 30 days (${upcoming.length})</span></div>
    </div>
    <ul class="ued-list ued-due-list">${rows}</ul>
    <button class="ued-btn" style="margin-top:.75rem" onclick="showPanel('payments')">Open payments</button>
  </section>`;
}
function uedDashboardTimelineBlock(){
  const fmtT=t=>{ if(!t) return ''; const p=String(t).split(':'); if(p.length<2) return t; let h=+p[0]; const m=p[1]; if(isNaN(h)) return t; const ap=h>=12?'PM':'AM'; h=h%12||12; return h+':'+m+' '+ap; };
  const rows=safeArray(data.timeline).filter(e=>e.time||e.event).slice().sort((a,b)=>String(a.time||'').localeCompare(String(b.time||'')));
  const body=rows.length?rows.map(e=>`<li><span class="num">${uedEsc(fmtT(e.time)||'--')}</span><b>${uedEsc(e.event||'Event')}</b><small>${[e.location,e.responsible,e.duration].filter(Boolean).map(uedEsc).join(' · ')}</small></li>`).join(''):`<li><span class="num">01</span><b>No wedding-day events yet</b><small>Add your timeline to see it here.</small></li>`;
  return `<section class="ued-panel span12">${uedCaption('cal','Wedding-Day Timeline',rows.length?`${rows.length} events`:'') }<ul class="ued-list">${body}</ul><button class="ued-btn" style="margin-top:.85rem" onclick="showPanel('timeline')">Edit full timeline</button></section>`;
}
function uedCountdownParts(c){
  if(!c || c.diffDays === null || c.diffDays === undefined) return {months:'--',days:'--',hours:c?.hours||'--',minutes:c?.minutes||'--',seconds:c?.seconds||'--'};
  if(c.past) return {months:'0',days:'0',hours:c.hours||'00',minutes:c.minutes||'00',seconds:c.seconds||'00'};
  const totalDays=Math.max(0,Number(c.diffDays)||0);
  const months=Math.floor(totalDays/30);
  const days=totalDays%30;
  return {months:String(months).padStart(2,'0'),days:String(days).padStart(2,'0'),hours:c.hours,minutes:c.minutes,seconds:c.seconds};
}

function updateDashboardLiveCountdown(){
  const activePanel = document.body.getAttribute('data-active-panel');
  const dashboardVisible = document.getElementById('panel-dashboard')?.classList.contains('active');
  if (activePanel && activePanel !== 'dashboard' && !dashboardVisible) return;
  const c = dashboardCountdownState();
  const parts = uedCountdownParts(c);
  const set = (id, value) => { const el = document.getElementById(id); if (el) el.textContent = value; };
  set('dash-countdown-months', parts.months);
  set('dash-countdown-days', parts.days);
  set('dash-countdown-hours', parts.hours);
  set('dash-countdown-minutes', parts.minutes);
  set('dash-countdown-seconds', parts.seconds);
  set('dash-countdown-sub', c.past ? 'Wedding celebrated' : 'until your wedding celebration!');
  set('dash-days-remaining', c.diffDays === null ? '-' : (c.past ? '0' : String(c.diffDays)));
}

function animateEditorialDashboardNumber(el){
  if(!el || el.dataset.motionDone === '1' || /^dash-countdown-/.test(el.id || '')) return;
  const original = (el.textContent || '').trim();
  if(!original || original.includes('/') || /--|[A-Za-z]/.test(original.replace(/paid|due/ig,''))) return;
  const match = original.match(/-?\$?[\d,]+(?:\.\d+)?%?/);
  if(!match) return;
  const token = match[0];
  const numeric = Number(token.replace(/[$,%]/g,''));
  if(!Number.isFinite(numeric)) return;
  const prefix = original.slice(0, match.index) + (token.includes('$') ? '$' : '');
  const suffix = (token.includes('%') ? '%' : '') + original.slice((match.index || 0) + token.length);
  const decimals = /\.\d+/.test(token) ? token.split('.')[1].replace(/[^\d]/g,'').length : 0;
  const formatter = value => {
    const abs = Math.abs(value);
    const n = decimals ? abs.toFixed(decimals) : Math.round(abs).toLocaleString();
    return `${value < 0 ? '-' : ''}${prefix}${n}${suffix}`;
  };
  const start = performance.now();
  const duration = 850;
  el.dataset.motionDone = '1';
  const step = now => {
    const progress = Math.min(1, (now - start) / duration);
    const eased = 1 - Math.pow(1 - progress, 3);
    el.textContent = formatter(numeric * eased);
    if(progress < 1) requestAnimationFrame(step);
    else el.textContent = original;
  };
  requestAnimationFrame(step);
}
function activateEditorialDashboardMotion(){
  const root = document.getElementById('dash-v4-root');
  if(!root) return;
  root.classList.remove('ued-motion-ready');
  root.querySelectorAll('[data-motion-done]').forEach(el => delete el.dataset.motionDone);
  void root.offsetWidth;
  root.classList.add('ued-motion-ready');
  root.querySelectorAll('.ued-stat b, .ued-mini b').forEach(animateEditorialDashboardNumber);
}
function activateEditorialStatMotion(panelOrId, options = {}){
  const panel = typeof panelOrId === 'string' ? document.getElementById('panel-' + panelOrId) : panelOrId;
  if(!panel || !panel.querySelectorAll) return;
  const valueSelector = [
    '.m-stat-val',
    '.ued-stat > b',
    '.stat-val',
    '.stat-value',
    '.stat-number',
    '.metric-value',
    '.stat-tile-val',
    '.cs-value',
    '.es-value',
    '[class*="-stat-value"]',
    '[class*="-stat-val"]'
  ].join(',');
  const values = [...panel.querySelectorAll(valueSelector)].filter(el =>
    !el.closest('table, .m-mast-wrap, .ued-count-grid, .m-countdown-grid') &&
    !/^dash-countdown-/.test(el.id || '')
  );
  if(options.reset){
    panel.classList.remove('ued-stat-motion-ready');
    values.forEach(el => delete el.dataset.motionDone);
    void panel.offsetWidth;
  }
  panel.classList.add('ued-stat-motion-ready');
  values.forEach(animateEditorialDashboardNumber);
}

function setupFoundationProgress(){
  const s = data.setup || {};
  const items = [
    !!((s.bride||'').trim() && (s.groom||'').trim()),
    !!s.date,
    !!(s['venue-ceremony']||'').trim(),
    !!(s['venue-reception']||'').trim(),
    parseFloat(s.budget) > 0,
    parseInt(s.guests || '0', 10) > 0,
    !!(s.style||'').trim(),
    !!(s.timezone||'').trim(),
    !!(s.verse||'').trim(),
    !!(s.mission||'').trim(),
    !!s.photo
  ];
  const completed = items.filter(Boolean).length;
  const total = items.length;
  const pct = completed ? Math.max(8, Math.round(completed / total * 100)) : 0;
  return { completed, total, pct };
}
function dashFoundationMeterHTML(){
  const f = setupFoundationProgress();
  return `<div class="dash-foundation-meter app-card"><h4>Foundation</h4><div class="dfm-val">${f.completed} of ${f.total}</div><span class="ued-soft">Wedding Setup checklist</span><div class="dfm-track"><b class="dfm-fill" style="width:${f.pct}%"></b></div><button type="button" class="page-context-strip-link" style="margin-top:var(--space-3)" onclick="showPanel('setup')">Continue setup</button></div>`;
}
function dashAlertsStackHTML(guidance){
  const alerts = guidance.alerts.slice(0, 6);
  const kindLabel = { rsvp:'RSVP', budget:'Budget', vendor:'Vendors', legal:'Legal', backup:'Backup', general:'General' };
  const body = alerts.length ? alerts.map(a => `<button type="button" class="guide-alert${a.priority===1?' urgent':''}" onclick="${a.action || `showPanel('${a.page}')`}"><span class="guide-alert-icon">${a.priority===1?'!':'i'}</span><span><span class="guide-alert-title">${a.kind && kindLabel[a.kind] ? `<em class="attention-kind">${escapeHtml(kindLabel[a.kind])}</em> ` : ''}${escapeHtml(a.title)}</span><span class="guide-alert-note">${escapeHtml(a.note)}</span></span></button>`).join('') : `<div class="guide-alert"><span class="guide-alert-icon">✓</span><span><span class="guide-alert-title">All clear for now</span><span class="guide-alert-note">No urgent alerts — keep going with your next step.</span></span></div>`;
  return `<div id="dash-attention-hub" class="dash-alerts-stack app-card attention-hub"><div class="attention-hub-head"><h4>Needs attention</h4><span class="attention-hub-count">${guidance.attentionCount || 0} item${(guidance.attentionCount || 0) === 1 ? '' : 's'}</span></div>${body}</div>`;
}

/* ── Dashboard "Needs you" — action-first card built from real data ────────
   Surfaces the few things that actually need the couple (Pareto): overdue
   payments, guests with no meal, events this week, tasks due soon. Semantic
   dots (red = urgent/overdue, amber = soon) signal what and how urgent. */
function dashNeedsAttention(){
  var items=[];
  var today=new Date(); today.setHours(0,0,0,0);
  var d7=new Date(today); d7.setDate(today.getDate()+7);
  var d14=new Date(today); d14.setDate(today.getDate()+14);
  function toD(s){ if(!s) return null; var d=new Date(String(s).slice(0,10)+'T00:00:00'); return isNaN(d)?null:d; }
  try {
    var payments=safeArray(data.payments);
    var overdue=payments.filter(function(p){ if(/paid|complete/i.test(p.status||'')) return false; var d=toD(p.date||p.due); return d&&d<today; }).length;
    if(overdue>0) items.push({dot:'red', text:overdue+' payment'+(overdue===1?'':'s')+' overdue', sub:'Payments', panel:'payments', cta:'Review payments'});
  } catch(e){}
  try {
    var guests=safeArray(data.guests);
    var noMeal=guests.filter(function(g){ return /yes|accepted/i.test(g.rsvp||'') && !String(g.meal||'').trim(); }).length;
    if(noMeal>0) items.push({dot:'amber', text:noMeal+' guest'+(noMeal===1?'':'s')+' need a meal choice', sub:'Guest List', panel:'guests', cta:'Assign meals'});
  } catch(e){}
  try {
    var events=(typeof buildSmartCalendarEvents==='function')?buildSmartCalendarEvents():[];
    var t0=(typeof todayISO==='function')?todayISO():today.toISOString().slice(0,10);
    var t7s=d7.toISOString().slice(0,10);
    var week=events.filter(function(e){ return e.date && e.date>=t0 && e.date<=t7s; });
    if(week.length){ items.push({dot:'amber', text:(week[0].title||'An event')+' this week', sub:'Smart Calendar', panel:'calendar', cta:'Open calendar'}); }
  } catch(e){}
  try {
    var tasks=safeArray(data.tasks).filter(function(t){ if(/complete/i.test(t.status||'')) return false; var d=toD(t.date); return d&&d<=d14; });
    if(tasks.length){ var anyOver=tasks.some(function(t){ var d=toD(t.date); return d&&d<today; }); items.push({dot:anyOver?'red':'amber', text:tasks.length+' task'+(tasks.length===1?'':'s')+' due soon', sub:'Planning Timeline', panel:'tasks', cta:'View tasks'}); }
  } catch(e){}
  return items;
}
function dashNeedsAttentionHTML(){
  var items=dashNeedsAttention();
  var dc={red:'#c0392b', amber:'#c9962b', green:'#2f7050'};
  if(!items.length){
    return '<article class="ued-panel dash-needs" data-dash-card="needs-attention"><div class="dash-needs-head">'+(typeof uedIcon==='function'?uedIcon('shield'):'')+'<span>Needs you</span></div><div class="dash-needs-empty">'+(typeof uedIcon==='function'?uedIcon('check'):'✓')+' You’re all caught up</div></article>';
  }
  var primary=items[0];
  var rows=items.slice(0,4).map(function(it){
    return '<button type="button" class="dash-needs-row" onclick="showPanel(\''+it.panel+'\')" aria-label="'+uedEsc(it.text)+'"><span class="dash-needs-dot" style="background:'+(dc[it.dot]||dc.amber)+'"></span><span class="dash-needs-text"><b>'+uedEsc(it.text)+'</b><em>'+uedEsc(it.sub)+'</em></span><span class="dash-needs-chev" aria-hidden="true">›</span></button>';
  }).join('');
  return '<article class="ued-panel dash-needs" data-dash-card="needs-attention"><div class="dash-needs-head">'+(typeof uedIcon==='function'?uedIcon('shield'):'')+'<span>Needs you</span></div><div class="dash-needs-list">'+rows+'</div><button type="button" class="dash-needs-cta" onclick="showPanel(\''+primary.panel+'\')">'+uedEsc(primary.cta)+' →</button></article>';
}
function renderDashboard() {
  if(typeof syncCateringToBudget==='function') syncCateringToBudget();
  if(typeof syncPaymentsToBudget==='function') syncPaymentsToBudget();
  if(typeof syncWeddingWeekendToBudget==='function') syncWeddingWeekendToBudget();
  const panel=document.getElementById('panel-dashboard');
  const root=document.getElementById('dash-v4-root');
  if(!panel || !root) return;
  if (typeof uxRestorePanelDom === 'function') uxRestorePanelDom('dashboard');
  panel.classList.add('ued-scope');
  const totalBudget=parseFloat(data.setup.budget)||0;
  const totalSpent=typeof budgetTotalActual==='function'?budgetTotalActual():0;
  const remaining=totalBudget-totalSpent;
  const guests=safeArray(data.guests);
  const guestHeadTotal=typeof guestAdults==='function'?guestAdults()+guestKids():guests.length;
  const guestHeadYes=typeof guestAdults==='function'?guestAdults(g=>g.rsvp==='Yes'||g.rsvp==='Accepted')+guestKids(g=>g.rsvp==='Yes'||g.rsvp==='Accepted'):guests.filter(g=>g.rsvp==='Yes'||g.rsvp==='Accepted').length;
  const tasks=safeArray(data.tasks);
  const done=tasks.filter(t=>t.status==='Complete').length;
  const inProgress=tasks.filter(t=>t.status==='In Progress').length;
  const taskPct=tasks.length?Math.round(done/tasks.length*100):0;
  const planningPct=tasks.length?Math.round(((done+inProgress*.45)/tasks.length)*100):0;
  const rsvpAnswered=guests.filter(g=>g.rsvp && g.rsvp!=='Pending').length;
  const rsvpPct=guests.length?Math.round(rsvpAnswered/guests.length*100):0;
  const payments=safeArray(data.payments);
  const paidPayments=payments.filter(p=>/paid/i.test(p.status||'')).length;
  const paymentPct=payments.length?Math.round(paidPayments/payments.length*100):0;
  const budgetPct=totalBudget?Math.min(100,Math.round(totalSpent/totalBudget*100)):0;
  const bride=data.setup.bride||'', groom=data.setup.groom||'';
  const couple=bride&&groom?`${uedEsc(bride)} &amp; ${uedEsc(groom)}`:'Your Covenant Celebration';
  const weddingDate=typeof dashboardFormatWeddingDate==='function'?dashboardFormatWeddingDate():(data.setup.date||'Add wedding date');
  const venue=data.setup['venue-ceremony']||data.setup.church||'Add ceremony venue';
  const countdown=dashboardCountdownState();
  const parts=uedCountdownParts(countdown);
  const spelledWeddingDate=(function(){
    try{
      const iso=data.setup.date; if(!iso) return weddingDate;
      const d=new Date(String(iso).slice(0,10)+'T00:00:00'); if(isNaN(d.getTime())) return weddingDate;
      const ord=['','first','second','third','fourth','fifth','sixth','seventh','eighth','ninth','tenth','eleventh','twelfth','thirteenth','fourteenth','fifteenth','sixteenth','seventeenth','eighteenth','nineteenth','twentieth','twenty-first','twenty-second','twenty-third','twenty-fourth','twenty-fifth','twenty-sixth','twenty-seventh','twenty-eighth','twenty-ninth','thirtieth','thirty-first'];
      const months=['January','February','March','April','May','June','July','August','September','October','November','December'];
      return 'The '+ord[d.getDate()]+' of '+months[d.getMonth()]+', '+d.getFullYear();
    }catch(e){ return weddingDate; }
  })();
  const events=typeof buildSmartCalendarEvents==='function'?buildSmartCalendarEvents():[];
  const today=typeof todayISO==='function'?todayISO():new Date().toISOString().slice(0,10);
  const upcoming=events.filter(e=>e.date&&e.date>=today).sort((a,b)=>String(a.date).localeCompare(String(b.date))).slice(0,5);
  const nextHtml=upcoming.length?upcoming.map((e,i)=>`<li><span class="num">${String(i+1).padStart(2,'0')}</span><b>${uedEsc(e.title||'Event')}</b><time>${uedEsc(e.date||'')}</time></li>`).join(''):`<li><span class="num">01</span><b>No upcoming items yet</b><small>Add tasks, payments, or appointments</small></li>`;
  const budgetCats=safeArray(data.budget).map((c,i)=>({name:c.cat||`Category ${i+1}`,spent:typeof catSpent==='function'?catSpent(c):0,planned:typeof catPlanned==='function'?catPlanned(c):0}));
  const maxSpent=Math.max(1,...budgetCats.map(c=>c.spent));
  const budgetBars=budgetCats.length?budgetCats.map(c=>`<div class="ued-bar"><span class="ued-bar-name">${uedEsc(c.name)}</span><span class="ued-bar-track"><b class="ued-bar-fill" style="width:${c.spent?Math.max(3,Math.round(c.spent/maxSpent*100)):0}%"></b></span><span class="ued-bar-val">${uedMoney(c.spent)}</span></div>`).join(''):`<div class="ued-soft">No budget categories yet.</div>`;
  const budgetBarsVertical=budgetCats.length?`<div class="ued-vbars">${budgetCats.map((c,i)=>{const pct=c.planned?Math.round(c.spent/c.planned*100):0;const over=c.planned&&c.spent>c.planned;return `<button type="button" class="ued-vbar${over?' over':''}" onclick="dashBudgetBarClick(${i})" title="${uedEsc(c.name)} — ${uedMoney(c.spent)} spent${c.planned?` of ${uedMoney(c.planned)} planned (${pct}%)`:''}"><div class="ued-vbar-val">${uedMoney(c.spent)}</div><div class="ued-vbar-track"><b class="ued-vbar-fill" style="height:${c.spent?Math.max(3,Math.round(c.spent/maxSpent*100)):0}%"></b></div><div class="ued-vbar-name">${uedEsc(c.name)}</div></button>`;}).join('')}</div>`:`<div class="ued-soft">No budget categories yet.</div>`;
  const pctOf=(n,d)=>d>0?Math.round((Number(n)||0)/(Number(d)||0)*100):0;
  const gYes=guests.filter(g=>g.rsvp==='Yes'||g.rsvp==='Accepted').length;
  const gNo=guests.filter(g=>g.rsvp==='No'||g.rsvp==='Declined').length;
  const gPend=guests.filter(g=>!g.rsvp||g.rsvp==='Pending').length;
  const gMaybe=guests.filter(g=>g.rsvp==='Maybe').length;
  const gTot=guests.length||1;
  const rsvpBreakdown=[
    {label:'Attending',count:gYes,pct:pctOf(gYes,gTot),color:'var(--ued-forest)'},
    {label:'Declined',count:gNo,pct:pctOf(gNo,gTot),color:'var(--ued-danger)'},
    {label:'Pending',count:gPend,pct:pctOf(gPend,gTot),color:'var(--ued-gold)'},
    {label:'Maybe',count:gMaybe,pct:pctOf(gMaybe,gTot),color:'var(--ued-line2)'}
  ];
  let pPaid=0,pPend=0,pOver=0;
  payments.forEach(p=>{ const s=String(p.status||'').toLowerCase(); if(/paid|complete/.test(s)) pPaid++; else if(/overdue|late/.test(s)) pOver++; else pPend++; });
  const pTot=payments.length||1;
  const paymentBreakdown=[
    {label:'Paid',count:pPaid,pct:pctOf(pPaid,pTot),color:'var(--ued-forest)'},
    {label:'Pending',count:pPend,pct:pctOf(pPend,pTot),color:'var(--ued-gold)'},
    {label:'Overdue',count:pOver,pct:pctOf(pOver,pTot),color:'var(--ued-danger)'}
  ];
  const vendors=safeArray(data.vendors);
  const vTot=vendors.length||1;
  const vPaid=vendors.filter(v=>/paid|complete/i.test(v.status||'')).length;
  const vBooked=vendors.filter(v=>/^booked$/i.test(v.status||'')||(/booked/i.test(v.status||'')&&!/paid/i.test(v.status||''))).length;
  const vContact=vendors.filter(v=>/contact|quote|meeting|considering|tasting/i.test(v.status||'')).length;
  const vResearch=Math.max(0,vendors.length-vPaid-vBooked-vContact);
  const vendorBreakdown=[
    {label:'Researching',count:vResearch,pct:pctOf(vResearch,vTot),color:'var(--ued-line2)'},
    {label:'Contacted',count:vContact,pct:pctOf(vContact,vTot),color:'var(--ued-gold)'},
    {label:'Booked',count:vBooked,pct:pctOf(vBooked,vTot),color:'var(--ued-forest)'},
    {label:'Paid in full',count:vPaid,pct:pctOf(vPaid,vTot),color:'var(--ued-forest-deep)'}
  ];
  const guidance = typeof plannerGuidanceState === 'function' ? plannerGuidanceState() : { alerts: [], attentionCount: 0 };
  root.innerHTML=`<div class="ued-page">

    <div data-dash-card="essentials-hub">${renderEssentialsHubCard(true)}</div>
    <div data-dash-card="data-hub">${dashDataHubCardHTML()}</div>
    <div data-dash-card="countdown">
    <section class="dash-hero">
      <div class="dash-hero-count">
        <p class="cdc-eyebrow">Until we say “I do”</p>
        <div class="cdc-tiles">
          <div class="cdc-tile"><b id="dash-countdown-months">${uedEsc(parts.months)}</b><span>Months</span></div>
          <div class="cdc-tile"><b id="dash-countdown-days">${uedEsc(parts.days)}</b><span>Days</span></div>
          <div class="cdc-tile"><b id="dash-countdown-hours">${uedEsc(parts.hours)}</b><span>Hours</span></div>
          <div class="cdc-tile"><b id="dash-countdown-minutes">${uedEsc(parts.minutes)}</b><span>Minutes</span></div>
          <div class="cdc-tile"><b id="dash-countdown-seconds">${uedEsc(parts.seconds)}</b><span>Seconds</span></div>
        </div>
        <div class="cdc-sub" id="dash-countdown-sub">${countdown.past?'Wedding celebrated':'until your wedding celebration!'}</div>
      </div>
      <div class="dash-hero-meta">
        <div class="dash-hero-kicker">Together in covenant</div>
        <div class="dash-hero-couple">${bride&&groom?`${uedEsc(bride)}<br><span class="dash-hero-and">and</span> ${uedEsc(groom)}`:couple}</div>
        <div class="dash-hero-flourish"><span></span><i></i><span></span></div>
        <div class="dash-hero-date">${uedEsc(spelledWeddingDate)}</div>
        <div class="dash-hero-venue">${uedEsc(venue)}</div>
      </div>
    </section>
    </div>
    <section class="ued-band" style="--ued-band-cols:5" data-dash-card="stats-band">${uedStat(uedMoney(remaining),'Budget left',`${budgetPct}% used`,remaining<0)}${uedStat(`${guestHeadYes} / ${guestHeadTotal}`,'Attending',`${rsvpPct}% RSVPs in`)}${uedStat(`${taskPct}%`,'Tasks',`${done} of ${tasks.length} complete`)}${uedStat(payments.length,'Payments',`${paymentPct}% paid`)}${uedStat(safeArray(data.vendors).length,'Vendors','Tracked')}</section>
    <article class="ued-panel dash-progress-dominant" data-dash-card="planning-progress">${uedCaption('bars','Planning Progress')}<div class="ued-progress">${uedProgressRow('Overall',planningPct)}${uedProgressRow('Budget used',budgetPct)}${uedProgressRow('Guest RSVPs',rsvpPct)}${uedProgressRow('Payments paid',paymentPct)}</div></article>
    ${dashNeedsAttentionHTML()}
    <section class="ued-grid dash-priority-row">
      <div data-dash-card="setup-checklist">${typeof renderSetupChecklistCard==='function'?renderSetupChecklistCard(true):dashFoundationMeterHTML()}</div>
      <article class="ued-panel span12" data-dash-card="true-total">${trueTotalBannerHTML(true)}</article>
    </section>
    <div data-dash-card="pinned-strip">${typeof renderPinnedStrip==='function'?renderPinnedStrip():''}</div>
    <section class="ued-grid">
      <article class="ued-panel span4" data-dash-card="next-up">${uedCaption('flag','Next Up')}<ul class="ued-list">${nextHtml}</ul></article>
      ${uedBreakdownCard('users','RSVP Status',rsvpPct,'RSVPs in',rsvpBreakdown,'rsvp-breakdown')}
      ${uedBreakdownCard('coin','Payments',paymentPct,'Paid',paymentBreakdown,'payments-breakdown')}
      ${uedBreakdownCard('briefcase','Vendor Booking',pctOf(vBooked+vPaid,vTot),'Booked',vendorBreakdown,'vendor-breakdown')}
      <div data-dash-card="payments-due">${uedPaymentsDueCard()}</div>
      <article class="ued-panel span6" data-dash-card="data-health">${uedCaption('shield','Data Health')}<ul class="ued-list">${uedDataHealthList(4)}</ul></article>
      ${typeof uxPlanningHealthDigest==='function'?uxPlanningHealthDigest(5):''}
      <div data-dash-card="share-readiness">${uedShareReadinessCard()}</div>
      <article class="ued-panel span12" data-dash-card="budget-snapshot">${uedCaption('book','Budget Snapshot')}${budgetBarsVertical}</article>
      <div data-dash-card="section-progress">${uedDashboardSectionProgress()}</div>
      <article class="ued-panel span12" data-dash-card="budget-by-category-bars">${uedCaption('bars','Budget by Category',budgetCats.length?`${budgetCats.length} categories`:'')}<div class="ued-bars">${budgetBars}</div></article>
      <div data-dash-card="guidance-blocks">${uedDashboardGuidanceBlocks()}</div>
      <div data-dash-card="timeline-block">${uedDashboardTimelineBlock()}</div>
      <section class="ued-panel span12" style="text-align:center" data-dash-card="covenant-encouragement">${uedCaption('heart','Covenant Encouragement')}<div class="ued-soft" style="font-family:var(--font-serif,Georgia,serif);font-size:1.1rem"><i>Let all that you do be done in love.</i> — 1 Corinthians 16:14</div></section>
    </section>
    <div id="nav-metric-tip" class="nav-metric-tip-wrap" hidden></div>
    <section class="ued-info" data-dash-card="couple-info"><div class="ued-info-cell"><div class="ued-info-k">Couple</div><div class="ued-info-v">${couple}</div></div><div class="ued-info-cell"><div class="ued-info-k">Wedding date</div><div class="ued-info-v">${uedEsc(weddingDate)}</div></div><div class="ued-info-cell"><div class="ued-info-k">Ceremony venue</div><div class="ued-info-v">${uedEsc(venue)}</div></div><div class="ued-info-cell"><div class="ued-info-k">Budget</div><div class="ued-info-v">${uedMoney(totalBudget)}</div></div></section>
  </div>`;
  applyDashboardCardLayout(root.querySelector('.ued-page'));
  if (typeof renderNavMetricGetStartedTip === 'function') renderNavMetricGetStartedTip();
  startDashboardLiveCountdown();
  if (typeof updateTopbarNotificationsBell === 'function') updateTopbarNotificationsBell();
  if (typeof checkMilestoneCelebrations === 'function') checkMilestoneCelebrations();
  requestAnimationFrame(activateEditorialDashboardMotion);
  if(typeof renderHeroPhoto === 'function') renderHeroPhoto();
}

/* ── Guests redesign shell (3b · Tasks / Appointments pattern · redesign-step12a) ─ */
window._guestUiFilters = window._guestUiFilters || { side:'all', rsvp:'all', table:'all', dietary:'all', event:'all', q:'' };
window._guestRailView = window._guestRailView || 'all';
window._guestRailGroupBy = window._guestRailGroupBy || 'side';
let _guestSortName = 'asc';
let _guestCardPage = 0;

function guestRailView(){
  if (typeof getSavedView === 'function') return getSavedView('guests', window._guestRailView || 'all');
  return window._guestRailView || 'all';
}
function guestRailGroupByMode(){
  if (typeof getSavedView === 'function') return getSavedView('guestsGroupBy', window._guestRailGroupBy || 'side');
  return window._guestRailGroupBy || 'side';
}
function guestHasAddress(g){
  return !!(String(g && (g.address1 || g.address) || '').trim() ||
    String(g && g.city || '').trim() ||
    String(g && g.zip || '').trim());
}
function guestIsSeated(g){
  return !!(typeof tableMatchKey === 'function' ? tableMatchKey(g && g.table) : String(g && g.table || '').trim());
}
function guestIsAccepted(g){ return /yes|accepted/i.test(String(g && g.rsvp || '')); }
function guestIsDeclined(g){ return /no|declined|regret/i.test(String(g && g.rsvp || '')); }
function guestIsPendingRsvp(g){
  if (typeof guestRsvpPending === 'function') return guestRsvpPending(g);
  return !String(g && g.rsvp || '').trim() || /pending/i.test(String(g && g.rsvp || ''));
}
function guestNeedsMeal(g){
  return guestIsAccepted(g) && !String(g && g.meal || '').trim();
}
function guestMatchesRailView(g, view){
  const v = view || 'all';
  if (v === 'all') return true;
  if (v === 'unconfirmed' || v === 'pending') return guestIsPendingRsvp(g);
  if (v === 'no-meal') return guestNeedsMeal(g);
  if (v === 'not-invited') return !(g.invited || (typeof guestIsInvited === 'function' && guestIsInvited(g)));
  if (v === 'needs-address') return !guestHasAddress(g);
  if (v === 'unseated') return !guestIsSeated(g);
  if (v === 'thankyou-pending') {
    if (g.thankyou === false) return true;
    const gifts = typeof safeArray === 'function' ? safeArray(data.gifts) : (data.gifts || []);
    const name = String(g.name || '').toLowerCase();
    const hh = String(g.household || '').toLowerCase();
    return gifts.some(gift => {
      if (gift.thankyou) return false;
      const from = String(gift.from || '').toLowerCase();
      return from && (from === name || from === hh || (name && from.includes(name)) || (hh && from.includes(hh)));
    });
  }
  if (v === 'side-bride') return String(g.side || '') === 'Bride';
  if (v === 'side-groom') return String(g.side || '') === 'Groom';
  if (v === 'side-both') {
    const s = String(g.side || 'Both');
    return s === 'Both' || s === 'Family' || !g.side;
  }
  return true;
}
function guestContactHint(g){
  if (String(g && g.email || '').trim()) return 'Email ✓';
  if (String(g && g.phone || '').trim()) return 'Phone ✓';
  if (!guestHasAddress(g)) return 'No address';
  return '—';
}
function guestNameSubline(g){
  const role = String(g && g.role || '');
  if (/child|kid|infant|minor/i.test(role)) return '· child';
  if (/plus.?one|guest of/i.test(role)) return role;
  const notes = String(g && g.notes || '');
  const m = notes.match(/plus\s*one\s+of\s+([^.\n]+)/i);
  if (m) return 'Plus one of ' + m[1].trim();
  if (g && g.plusoneHost) return 'Plus one of ' + g.plusoneHost;
  return '';
}
function guestRsvpPillHtml(rsvp){
  const v = rsvp || 'Pending';
  const scheme = (/yes|accept/i.test(v) ? 'green'
    : /no|declin|regret/i.test(v) ? 'red'
    : /not invited/i.test(v) ? 'neutral'
    : 'amber');
  if (typeof pill === 'function') {
    try { return pill(v, 'rsvp-' + scheme); } catch (e) { /* fall through */ }
  }
  return `<span class="status-pill" data-pillscheme="${scheme}">${escapeHtml(v)}</span>`;
}
function guestDisplayRsvp(g){
  if (!(g.invited || (typeof guestIsInvited === 'function' && guestIsInvited(g))) && guestIsPendingRsvp(g)) {
    return 'Not invited';
  }
  return g.rsvp || 'Pending';
}
function guestTableLabelShort(table){
  const t = String(table || '').trim();
  if (!t) return '—';
  if (/^t?\d+$/i.test(t)) return 'T' + t.replace(/^t/i, '');
  if (/^table\s*/i.test(t)) return t.replace(/^table\s*/i, 'T');
  return t;
}
function guestRowGroupMeta(row){
  const mode = guestRailGroupByMode();
  if (mode === 'side') {
    const side = String(row && row.side || '').trim() || 'Both';
    const sideTitle = /bride/i.test(side) ? 'Bride’s side'
      : /groom/i.test(side) ? 'Groom’s side'
      : (side === 'Both' ? 'Both sides' : side);
    return {
      key: 'side:' + side.toLowerCase(),
      residual: false,
      sort: side.toLowerCase() === 'bride' ? '0' : side.toLowerCase() === 'groom' ? '1' : '2',
      title: sideTitle,
      sideRaw: side,
      why: ''
    };
  }
  if (mode === 'rsvp') {
    const rsvp = String(row && row.rsvp || '').trim() || 'Pending';
    return {
      key: 'rsvp:' + rsvp.toLowerCase(),
      residual: false,
      sort: /pending/i.test(rsvp) ? '1' : /accept|yes/i.test(rsvp) ? '0' : /declin|no/i.test(rsvp) ? '2' : '3',
      title: rsvp,
      why: ''
    };
  }
  if (mode === 'table') {
    const table = String(row && row.table || '').trim();
    if (!table) {
      return {
        key: '__unseated__',
        residual: true,
        sort: '\uffff',
        title: 'Unseated',
        why: 'no table assigned'
      };
    }
    const label = typeof tableLabel === 'function' ? tableLabel(table) : table;
    return {
      key: 'table:' + (typeof tableMatchKey === 'function' ? tableMatchKey(table) : table.toLowerCase()),
      residual: false,
      sort: String(label).toLowerCase(),
      title: label,
      why: ''
    };
  }
  if (mode === 'group') {
    const group = String(row && row.group || '').trim();
    if (!group) {
      return {
        key: '__ungrouped__',
        residual: true,
        sort: '\uffff',
        title: 'Ungrouped',
        why: 'no group set'
      };
    }
    return {
      key: 'group:' + group.toLowerCase(),
      residual: false,
      sort: group.toLowerCase(),
      title: group,
      why: ''
    };
  }
  /* Default: household (mock 3b) */
  const hh = String(row && row.household || '').trim();
  if (!hh) {
    return {
      key: '__no_household__',
      residual: true,
      sort: '\uffff',
      title: 'No household',
      why: 'no household set'
    };
  }
  const title = /household$/i.test(hh) ? hh : (hh + ' household');
  return {
    key: 'hh:' + hh.toLowerCase(),
    residual: false,
    sort: hh.toLowerCase(),
    title: title,
    why: ''
  };
}
function guestGroupHeaderLabel(meta, groupRows){
  const items = groupRows || [];
  const n = items.length;
  const guestWord = n === 1 ? '1 guest' : (n + ' guests');
  if (meta && meta.residual) {
    return (meta.title || 'Unassigned') + ' · ' + guestWord + ' · ' + (meta.why || 'unassigned');
  }
  const mode = guestRailGroupByMode();
  const rows = items.map(it => (it && it.r != null ? it.r : it));
  const pending = rows.filter(g => guestIsPendingRsvp(g)).length;
  const accepted = rows.filter(g => guestIsAccepted(g)).length;
  const notInvited = rows.filter(g => !(g.invited || (typeof guestIsInvited === 'function' && guestIsInvited(g)))).length;
  const title = (meta && meta.title) || 'Group';
  if (mode === 'rsvp') return title + ' · ' + guestWord;
  /* Mock 21a group banners: Bride's side · 64 guests · 41 accepted · 6 not invited */
  if (mode === 'side') {
    return title + ' · ' + guestWord
      + ' · ' + accepted + ' accepted'
      + (notInvited ? (' · ' + notInvited + ' not invited') : '');
  }
  if (mode === 'table' || mode === 'group') {
    return title + ' · ' + guestWord + (pending ? (' · ' + pending + ' pending') : '');
  }
  if (pending && pending === n && accepted === 0) {
    if (notInvited === n) return title + ' · ' + guestWord + ' · not invited yet';
  }
  if (pending) return title + ' · ' + guestWord + ' · ' + pending + ' pending';
  if (accepted === n && n) return title + ' · ' + guestWord + ' · all accepted';
  return title + ' · ' + guestWord;
}

