  function arrOf(e){ const d=ENTITIES[e]; if(!d) return []; let a=d.array(); return Array.isArray(a)?a:[]; }
  function ensureIds(e){ arrOf(e).forEach(r=>{ if(!r._id){ if(typeof ensureRowId==='function'){ try{ ensureRowId(r,e); }catch(_){} } if(!r._id) r._id=newId(e); } }); }
  function newId(e){ if(typeof nextRecordId==='function'){ try{ return nextRecordId(e); }catch(_){} }
    return (ENTITIES[e]&&ENTITIES[e].prefix||'REC')+'-'+Date.now().toString(36); }
  const DB = {
    all:(e)=>arrOf(e),
    get:(e,id)=>arrOf(e).find(r=>String(r._id)===String(id))||null,
    where:(e,fn)=>arrOf(e).filter(fn),
    label:(e,id)=>{ const r=DB.get(e,id); return r?(r[ENTITIES[e].labelField]||''):''; },
    add:(e,rec)=>{ rec=rec||{}; rec._id=rec._id||newId(e); arrOf(e).push(rec); saveAll(); return rec; },
    remove:(e,id)=>{ const a=arrOf(e); const i=a.findIndex(r=>String(r._id)===String(id)); if(i>-1){ a.splice(i,1); saveAll(); } }
  };

  /* ---------- options + status color ---------- */
  const OPTIONS = {
    counselingStatus:['Not Started','Scheduled','Completed'],
    shotPriority:['Must-Have','Important','Optional'],
    partyRole:['Maid of Honor','Matron of Honor','Bridesmaid','Junior Bridesmaid','Best Man','Groomsman','Usher','Flower Girl','Ring Bearer','Honor Attendant','Reader','Officiant Assistant'],
    partyStatus:['Dress Ordered','Dress Ready','Tux Confirmed','Fitting Scheduled','Tux Fitting','Outfit Ready','Needs Follow-Up','Not Started'],
    vendorStatus:(typeof VENDOR_STATUS!=='undefined'?VENDOR_STATUS:['Researching','Contacted','Quote Received','Considering','Meeting Scheduled','Tasting Scheduled','Booked','Paid','Complete','Not Booked']),
    giftCategory:(typeof GIFT_CATEGORIES!=='undefined'?GIFT_CATEGORIES:['Registry','Cash','Gift Card','Handmade','Other'])
  };
  function statusColor(v){
    const s=String(v||'').toLowerCase();
    if(/cancel|declin/.test(s)) return 'redmuted';
    if(/must[- ]?have/.test(s)) return 'red';
    if(/overdue|missing|follow/.test(s)) return 'red';
    if(/complete|paid|confirm|booked|packed|\bdone\b|signed|sent/.test(s)) return 'green';
    if(/\bin progress\b|progressing/.test(s)) return 'blue';
    if(/important|partial|schedul|\bdue\b|payment due/.test(s)) return 'gold';
    if(/optional|flexible|tentative/.test(s)) return 'blue';
    return 'gray';
  }

