  window.cwpBulkEdit=(key)=>{ const s=st(key), d=TABLES[key]; const id=[...s.sel][0]; if(!id) return; if(typeof d.editFn==='function'){ const r=DB.get(d.entity,id); if(r){ d.editFn(r); return; } } window.cwpOpenEditor(d.entity,id); };
  window.cwpSelectedCount=(key)=>st(key).sel.size;
  window.cwpSelectedIds=(key)=>[...st(key).sel];
  window.cwpOpenEditor=(entity,id)=>{ if(typeof openRecordEditor==='function'){ const i=indexOf(entity,id); if(i>-1) openRecordEditor(entity,i); } else { openEditor(entity,id); } };
  window.cwpCloseEditor=()=>{ const o=document.getElementById('cwp-modal'); if(o) o.hidden=true; };
  window.cwpEditorSave=(addAnother)=>{ readEditor(); const key=EDITOR.key, d=TABLES[key]; renderRows(key); if(addAnother){ const rec=DB.add(d.entity, d.newRecord?d.newRecord():{}); renderRows(key); openEditor(d.entity, rec._id); } else { cwpCloseEditor(); } if(typeof afterCwpChange==='function') afterCwpChange(d.entity); };
  window.cwpEditorDelete=async ()=>{ const d=TABLES[EDITOR.key]; if(!(await covConfirm('Delete this '+(ENTITIES[EDITOR.entity].label||'record').toLowerCase()+'?', {title:'Delete record?', danger:true, okText:'Delete'}))) return; DB.remove(EDITOR.entity,EDITOR.id); renderRows(EDITOR.key); cwpCloseEditor(); };
