/* ============================================================
   FIELD PICKER — reusable option dropdown (replaces native <datalist>)
   Always shows the full option list on focus, filters as you type,
   click to insert. multi:true appends (comma-separated) so several
   values can be chosen. Used for relational option fields that pull
   choices from another table (Assigned To, Vendor, etc.).
   ============================================================ */
var _fpState = { input:null, options:[], multi:false, getOptions:null };
function _fpOutside(ev){
  var p = document.getElementById('field-picker-pop');
  if(p && !p.contains(ev.target) && ev.target !== _fpState.input) closeFieldPicker();
}
function closeFieldPicker(){
  var p = document.getElementById('field-picker-pop'); if(p) p.remove();
  document.removeEventListener('mousedown', _fpOutside, true);
  _fpState.input = null;
}
function openFieldPicker(input, getOptions, cfg){
  cfg = cfg || {};
  var multi = !!cfg.multi;
  var options = (typeof getOptions === 'function') ? (getOptions() || []) : (getOptions || []);
  _fpState = { input:input, options:options, multi:multi, getOptions:getOptions };
  var val = input.value || '';
  var seg = multi ? (val.split(',').pop().trim()) : val.trim();
  var q = seg.toLowerCase();
  var list = q ? options.filter(function(o){ return String(o).toLowerCase().indexOf(q) !== -1; }) : options.slice();
  if(!list.length && q) list = options.slice(); // if nothing matches the segment, still show everything
  var pop = document.getElementById('field-picker-pop');
  if(!pop){
    pop = document.createElement('div'); pop.id = 'field-picker-pop'; pop.className = 'field-picker-pop';
    document.body.appendChild(pop);
    setTimeout(function(){ document.addEventListener('mousedown', _fpOutside, true); }, 0);
  }
  pop.innerHTML = list.length
    ? list.map(function(o){ return '<div class="fpick-item" data-val="'+escapeHtml(o)+'">'+escapeHtml(o)+'</div>'; }).join('')
    : '<div class="fpick-empty">No options</div>';
  Array.prototype.forEach.call(pop.querySelectorAll('.fpick-item'), function(it){
    it.addEventListener('mousedown', function(ev){ ev.preventDefault(); pickFieldOption(it.getAttribute('data-val')); });
  });
  var r = input.getBoundingClientRect();
  var minW = Math.max(180, r.width);
  if (typeof window.rdAnchorToButton === 'function') {
    window.rdAnchorToButton(pop, input, { minWidth: minW, gap: 2, zIndex: 2147483600 });
  } else {
    pop.style.position = 'fixed';
    pop.style.display = 'inline-block';
    pop.style.width = 'max-content';
    pop.style.minWidth = minW + 'px';
    pop.style.top = (r.bottom + 2) + 'px';
    pop.style.left = Math.max(8, Math.min(r.left, window.innerWidth - minW - 8)) + 'px';
  }
}
function pickFieldOption(val){
  var s = _fpState, input = s.input; if(!input) return;
  if(s.multi){
    var parts = input.value.split(',').map(function(x){ return x.trim(); }).filter(Boolean);
    parts.pop(); // drop the partial segment being typed
    if(parts.indexOf(val) === -1) parts.push(val);
    input.value = parts.join(', ') + ', ';
  } else {
    input.value = val;
  }
  input.dispatchEvent(new Event('input', { bubbles:true })); // fire the field's existing oninput (updateTask etc.)
  input.focus();
  if(s.multi){ openFieldPicker(input, s.getOptions, { multi:true }); } else { closeFieldPicker(); }
}

/* Assigned To (Tasks / Timeline) — pulls names from guests + wedding party */
function taskAssignedOptions(){
  var set = new Set(['Bride','Groom','Both','Wedding Party','Family','Coordinator','Maid of Honor','Best Man','Planner']);
  (data.guests||[]).forEach(function(g){ if(g.name && g.name.trim()) set.add(g.name.trim()); (g.companions||[]).forEach(function(c){ if(c.name && c.name.trim()) set.add(c.name.trim()); }); });
  (data.party||[]).forEach(function(p){ if(p.name && p.name.trim()) set.add(p.name.trim()); });
  return [...set];
}
function openAssignedPicker(input){ openFieldPicker(input, taskAssignedOptions, { multi:true }); }

/* ============================================================
   TASKS = PLANNING TIMELINE  (consolidation)
   Migrates old data.plan into data.tasks (once), adds sub-task
   support + phase/suggested-date presets on the tasks table.
   ============================================================ */
function taskStatusFromPlan(s){ s=String(s||'').toLowerCase(); if(s.indexOf('complete')>-1) return 'Complete'; if(s.indexOf('progress')>-1) return 'In Progress'; return 'Not Started'; }
function migratePlanIntoTasks(){
  if(typeof data==='undefined' || !data || data._planMergedIntoTasks) return;
  data.tasks = Array.isArray(data.tasks) ? data.tasks : [];
  if(Array.isArray(data.plan) && data.plan.length){
    data.plan.forEach(function(p){
      data.tasks.push({
        _id: p._id || (typeof nextRecordId==='function'? nextRecordId('tasks') : 'TSK-'+Date.now().toString(36)+Math.random().toString(36).slice(2,5)),
        task: p.task||'', cat: p.cat||'', phase: normalizePlanPhase(p.phase||''),
        priority: p.priority||'Medium', assigned: p.owner||p.assigned||'',
        date: p.due||'', suggestedDue: p.suggestedDue||'',
        status: taskStatusFromPlan(p.status), done: !!p.done,
        notes: p.notes||'', subtasks: Array.isArray(p.subtasks)? p.subtasks : []
      });
    });
    data.plan = [];
  }
  data._planMergedIntoTasks = true;
  save();
}

/* ---- Task sub-tasks (expandable checklist inside the Task Name cell) ---- */
const expandedTaskSubs = new Set();
function taskSubArr(i){ if(!data.tasks[i]) return []; if(!Array.isArray(data.tasks[i].subtasks)) data.tasks[i].subtasks=[]; return data.tasks[i].subtasks; }
function toggleTaskSub(i){ if(expandedTaskSubs.has(i)) expandedTaskSubs.delete(i); else expandedTaskSubs.add(i); renderTasks(); }
function addTaskSubtask(i){ taskSubArr(i).push({text:'',done:false}); expandedTaskSubs.add(i); save(); renderTasks(); }
function removeTaskSubtask(i,si){ const s=taskSubArr(i); if(s[si]!==undefined){ s.splice(si,1); save(); renderTasks(); } }
function updateTaskSubtaskText(i,si,v){ const s=taskSubArr(i); if(s[si]){ s[si].text=v; save(); } }
function toggleTaskSubtaskDone(i,si,checked){ const s=taskSubArr(i); if(s[si]){ s[si].done=checked; save(); renderTasks(); } }
function taskSubtaskRow(i){
  const subs = taskSubArr(i);
  const cols = document.querySelectorAll('#panel-tasks .tasks-table thead th').length || 10;
  const items = subs.map((s,si)=>`<div class="plan-sub-item"><label class="plan-sub-check"><input type="checkbox" ${s.done?'checked':''} onchange="toggleTaskSubtaskDone(${i},${si},this.checked)"></label><input type="text" class="plan-sub-text" value="${escapeHtml(s.text||'')}" placeholder="Describe this step…" oninput="updateTaskSubtaskText(${i},${si},this.value)">${plannerTrashButton(`removeTaskSubtask(${i},${si})`,'Remove subtask')}</div>`).join('') || '<div class="plan-sub-empty">No subtasks yet — add the steps for this task.</div>';
  return `<tr class="plan-sub-row" data-no-bulk="true"><td colspan="${cols}"><div class="plan-sub-wrap"><div class="plan-sub-head">${escapeHtml(data.tasks[i].task||'Task')} — subtasks</div>${items}<button type="button" class="btn btn-outline btn-sm plan-sub-add" onclick="addTaskSubtask(${i})">+ Add subtask</button></div></td></tr>`;
}

