async function loadTaskTimelinePreset(){
  if(data.tasks.length && !await starterConfirm('Add the 12-Month Planning Timeline ('+TASK_TIMELINE_PRESET.length+' tasks) to your list?')) return;
  const phaseCounts={};
  TASK_TIMELINE_PRESET.forEach(function(row){
    const phase=row[0], task=row[1], priority=row[2], assigned=row[3];
    const clean=normalizePlanPhase(phase); const n=phaseCounts[clean]||0; phaseCounts[clean]=n+1;
    const suggested=planPhaseBaseDate(clean,n);
    data.tasks.push({_id:nextRecordId('tasks'),task:task,cat:'',phase:clean,priority:priority||'Medium',assigned:assigned||'Both',date:'',suggestedDue:suggested,status:'Not Started',done:false,notes:'',subtasks:[]});
  });
  save(); renderTasks();
}
async function loadTaskFullChecklist(){
  if(data.tasks.length && !await starterConfirm('Add the Full Wedding Checklist (59 tasks across 8 phases) to your list?')) return;
  const phaseCounts={};
  FULL_CHECKLIST.forEach(function(row){
    const phase=row[0], task=row[1], subCount=row[2]||0, doneCount=row[3]||0;
    const clean=normalizePlanPhase(phase); const off=phaseCounts[clean]||0; phaseCounts[clean]=off+1;
    const suggested=planPhaseBaseDate(clean,off);
    const subtasks=[]; for(let n=0;n<subCount;n++) subtasks.push({text:'',done:n<doneCount});
    data.tasks.push({_id:nextRecordId('tasks'),task:task,cat:'',phase:clean,priority:'Medium',assigned:'Both',date:suggested,suggestedDue:suggested,status:(doneCount>0&&doneCount<subCount)?'In Progress':'Not Started',done:false,notes:'',subtasks:subtasks});
  });
  save(); renderTasks();
}

/* Phase color coding for the Planning Timeline (Tasks) table */
function taskPhaseClass(phase){
  switch(String(phase||'')){
    case '12+ Months Before': return 'phase-12';
    case '9-12 Months Before': return 'phase-9';
    case '6-9 Months Before': return 'phase-6';
    case '3 Months Before': return 'phase-3';
    case '1 Month Before': return 'phase-month';
    case '1 Week Before': return 'phase-week';
    case 'Wedding Day': return 'phase-after';
    case 'After the Wedding': return 'phase-after';
    default: return '';
  }
}
function updateTaskPhase(i, sel){
  updateTask(i,'phase',sel.value);
  const w = sel.closest('.task-phase-pill');
  if(w) w.className = 'task-phase-pill ' + taskPhaseClass(sel.value);
}

/* ============================================================
   PT — reusable planner-table behavior engine
   Selection + Edit/Delete Selected + Excel-style per-column
   header filters + search. Generalized from the Tasks table.
   A page still renders its own rows, but uses PT for the
   toolbar buttons, the selection column, the header filters,
   and the search box. Register once per table with PT.register.
   ============================================================ */
window.PT = window.PT || { tables:{}, state:{} };
PT.register = function(key, cfg){ PT.tables[key] = cfg; if(!PT.state[key]) PT.state[key] = { sel:new Set(), colf:{} }; };
PT._cfg  = function(key){ return PT.tables[key] || {}; };
PT._data = function(key){ var c = PT._cfg(key); var a = c.data ? c.data() : []; return Array.isArray(a) ? a : []; };
PT._render = function(key){ var c = PT._cfg(key); if(typeof c.render === 'function') c.render(); };

PT.filtered = function(key){
  var c = PT._cfg(key), st = PT.state[key], fields = c.fields || [];
  var el = document.getElementById(c.searchId), q = ((el && el.value) || '').trim().toLowerCase();
  return PT._data(key).map(function(row,i){ return { row:row, i:i }; }).filter(function(o){
    var row = o.row;
    for(var f in st.colf){ var set = st.colf[f]; if(!set) continue; if(!set.has(String(row[f]==null?'':row[f]).trim())) return false; }
    if(q){ var hay = fields.map(function(f){ return row[f]; }).join(' ').toLowerCase(); if(hay.indexOf(q) === -1) return false; }
    return true;
  });
};

/* selection */
PT.rowCheckbox = function(key, i){
  var checked = PT.state[key].sel.has(String(i)) ? 'checked' : '';
  return '<td class="sel-col"><input type="checkbox" class="pt-rowsel" '+checked+' onchange="PT.toggleRow(\''+key+'\','+i+',this.checked)" onclick="event.stopPropagation()"></td>';
};
PT.toggleRow = function(key, i, on){ var s = PT.state[key].sel; if(on) s.add(String(i)); else s.delete(String(i)); PT.updateBulkUI(key); };
PT.toggleAll = function(key, on){ var s = PT.state[key].sel; s.clear(); if(on) PT.filtered(key).forEach(function(o){ s.add(String(o.i)); }); PT._render(key); };
PT.selected = function(key){ return [...PT.state[key].sel].map(Number).filter(function(n){ return !isNaN(n) && PT._data(key)[n]; }); };
PT.updateBulkUI = function(key){
  var c = PT._cfg(key), n = PT.selected(key).length;
  var e = document.getElementById(c.editBtnId);   if(e) e.disabled = (n !== 1);
  var d = document.getElementById(c.deleteBtnId);  if(d) d.disabled = (n === 0);
  var sa = document.getElementById(c.selectAllId); if(sa){ var total = PT.filtered(key).length; sa.checked = total > 0 && n >= total; }
};
PT.editSelected = function(key){ var idx = PT.selected(key); if(idx.length === 1 && typeof openRecordEditor === 'function') openRecordEditor(PT._cfg(key).entity, idx[0]); };
PT.deleteSelected = async function(key){
  var idx = PT.selected(key).sort(function(a,b){ return b - a; }); if(!idx.length) return;
  var noun = PT._cfg(key).noun || 'item';
  if(!(await covConfirm('Delete ' + idx.length + ' selected ' + noun + (idx.length === 1 ? '' : 's') + '?', {title:'Delete items?', danger:true, okText:'Delete'}))) return;
  var arr = PT._data(key); idx.forEach(function(i){ arr.splice(i, 1); }); PT.state[key].sel.clear();
  if(typeof save === 'function') save(); PT._render(key);
};

/* search + clear */
PT.search = function(key){ PT._render(key); };
PT.clearFilters = function(key){ PT.state[key].colf = {}; var c = PT._cfg(key); var s = document.getElementById(c.searchId); if(s) s.value = ''; PT.closeColFilter(); PT._render(key); };

/* Excel-style per-column header filters */
PT.headerFilter = function(key, field, label){ return '<button class="col-filter" type="button" data-col="'+field+'" onclick="PT.openColFilter(\''+key+'\',\''+field+'\',this)" aria-label="Filter '+label+'">▾</button>'; };
PT.distinct = function(key, field){ return [...new Set(PT._data(key).map(function(r){ return String(r[field]==null?'':r[field]).trim(); }))].sort(function(a,b){ return a.localeCompare(b); }); };
PT.markActive = function(key){ var c = PT._cfg(key), panel = document.getElementById(c.panel); if(!panel) return; panel.querySelectorAll('.col-filter').forEach(function(btn){ btn.classList.toggle('active', !!PT.state[key].colf[btn.getAttribute('data-col')]); }); };
PT._colState = { key:null, field:null };
PT._colOutside = function(ev){ var p = document.getElementById('pt-col-pop'); if(p && !p.contains(ev.target) && !ev.target.closest('.col-filter')) PT.closeColFilter(); };
PT.closeColFilter = function(){ var p = document.getElementById('pt-col-pop'); if(p) p.remove(); document.removeEventListener('mousedown', PT._colOutside, true); };
PT.openColFilter = function(key, field, btn){
  var ex = document.getElementById('pt-col-pop');
  if(ex){ var same = (PT._colState.key === key && PT._colState.field === field); PT.closeColFilter(); if(same) return; }
  PT._colState = { key:key, field:field };
  var values = PT.distinct(key, field), sel = PT.state[key].colf[field];
  var pop = document.createElement('div'); pop.className = 'col-filter-pop'; pop.id = 'pt-col-pop';
  pop.innerHTML =
    '<div class="cfp-search"><input type="text" placeholder="Search values…" oninput="PT.cfpFilter(this.value)"></div>'
    + '<label class="cfp-item cfp-all"><input type="checkbox" id="pt-cfp-all" ' + (!sel ? 'checked' : '') + ' onchange="PT.colAll(\''+key+'\',\''+field+'\',this.checked)"> (Select All)</label>'
    + '<div class="cfp-list">' + values.map(function(v){
        var checked = (!sel || sel.has(v)) ? 'checked' : '';
        var label = v === '' ? '(Blanks)' : escapeHtml(v);
        return '<label class="cfp-item" data-val="'+escapeHtml(v).toLowerCase()+'"><input type="checkbox" value="'+escapeHtml(v)+'" '+checked+' onchange="PT.colToggle(\''+key+'\',\''+field+'\',this.value,this.checked)"> '+label+'</label>';
      }).join('') + '</div>'
    + '<div class="cfp-actions"><button type="button" class="cfp-btn" onclick="PT.colClear(\''+key+'\',\''+field+'\')">Clear</button><button type="button" class="cfp-btn cfp-btn-primary" onclick="PT.closeColFilter()">Done</button></div>';
  document.body.appendChild(pop);
  if (typeof window.rdAnchorToButton === 'function') {
    window.rdAnchorToButton(pop, btn, { keepWidth: true, minWidth: 236, gap: 4, zIndex: 2147483600 });
  } else {
    pop.style.position = 'fixed';
    pop.style.display = 'inline-block';
    var r = btn.getBoundingClientRect();
    var w = Math.max(pop.offsetWidth || 0, 236);
    pop.style.left = Math.max(8, Math.min(r.left, window.innerWidth - w - 8)) + 'px';
    pop.style.top = (r.bottom + 4) + 'px';
  }
  setTimeout(function(){ document.addEventListener('mousedown', PT._colOutside, true); }, 0);
};
PT.cfpFilter = function(q){ q = (q||'').toLowerCase(); document.querySelectorAll('#pt-col-pop .cfp-list .cfp-item').forEach(function(it){ it.style.display = (!q || (it.getAttribute('data-val')||'').indexOf(q) !== -1) ? '' : 'none'; }); };
PT.colToggle = function(key, field, val, on){
  var s = PT.state[key].colf[field]; if(!s){ s = new Set(PT.distinct(key, field)); PT.state[key].colf[field] = s; }
  if(on) s.add(val); else s.delete(val);
  if(s.size === PT.distinct(key, field).length) delete PT.state[key].colf[field];
  var all = document.getElementById('pt-cfp-all'); if(all) all.checked = !PT.state[key].colf[field];
  PT._render(key);
};
PT.colAll = function(key, field, on){ if(on) delete PT.state[key].colf[field]; else PT.state[key].colf[field] = new Set(); document.querySelectorAll('#pt-col-pop .cfp-list input[type=checkbox]').forEach(function(cb){ cb.checked = on; }); PT._render(key); };
PT.colClear = function(key, field){ delete PT.state[key].colf[field]; PT._render(key); PT.closeColFilter(); };

/* call at the end of a table's render */
PT.mount = function(key){ PT.updateBulkUI(key); PT.markActive(key); };

/* Dashboard Budget Snapshot — click a bar to open that category on the Budget page */
function dashBudgetBarClick(i){
  if (typeof activeBudgetCategoryIndex !== 'undefined') activeBudgetCategoryIndex = i;
  showPanel('budget');
}
